INSERT INTO `accounts` (`username`, `password`, `character_name`, `server`, `gold`, `gem`, `void_stone`, `purple_ticket`, `leya_ticket`, `level`, `exp`, `vip_level`, `stamina`, `cur_troop`, `created_at`, `last_login`) VALUES ('player1', 'player123', 'Đấu Sĩ Tập Sự', 'S1 - Quyết Chiến Chi Thành', 1000000, 1000, 100, 10, 10, 1, 0, 0, 120, 1, NOW(), NOW());
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10001, 'Rồng Trắng Mắt Xanh', 'Rồng', 'Quang', 'Mắt Xanh', 8, 3000, 2500, 'UR', 0, 3, 'qybl', 'Một con rồng huyền thoại nổi tiếng với sức tấn công cao. Bất cứ đối phương nào cũng có thể bị đè bẹp - sức công phá của nó là khôn lường.', '|Kết hợp thông thường|\\nDragon Dominator + Sáo rồng triệu hồi + Rồng Trắng Mắt Xanh\\nRồng Trắng Mắt Xanh + Đạn gió nổ\\n\\n|Triệu hồi hợp nhất|\\nKhi có 3 Rồng Trắng Mắt Xanh trên tay hoặc trên sân và có Blue-Eyes Ultra Dragon trong Bộ Bài phụ - bạn có thể sử dụng Phép Thuật <Fusion> để hợp nhất và triệu hồi Blue-Eyes Ultra Dragon.'),
(10002, 'Phù Thủy Trắng', 'Pháp Sư', 'Quang', 'Không có', 4, 1700, 1900, 'UR', 0, 3, 'sldbmd', 'Có thể trở thành một Phù Thủy chiến đấu cao cấp hơn sau nhiều năm hiểu biết về Phép Thuật.', '|Mô tả|\\nBất kể Phép Thuật của bạn hay của đối phương - White Magician lành nghề có thể thêm một phản Phép Thuật\\nKhi kỹ năng được kích hoạt - Kiếm sĩ hủy diệt sẽ được triệu hồi đặc biệt từ Nghĩa Địa trước tiên. Nếu không có ai trong Nghĩa Địa - nó sẽ được triệu hồi đặc biệt từ Bộ Bài. Bộ Bài sẽ không triệu hồi đặc biệt từ tay bài ở cuối. Nếu không có lệnh triệu hồi đặc biệt từ tay - kỹ năng không thể được kích hoạt.'),
(10003, 'Phù Thủy Thời Gian', 'Pháp Sư', 'Quang', 'Không có', 2, 500, 400, 'UR', 0, 3, 'sjmss', 'Một Phù Thủy bí ẩn - chưa ai từng nhìn thấy anh ta - hoặc đã nhìn thấy anh ta nhưng quên mất anh ta.', '|Mô tả|\\nKỹ năng cũng có thể được kích hoạt khi Time Magician được triệu hồi đặc biệt\\nKỹ năng không thể được kích hoạt nếu Time Magician bị phá hủy bởi bẫy khi tiến vào.'),
(10004, 'Phù Thủy Bóng Đêm', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 7, 2500, 2100, 'UR', 0, 3, 'ahmss', 'Là một Phù Thủy - sức tấn công và sức phòng thủ của anh ta đều ở mức cao nhất.', '|Kết hợp thông thường|\\nCô gái Phù Thủy bóng tối + Đá quý hiền triết - Triệu hồi đặc biệt Phù Thủy bóng tối\\nVòng tròn Phù Thủy Triệu hồi đặc biệt Cô gái Phù Thủy bóng tối + Đá quý hiền triết - Triệu hồi đặc biệt Phù Thủy bóng tối\\nTriệu hồi thường và Triệu hồi đặc biệt Phù Thủy bóng tối khi có mảng Phù Thủy bóng tối\\nPhù Thủy bóng tối + Thiên kiếm\\nPhù Thủy bóng tối + Phù Thủy bóng tối\\nCô gái Phù Thủy bóng tối + Phù Thủy bóng tối + Phù Thủy nổ đen'),
(10005, 'Phù Thủy Áo Đen', 'Pháp Sư', 'Ám', 'Không có', 4, 1900, 1700, 'UR', 0, 3, 'sldhmd', 'Chỉ qua nhiều năm tích lũy Phép Thuật - người ta mới có thể trở thành một Phù Thủy cao cấp hơn.', '0'),
(10006, 'Nữ Phù Thủy Áo Đen', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 6, 2000, 1700, 'UR', 0, 3, 'hmsss', 'Đệ tử đáng tự hào nhất của Phù Thủy bóng tối.', '|Giải thích|\\nViệc tăng sức tấn công của Cô gái Phép Thuật bóng tối chỉ liên quan đến số lượng Phù Thủy bóng tối trong Nghĩa Địa của cả hai bên và không liên quan gì đến Phù Thủy bóng tối trên sân. Các Phù Thủy Bóng tối bị loại sẽ không được tính vào phần thưởng sức mạnh tấn công\\n\\n|Kết hợp chung|\\nCô gái Phép Thuật bóng tối +Đá quý hiền triết - triệu hồi đặc biệt Phù Thủy bóng tối\\nVòng tròn Phù Thủy - triệu hồi đặc biệt Cô gái Phép Thuật bóng tối+Đá quý hiền nhân - triệu hồi đặc biệt Phù Thủy bóng tối\\nCô gái Phép Thuật bóng tối+Phù Thủy bóng tối+Ma thuật vụ nổ đen\\nCô gái Phép Thuật bóng tối+Ma thuật vụ nổ đen'),
(10007, 'Baby Dragon', 'Rồng', 'Phong', 'Không có', 3, 1200, 700, 'R', 0, 3, 'bbl', 'Sau khi kết hợp với Phù Thủy thời gian - nó có thể trở thành con rồng nghìn năm và kiểm soát tình hình chung.', '0'),
(10008, 'Công nghệ điện tử Pterosaur', 'Máy Móc', 'Phong', 'Không có', 5, 2500, 1600, 'UR', 0, 3, 'dzkjyl', 'Một loài thằn lằn bay được tăng cường cơ học. Khi anh ta bị một con rồng đánh bại và sắp chết - chủ nhân của anh ta đã biến anh ta thành cơ giới hóa.', '0'),
(10009, 'X·Thủ lĩnh Ganon', 'Máy Móc', 'Quang', 'Không có', 4, 1800, 1500, 'UR', 0, 3, 'xsljn', 'Một con Quái Thú được trang bị một khẩu pháo mạnh mẽ và khả năng kết hợp. Sử dụng toàn bộ cơ thể và tách ra để thực hiện nhiều đòn tấn công khác nhau.', '0'),
(10010, 'Y·Vòi', 'Máy Móc', 'Quang', 'Không có', 4, 1500, 1600, 'UR', 0, 3, 'ylt', 'Một con Quái Thú có khả năng kết hợp.', '0'),
(10011, 'Z·Đường ray kim loại', 'Máy Móc', 'Quang', 'Không có', 4, 1500, 1300, 'UR', 0, 3, 'zjsld', 'Một con Quái Thú có khả năng kết hợp.', '0'),
(10012, 'Nhà hóa học kênh tối Zaki', 'Pháp Sư', 'Ám', 'Không có', 3, 600, 1500, 'R', 0, 3, 'adhszq', 'Đạo sĩ đến và đi không dấu vết - sử dụng những động tác khó tin để tránh các đòn tấn công.', '0'),
(10013, 'Quỷ Chilufa', 'Ác Ma', 'Ám', 'Ác Ma', 6, 2200, 2500, 'UR', 0, 3, 'jlfem', 'Một con quỷ mạnh mẽ tiếp tục gây rắc rối cho kẻ thù của nó ngay cả sau khi chết.', '|Mô tả|\\nKỹ năng có thể được kích hoạt khi vào Nghĩa Địa do thiệt hại trong trận chiến hoặc hiến tế vào Nghĩa Địa.'),
(10014, 'Thỏ đen', 'Thú', 'Ám', 'Không có', 4, 1100, 1500, 'R', 0, 3, 'aht', 'Roger Rabbit trong thế giới phim hoạt hình Mỹ. Thường hành động nhanh chóng và vội vàng.', '0'),
(10015, 'mắt đen nhìn xa trông rộng', 'Pháp Sư', 'Ám', 'Không có', 2, 0, 1400, 'UR', 0, 3, 'ayhxs', 'Một Phù Thủy có thể Phong Tộc ấn các đòn tấn công.', '|Mô tả|\\nDark-Eye IMa Phápginator không thể khóa Quái Thú bằng khiên Quái Thú và Tường chắn Quái Thú - nhưng một khi đã bị khóa bởi Dark-Eye IMa Phápginator - khiên Quái Thú và Tường chắn Quái Thú mới được thêm vào không thể mở chặn <khối>.'),
(10016, 'Baphomet', 'Ác Ma', 'Ám', 'Ma Thú', 5, 1400, 1800, 'SR', 0, 3, 'bft', 'Một con quỷ rất mạnh thường xuất hiện theo cặp với Gazelle.', '|Các kết hợp thường dùng|\\nKiller ToMa Pháptoes + Baphomet'),
(10017, 'Kiếm sĩ lửa xanh', 'Chiến Sĩ', 'Thủy', 'Không có', 4, 1800, 1600, 'UR', 0, 3, 'cyjs', 'Một kiếm sĩ cầm một thanh kiếm rực lửa màu xanh.', '|Giải thích|\\nNếu Kiếm sĩ Ngọn lửa Xanh bị đối phương tiêu diệt thông qua <Loại trừ> - anh ta không thể kích hoạt <Kế thừa Kiếm thuật>'),
(10018, 'chiến binh bánh răng', 'Máy Móc', 'Thủy', 'Không có', 6, 1800, 2000, 'N', 0, 3, 'clzs', 'Những chiến binh robot sinh ra để chiến đấu. Được làm bằng kim loại sẽ không rỉ sét.', '0'),
(10019, 'Đội trưởng sạc', 'Chiến Sĩ', 'Địa', 'Không có', 3, 1200, 400, 'UR', 0, 3, 'cfddz', 'Người đội trưởng luôn đi đầu trên chiến tuyến được quân lính vô cùng yêu mến.', '0'),
(10020, 'Kiếm sĩ Masaki', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1100, 1100, 'N', 0, 3, 'jhzs', 'Người ta nói rằng anh ta là một kiếm sĩ huyền thoại đã giết chết một trăm người.', '0'),
(10021, 'Chiến binh nam châm α', 'Nham Thạch', 'Địa', 'Chiến Binh Nam Châm', 4, 1400, 1700, 'SR', 0, 3, 'cszsa', 'Sử dụng α - β và γ để biến đổi cơ thể.', '0'),
(10022, 'Chiến binh nam châm Beta', 'Nham Thạch', 'Địa', 'Chiến Binh Nam Châm', 4, 1700, 1600, 'SR', 0, 3, 'cszsb', 'Sử dụng α - β và γ để biến đổi cơ thể.', '0'),
(10023, 'Chiến binh nam châm |', 'Nham Thạch', 'Địa', 'Chiến Binh Nam Châm', 4, 1500, 1800, 'SR', 0, 3, 'cszsg', 'Sử dụng α - β và γ để biến đổi cơ thể.', '0'),
(10024, 'rùa máy phóng', 'Thủy Tộc', 'Hỏa', 'Không có', 5, 1000, 2000, 'R', 0, 3, 'tsg', 'Quỹ đạo khổng lồ có thể phóng bất cứ thứ gì.', '0'),
(10025, 'trứng rồng', 'Rồng', 'Thủy', 'Không có', 7, 2200, 2600, 'SR', 0, 3, 'dl', 'Rồng được bao quanh bởi vỏ trứng. Nếu bạn nghĩ mình chỉ là một đứa con nít thì bạn sẽ phải chịu nhiều đau khổ.', '0'),
(10026, 'Con quỷ đèn', 'Ác Ma', 'Ám', 'Không có', 4, 1800, 1000, 'UR', 0, 3, 'dzmj', 'Thần đèn tuân theo mọi yêu cầu và mệnh lệnh của chủ nhân gọi mình.', '|Mô tả|\\nNhững con Quái Thú mạnh mẽ được tặng cho lần gửi tiền đầu tiên'),
(10027, 'Kiếm sĩ sao đất', 'Chiến Sĩ', 'Địa', 'Không có', 3, 500, 1200, 'N', 0, 3, 'dxjs', 'Một kiếm sĩ tiên với sức mạnh đáng kinh ngạc mặc dù kiếm thuật của anh ta còn non nớt.', '0'),
(10028, 'cá ngựa hoàng đế', 'Hải Long', 'Quang', 'Không có', 4, 1700, 1650, 'UR', 0, 3, 'dwhm', 'Cá ngựa Ma Phápng trong mình dòng máu của hoàng đế - có mối liên hệ cực độ với nguyên tố ánh sáng.', '|Mô tả|\\nKhi triệu hồi Quái Thú ánh sáng cấp cao - 1 Cá Ngựa Hoàng Gia được coi như 2 vật hiến tế\\n\\n|Các kết hợp thông thường|\\nHiến tế Cá Ngựa Hoàng Gia để triệu hồi Rồng Trắng Mắt Xanh - hoặc Guildford - hoặc Guardian Joan of Arc - hoặc Wingweaver - hoặc Diamond Dragon - hoặc Holy Night Dragon'),
(10029, 'Triệu hồi quỷ', 'Ác Ma', 'Ám', 'Ác Ma', 6, 2500, 1200, 'UR', 0, 3, 'emzh', 'Một con quỷ sử dụng sức mạnh bóng tối để làm rối loạn tâm trí con người. Được biết đến với sức mạnh đáng kể trong tộc quỷ.', '|Mô tả|\\nMột trong những Quái Thú hiến tế đơn mạnh nhất trong trò chơi\\n\\n|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(10030, 'Chiến binh rồng', 'Thú', 'Địa', 'Không có', 4, 1500, 1200, 'R', 0, 3, 'flzs', 'Một người thằn lằn với kỹ năng kiếm thuật xuất sắc - vung kiếm với tốc độ âm thanh.', '0'),
(10031, 'yêu tinh cổ đại', 'Pháp Sư', 'Quang', 'Không có', 4, 1450, 1200, 'R', 0, 3, 'gdjl', 'Một con yêu tinh đã sống hàng nghìn năm và có thể điều khiển yêu tinh tấn công.', '0'),
(10032, 'kẻ lừa đảo', 'Pháp Sư', 'Phong', 'Không có', 5, 2000, 1200, 'UR', 0, 3, 'gss', 'Phù Thủy đầy bí ẩn và hoàn toàn không thể đoán trước được anh ta sẽ làm gì tiếp theo.', '|Mô tả|\\nKẻ lừa đảo - người có thể được triệu tập đặc biệt bằng cách vứt các lá bài vào Nghĩa Địa - là một trong những lá bài cốt lõi của dòng aggro. Với Phép Thuật của Trickster - nó còn có thể nhanh chóng lan rộng khắp sân - nhanh chóng hiến tế chiến thuật của Quái Thú cấp cao\\nKỹ năng bỏ một lá bài trên tay rất mạnh khi kết hợp với Quái Thú từ thế giới bóng tối.'),
(10033, 'hiệp sĩ vua', 'Chiến Sĩ', 'Quang', 'Không có', 4, 1600, 1400, 'SR', 0, 3, 'gwqs', 'Khi Queen Knight xuất hiện trên chiến trường - khả năng của King Knight trở nên rõ ràng.', '|Mô tả|\\nĐiều kiện triệu hồi Hiệp sĩ Cận vệ\\n1. Triệu hồi King Knight khi có Queen Knight bên cạnh bạn\\n2. Ngoài ra còn có một Hiệp sĩ bảo vệ trong Bộ Bài của bạn.'),
(10034, 'hiệp sĩ bóng đêm gaia', 'Chiến Sĩ', 'Ám', 'Kỵ Sĩ Gaia', 7, 2300, 2100, 'R', 0, 3, 'ahqsgy', 'Một hiệp sĩ cưỡi ngựa nhanh như chớp. Hãy coi chừng các cuộc tấn công lung tung.', '0'),
(10035, 'Phù Thủy Tộc rừng đen', 'Pháp Sư', 'Ám', 'Không có', 4, 1100, 1200, 'UR', 0, 3, 'hsldmn', 'Phù Thủy Tộc sống trong khu rừng tối tăm có một nơi ở rất hẻo lánh.', '|Mô tả|\\nCác kỹ năng phù Thủy Tộc của Rừng Đen có thể được kích hoạt khi bị tiêu diệt hoặc hiến tế - nhưng không thể kích hoạt khi bị <loại trừ>'),
(10036, 'Gazelle - Vua Ma Pháp thú', 'Thú', 'Địa', 'Ma Thú', 4, 1500, 1200, 'R', 0, 3, 'hswjze', 'Nó chạy quá nhanh và trông giống như một con thú Ma Pháp.', '0'),
(10037, 'nữ hoàng hiệp sĩ', 'Chiến Sĩ', 'Quang', 'Không có', 4, 1500, 1600, 'R', 0, 3, 'hhqs', 'Sử dụng những động tác uyển chuyển để đánh lừa kẻ thù - nắm bắt khoảng trống của đối phương và tấn công nhanh chóng lần lượt.', '|Mô tả|\\nĐiều kiện triệu hồi Hiệp sĩ Cận vệ\\n1. Triệu hồi King Knight khi có Queen Knight bên cạnh bạn\\n2. Ngoài ra còn có một Hiệp sĩ bảo vệ trong Bộ Bài của bạn.'),
(10038, 'Chiến binh hỗn loạn · Sứ giả khai mạc', 'Chiến Sĩ', 'Quang', 'Chiến Binh Hỗn Độn', 8, 3000, 2500, 'UR', 0, 1, 'kpdsz', 'Một biểu tượng của thời đại.', '0'),
(10039, 'chiến binh tên lửa', 'Chiến Sĩ', 'Quang', 'Không có', 4, 1500, 1300, 'UR', 0, 3, 'hjzs', 'Một chiến binh Phép Thuật có thể biến thành tên lửa.', '|Mô tả|\\n<Sẵn sàng> chỉ có hiệu lực ở lượt của mình - không có hiệu lực ở lượt của đối phương'),
(10040, 'người điều khiển ngọn lửa', 'Pháp Sư', 'Thủy', 'Không có', 3, 900, 1000, 'N', 0, 3, 'hyczz', 'Di chuyển qua biển lửa một cách dễ dàng để phát động các cuộc tấn công.', '0'),
(10041, 'Kiếm sĩ yêu tinh', 'Chiến Sĩ', 'Địa', 'Chiến Binh Tinh Linh', 4, 1400, 1200, 'R', 0, 3, 'jljs', 'Một yêu tinh đã học được nghệ thuật kiếm thuật. Lừa kẻ thù bằng những đòn tấn công nhanh.', '0'),
(10042, 'Người bảo vệ tấm khiên vĩ đại', 'Chiến Sĩ', 'Địa', 'Không có', 4, 100, 2600, 'UR', 0, 3, 'jdswz', 'Cánh tay khỏe có thể nâng được những tấm khiên khổng lồ.', '|Mô tả|\\n<Khiên Phép Thuật> chỉ có thể bù đắp tác động của hiệu ứng Phép Thuật một lần - cho dù đó là của bạn hay của đối phương.'),
(10043, 'Đột kích rìu lớn', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1700, 1150, 'SR', 0, 3, 'jfxjz', 'Chiến binh rìu. Đòn tấn công bằng rìu bằng một tay khá mạnh mẽ.', '0'),
(10044, 'virus khổng lồ', 'Ác Ma', 'Ám', 'Không có', 2, 1000, 100, 'UR', 0, 3, 'jxbd', 'Cách nhận được: |Phần thưởng nạp lại tích lũy - phần thưởng cấp Quỹ tăng trưởng|.', '|Mô tả|\\nVirus khổng lồ không thể kích hoạt các kỹ năng khi bị phá hủy bởi Phép Thuật hoặc bẫy - cũng như không thể kích hoạt các kỹ năng khi bị <loại trừ>'),
(10045, 'cá sấu hoạt hình', 'Bò Sát', 'Hỏa', 'Không có', 4, 800, 1600, 'R', 0, 3, 'ktey', 'Một con Quái Thú hình cá sấu xuất hiện trong thế giới phim hoạt hình Mỹ.', '0'),
(10046, 'cung nàng tiên cá', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1400, 1500, 'R', 0, 3, 'lgmry', 'Một nàng tiên cá thường trốn trong vỏ sò và bắn tên vào những người đến gần mà không được phép.', '0'),
(10047, 'chiến binh rìu hổ', 'Chiến Sĩ Thú', 'Địa', 'Không có', 4, 1300, 1100, 'N', 0, 3, 'lhfzs', 'Một chiến binh quái thú cầm một chiếc rìu khổng lồ. Nó có thể phóng ra những con búp bê di chuyển nhanh với những đòn tấn công mạnh mẽ.', '0'),
(10048, 'Kuriboh', 'Ác Ma', 'Ám', 'Kuriboh', 1, 300, 200, 'R', 0, 3, 'lzq', 'Một quả bóng hạt dẻ rất dễ thương có thể giảm sát thương.', '0'),
(10049, 'Rồng linh hồn', 'Rồng', 'Phong', 'Không có', 4, 1000, 1000, 'R', 0, 3, 'lhl', 'Sinh vật được hình thành bằng cách tập hợp linh hồn rồng duy trì hình dạng cơ bản của rồng.', '0'),
(10050, 'Thước rồng', 'Pháp Sư', 'Ám', 'Không có', 4, 1200, 1100, 'UR', 0, 3, 'lzzpz', 'Một Phù Thủy mạnh mẽ có thể điều khiển rồng.', '|Các kết hợp thường dùng|\\nThần Long + Sáo Gọi Rồng + Rồng Trắng Mắt Xanh'),
(10051, 'Nghĩa Địa voi Ma Pháp mút', 'Khủng Long', 'Địa', 'Không có', 3, 1200, 800, 'R', 0, 3, 'mmdmc', 'Những con voi Ma Pháp mút canh giữ mộ của bạn bè chúng sẽ tấn công không thương tiếc bất kỳ kẻ cướp mộ nào dÁm Tộc giẫm đạp lên mộ.', '0'),
(10052, 'chú hề trong mơ', 'Chiến Sĩ', 'Địa', 'Không có', 3, 1200, 900, 'UR', 0, 3, 'mhxc', 'Một chú hề khiến đối phương bối rối bằng một phiên bản Phép Thuật giả tưởng.', '0'),
(10053, 'Mahavira', 'Pháp Sư', 'Quang', 'Không có', 4, 1550, 1400, 'UR', 0, 1, 'mkpl', 'Cách nhận: |Mời 5 người bạn và đạt cấp 35 với bất kỳ nhân vật nào|.', '|Mô tả|\\nMỗi khi Mahavira có được một thiết bị - ngoài hiệu ứng của chính trang bị đó - 500 điểm tấn công sẽ được cộng thêm\\n\\n|Phương thức mua lại|\\nBạn có thể nhận được nó bằng cách mời 5 người bạn và tất cả bạn bè đều được nâng cấp lên cấp 35.'),
(10054, 'Valkyrie Phép Thuật', 'Pháp Sư', 'Quang', 'Không có', 4, 1600, 1800, 'UR', 0, 3, 'msnws', 'Một Phù Thủy kết hợp giữa Phép Thuật và võ thuật gần như không có đối phương ở cùng cấp độ.', '|Mô tả|\\nNếu có 2 Magic Valkyrie trên sân phe ta - nó sẽ tạo thành một màn khiêu khích kép và đối phương sẽ không thể tấn công bất kỳ Quái Thú Phù Thủy nào trên sân phe ta nữa.'),
(10055, 'thợ săn Quái Thú', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1500, 1200, 'R', 0, 3, 'mwdsr', 'Người thợ săn săn người có sức mạnh có thể đập vỡ cả đá.', '0'),
(10056, 'người đàn ông mặt chim', 'Chim Thú', 'Phong', 'Không có', 4, 1600, 1600, 'SR', 0, 3, 'nmr', 'Anh ta có đầu diều hâu và thân hình - tôi không biết anh ta có đeo mặt nạ hay không.', '0'),
(10057, 'sa giông', 'Ác Ma', 'Phong', 'Không có', 4, 1900, 400, 'UR', 0, 3, 'nt', 'Một con quỷ với những đòn tấn công cực kỳ mạnh mẽ.', '0'),
(10058, 'Kiếm sĩ hủy diệt', 'Chiến Sĩ', 'Địa', 'Kiếm Sĩ Diệt Rồng', 7, 2600, 2300, 'UR', 0, 3, 'phjs', 'Một kiếm sĩ có sức công phá lớn.', '|Mô tả|\\nHiệu ứng kỹ năng của Kiếm sĩ hủy diệt không tính số lượng Quái Thú loại Rồng <của riêng>.'),
(10059, 'Rồng hủy diệt Gandora', 'Rồng', 'Ám', 'Gandora', 8, 0, 0, 'UR', 0, 1, 'phlgdl', 'Một con rồng có thể phá hủy mọi thứ.', '|Mô tả|\\nQuái Thú phần thưởng nhận được ở cấp VIP 10 có khả năng quay trở lại mạnh nhất trong trò chơi.'),
(10060, 'Chiến binh báo đen', 'Chiến Sĩ Thú', 'Phong', 'Không có', 4, 2000, 1600, 'UR', 0, 3, 'qhzbzs', 'Một sát thủ cấp cao không thể nhận dạng được trong bóng tối.', '|Mô tả|\\nSau khi kích hoạt thành công các kỹ năng của Chiến binh báo đen - Chiến binh báo đen sẽ không thể tấn công. Khả năng định vị mạnh mẽ của nó khiến nó trở thành vật liệu hiến tế tốt nhất\\n\\n|Cách lấy|\\nCó thể mua tại Time Capsule'),
(10061, 'Chimeric Manticore', 'Thú', 'Địa', 'Không có', 8, 2800, 2500, 'UR', 0, 3, 'xhxws', 'Một con thú thần thoại tồn tại trong truyền thuyết.', '0'),
(10062, 'Người nhân tạo·Kẻ gây sốc tâm linh', 'Máy Móc', 'Ám', 'Người Nhân Tạo Jinzo', 6, 2400, 1500, 'UR', 0, 3, 'rzrnlzsz', 'Người nhân tạo có khả năng điều khiển từ xa mạnh mẽ và có thể tác động đến các lá bài bẫy trên chiến trường để kiểm soát tình hình chiến đấu.', '0'),
(10063, 'Quái Thú ba mắt', 'Ác Ma', 'Ám', 'Không có', 3, 1000, 600, 'SR', 0, 3, 'syg', 'Một con Quái Thú có ba mắt. Người ta nói rằng con mắt thứ ba có thể khiến kẻ thù bối rối.', '0'),
(10064, 'chú hề sát thủ', 'Ác Ma', 'Địa', 'Không có', 4, 1350, 1400, 'UR', 0, 3, 'srxc', 'Khi một người giết ai đó - anh ta sẽ trở thành một con quỷ.', '0'),
(10065, 'Valkyrie mạnh mẽ', 'Thiên Thần', 'Quang', 'Không có', 4, 1800, 1050, 'UR', 0, 3, 'slnws', 'Thiên thần ánh sáng dũng cảm có trái tim công lý mạnh mẽ và sẽ không bao giờ chạy trốn khỏi một trận thua.', '|Mô tả|\\nLà một Quái Thú bình thường thuộc họ thiên thần - kết hợp với hiệp sĩ Gawain có khả năng nhanh chóng mở rộng Địa Tộc bàn.'),
(10066, 'Thánh Phù Thủy', 'Pháp Sư', 'Quang', 'Không có', 1, 300, 400, 'UR', 0, 3, 'ssmss', 'Một Phù Thủy yêu tinh thành thạo Phép Thuật.', '0'),
(10067, 'búp bê thiêng liêng', 'Pháp Sư', 'Quang', 'Không có', 4, 1600, 1000, 'R', 0, 3, 'ssro', 'Một con rối điều khiển sức mạnh thần thánh. Sức tấn công rất mạnh trong bóng tối.', '0'),
(10068, 'Chúa Thánh Thần', 'Pháp Sư', 'Quang', 'Không có', 4, 800, 2000, 'UR', 0, 3, 'sjl', 'Mặc dù là một yêu tinh mỏng Ma Phápnh nhưng nó có khả năng phòng thủ mạnh mẽ nhờ sức mạnh thần thánh của mình.', '|Mô tả|\\nKhả năng đứng mạnh mẽ khiến nó trở thành vật liệu hiến tế tốt nhất\\n\\n|Cách lấy|\\nCó thể mua trong Time Capsule'),
(10069, 'tinh thần song sinh', 'Pháp Sư', 'Địa', 'Không có', 4, 1900, 900, 'UR', 0, 3, 'ssjl', 'Hai chị em tiên sinh đôi phối hợp tấn công lẫn nhau.', '|Mô tả|\\nPhần thưởng Quái Thú nhận được khi nhân vật Muto Yugi nâng cấp lên cấp 60 - rất mạnh.'),
(10070, 'hiệp sĩ sắt được giải thoát', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1800, 1600, 'UR', 0, 3, 'tqsfld', 'Bởi vì bị giới hạn trong bộ giáp thép nên anh ta không thể sử dụng các trang bị khác.', '|Mô tả|\\nCác kỹ năng của Iron Knight Fried ngăn Hiệp sĩ sắt trang bị thiết bị buff - nhưng nó cũng không thể trang bị thiết bị Phép Thuật debuff hoặc bẫy. Nó thường được sử dụng để phá hủy Lời nguyền quẻ - Lời nguyền bóng tối - Phong tỏa dây chuyền - Rìu chia dần và các Cạm Bẫy khác của đối phương.'),
(10071, 'Hiệp sĩ bảo vệ', 'Chiến Sĩ', 'Quang', 'Không có', 5, 1900, 1000, 'R', 0, 3, 'wbqs', 'Một chiến binh thành thạo tất cả các kỹ năng kiếm thuật. Anh ấy có ý thức mạnh mẽ về công lý và chiến đấu để bảo vệ kẻ yếu.', '|Mô tả|\\nĐiều kiện triệu hồi Hiệp sĩ Cận vệ\\n1. Triệu hồi King Knight khi có Queen Knight bên cạnh bạn\\n2. Ngoài ra còn có một Hiệp sĩ bảo vệ trong Bộ Bài của bạn.'),
(10072, 'Người tưởng tượng vô diện', 'Pháp Sư', 'Ám', 'Không có', 6, 1200, 2200, 'SR', 0, 3, 'wlhxs', 'Tạo bóng Ma Pháp để dễ dàng tránh đòn tấn công của kẻ thù.', '|Các kết hợp thường dùng|\\nKilling ToMa Phápto + Faceless IMa Phápgineer'),
(10073, 'Kỵ sĩ không đầu', 'Ác Ma', 'Địa', 'Không có', 4, 1450, 1700, 'SR', 0, 3, 'wtqs', 'Hiệp sĩ bất tử bị kết án là kẻ nổi loạn và bị xử tử - đang tìm kiếm những gì mình đã mất và sẽ tấn công bất cứ ai anh gặp.', '0'),
(10074, 'Hoàng đế Warcraft đẫm máu', 'Chiến Sĩ Thú', 'Ám', 'Không có', 5, 1900, 1200, 'UR', 0, 3, 'xmsrdw', 'Hoàng đế Warcraft máu lửa có khát máu cực kỳ mãnh liệt.', '0'),
(10075, 'chiến binh chiến đấu aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1500, 1300, 'R', 0, 3, 'ymxgdzs', 'Một chiến binh Amazoness mạnh mẽ - được các vị thần bảo vệ.', '0'),
(10076, 'kiếm sĩ aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1500, 1600, 'SR', 0, 3, 'ymxjs', 'Thiệt hại nhận được có thể được giảm bớt thông qua Phép Thuật của Amazoness.', '|Mô tả|\\nKỹ năng của Kiếm sĩ Amazoness sử dụng đòn tấn công liều chết để gây sát thương cho sức khỏe của đối phương khi đối phương triệu hồi Quái Thú cấp cao - Ma Phápng lại khả năng quay trở lại\\n|Các kết hợp thông thường|\\nKiếm sĩ Amazoness + Cỗ máy thời gian\\nKiếm sĩ Amazoness + Ý chí Amazoness\\nKiếm sĩ Amazoness + Sự hồi sinh của người chết\\nKiếm sĩ Amazoness + Chôn cất sớm'),
(10077, 'Nhà sản xuất chuỗi Amazoness', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1500, 1300, 'UR', 0, 3, 'ymxsls', 'Một chiến binh Amazoness chuyên tấn công tầm xa.', '|Mô tả|\\nCác kỹ năng của Amazoness Chainer không thể được kích hoạt khi mạng sống của một người nhỏ hơn hoặc bằng 1000\\nCác kỹ năng của Amazoness Chainer không thể được kích hoạt khi người chơi đối phương không có bài trên tay'),
(10078, 'Lính đá', 'Nham Thạch', 'Địa', 'Không có', 3, 1300, 2000, 'UR', 0, 3, 'ysjb', 'Người lính khổng lồ bằng đá. Cuộc tấn công của cổ tay dày làm rung chuyển mặt đất.', '0'),
(10079, 'Ma Phápn rợ 1', 'Chiến Sĩ', 'Địa', 'Không có', 5, 1550, 1800, 'R', 0, 3, 'ymryh', 'Những kẻ Ma Phápn rợ mạnh mẽ thường xuất hiện theo nhóm.', '0'),
