(10093, 'ấu trùng bé', 'Côn Trùng', 'Địa', 'Không có', 1, 300, 200, 'UR', 0, 3, 'ycbb', 'Không rõ nó sẽ trở thành loại sâu bướm nhỏ nào khi lớn lên.', '0'),
(10094, 'kén tiến hóa', 'Côn Trùng', 'Địa', 'Không có', 3, 0, 2000, 'UR', 0, 3, 'jhzj', 'Một sinh vật huyền diệu có thể tiến hóa ấu trùng con.', '0'),
(10095, 'Vua khủng long hai đầu', 'Khủng Long', 'Địa', 'Không có', 4, 1600, 1200, 'R', 0, 3, 'stklw', 'Một con Quái Thú mạnh mẽ trong số các loài khủng long - hai đầu của nó tấn công cùng một lúc.', '0'),
(10096, 'Rồng siêu đầu búa', 'Khủng Long', 'Địa', 'Không có', 4, 1500, 1200, 'SR', 0, 3, 'cjcsl', 'Cú húc đầu khổng lồ của nó có thể dễ dàng làm vỡ đá.', '|Mô tả|\\nMột lá bài rất hữu ích trong Arena Gate. Nó hiến tế sức khỏe để loại bỏ Quái Thú cấp cao trên sân đối phương.'),
(10097, 'Quái Thú có sừng kiếm', 'Khủng Long', 'Địa', 'Không có', 4, 1400, 1200, 'R', 0, 3, 'mjjjs', 'Những chiếc sừng sắc nhọn trên đầu nó có thể xuyên thủng bất cứ thứ gì.', '0'),
(10098, 'khủng long sừng', 'Khủng Long', 'Địa', 'Không có', 6, 1800, 2000, 'R', 0, 3, 'jl', 'Một con khủng long có sừng khắp cơ thể. Cuộc tấn công bất ngờ rất mạnh mẽ!', '0'),
(10099, 'Khủng bố đen tối', 'Khủng Long', 'Địa', 'Không có', 7, 2600, 1800, 'SR', 0, 3, 'ahks', 'Hành vi nguy hiểm nhất là khi bạn chuẩn bị phòng thủ trước các cuộc tấn công của nó.', '0'),
(10100, 'Brachiosaurus băng giá', 'Khủng Long', 'Hỏa', 'Không có', 6, 2600, 1700, 'UR', 0, 3, 'bswl', 'Nhờ thần kinh chậm chạp và sự nhạy cảm của mình - anh ta có sức sống đáng sợ để sống sót qua kỷ băng hà dù bị đóng băng. Nó có khả năng chống lạnh cực kỳ cao.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10101, 'mực quỷ', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1200, 1400, 'N', 0, 3, 'emwz', 'Bạch tuộc khổng lồ ẩn nấp dưới biển. Xuất hiện bất ngờ từ biển và tấn công.', '0'),
(10102, 'sứa', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1200, 1500, 'R', 0, 3, 'sm', 'Sứa trôi nổi trên biển - thân trong suốt khiến chúng khó bị phát hiện.', '0'),
(10103, 'cá mập trắng lớn', 'Cá', 'Hỏa', 'Không có', 4, 1600, 800, 'R', 0, 3, 'dbs', 'Một con cá mập trắng khổng lồ nếu bị cắn sẽ không bao giờ có thể trốn thoát.', '0'),
(10104, 'cá bay', 'Cá', 'Phong', 'Không có', 4, 800, 500, 'N', 0, 3, 'fy', 'Người ta nói rằng ai nhìn thấy nó bay trên bầu trời sẽ được ban ba điều ước.', '0'),
(10105, 'nửa thú nửa cá', 'Cá', 'Hỏa', 'Không có', 6, 2400, 2000, 'UR', 0, 3, 'bys', 'Nó có thể tấn công nhanh như thú trên cạn và như cá dưới biển.', '0'),
(10106, 'thần rồng biển', 'Hải Long', 'Hỏa', 'Không có', 5, 1800, 1500, 'N', 0, 3, 'hls', 'Con rồng biển được mệnh danh là Chúa tể của đại dương. Tạo ra một cơn sóng thần nuốt chửng mọi thứ.', '0'),
(10107, 'ngư dân huyền thoại', 'Chiến Sĩ', 'Hỏa', 'Không có', 5, 1850, 1600, 'R', 0, 3, 'csdyr', 'Người ngư dân huyền thoại - người hiểu rõ bản chất của biển - là thợ săn mạnh nhất trên biển.', '0'),
(10108, 'hồn Ma Pháp đầu ngựa', 'Zombie', 'Địa', 'Không có', 4, 1700, 800, 'UR', 0, 3, 'mtg', 'Giỏi kêu gọi các sinh vật trong nghĩa trang.', '|Mô tả|\\nBất kỳ hồn Ma Pháp đầu ngựa nào bị tiêu diệt dưới mọi hình thức đều có thể kích hoạt kỹ năng chiêu mộ Quái Thú bất tử từ Nghĩa Địa.'),
(10109, 'yêu tinh zombie', 'Zombie', 'Ám', 'Ghostrick', 4, 1100, 1050, 'UR', 0, 3, 'gbljs', 'Rất khó để nắm bắt được nó bằng hành động - rất phức tạp.', '|Mô tả|\\nViệc tiêu diệt các lá bài ở đầu Bộ Bài của đối phương cũng làm mất đi hy vọng lội ngược dòng của đối phương\\nNgay cả khi nó bị tiêu diệt - bạn sẽ không bị mất lá bài\\n\\n|Các kết hợp thông thường|\\nGoblin Zombie + Vampire Dragon\\nGoblin Zombie + Necropot\\nGoblin Zombie + Horse-head Ghost\\nGoblin Zombie + Pumpkin Princess'),
(10110, 'hóa trị hai', 'Zombie', 'Ám', 'Không có', 4, 1700, 1650, 'UR', 0, 3, 'sjt', 'Một cặp cộng sinh sống cùng nhau và không có cách nào tách rời ngoại trừ cái chết.', '|Mô tả|\\nKhi triệu hồi một Quái Thú bóng tối cấp cao - 1 hóa trị hai được coi là 2 vật hiến tế\\n\\n|Các kết hợp thông thường|\\nHiến tế một Quái Thú hóa trị hai sẽ triệu hồi những Quái Thú mạnh mẽ như Dark Magician - Red-Eyed Black Dragon - Fallen Superbia - v.v.'),
(10111, 'Gernia', 'Zombie', 'Ám', 'Không có', 4, 1300, 1200, 'SR', 0, 3, 'jeny', 'Hầu như không có cách nào để giết và bằng cách nào đó có thể tái sinh sau khi chết.', '|Mô tả|\\nJelnia có lợi thế tự nhiên trước các lá bài của đối phương như Bẫy hoặc Khiên thánh.'),
(10112, 'Ma cà rồng', 'Zombie', 'Ám', 'Không có', 4, 1300, 1500, 'SR', 0, 3, 'xxg', 'Một con Quái Thú thích tra tấn từ từ đến chết người.', '|Mô tả|\\nKỹ năng có thể được kích hoạt bằng cách tấn công trực tiếp người chơi hoặc tấn công Quái Thú gây sát thương cho người chơi đối phương.'),
(10113, 'Xác sống cắt linh hồn', 'Zombie', 'Ám', 'Không có', 3, 300, 200, 'R', 0, 3, 'xhdsl', 'Một linh hồn bất tử độc ác thích xé nát linh hồn người khác để mua vui.', '0'),
(10114, 'Vua bí ngô Ma Pháp', 'Zombie', 'Ám', 'Không có', 6, 1800, 2000, 'SR', 0, 3, 'ylngw', 'Điều tôi thích nhất trong lễ Phục sinh là hóa trang thành một chiếc đèn bí ngô và khiến người khác sợ hãi.', '|Mô tả|\\nSau khi vào sân: tấn công và phòng thủ trong hiệp là 1900/2100 - sau khi phát triển toàn diện là 2100/2300.'),
(10115, 'Viên đá trắng huyền thoại', 'Rồng', 'Quang', 'Không có', 1, 300, 250, 'UR', 0, 3, 'csdbs', 'Một viên đá đặc biệt từng xuất hiện ở nơi tụ tập Rồng Trắng Mắt Xanh. Người ta nói rằng Rồng Trắng Mắt Xanh có thể cảm nhận được năng lượng phát ra từ nó.', '|Mô tả|\\nKỹ năng đá trắng huyền thoại có thể được kích hoạt khi bị tiêu diệt hoặc hiến tế - nhưng không thể kích hoạt khi bị <loại trừ>'),
(10116, 'đá trắng cổ', 'Rồng', 'Quang', 'Không có', 1, 600, 500, 'UR', 0, 3, 'tgdbs', 'Đá tồn tại từ thời cổ đại và tỏa ra năng lượng ấm áp.', '0'),
(10117, 'Cá ngựa', 'Chiến Sĩ', 'Quang', 'Không có', 3, 200, 700, 'UR', 0, 3, 'hmx', 'Tiếp xúc lâu dài với Rồng Trắng Mắt Xanh giúp tôi hiểu hết được suy nghĩ của Rồng Trắng Mắt Xanh.', '0'),
(10118, 'Rồng đen mới nở', 'Rồng', 'Ám', 'Mắt Đỏ', 1, 800, 500, 'UR', 0, 3, 'hlzc', 'Con của con rồng đen mắt đỏ thực sự - nhưng vẫn nhận được sự ban phước của lửa và có thể phun ra ngọn lửa rực rỡ sau khi sinh ra.', '|Mô tả|\\nKỹ năng ấp rồng đen có thể được kích hoạt khi nó bị tiêu diệt hoặc hiến tế - nhưng không thể kích hoạt khi bị <loại trừ>\\nKỹ năng ấp rồng đen không thể được kích hoạt khi không có Rồng đen mắt đỏ trên tay.'),
(10119, 'hổ cưng aMa Phápzon', 'Thú', 'Địa', 'Amazoness', 4, 1100, 1500, 'UR', 0, 3, 'ymxcwh', 'Sống trong bộ tộc Amazoness lâu đời - đối xử rất thân mật với mọi người', '0'),
(10120, 'chiến binh thần thánh aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1700, 300, 'UR', 0, 3, 'ymxszs', 'Một chiến binh tập trung vào chiến đấu - càng có nhiều đồng đội thì hiệu quả chiến đấu của anh ta sẽ càng mạnh mẽ.', '|Giải thích|\\nBản thân Thánh chiến Amazoness cũng có từ khóa <Amazoness> nên khi trên sân chỉ có 1 Thánh chiến binh Amazoness thì sức tấn công là 1800 - còn khi có 1 Thánh chiến binh Amazoness và 1 quái thú Amazoness khác trên sân thì sức tấn công là 1900 - v.v.'),
(10121, 'Thực tập sinh Amazoness', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1500, 1300, 'UR', 0, 3, 'ymxxls', 'Nắm vững chiến thuật phá vỡ đội hình địch', '|Mô tả|\\nĐòn tấn công của Amazoness Trainee sẽ không khiến Quái Thú đi vào Nghĩa Địa và sẽ không kích hoạt kỹ năng vào Nghĩa Địa của Quái Thú đối phương. Mỗi khi một con Quái Thú bị tiêu diệt - đòn tấn công của một người sẽ tăng thêm 200 và học viên Amazoness ngày càng trở nên mạnh mẽ hơn\\n\\n|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(10122, 'Cây xô thơm Amazoness', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1400, 700, 'SR', 0, 3, 'ymxxz', 'Chuyên về lĩnh vực Phép Thuật và bẫy - đồng thời sử dụng khả năng điều khiển từ xa mạnh mẽ để phá vỡ Phép Thuật và bẫy vào những thời điểm quan trọng.', '0'),
(10123, 'nữ hoàng aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 6, 2400, 1800, 'UR', 0, 2, 'ymxnw', 'Nữ hoàng của bộ tộc Amazoness được mọi bộ tộc vô cùng yêu quý. Bất cứ khi nào cô ấy xuất hiện trên chiến trường đều là khởi đầu của chiến thắng.', '0'),
(10124, 'cà chua sát thủ', 'Thực Vật', 'Ám', 'Không có', 4, 1400, 1100, 'SR', 0, 3, 'srfq', 'Cà chua đột biến có kích thước khổng lồ và thường di chuyển trong bóng tối.', '|Mô tả|\\nSau khi Killer ToMa Phápto chết - hãy triệu hồi Quái Thú từ Bộ Bài - điều này không chỉ có thể cung cấp Quái Thú mới trên sân mà còn rút ngắn chiều dài của Bộ Bài thông qua các lệnh triệu hồi đặc biệt\\nĐiều kiện kích hoạt cho kỹ năng này là\\n1. Bị tiêu diệt khỏi chiến trường trong trận chiến (kỹ năng không thể kích hoạt nếu bị tiêu diệt bởi hiệu ứng)\\n2. Vào Nghĩa Địa (kỹ năng không thể kích hoạt nếu nó bị loại trừ)\\n3. Có một Quái Thú thuộc tính bóng tối có sức tấn công từ 1500 trở xuống trong Bộ Bài'),
(10125, 'Rồng đeo mặt nạ', 'Rồng', 'Thủy', 'Không có', 3, 1400, 1100, 'SR', 0, 3, 'jml', 'Không ai biết con rồng bí ẩn dưới lớp mặt nạ trông như thế nào.', '|Mô tả|\\nSau khi Masked Dragon chết - triệu hồi Quái Thú từ Bộ Bài - điều này không chỉ có thể cung cấp Quái Thú mới trên sân mà còn rút ngắn chiều dài của Bộ Bài thông qua các lệnh triệu hồi đặc biệt\\nĐiều kiện kích hoạt cho kỹ năng này là\\n1. Bị tiêu diệt khỏi chiến trường trong trận chiến (kỹ năng không thể kích hoạt nếu nó bị tiêu diệt bởi hiệu ứng)\\n2. Vào Nghĩa Địa (kỹ năng không thể kích hoạt nếu nó bị loại trừ)\\n3. Có một Quái Thú loại rồng trong Bộ Bài có sức tấn công từ 1500 trở xuống'),
(10126, 'Dole Dora', 'Rồng', 'Phong', 'Không có', 3, 1500, 1200, 'UR', 0, 3, 'dedl', 'Con rồng bất tử huyền thoại - chưa ai từng thấy nó chết', '|Mô tả|\\nDol-Dora là Quái Thú ổn định nhất trên sân. Sau khi chết - nó còn có thể cung cấp Quái Thú hiến tế ổn định để toàn đội lấy lại thế trận trên sân.'),
(10127, 'Nữ chiến binh vùng hoang dã', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1100, 1200, 'SR', 0, 3, 'hydnzs', 'Nữ chiến binh xinh đẹp và mạnh mẽ là người tình trong mơ của nhiều người', '|Mô tả|\\nNữ chiến binh của vùng hoang dã triệu hồi Quái Thú từ Bộ Bài sau khi chết - điều này không chỉ có thể cung cấp Quái Thú mới trên chiến trường mà còn rút ngắn chiều dài của Bộ Bài thông qua các lệnh triệu hồi đặc biệt\\nĐiều kiện kích hoạt cho kỹ năng này là\\n1. Bị tiêu diệt khỏi chiến trường trong trận chiến (kỹ năng không thể kích hoạt nếu bị tiêu diệt bởi hiệu ứng)\\n2. Vào Nghĩa Địa (kỹ năng không thể kích hoạt nếu nó bị loại trừ)\\n3. Có những Quái Thú loại chiến binh có sức tấn công từ 1500 trở xuống trong Bộ Bài.'),
(10128, 'Kẻ trộm Ma Pháp màu trắng', 'Pháp Sư', 'Quang', 'Không có', 3, 1000, 700, 'SR', 0, 3, 'bygd', 'Một bóng người màu trắng trong đêm tối đặc biệt bắt mắt - thường xuyên dùng Ma Pháp pháp kỳ quái để trộm cắp.', '0'),
(10129, 'Kỵ binh nhỏ', 'Chiến Sĩ', 'Địa', 'Không có', 1, 900, 500, 'UR', 0, 3, 'xqb', 'Dù kích thước dễ bị bỏ qua nhưng sức mạnh bùng nổ khó có thể bỏ qua', '0'),
(10130, 'Người triệu hồi Suzaku', 'Pháp Sư', 'Thủy', 'Không có', 4, 1600, 1300, 'UR', 0, 3, 'zqzhs', 'Tôi có thể triệu hồi sức mạnh của Suzaku và truyền nó vào vũ khí lạnh - nhưng vì tôi là Phù Thủy nên tôi không thích sử dụng vũ khí lạnh.', '|Mô tả|\\nSau khi Người triệu hồi Suzaku chết - nó sẽ triệu hồi Quái Thú từ Bộ Bài - điều này không chỉ có thể cung cấp Quái Thú mới trên sân mà còn rút ngắn chiều dài của Bộ Bài thông qua các lần triệu hồi đặc biệt\\nĐiều kiện kích hoạt cho kỹ năng này là\\n1. Bị tiêu diệt khỏi chiến trường trong trận chiến (kỹ năng không thể kích hoạt nếu nó bị tiêu diệt bởi hiệu ứng)\\n2. Vào Nghĩa Địa (kỹ năng không thể kích hoạt nếu nó bị loại trừ)\\n3. Có những Quái Thú loại chiến binh có sức tấn công từ 1500 trở xuống trong Bộ Bài.'),
(10131, 'Thánh kiếm Elf', 'Chiến Sĩ', 'Địa', 'Chiến Binh Tinh Linh', 4, 2100, 700, 'UR', 0, 3, 'jlsjs', 'Một số rất ít kiếm sĩ yêu tinh đã trở thành những chiến binh cao cấp hơn sau khi được các yêu tinh thánh thiện ban phước.', '0'),
(10132, 'Người khổng lồ điện tử Phép Thuật', 'Chiến Sĩ', 'Ám', 'Không có', 6, 2200, 1200, 'UR', 0, 1, 'mddzjr', 'Cách nhận: |Phần thưởng khi mời 10 người bạn và đạt cấp 35 với bất kỳ nhân vật nào|.', '|Mô tả|\\nBạn có thể nhận được nó bằng cách mời 10 người bạn và tất cả bạn bè đều được nâng cấp lên cấp 35 - có thể nhanh chóng mở rộng lĩnh vực.'),
(10133, 'Các dẫn xuất của Dole Dora', 'Rồng', 'Phong', 'Không có', 3, 1000, 1000, 'UR', 0, 3, 'dedl', 'Con rồng bất tử huyền thoại - chưa ai từng thấy nó chết', '0'),
(10134, 'rồng ba đầu', 'Rồng', 'Thủy', 'Không có', 5, 1600, 1800, 'N', 0, 3, 'stjl', 'Dùng ba cái đầu của nó liên tục phun lửa - biến khu vực xung quanh thành biển lửa!', '0'),
(10135, 'Rồng lưỡi liềm', 'Rồng', 'Ám', 'Không có', 7, 2200, 2350, 'R', 0, 3, 'xyl', 'Một chiến binh rồng được cho là đến từ mặt trăng và cầm thanh kiếm Mikazuki.', '0'),
(10136, 'Tiểu Long', 'Rồng', 'Phong', 'Không có', 2, 600, 700, 'N', 0, 3, 'xl', 'Một con rồng nhỏ. Sử dụng toàn bộ cơ thể nhỏ bé của bạn để tấn công.', '0'),
(10137, 'rồng đỏ', 'Rồng', 'Thủy', 'Không có', 6, 1700, 1900, 'N', 0, 3, 'hl', 'Một con rồng đỏ bắn ra những quả cầu lửa và biến khu vực xung quanh thành biển lửa.', '0'),
(10138, 'Người lính thằn lằn', 'Rồng', 'Phong', 'Không có', 3, 1100, 800, 'N', 0, 3, 'xyb', 'Một chủng tộc thú nhân có nguồn gốc từ rồng. Trong số những con rồng - chúng nhỏ bé và nhanh nhẹn. Giàu có về mặt chiến lược.', '0'),
(10139, 'Rồng kim cương', 'Rồng', 'Quang', 'Không có', 7, 2100, 2800, 'UR', 0, 3, 'zsl', 'Một con rồng có toàn bộ cơ thể được làm bằng kim cương - ánh sáng rực rỡ của nó có thể khiến kẻ thù bối rối.', '0'),
(10140, 'Săn rồng', 'Rồng', 'Ám', 'Không có', 3, 1700, 100, 'SR', 0, 3, 'll', 'Một con rồng giết chết con mồi bằng răng nanh của nó. Nó tấn công nhanh và sắc bén nhưng không có khả năng phòng thủ.', '0'),
(10141, 'Rồng cấp thấp hơn', 'Rồng', 'Phong', 'Không có', 4, 1200, 1000, 'N', 0, 3, 'xjl', 'Một con rồng cấp thấp không mạnh lắm và thậm chí không thể sử dụng đòn tấn công bằng hơi thở.', '0'),
(10142, 'Rồng Tiên', 'Rồng', 'Phong', 'Không có', 4, 1100, 1200, 'N', 0, 3, 'yjl', 'Một nàng tiên rồng mạnh mẽ đến bất ngờ trong số các nàng tiên và rất xinh đẹp.', '0'),
(10143, 'rồng đêm thánh', 'Rồng', 'Quang', 'Không có', 7, 2500, 2300, 'SR', 0, 3, 'syl', 'Ngọn lửa thánh thiêu rụi những kẻ làm ác và đó là một con rồng sở hữu sức mạnh thần thánh.', '0'),
(10144, 'rồng trời', 'Rồng', 'Phong', 'Không có', 6, 1900, 1800, 'N', 0, 3, 'tkl', 'Một con rồng trông giống như một con chim có bốn cánh và tấn công bằng những chiếc lông vũ giống như lưỡi dao.', '0'),
(10145, 'Voldemort', 'Rồng', 'Địa', 'Không có', 5, 1600, 1400, 'N', 0, 3, 'fdl', 'Một con rồng yếu ớt không thể bay nhưng đòn tấn công của nó vẫn rất mạnh.', '0'),
(10146, 'Rồng quỷ', 'Rồng', 'Ám', 'Không có', 4, 1500, 1200, 'R', 0, 3, 'eml', 'Một con rồng hung ác. Thở ra lửa ác làm người trở nên ác độc.', '0'),
(10147, 'Rồng thỏ', 'Rồng', 'Quang', 'Không có', 8, 2950, 2900, 'UR', 0, 3, 'tl', 'Một loài rồng đột biến sống ở vùng tuyết. Đôi tai khổng lồ của nó có thể phân biệt được âm thanh cách xa hàng nghìn mét - đồng thời kết hợp với sức bật nhảy đáng kinh ngạc của nó - con mồi mà nó nhắm đến không còn nơi nào để trốn thoát.', '0'),
(10148, 'Rồng sao băng', 'Rồng', 'Địa', 'Không có', 6, 1800, 2000, 'R', 0, 3, 'lxzl', 'Một con rồng sao băng rơi xuống Trái đất từ ​​nơi tận cùng của vũ trụ.', '0'),
(10149, 'Rồng khiên một mắt', 'Rồng', 'Phong', 'Không có', 3, 700, 1300, 'R', 0, 3, 'dydl', 'Tấm khiên trên người không chỉ bảo vệ cơ thể mà còn có thể dùng để tấn công.', '0'),
(10150, 'Shenlong·Rồng ngày tận thế', 'Rồng', 'Quang', 'Không có', 4, 1500, 1000, 'R', 0, 3, 'slmrl', 'Một con rồng huyền thoại được đồn đại là sứ giả của Chúa. Người ta nói khi nó nổi giận thì thế giới sẽ chìm xuống biển.', '0'),
(10151, 'Vua rồng bóng tối', 'Rồng', 'Ám', 'Không có', 4, 1500, 800, 'R', 0, 3, 'ahzlw', 'Những con rồng sống trong bóng tối sâu thẳm đã sống trong bóng tối một thời gian dài. Tầm nhìn không tốt lắm.', '0'),
(10152, 'Vua rồng đen của rừng xanh', 'Rồng', 'Địa', 'Không có', 6, 2100, 1800, 'R', 0, 3, 'mldhlw', 'Vua rồng bóng tối sống sâu trong rừng rậm. Những kẻ kêu cót két chỉ biết ăn cây.', '0'),
(10153, 'rồng hiệp sĩ độc ác', 'Rồng', 'Ám', 'Không có', 7, 2350, 2400, 'R', 0, 3, 'xeqsl', 'Một con Quái Thú là hiện thân của một con rồng trú ngụ trong trái tim của một hiệp sĩ độc ác.', '0'),
(10154, 'Rồng đuôi điện', 'Rồng', 'Quang', 'Không có', 6, 2500, 1000, 'UR', 0, 3, 'dqwl', 'Trên bầu trời luôn có những con rồng vướng điện. Nó đã tồn tại từ thời cổ đại và vẫn còn nhiều điều bí ẩn về hệ sinh thái của nó - nhưng việc đánh bắt bị cấm do các quy tắc cổ xưa.', '0'),
(10155, 'Triceratops', 'Rồng', 'Ám', 'Không có', 8, 2850, 2350, 'SR', 0, 3, 'sjml', 'Một con rồng quỷ có đặc điểm là ba chiếc sừng mọc ra từ đầu.', '0'),
(10156, 'Ác Long', 'Rồng', 'Phong', 'Không có', 3, 900, 900, 'N', 0, 3, 'mtxl', 'Một con rồng có hai đầu. Dùng hai miệng để đè bẹp kẻ thù.', '0'),
(10157, 'Rồng ngọc lục bảo', 'Rồng', 'Phong', 'Không có', 6, 2400, 1400, 'UR', 0, 3, 'lbsl', 'Con rồng ăn ngọc lục bảo. Vô số người đã bị vẻ đẹp của nó thu hút và mất mạng.', '0'),
(10158, 'Rồng ẩn trong hang', 'Rồng', 'Phong', 'Không có', 4, 1300, 2000, 'UR', 0, 3, 'dxdql', 'Con rồng ẩn nấp trong hang động. Bình thường rất ngoan ngoãn nhưng một khi tức giận có thể rất đáng sợ. Truyền thuyết kể rằng nó đang bảo vệ khối tài sản khổng lồ.', '0'),
(10159, 'Rồng bảo vệ Địa Tộc ngục', 'Rồng', 'Thủy', 'Không có', 1, 100, 2000, 'UR', 0, 3, 'yyhwl', 'Một chiến binh bảo vệ Hỏa ngục có thể điều khiển lửa một cách dễ dàng. Tạo một lá chắn nóng bỏng để phản ánh các cuộc tấn công của kẻ thù.', '0'),
(10160, 'Rồng Sapphire', 'Rồng', 'Phong', 'Không có', 4, 1900, 1600, 'UR', 0, 3, 'lbsl', 'Toàn thân được bao phủ bởi ngọc bích - một con rồng vô cùng đẹp mắt. Mặc dù tôi không thích sự cạnh tranh. Nhưng nó có sức tấn công rất cao.', '0'),
(10161, 'Rồng đá thon dài', 'Rồng', 'Ám', 'Không có', 6, 0, 2400, 'SR', 0, 3, 'lcsl', 'Một con rồng có vảy phát ra ánh sáng đẹp độc đáo được gọi là quầng labradorite. Ánh sáng chói lóa do vảy tạo ra có sức mạnh dẫn dắt tâm hồn người xem và giải phóng cảm xúc bên trong của họ.', '0'),
(10162, 'rắn biển thiên hà', 'Rồng', 'Quang', 'Không có', 2, 1000, 0, 'N', 0, 3, 'yhhs', 'Một con rồng được cho là xuất hiện vào lúc hoàng hôn. Nó có tên như vậy vì vẻ ngoài bí ẩn giống như đang bơi trong biển sao khi bay. Mặc dù người ta nói rằng chỉ có một số ít người chứng kiến ​​sự xuất hiện của nó nhưng người ta nói rằng những ai May mắn chứng kiến ​​được nó sẽ có được sức mạnh mới.', '0'),
(10163, 'Rồng Alexandrite', 'Rồng', 'Quang', 'Không có', 4, 2000, 100, 'UR', 0, 3, 'zcyl', 'Một con rồng quý hiếm có vảy alexandrite. Những chiếc vảy tuyệt đẹp Ma Phápng tên vị hoàng đế cổ đại và được coi là biểu tượng của sự huyền bí.', '0'),
(10164, 'Thằn lằn bay bảo vệ thành phố', 'Rồng', 'Phong', 'Không có', 4, 1400, 1200, 'N', 0, 3, 'scdyl', 'Con rồng canh giữ ngôi làng nhanh chóng từ trên trời lao xuống tấn công kẻ thù.', '0'),
(10165, 'Con dấu thần thánh của rồng', 'Rồng', 'Quang', 'Hieratic', 8, 0, 0, 'N', 0, 3, 'slzsky', 'Một thánh tích thiêng liêng Ma Phápng một hình khắc bí ẩn. Truyền thuyết kể rằng đó là vật Phong Tộc ấn sức mạnh của một con rồng có sức mạnh thần thánh. Dưới ánh nắng vàng - sau một thời gian dài nó được gọi là đá mặt trời bởi sự linh thiêng của nó.', '0'),
(10166, 'Phù Thủy Tộc của Dragon Core', 'Rồng', 'Ám', 'Không có', 8, 2300, 3000, 'UR', 0, 3, 'lhdzlz', 'Cô ấy đã săn rồng trong một thời gian dài và bị máu rồng bắn tung tóe nên đã thu được một nữ chiến binh có sức mạnh phi thường. Bởi vì linh hồn của anh ta bị vấy bẩn bởi sự oán giận của con rồng mà anh ta đã giết - cuối cùng anh ta đã biến thành lõi rồng độc ác gieo rắc bệnh dịch.', '|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(10167, 'Máy photocopy', 'Chiến Sĩ', 'Địa', 'Không có', 2, 600, 500, 'N', 0, 3, 'fyz', 'Một chiến binh biến hình thành nhiều kẻ thù khác nhau để đánh lừa chúng chiến đấu.', '0'),
(10168, 'hibiki', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1450, 1000, 'N', 0, 3, 'xn', 'Tạo ra tiếng ồn làm gián đoạn thính giác và khiến đối phương không thể di chuyển.', '0'),
(10169, 'đá', 'Chiến Sĩ', 'Hỏa', 'Không có', 3, 800, 1200, 'N', 0, 3, 'b', 'Một chiến binh có toàn bộ cơ thể được làm bằng băng. Đóng băng mọi thứ tiếp xúc với nó.', '0'),
(10170, 'Chiến binh áo giáp·Diệt Ma Pháp', 'Chiến Sĩ', 'Địa', 'Không có', 5, 1500, 1700, 'N', 0, 3, 'kwzzg', 'Anh ta thích chiến đấu một chọi một và có thể nắm bắt cơ hội trong giây lát để phát động phản công.', '0'),
(10171, 'Doron', 'Chiến Sĩ', 'Địa', 'Không có', 2, 900, 500, 'N', 0, 3, 'dl', 'Hãy cẩn thận với những con Quái Thú bị bao vây bởi các bản sao!', '0'),
(10172, 'cô gái âm thanh', 'Chiến Sĩ', 'Địa', 'Không có', 3, 1200, 900, 'N', 0, 3, 'yn', 'Một cô gái giỏi điều khiển âm thanh. Cô có thể biến những nốt nhạc thành những chiếc liềm để tấn công kẻ thù.', '0'),
(10173, 'Sứ giả mặt trăng', 'Chiến Sĩ', 'Quang', 'Không có', 4, 1100, 1000, 'N', 0, 3, 'yzsz', 'Một chiến binh phục vụ Nữ thần Mặt trăng. Tấn công bằng cờ vây hình lưỡi liềm!', '0'),
(10174, 'kẻ rình rập cái chết', 'Chiến Sĩ', 'Ám', 'Không có', 3, 900, 800, 'N', 0, 3, 'swqxz', 'Một chiến binh bọ cạp di chuyển nhanh chóng - bắt đối phương bằng càng và có nọc độc.', '0'),
(10175, 'Đạo giáo đeo mặt nạ', 'Chiến Sĩ', 'Ám', 'Không có', 2, 500, 700, 'N', 0, 3, 'jmdh', 'Một chiến binh nhảy múa trong vũ điệu chết chóc trong khi dùng lưỡi hái chém kẻ thù của mình.', '0'),
(10176, 'Áo giáp cứng', 'Chiến Sĩ', 'Địa', 'Không có', 3, 300, 1200, 'N', 0, 3, 'jykj', 'Áo giáp của linh hồn và cơ thể cứng rắn được trang bị cho chiến binh.', '0'),
(10177, 'Chiến binh đuôi kiếm bọc thép', 'Chiến Sĩ', 'Địa', 'Không có', 3, 700, 1300, 'R', 0, 3, 'kjjwzs', 'Một chiến binh kỳ lạ với cái đuôi giống thanh kiếm. Thực hiện ba đòn tấn công liên tiếp bằng cả tay và đuôi.', '0'),
(10178, 'thanh kiếm Phép Thuật bị nguyền rủa', 'Chiến Sĩ', 'Ám', 'Không có', 4, 1400, 800, 'N', 0, 3, 'bzzdmj', 'Người ta nói rằng những ai vượt qua được lời nguyền đặt lên mình sẽ có được sức mạnh từ nó.', '0'),
(10179, 'trứng Quái Thú', 'Chiến Sĩ', 'Địa', 'Không có', 3, 600, 900, 'N', 0, 3, 'gsd', 'Chiến binh bí ẩn bảo vệ toàn bộ cơ thể mình bằng vỏ trứng tấn công bằng vỏ bay.', '0'),
(10180, 'búp bê ăn thịt người', 'Chiến Sĩ', 'Địa', 'Không có', 3, 1200, 900, 'N', 0, 3, 'srwo', 'Nó trông giống như một con búp bê giẻ rách dễ thương và sử dụng cái miệng có khóa kéo để che chắn kẻ thù và tấn công chúng.', '0'),
(10181, 'Vận động viên trượt ván lưỡi', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1400, 1500, 'R', 0, 3, 'lrhbz', 'Vũ công trên băng - chiến binh tuyệt đẹp. Với chiêu thức đặc biệt - Axel Slice - nó tấn công Quái Thú địch một cách ngoạn mục.', '0'),
(10182, 'anh hùng đài phát thanh', 'Chiến Sĩ', 'Địa', 'Không có', 3, 1250, 700, 'R', 0, 3, 'dbyx', 'Một chiến binh bối rối đến đây từ một thế giới khác.', '0'),
(10183, 'người đẹp bị chặt đầu', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1600, 800, 'R', 0, 3, 'zsdmn', 'Đằng sau khuôn mặt xinh đẹp ấy là một người phụ nữ đã từng dùng dao chặt đầu nhiều người.', '0'),
(10184, 'Kiếm sĩ tàng hình trả thù', 'Chiến Sĩ', 'Ám', 'Không có', 6, 2000, 1600, 'R', 0, 3, 'fcqxjs', 'Một con Quái Thú chứa đựng sự oán giận của những đồng đội bị sát hại.', '0'),
(10185, 'Lá chắn thiên niên kỷ', 'Chiến Sĩ', 'Địa', 'Không có', 5, 0, 3000, 'UR', 0, 3, 'qnd', 'Nó được cho là chiếc khiên huyền thoại được truyền lại từ hoàng gia Ai Cập cổ đại. Có tin đồn rằng nó có thể chống lại bất kể đòn tấn công mạnh đến đâu.', '0'),
(10186, 'Người giữ ngai vàng', 'Chiến Sĩ', 'Địa', 'Không có', 4, 800, 1500, 'R', 0, 3, 'wzshz', 'Công chúa bảo vệ ngai vàng khỏi kẻ thù nước ngoài khi nhà vua đi vắng. Phòng thủ cao.', '0'),
(10187, 'Bộ xương máu', 'Chiến Sĩ', 'Hỏa', 'Không có', 4, 1600, 900, 'R', 0, 3, 'xhgh', 'Những con tàu cướp biển với những bộ xương màu đỏ trên mũi tàu xuất hiện một cách kỳ quái ở mọi vùng biển - tấn công các tàu chở khách và tàu chở hàng.', '0'),
(10188, 'Artimit', 'Chiến Sĩ', 'Địa', 'Không có', 3, 700, 1000, 'N', 0, 3, 'atmt', 'Một chiến binh chiến đấu bằng tay không mà không sử dụng bất kỳ loại vũ khí nào.', '0'),
(10189, 'Chiến binh của vương quốc quỷ bóng tối·Thanh kiếm bóng tối', 'Chiến Sĩ', 'Ám', 'Không có', 4, 1800, 1500, 'UR', 0, 3, 'ahzj', 'Một chiến binh đến từ Vương quốc Quỷ bóng tối - người được cho là có thể điều khiển rồng. Sức mạnh của đòn tấn công chém mà thế lực tà ác sử dụng thật đáng kinh ngạc.', '0'),
(10190, 'satan', 'Pháp Sư', 'Ám', 'Không có', 2, 700, 600, 'N', 0, 3, 'stn', 'Nguyền rủa kẻ thù. Một Phù Thủy có thể làm bất động mọi người.', '0'),
(10191, 'Quái Thú bão', 'Pháp Sư', 'Phong', 'Không có', 2, 900, 200, 'N', 0, 3, 'jfg', 'Một cơn lốc xoáy ở nơi hoang dã. Chém đối phương bằng lưỡi kiếm gió.', '0'),
(10192, 'người tung hứng', 'Pháp Sư', 'Quang', 'Không có', 3, 600, 900, 'N', 0, 3, 'xfs', 'Sử dụng Phép Thuật như Phép Thuật để đánh bại đối phương. Nó cũng sẽ thả chim bồ câu để tấn công.', '0'),
(10193, 'năng lượng thần thánh', 'Pháp Sư', 'Quang', 'Không có', 2, 600, 800, 'N', 0, 3, 'ssnl', 'Dù run rẩy nhưng nó được bảo vệ bởi sức mạnh của Chúa Thánh Thần.', '0'),
(10194, 'Linh hồn của đá', 'Pháp Sư', 'Địa', 'Không có', 5, 1650, 1900, 'N', 0, 3, 'yszjl', 'Một tinh thần đá trông giống như một bánh xe ngón tay cái. Cả tấn công và phòng thủ đều rất mạnh.', '0'),
(10195, 'nữ hoàng của vũ trụ', 'Pháp Sư', 'Ám', 'Không có', 8, 2900, 2450, 'UR', 0, 3, 'yznw', 'Nữ hoàng cai trị tất cả các hành tinh tồn tại trong vũ trụ.', '0'),
(10196, 'yêu tinh sách', 'Pháp Sư', 'Ám', 'Không có', 2, 650, 500, 'N', 0, 3, 'szjl', 'Phù Thủy tạo hình cuốn sách. Có tất cả các loại Phép Thuật được viết về nó.', '0'),
(10197, 'Âm dương sư · Đạo', 'Pháp Sư', 'Địa', 'Không có', 3, 1200, 900, 'N', 0, 3, 'yysd', 'Một Phù Thủy ăn mòn sức mạnh âm dương và tạo ra sức mạnh tà ác.', '0'),
(10198, 'Bậc thầy Phong Tộc ấn·Mingqing', 'Pháp Sư', 'Ám', 'Không có', 3, 1100, 900, 'N', 0, 3, 'fysmq', 'Một số nhân vật có thể sử dụng Phép Thuật Phong Tộc ấn. Nguồn gốc của nó vẫn còn là một bí ẩn.', '0'),
(10199, 'Phù Thủy mặt trăng', 'Pháp Sư', 'Quang', 'Không có', 5, 1200, 1700, 'N', 0, 3, 'yzmfs', 'Phù Thủy sống trên mặt trăng. Sử dụng sức mạnh Phép Thuật của mặt trăng để khiến đối phương bối rối.', '0'),
(10200, 'sư tử phù Thủy Tộc', 'Pháp Sư', 'Địa', 'Không có', 5, 1350, 1200, 'N', 0, 3, 'sznw', 'Một Phù Thủy mặc áo choàng đen. Hình dạng thật của nó là một con sư tử chỉ biết nói.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10201, 'Người theo dõi bóng tối', 'Pháp Sư', 'Ám', 'Không có', 2, 700, 500, 'N', 0, 3, 'hascz', 'Một Phù Thủy tôn thờ bóng tối. Kêu gọi trên tay Phép Thuật kéo kẻ thù vào bóng tối.', '0'),
(10202, 'Phù Thủy Tộc tử thần', 'Pháp Sư', 'Ám', 'Không có', 4, 1450, 1200, 'N', 0, 3, 'swws', 'Một Phù Thủy giỏi Phép Thuật tử thần đã lập khế ước với bóng tối.', '0'),
(10203, 'Món quà của nàng tiên', 'Pháp Sư', 'Quang', 'Không có', 4, 1400, 1000, 'N', 0, 3, 'yjdzl', 'Trong khi bay - nó lan truyền Phép Thuật khiến mọi người đều vui vẻ.', '0'),
(10204, 'Quý ông huyền diệu·J', 'Pháp Sư', 'Ám', 'Không có', 4, 1500, 1600, 'R', 0, 3, 'mdssj', 'Ăn mặc kỳ lạ và làm những điều xấu và giúp đỡ mọi người một cách thất thường.', '0'),
(10205, 'cô gái ánh trăng', 'Pháp Sư', 'Quang', 'Không có', 4, 1500, 1300, 'R', 0, 3, 'ygsn', 'Một Phù Thủy được mặt trăng ban phước. Phép Thuật bí ẩn có thể khiến con người nhìn thấy ảo giác.', '0'),
(10206, 'Kiếm sĩ Phép Thuật Terrance', 'Pháp Sư', 'Địa', 'Không có', 6, 2600, 200, 'UR', 0, 3, 'mfjstls', 'Một Phù Thủy rất mạnh mẽ. Có vẻ như tôi vừa trở về từ một chuyến du hành đến một chiều không gian khác.', '0'),
(10207, 'Thiên Nhãn Giáo Thần', 'Pháp Sư', 'Ám', 'Không có', 1, 0, 0, 'N', 0, 3, 'qyxjs', 'Một vị thần độc ác có thể điều khiển trái tim con người. Hàng ngàn con mắt tà ác của hắn có thể nhìn thấu trái tim tiêu cực của mọi người và không ngừng củng cố họ.', '0'),
(10208, 'Hiệp sĩ Phép Thuật đen', 'Chiến Sĩ', 'Ám', 'Không có', 7, 2500, 2100, 'SR', 0, 3, 'hmsqs', 'Một Quái Thú được triệu hồi khi <Phù Thủy Áo Đen> được trao <Danh hiệu Hiệp sĩ>.', '|Mô tả|\\nLá bài này phải được triệu hồi bằng cách sử dụng <Danh hiệu Hiệp sĩ>. Việc triệu hồi nó có thể ngẫu nhiên hủy một lá bài trên sân đối phương.'),
(10209, 'Nhà hiền triết vĩ đại trong màu đen', 'Pháp Sư', 'Ám', 'Không có', 9, 2800, 3200, 'N', 0, 3, 'hydxz', 'Khi đồng xu <Time Magician> dương - <Dark Magician> trên sân có thể tiến hóa thành hình dạng tối thượng.', '0'),
(10210, 'Hiệp sĩ Ma Pháp', 'Chiến Sĩ', 'Quang', 'Không có', 8, 2800, 2000, 'UR', 0, 3, 'hyzqs', '<Hiệp sĩ ngọn lửa đen> Vượt qua bóng tối và trải nghiệm lễ rửa tội bằng ánh sáng để đạt đến hình dạng tối thượng.', '|Kết hợp thông thường|\\nNhà khoa học Phép Thuật xuất hiện và triệu hồi Hiệp sĩ ngọn lửa đen. Hiệp sĩ Ngọn lửa Đen tấn công Quái Thú của đối phương với 2200 đòn tấn công trở lên. Sau khi bị tiêu diệt - Hiệp sĩ bóng Ma Pháp được triệu tập để loại bỏ nó.'),
(10211, 'Kiếm sĩ cởi trần Kea Freed', 'Chiến Sĩ', 'Quang', 'Không có', 7, 2600, 2200, 'UR', 0, 3, 'cbjsjyfld', 'Một Quái Thú được triệu hồi khi <Iron Knight Freed> sử dụng <Restraint Release>.', '0'),
(10212, 'rồng mắt xanh', 'Rồng', 'Quang', 'Mắt Xanh', 10, 3000, 2500, 'UR', 0, 3, 'qygl', 'Khi <Blue Eyes UltiMa Phápte Dragon> bị loại bỏ khỏi sân đấu - nó sẽ xuất hiện trở lại ở dạng này.', '|Mô tả|\\nMột trong những Quái Thú mạnh nhất trong trò chơi - nó có 3 lá chắn miễn phí và miễn nhiễm với mọi hiệu ứng bẫy và Phép Thuật của Quái Thú.'),
(10213, 'Ba chị em Harpy', 'Chim Thú', 'Phong', 'Harpie', 6, 1950, 2100, 'SR', 0, 3, 'yssjm', 'Một con Quái Thú được triệu hồi bởi Phép Thuật <Bản sao tuyệt đẹp>.', '0'),
(10214, 'Phù Thủy đen hỗn loạn', 'Pháp Sư', 'Ám', 'Không có', 8, 2800, 2600, 'UR', 0, 3, 'hdzhmd', 'Một trong ba người lính ngự lâm của Phép Thuật đen.', '0'),
(10215, 'bướm đêm lớn', 'Côn Trùng', 'Địa', 'Không có', 8, 2600, 2500, 'UR', 0, 3, 'dfe', '<Baby Larva> là Quái Thú biến thành sau 4 lượt.', '0'),
(10216, 'Con bướm khổng lồ cuối cùng', 'Côn Trùng', 'Địa', 'Không có', 8, 3500, 3000, 'UR', 0, 3, 'jjdfe', '<Big Moth> Quái Thú sẽ trở thành Quái Thú sau 4 lượt.', '0'),
(10218, 'Hiệp sĩ bóng đêm Gaia xứ Gale', 'Chiến Sĩ', 'Địa', 'Kỵ Sĩ Gaia', 7, 2300, 2100, 'UR', 0, 3, 'jfzahqsgy', 'Một hiệp sĩ cưỡi ngựa nhanh như chớp. Hãy coi chừng các cuộc tấn công lung tung.', '|Mô tả|\\nMột trong những lá bài cốt lõi của Bộ Bài tấn công nhanh - nó có thể được triệu hồi đặc biệt khi tất cả các lá bài khác trong tay đã được sử dụng hết.'),
(10219, 'Côn trùng vảy thương', 'Rồng', 'Phong', 'Không có', 4, 1800, 1200, 'UR', 0, 3, 'cqlc', 'Một chiến binh rồng cầm một ngọn giáo khổng lồ.', '|Mô tả|\\nXuyên thủng phòng thủ là một kỹ năng rất mạnh mẽ. Nó có thể tiêu diệt Quái Thú trong trạng thái phòng thủ và cũng có thể gây tổn hại đến máu của đối phương.'),
(10220, 'người cầm giáo', 'Rồng', 'Ám', 'Không có', 4, 1500, 1800, 'UR', 0, 3, 'qblr', 'Những người bảo vệ trung thành xung quanh Vua Rồng có đôi cánh rất lớn.', '|Mô tả|\\nXuyên thủng phòng thủ là một kỹ năng rất mạnh mẽ. Nó có thể tiêu diệt Quái Thú trong trạng thái phòng thủ và cũng có thể gây tổn hại đến máu của đối phương.'),
(10221, 'dẫn xuất cừu', 'Thú', 'Địa', 'Không có', 1, 0, 0, 'N', 0, 3, 'zyysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10222, 'Kiếm sĩ lửa', 'Hỏa Tộc', 'Thủy', 'Không có', 4, 1700, 1100, 'SR', 0, 3, 'yzjh', 'Truyền thuyết kể rằng kiếm sĩ không May rơi vào núi lửa và có được khả năng phát ra lửa.', '0'),
(10223, 'Vua Thần Cây Xanh', 'Thực Vật', 'Địa', 'Không có', 4, 500, 1600, 'R', 0, 3, 'lszlw', 'Một vị vua trẻ sống ở một nơi có cây xanh bao quanh và cai trị khu rừng.', '0'),
(10225, 'Thánh hiệp sĩ Ishzak', 'Chiến Sĩ', 'Quang', 'Không có', 6, 2300, 1800, 'UR', 0, 3, 'sdqsyszk', 'Một chiến binh mặc áo giáp trắng và cầm một thanh kiếm khổng lồ.', '|Mô tả|\\n<Loại trừ> là một trong những kỹ năng mạnh nhất của Quái Thú trong trò chơi. Quái Thú bị loại trừ không thể vào Nghĩa Địa - không thể kích hoạt các kỹ năng đi vào Nghĩa Địa và không thể hồi sinh từ Nghĩa Địa.'),
(10226, 'Warcraft đẫm máu', 'Chiến Sĩ Thú', 'Ám', 'Không có', 4, 1900, 1200, 'UR', 0, 3, 'xxmsr', 'Những người Warcraft đều kiêu ngạo làm tất cả những điều xấu - và chiếc rìu trong tay họ nhuốm máu.', '|Mô tả|\\nNhân vật Seto Kaiba nâng cấp lên cấp 60 để nhận thưởng Quái Thú rất mạnh.'),
(10227, 'Nhập quỷ · Bloodstone', 'Nham Thạch', 'Ám', 'Linh Hồn Nhập', 4, 1950, 650, 'UR', 0, 3, 'rmgxs', 'Không tìm kiếm điều gì khác - sự kết thúc - sự hủy diệt - sự hủy diệt - sự thăng hoa của những ý nghĩ xấu xa - sự xâm lược của Ma Pháp quỷ - sự sinh ra của các linh hồn - ác và ác - trong sáng và thuần khiết.', '|Mô tả|\\nNhân vật Jonouchi Katsuya nâng cấp lên cấp 60 để nhận thưởng Quái Thú rất mạnh.'),
(10228, 'Brachiosaurus đen tối', 'Khủng Long', 'Địa', 'Không có', 4, 1800, 1100, 'UR', 0, 1, 'ahwl', 'Cách nhận được: |Phần thưởng nạp tiền tích lũy|.', '|Mô tả|\\nQuái Thú phần thưởng nhận được ở cấp VIP 5 có thể đối phó với hầu hết Quái Thú có sức tấn công cao hơn khả năng phòng thủ của chúng.'),
(10229, 'bảo vệ ham muốn', 'Chiến Sĩ', 'Thủy', 'Không có', 4, 1500, 1800, 'UR', 0, 3, 'qysw', 'Người bảo vệ sinh ra trong chai dục vọng có thể cảm nhận được vị trí của cái chai dù nó ở xa đến đâu.', '0'),
(10230, 'Vực thẳm rạng rỡ', 'Thiên Thần', 'Quang', 'Không có', 4, 1600, 1800, 'SR', 0, 3, 'ghsy', 'Một con Quái Thú có cả sức mạnh ánh sáng và bóng tối.', '0'),
(10231, 'Gió Thần', 'Thiên Thần', 'Phong', 'Không có', 3, 0, 1800, 'UR', 0, 3, 'wfzjl', 'Linh hồn trong gió rất tốt bụng và người ta nói rằng ai nhìn thấy cô ấy sẽ hạnh phúc.', '0'),
(10232, 'Zorga', 'Thiên Thần', 'Địa', 'Không có', 4, 1700, 1200, 'UR', 0, 3, 'zej', 'Một thiên thần sẵn sàng hiến tế bản thân mình.', '0'),
(10233, 'Máy dệt cánh', 'Thiên Thần', 'Quang', 'Không có', 7, 2750, 2400, 'UR', 0, 3, 'zyz', 'Seraphim kiểm soát tự do và hy vọng của con người.', '|Kết hợp thông thường|\\nThần thánh ánh sáng + Cấu trúc thần thánh + Dệt cánh'),
(10234, 'Hiệp sĩ bầu trời Perseus', 'Thiên Thần', 'Quang', 'Perseus', 5, 1900, 1400, 'UR', 0, 3, 'tkqspexs', 'Anh đã được trao tặng danh hiệu Sky Knight vinh Quang Tộc và tin vào Holy Light.', '|Mô tả|\\nSky Perseus là một trong những Quái Thú hiến tế đơn lẻ hữu ích nhất. Kỹ năng xuyên phá phòng thủ của nó cho phép nó rút thêm bài cho mỗi lần tấn công thành công.'),
(10235, 'con mắt của nữ thần tâm trí', 'Thiên Thần', 'Quang', 'Không có', 4, 1200, 1000, 'UR', 0, 3, 'xyzns', 'Làm chủ bí mật của sự hợp nhất thông qua việc quan sát cẩn thận qua con mắt thứ ba trên đầu.', '|Mô tả|\\nLá bài cốt lõi của hệ thống dung hợp - nó có thể thay thế nguyên liệu Dung Hợp để Triệu Hồi Dung Hợp\\nNữ thần Mắt Trái tim không thể thay thế Quái Thú nếu không có tên lá bài cụ thể - chẳng hạn như Disruption'),
(10236, 'Macaron kẹo dẻo', 'Thiên Thần', 'Quang', 'Không có', 1, 200, 200, 'UR', 0, 3, 'mklmht', 'Hương thơm làm dịu tâm trí.', '0'),
(10237, 'Venus - Đại lý của sự sáng tạo', 'Thiên Thần', 'Quang', 'Không có', 3, 1600, 0, 'SR', 0, 3, 'czzdxzwns', 'Hiện thân của tình yêu và sắc đẹp.', '0'),
(10238, 'Yêu tinh của nồi dục vọng', 'Thiên Thần', 'Quang', 'Không có', 1, 100, 100, 'SR', 0, 3, 'qyzhdjl', 'Thần đèn sống trong lọ dục vọng được cho là sẽ Ma Phápng lại May mắn cho bất cứ ai nhìn thấy anh ta.', '0'),
(10239, 'thiên thần rạng rỡ', 'Thiên Thần', 'Quang', 'Không có', 4, 1400, 800, 'SR', 0, 3, 'ghts', 'Thiên thần bốn cánh khiêm tốn và mạnh mẽ - sẵn sàng giúp đỡ các thiên thần khác.', '0'),
(10240, 'đồng hồ cát dũng cảm', 'Thiên Thần', 'Quang', 'Không có', 4, 1100, 1200, 'SR', 0, 3, 'yqzsl', 'Đồng hồ cát tượng trưng cho lòng dũng cảm và thực hiện ý tưởng chiến đấu liều chết để sinh tồn.', '0'),
(10241, 'Argentina', 'Thiên Thần', 'Địa', 'Xúc Xắc Speedroid', 4, 1500, 1300, 'SR', 0, 3, 'ajd', 'Dường như trong cơ thể có một cánh cổng có thể hồi sinh các thiên thần - nhưng đôi khi nó không thành công.', '0'),
(10242, 'Bóng hạt dẻ cánh', 'Thiên Thần', 'Quang', 'Kuriboh', 1, 300, 200, 'SR', 0, 3, 'yylzq', 'Quả bóng hạt dẻ biến thành thiên thần.', '0'),
(10243, 'nữ hoàng bóng đêm', 'Thiên Thần', 'Quang', 'Không có', 7, 2100, 800, 'SR', 0, 3, 'byznw', 'Nữ hoàng bóng đêm đi theo con đường riêng của mình có khuôn mặt hoàn hảo.', '0'),
(10244, 'Hình ảnh rào cản nhấp nháy', 'Thiên Thần', 'Quang', 'Không có', 4, 1000, 1000, 'R', 0, 3, 'sgzjjx', 'Rào chắn thuộc tính ánh sáng có thể chặn sự xâm nhập của các nguyên tố khác.', '0'),
(10245, 'Hấp thụ Thiên Nhi', 'Thiên Thần', 'Quang', 'Không có', 4, 1300, 1000, 'R', 0, 3, 'xste', 'Thiên thần tuy vẫn còn ở tuổi thiếu niên nhưng lại sở hữu sức mạnh mạnh mẽ hơn những thiên thần cùng tuổi.', '0'),
(10246, 'Thiên thần sa ngã Mary', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 5, 1700, 1200, 'R', 0, 3, 'dtsml', 'Anh ấy vốn là một thiên thần giỏi chữa bệnh - nhưng anh ấy đã trở thành một thiên thần sa ngã trong một cuộc chiến giữa thiên giới.', '0'),
(10247, 'Quay lại thiên thần', 'Thiên Thần', 'Quang', 'Không có', 2, 800, 100, 'R', 0, 3, 'zsts', 'Khi có bạn đồng hành - bạn sẽ trở nên mạnh mẽ hơn.', '0'),
(10248, 'chiến binh jera', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1600, 1600, 'R', 0, 3, 'jldzs', 'Một chiến binh tìm kiếm vị trí của một thánh Địa Tộc để có được sức mạnh của một tổng lãnh thiên thần. Để thoát khỏi sự cÁm Tộc dỗ của tộc quỷ hung ác - anh đã chiến đấu một mình.', '0'),
(10249, 'hiệp sĩ hoàng gia', 'Thiên Thần', 'Quang', 'Không có', 3, 1300, 800, 'R', 0, 3, 'wjqs', 'Một cỗ máy chuyển động không ngừng trên chiến trường - điều khiến bất cứ ai sợ hãi là khả năng trẻ hóa hoàn toàn khi tiêu diệt kẻ thù.', '0'),
(10250, 'quả cầu thiêng liêng', 'Thiên Thần', 'Quang', 'Không có', 2, 500, 500, 'N', 0, 3, 'ssqt', 'Một tâm hồn thiên thần được bao bọc trong ánh sáng thiêng liêng. Người ta nói rằng những ai nhìn thấy vẻ ngoài xinh đẹp của nó đều có thể biến điều ước của mình thành hiện thực.', '0'),
(10251, 'dài', 'Thiên Thần', 'Quang', 'Không có', 1, 300, 100, 'N', 0, 3, 'yy', 'Một người vượt qua các thiên thần và không biết mình đang nghĩ gì. Một khi tức giận - hậu quả sẽ rất khủng khiếp.', '0'),
(10252, 'bộ điều khiển thời tiết', 'Thiên Thần', 'Quang', 'Không có', 2, 600, 400, 'N', 0, 3, 'qxkzy', 'Thời tiết có thể được thao túng một cách tự do. Thời tiết khó lường trên núi là do anh chàng này.', '0'),
(10253, 'những người yêu nhau hạnh phúc', 'Thiên Thần', 'Quang', 'Không có', 2, 800, 500, 'N', 0, 3, 'xflr', 'Một thiên thần nhỏ phát ra ánh sáng hình trái tim từ đầu để Ma Phápng lại hạnh phúc cho người yêu.', '0'),
(10254, 'Valkyrie', 'Thiên Thần', 'Quang', 'Không có', 5, 1800, 1700, 'N', 0, 3, 'nws', 'Thiên thần chiến đấu xuất hiện trong thần thoại sử dụng ngọn giáo trong tay để áp đặt sự trừng phạt thần thánh.', '0'),
(10255, 'Yêu tinh trứng có cánh', 'Thiên Thần', 'Quang', 'Không có', 3, 500, 1300, 'N', 0, 3, 'ydjl', 'Một thiên thần được bọc trong vỏ trứng. Sử dụng đôi cánh khổng lồ của nó để phòng thủ và tấn công.', '0'),
(10256, 'khác', 'Thiên Thần', 'Quang', 'Không có', 3, 750, 110, 'N', 0, 3, 'alsm', 'Nữ thần xinh đẹp bảo vệ mặt trăng. Sử dụng Moonlight Barrier để phòng thủ và tấn công.', '0'),
(10257, 'thiên thần tình bạn', 'Thiên Thần', 'Quang', 'Không có', 4, 1300, 1100, 'N', 0, 3, 'yyts', 'Ngay cả khi họ cãi nhau trong một cuộc đấu tay đôi - họ vẫn có thể làm hòa bằng cách thể hiện tình bạn.', '0'),
(10258, 'thiên thần nhỏ', 'Thiên Thần', 'Quang', 'Không có', 3, 600, 900, 'N', 0, 3, 'xts', 'Một thiên thần nhỏ dựa vào những chuyển động nhanh nhẹn để tránh các cuộc tấn công.', '0'),
(10259, 'Người giÁm Tộc hộ ElMa Pháp', 'Thiên Thần', 'Phong', 'Người Bảo Hộ', 3, 1300, 1200, 'UR', 0, 3, 'shzaem', 'Người bảo vệ dao găm bướm có thể Ám Tộc sát kẻ thù một cách chính xác.', '0'),
(10260, 'Nhà khoa học Phép Thuật', 'Pháp Sư', 'Ám', 'Không có', 1, 300, 300, 'UR', 0, 3, 'mdkxj', 'Một nhà khoa học điên thích nghiên cứu Quái Thú hợp nhất.', '|Mô tả|\\nMột trong những Quái Thú mạnh nhất để dọn sân\\n\\n|Các kết hợp phổ biến|\\nNhà khoa học Phép Thuật triệu hồi Hiệp sĩ ngọn lửa đen sau đó triệu tập Hiệp sĩ bóng Ma Pháp sau khi tự sát - điều này có thể loại bỏ nhiều Quái Thú mạnh mẽ\\nNhà khoa học Phép Thuật triệu tập Chim mặt trời đỏ để dọn sân sau đó hợp tác với Chim vòng tròn đối lưu trong Bộ Bài triệu hồi tổ én'),
(10261, 'Quái Thú nhãn cầu', 'Ác Ma', 'Ám', 'Không có', 1, 250, 350, 'R', 0, 3, 'yqg', 'Chúng xuất hiện theo nhóm và có ít sức tấn công.', '0'),
(10262, 'Ngày Greyfa', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1700, 1600, 'SR', 0, 3, 'dglf', 'Một chiến binh che giấu khả năng điều khiển rồng. Quá khứ của nó được bao quanh bởi bí ẩn.', '0'),
(10263, 'Công cụ truy đuổi flash', 'Thiên Thần', 'Quang', 'Không có', 3, 1600, 0, 'SR', 0, 3, 'sgzzfz', 'Sở hữu sức mạnh biến đổi không gian - anh ta có thể mở những cánh cổng đến các chiều không gian khác nhau.', '0'),
(10264, 'Cấu trúc thần thánh', 'Thiên Thần', 'Quang', 'Không có', 4, 1500, 0, 'SR', 0, 3, 'sgt', 'Rất thân thiện với các yếu tố nhẹ - nhưng vẫn có một số sai sót.', '0'),
(10265, 'Thiên thần sa ngã Edi Alaye', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 5, 2300, 2000, 'UR', 0, 3, 'dtsadaly', 'Thiên thần sa ngã bò ra khỏi mộ rất khó đối phó.', '0'),
(10266, 'Hiệp sĩ Gawain', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1900, 500, 'UR', 0, 1, 'sqsgw', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '|Mô tả|\\nPhần thưởng Quái Thú nhận được khi nhân vật Isis nâng cấp lên cấp 60 rất mạnh.'),
(10267, 'Chị của lòng thương xót', 'Thiên Thần', 'Quang', 'Không có', 4, 850, 2000, 'UR', 0, 3, 'dcdbxn', 'Một nữ tu có trái tim nhân hậu.', '0'),
(10268, 'Người bảo vệ Joan of Arc', 'Thiên Thần', 'Quang', 'Người Bảo Hộ', 7, 2800, 2000, 'UR', 0, 3, 'shzzd', 'Tổng lãnh thiên thần bảo vệ gia đình thiên thần.', '0'),
(10269, 'dẫn xuất nhân bản', 'Không có', 'Không có', 'Không có', 0, 0, 0, 'N', 0, 3, 'klysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10270, 'Rồng Trời Osiris', 'Thần Thú', 'Thần', 'Không có', 10, 0, 0, 'UR', 0, 1, 'axlsdtkl', 'Yugi Muto có được lá bài này sau khi chiến thắng trong trận chiến chống lại con rối của Malik Isudar - Sky Dragon quý tộc - một trong ba vị Thần Ảo.', '0'),
(10271, 'guildford', 'Chiến Sĩ', 'Quang', 'Không có', 8, 2800, 1400, 'UR', 0, 3, 'jefd', 'Những chiến binh giỏi sử dụng sức mạnh của tia sét thậm chí có thể tạo ra giông bão.', '|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(10272, 'Chim hồng hạc', 'Chim Thú', 'Thủy', 'Không có', 4, 1000, 800, 'SR', 0, 3, 'hyn', 'Toàn thân bị ngọn lửa thiêu đốt bao phủ - chỗ nào đi qua đều để lại vết cháy sém.', '0'),
(10273, 'nữ thần cố ý', 'Thiên Thần', 'Quang', 'Không có', 3, 950, 700, 'SR', 0, 3, 'rxdns', 'Tất cả phụ thuộc vào tâm trạng của bạn khi chiến đấu.', '0'),
(10274, 'Tu sĩ bão tố', 'Thiên Thần', 'Phong', 'Không có', 4, 1500, 1600, 'UR', 0, 3, 'bfxs', 'Bạn có thể đi qua cơn bão theo ý muốn.', '0'),
(10275, 'chim thiêng', 'Chim Thú', 'Phong', 'Không có', 4, 1500, 1100, 'R', 0, 3, 'sn', 'Một con chim có cái đuôi rất dài và ánh sáng thần thánh phát ra từ cơ thể nó.', '0'),
(10276, 'thợ săn bầu trời', 'Chim Thú', 'Phong', 'Không có', 4, 1550, 1200, 'R', 0, 3, 'tkls', 'Nó có một con dao giấu trong lông và từ trên trời lao xuống để tấn công.', '0'),
(10277, 'Người chim', 'Chim Thú', 'Phong', 'Không có', 4, 1800, 600, 'UR', 0, 3, 'nr', 'Người chim bay với tốc độ Mach 5. Ánh mắt của anh ta sắc bén hơn cả đại bàng.', '0'),
(10278, 'Thánh chim · Sếu', 'Chim Thú', 'Quang', 'Không có', 4, 1600, 400, 'UR', 0, 3, 'snxh', 'Có bộ lông trắng như tuyết tỏa ra hào Quang Tộc linh thiêng được cho là Ma Phápng lại May mắn.', '0'),
(10279, 'chim đối lưu', 'Chim Thú', 'Phong', 'Không có', 6, 2400, 2000, 'UR', 0, 3, 'dlqqn', 'Nó có thể phân tích chính xác các điều kiện luồng không khí để đưa ra phán đoán chính xác và tránh xa nguy hiểm.', '0'),
(10280, 'Chim có cánh cực Quang Tộc', 'Chim Thú', 'Hỏa', 'Không có', 4, 1200, 1600, 'SR', 0, 3, 'jgyn', 'Con chim chỉ có thể được nhìn thấy khi cực Quang Tộc xuất hiện và được cho là có khả năng du hành xuyên không gian.', '0'),
(10281, 'Cô gái Harpy Yi', 'Chim Thú', 'Phong', 'Harpie', 4, 1300, 1400, 'UR', 0, 3, 'ysnly', 'Một con thú Phép Thuật mọc lông vũ từ con người và thực hiện một điệu nhảy tuyệt đẹp để thực hiện một đòn tấn công nhanh.', '0'),
(10282, 'Harpy Shan', 'Chim Thú', 'Phong', 'Harpie', 4, 1300, 1400, 'SR', 0, 3, 'ysnls', 'Một con thú Phép Thuật mọc lông vũ từ con người và thực hiện một điệu nhảy tuyệt đẹp để thực hiện một đòn tấn công nhanh.', '0'),
(10284, 'Amazoness thổi kèn', 'Chiến Sĩ', 'Địa', 'Amazoness', 3, 800, 1500, 'SR', 0, 3, 'ymxcjb', 'Các trinh sát ở Amazoness rất giỏi ẩn náu.', '0'),
(10285, 'game bắn súng aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 4, 1400, 1000, 'SR', 0, 3, 'ymxss', 'Một chiến binh ở Amazoness chịu trách nhiệm tiêu diệt kẻ thù từ xa.', '0'),
(10286, 'Thần Gió Wendros', 'Chim Thú', 'Phong', 'Không có', 8, 2800, 2200, 'UR', 0, 3, 'wdls', 'Thần gió Wendros với đôi cánh đẹp lạ thường thường khiến người ta quên chụp ảnh.', '0'),
(10287, 'Nữ hoàng Harpy', 'Chim Thú', 'Phong', 'Harpie', 4, 1900, 1200, 'UR', 0, 3, 'ysnw', 'Nữ hoàng của loài Harpies - Ma Phápng trong mình dòng máu của cơn bão thiêng.', '|Mô tả|\\nPhần thưởng Quái Thú nhận được khi nhân vật Peacock Dance nâng cấp lên cấp 60 là rất mạnh.'),
(10288, 'Hoàng đế Trái đất GranMa Phápg', 'Nham Thạch', 'Địa', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'ddglmg', 'Vua đất có thể dễ dàng thay đổi cảnh quan.', '|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(10289, 'Thiên thần sa ngã Superbia', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 8, 2900, 2400, 'UR', 0, 3, 'dtssbby', 'Một thiên thần sa ngã mạnh mẽ có thể triệu hồi những người bạn đồng hành đã chết của mình.', '0'),
(10290, 'Anh hùng nguyên tố·Người có cánh', 'Chiến Sĩ', 'Phong', 'Anh Hùng Nguyên Tố', 3, 1000, 1000, 'R', 0, 3, 'ysyxyyx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10291, 'Anh hùng nguyên tố · Hot Girl', 'Chiến Sĩ', 'Thủy', 'Anh Hùng Nguyên Tố', 3, 1200, 800, 'R', 0, 3, 'ysyxbrnl', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10292, 'thiên thần sinh đôi', 'Thiên Thần', 'Quang', 'Không có', 4, 1700, 0, 'UR', 0, 3, 'ssts', 'Đôi thiên thần - kết nối với nhau.', '|Mô tả|\\nGần như bất khả chiến bại khi đối phương không có cách nào để gây tổn hại đến máu của chính mình. Điểm yếu của nó là sợ những Quái Thú có kỹ năng <Xuyên thủng phòng thủ> và lá bài có thể gây tổn hại đến sức khỏe của nó.'),
(10293, 'Người lính Titan đài tưởng niệm', 'Thần Thú', 'Thần', 'Không có', 10, 4000, 4000, 'UR', 0, 1, 'oblskjsb', 'Isis Isildar - một trong ba vị Thần Ảo của Titan God Weapon - đã đưa tấm lá bài này cho Seto Kaiba. Nó chỉ có thể nhận được bằng cách hiến tế đủ số lượng <Biểu tượng Chiến binh Khổng lồ> trong tàn tích của các vị thần.', '0'),
(10299, 'Phù Thủy hỗn loạn', 'Pháp Sư', 'Quang', 'Không có', 6, 2400, 1900, 'UR', 0, 3, 'hdmds', 'Một Phù Thủy sinh ra từ sự hỗn loạn có khả năng phân biệt tình hình chiến đấu.', '0'),
(10300, 'Người triệu hồi rồng xanh', 'Pháp Sư', 'Phong', 'Không có', 4, 1500, 600, 'UR', 0, 3, 'qlzhs', 'Là một trong Tứ Thánh Thú Triệu Hồi - anh ta có thể triệu hồi Rồng Xanh để chiến đấu vì mình.', '0'),
(10302, 'Máy đánh bạc AM·7', 'Máy Móc', 'Ám', 'Không có', 7, 2000, 2300, 'N', 0, 3, 'jzlhjamq', 'Người ta nói rằng khả năng của máy thay đổi tùy thuộc vào số lượng plug-in được thu thập.', '0'),
(10303, 'Máy tra tấn lưỡi đơn', 'Máy Móc', 'Ám', 'Không có', 6, 1750, 2000, 'N', 0, 3, 'dbrkwjx', 'Sử dụng lưỡi kiếm có cú xoay lớn để chia đôi đối phương! Thật là một cỗ máy tra tấn khủng khiếp!', '0'),
(10304, 'ảo tưởng sai lầm', 'Thần Thú', 'Thần', 'Không có', 6, 2500, 0, 'UR', 0, 1, 'xwhx', 'Một vị thần sinh ra từ ảo ảnh không thể phân biệt được hình dạng thật của mình.', '0'),
(10305, 'Mã thông báo ảo ảnh', 'Thần Thú', 'Thần', 'Không có', 1, 2500, 0, 'UR', 0, 3, 'hxysw', 'Bản sao vô tận.', '0'),
(10306, 'Con rối ảo ảnh', 'Thần Thú', 'Thần', 'Không có', 6, 2500, 0, 'UR', 0, 1, 'xwhxkl', 'Một con rối được tạo ra từ một tia tư tưởng tâm linh là một ảo ảnh sai lầm.', '0'),
(10307, 'lời tiên tri sai', 'Thần Thú', 'Thần', 'Không có', 6, 2500, 2000, 'UR', 0, 1, 'xwyy', 'Một vị thần sinh ra từ sự phù phiếm có sức mạnh tiên tri.', '0'),
(10308, 'Tinh thần nguyền rủa sai lầm', 'Thần Thú', 'Thần', 'Không có', 8, 2150, 2150, 'UR', 0, 1, 'xwzl', 'Một vị thần sinh ra từ sự phù phiếm - sở hữu sức mạnh của lời nguyền.', '0'),
(10309, 'Xáo trộn·Xanh', 'Thú', 'Quang', 'Ojama', 2, 0, 1000, 'N', 0, 3, 'rll', 'Một trong bộ ba quậy phá - dùng mọi thủ đoạn để gây rắc rối. Người ta nói rằng nếu ba người tập hợp lại với nhau thì sẽ có chuyện gì đó xảy ra.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10310, 'Rối loạn·Vàng', 'Thú', 'Quang', 'Ojama', 2, 0, 1000, 'N', 0, 3, 'rlh', 'Một trong bộ ba quậy phá - dùng mọi thủ đoạn để gây rắc rối. Người ta nói rằng nếu ba người tập hợp lại với nhau thì sẽ có chuyện gì đó xảy ra.', '0'),
(10311, 'Quấy rối·Đen', 'Thú', 'Quang', 'Ojama', 2, 0, 1000, 'N', 0, 3, 'rlh', 'Một trong bộ ba quậy phá - dùng mọi thủ đoạn để gây rắc rối. Người ta nói rằng nếu ba người tập hợp lại với nhau thì sẽ có chuyện gì đó xảy ra.', '0'),
(10312, 'Rối loạn · Đỏ', 'Thú', 'Quang', 'Ojama', 2, 0, 1000, 'UR', 0, 3, 'rlh', 'Một thành viên mới của bộ ba gây rối. Tại thời điểm này - nó đã trở thành một bộ tứ gây rối.', '|Mô tả|\\nSử dụng Disruption·Red để nhanh chóng mở rộng phạm vi và hiệu quả sẽ tốt hơn khi sử dụng với Bão Tam giác gián đoạn'),
(10313, 'Làm phiền màu xanh', 'Thú', 'Quang', 'Ojama', 2, 0, 1000, 'SR', 0, 3, 'rll', 'Một thành viên mới của bộ tứ gây rối. Tại thời điểm này - nó đã trở thành một nhóm năm người gây rối.', '|Mô tả|\\nThường xuyên sử dụng các đòn đánh tự sát để rút bài nhanh và hiệu quả sẽ tốt hơn khi sử dụng với Disruption Red'),
(10314, 'phá vỡ các token', 'Thú', 'Quang', 'Ojama', 2, 0, 1000, 'N', 0, 3, 'rlysw', 'Lá bài này có thể được sử dụng làm token.', '|Mô tả|\\nLá bài này có thể được sử dụng làm nguyên liệu Link'),
(10315, 'Bellinis thuộc hạ của Yandi', 'Hỏa Tộc', 'Thủy', 'Không có', 3, 800, 1000, 'UR', 0, 3, 'ydjcblns', 'Người hầu cận trung thành nhất của Hoàng đế Yan có thể hiến tế tất cả mọi thứ cho Hoàng đế Yan.', '|Mô tả|\\nHiệu ứng triệu hồi đặc biệt của Entei\'s Retainer có thể nhanh chóng triệu hồi Quái Thú cấp sao - khiến nó trở thành đối tác tốt của Entei Testaros\\nKỹ năng vứt bài trên tay rất mạnh khi kết hợp với Quái Thú từ Vương quốc bóng tối.'),
(10316, 'Entei Testaros', 'Hỏa Tộc', 'Thủy', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'ydtstls', 'Vị hoàng đế làm chủ được nguyên tố lửa có thể dễ dàng gây sát thương cho kẻ thù bằng lửa.', '|Mô tả|\\nKhi Entei được triệu tập bình thường - nó có thể khiến đối phương bỏ bài trên tay. Nó là một trong những lá bài cốt lõi của Phong Tộc cách cắt bài.'),
(10317, 'hạt dẻ ruy băng', 'Thiên Thần', 'Quang', 'Không có', 1, 300, 200, 'SR', 0, 3, 'ddlz', 'Những dải ruy băng đẹp rất tôn dáng và thường được dùng làm quà tỏ tình.', '|Mô tả|\\nKhi bị tiêu diệt: lá bài sẽ được trả về tay và hiệu ứng của <Flash Chaser> và <Ishzak> có thể bị bỏ qua.'),
(10318, 'Cổ tay trái của người bị Phong Tộc ấn', 'Pháp Sư', 'Ám', 'Phong Ấn Exodia', 1, 200, 300, 'UR', 0, 1, 'bfyzdzw', 'Khi kết hợp với <Cánh tay phải bị Phong Tộc ấn> - <Chân trái bị Phong Tộc ấn> - <Chân phải bị Phong Tộc ấn> và <Đầu bị Phong Tộc ấn> - bạn sẽ thắng trận đấu.', '|Mô tả|\\nThu thập 5 lá bài này trên tay bạn: <Cánh tay trái của người bị Phong Tộc ấn> - <Cánh tay phải của người bị Phong Tộc ấn> - <Chân trái của người bị Phong Tộc ấn> - <Chân phải của người bị Phong Tộc ấn> để trực tiếp giành chiến thắng trong trận chiến.'),
(10319, 'Cổ tay phải của người bị Phong Tộc ấn', 'Pháp Sư', 'Ám', 'Phong Ấn Exodia', 1, 200, 300, 'UR', 0, 1, 'bfyzdyw', 'Khi kết hợp với <Cánh tay trái bị Phong Tộc ấn> - <Chân trái bị Phong Tộc ấn> - <Chân phải bị Phong Tộc ấn> và <Đầu bị Phong Tộc ấn> - bạn sẽ thắng trận đấu.', '|Mô tả|\\nThu thập 5 lá bài này trên tay bạn: <Cánh tay trái của người bị Phong Tộc ấn> - <Cánh tay phải của người bị Phong Tộc ấn> - <Chân trái của người bị Phong Tộc ấn> - <Chân phải của người bị Phong Tộc ấn> để trực tiếp giành chiến thắng trong trận chiến.'),
(10320, 'bóng lăn', 'Nham Thạch', 'Địa', 'Không có', 3, 1350, 1600, 'SR', 0, 3, 'ggq', 'Nếu không nhìn kỹ - bạn sẽ không biết khi nào mình đang ở trạng thái tích cực.', '0'),
(10321, 'Xác sống của con quỷ trong mơ', 'Ác Ma', 'Ám', 'Không có', 4, 1300, 1800, 'SR', 0, 3, 'mydwl', 'Một con quỷ xâm nhập vào giấc mơ của một người đang ngủ và hút sinh lực của họ. Người bị Ám Tộc không thể tự mình thức dậy.', '0'),
(10322, 'gấu trúc giận dữ', 'Thú', 'Địa', 'Không có', 3, 800, 1600, 'UR', 0, 3, 'fndxm', 'Con gấu trúc thường rất ngoan ngoãn lại trở nên hung bạo không rõ lý do.', '|Kết hợp phổ biến|\\nBộ ba quậy phá + gấu trúc giận dữ'),
(10323, 'Magister đỏ sẫm', 'Pháp Sư', 'Ám', 'Không có', 6, 1700, 2200, 'UR', 0, 3, 'ahzmds', 'Truyền thuyết kể rằng Mặt Trăng Đỏ sẽ giáng xuống lục Địa Tộc vào ban đêm.', '|Mô tả|\\nSau khi hiệu ứng được kích hoạt thành công - nó tương đương với một con Quái Thú có 2300 đòn tấn công và 2200 phòng thủ\\nKỹ năng nhận thức Phép Thuật không chỉ có thể hạn chế việc sử dụng lá bài Phép Thuật của đối phương mà còn bổ sung khả năng phản Phép Thuật của chính mình bằng cách sử dụng lá bài Phép Thuật\\nBom Phép Thuật có thể tiêu diệt các lá bài trên tay của đối phương - mở rộng khoảng cách lá bài một cách hiệu quả\\n\\n|Kết hợp thông thường|\\nBiên giới bóng tối + Phù Thủy đỏ sẫm\\nPhù Thủy đỏ sẫm + Hồi sinh thần kỳ'),
(10324, 'Con chó ba đầu Photon', 'Thú', 'Quang', 'Photon', 3, 1300, 600, 'SR', 0, 3, 'gzstq', 'Nó có thể biến thành photon và di chuyển về phía sau của kẻ thù - làm gián đoạn quân tấn công bất ngờ của kẻ thù.', '|Mô tả|\\nKỹ năng của chó ba đầu photon chỉ có hiệu ứng trong một hiệp. Nếu sử dụng đúng cách - nó có thể tận dụng được lợi thế trên sân.'),
(10325, 'rồng Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 5, 2400, 0, 'UR', 0, 3, 'xxgl', 'Những con rồng có được dòng máu Ma Pháp cà rồng đã cải thiện khả năng kiểm soát cơ thể.', '|Mô tả|\\nViệc triệu hồi Rồng Ma Cà Rồng thông thường thành công sẽ có khả năng bổ sung lá bài khi vào Nghĩa Địa. Nó là một lá bài mạnh mẽ dành cho xác sống\\nNếu khả năng phòng thủ bằng 0 - nó có thể được lấy lại tốt hơn bởi Goblin Zombies - Black Forest Witch - v.v.'),
(10326, 'Công báo Warcraft tổng hợp', 'Ác Ma', 'Ám', 'Không có', 7, 0, 0, 'UR', 0, 3, 'hcmsjzt', 'Một con Quái Thú cực kỳ tàn ác - sau khi giết chết đối phương - nó sẽ nuốt chửng cơ thể của đối phương và dung hợp vào chính mình.', '|Mô tả|\\nKỹ năng của Gazette là lấy đi sức tấn công ban đầu của vật hiến tế.'),
(10327, 'Công chúa Ma Pháp · Công chúa bí ngô', 'Zombie', 'Ám', 'Không có', 3, 900, 1000, 'UR', 0, 3, 'nggz', 'Cô công chúa nhỏ mà Vua bí ngô yêu quý nhất lại rất tinh nghịch.', '|Mô tả|\\nCác kỹ năng của Công chúa bí ngô sẽ có hiệu lực nếu chúng bị tiêu diệt và đưa vào Nghĩa Địa. Bạn có thể sử dụng điều này để kiểm tra bẫy của đối phương\\nKỹ năng tái tạo Bí ngô có hiệu ứng hạn chế rất lớn đối với luồng tốc độ tấn công 1800.'),
(10328, 'Con búp bê bóng tối Nicolofia', 'Ác Ma', 'Ám', 'Không có', 8, 2200, 2800, 'UR', 0, 3, 'ahronklfy', 'Có tin đồn rằng anh ta là một con quỷ thích ôm búp bê - nhưng thực tế con búp bê đó chính là hình dạng thật của anh ta.', '|Mô tả|\\nQuái Thú mạnh nhất của Tộc Quỷ - ngoại hình tương đối dễ nhìn - giá trị phòng thủ siêu cao và khả năng kiểm soát mạnh mẽ sau khi bị tiêu diệt trong Nghĩa Địa khiến Tộc Quỷ trở thành một trong những chủng tộc khó đối phó nhất.'),
(10329, 'hồn Ma Pháp bạo lực', 'Ác Ma', 'Thủy', 'Không có', 4, 1700, 1100, 'SR', 0, 3, 'bg', 'Ma rất dễ nổi giận - khi nổi giận thì không phân biệt bạn và thù.', '|Mô tả|\\nMột kỹ năng đặc biệt nhắm vào máu của đối phương và kết hợp với một số lượng lớn Quái Thú có hiệu ứng quỷ - gây ra mối đe dọa rất cao đến tính mạng của đối phương.'),
(10330, 'bức tường Ma Pháp', 'Ác Ma', 'Ám', 'Không có', 4, 1000, 1850, 'UR', 0, 3, 'hyb', 'Bằng cách đọc được trí nhớ của đối phương - anh ta trở thành người được đối phương quan tâm và chơi đùa với cảm xúc của đối phương.', '|Mô tả|\\nNhững Quái Thú cấp thấp mạnh mẽ thuộc loại quỷ - những Quái Thú xuyên qua bức tường Ma Pháp cũng sẽ phải trả giá bằng cách trả lại lá bài về tay chúng.'),
(10331, 'Người giữ Nghĩa Địa', 'Ác Ma', 'Ám', 'Không có', 4, 0, 2000, 'UR', 0, 3, 'mcksz', 'Do nghĩa trang được chăm sóc lâu dài nên nơi đây nhuốm một bầu không khí chết chóc - thật đáng sợ.', '|Mô tả|\\nSự tồn tại của Graveyard Watcher là một hạn chế mạnh mẽ đối với Quái Thú Lời cuối cùng của đối phương - ngăn cản đối phương thực hiện các thói quen và dây chuyền.'),
(10332, 'Cơn ác mộng của Thebes', 'Ác Ma', 'Quang', 'Không có', 4, 1500, 500, 'SR', 0, 3, 'dbsdmy', 'Anh ta rõ ràng là một con quỷ nhưng lại sở hữu thuộc tính ánh sáng trái ngược. Các thuộc tính trái ngược nhau dẫn đến hiệu quả chiến đấu không ổn định.', '|Mô tả|\\nMột lá bài bổ sung cho Bộ Bài tấn công nhanh. Nó có hiệu ứng kỳ diệu khi được sử dụng trong những tình huống nhất định.'),
(10333, 'Bậc thầy bù nhìn của xác sống', 'Ác Ma', 'Ám', 'Không có', 6, 0, 0, 'UR', 0, 3, 'czsldkls', 'Thu thập và tinh luyện linh hồn xác sống thành những con rối ngoan ngoãn là niềm vui lớn nhất - nhưng bạn không quan tâm đến tiếng rên rỉ của linh hồn xác sống.', '|Mô tả|\\nTrả 2000 mạng để chiêu mộ hai Quái Thú loại quỷ từ Nghĩa Địa - việc thêm 3 Quái Thú vào sân cùng một lúc cũng sẽ khiến đối phương của bạn phải đau đầu vô cùng.'),
(10334, 'diều du kích', 'Ác Ma', 'Thủy', 'Không có', 4, 1600, 200, 'SR', 0, 3, 'yjfz', 'Những con quỷ lang thang trên không thường tấn công bất ngờ.', '|Mô tả|\\nMột kỹ năng đặc biệt nhắm vào máu của đối phương và kết hợp với một số lượng lớn Quái Thú có hiệu ứng quỷ - gây ra mối đe dọa rất cao đến tính mạng của đối phương.'),
(10335, 'Đánh chặn Ma Pháp quỷ', 'Ác Ma', 'Ám', 'Ác Ma', 4, 1400, 1600, 'SR', 0, 3, 'ljem', 'Một con quỷ thường Ám Tộc ảnh các trung tâm giao thông lớn và không chịu cho mọi người đi qua trừ khi họ trả một số tiền nhất định.', '|Mô tả|\\nMột kỹ năng đặc biệt nhắm vào máu của đối phương và kết hợp với một số lượng lớn Quái Thú có hiệu ứng quỷ - gây ra mối đe dọa rất cao đến tính mạng của đối phương.'),
(10336, 'Kẻ giết người trong bóng tối', 'Ác Ma', 'Ám', 'Không có', 4, 1400, 200, 'SR', 0, 3, 'ayss', 'Kẻ sát nhân ẩn náu trong bóng tối có khả năng dịch chuyển tức thời trong khoảng cách ngắn.', '0'),
(10337, 'Chó quỷ·Chó Hakki', 'Ác Ma', 'Ám', 'Không có', 3, 800, 800, 'SR', 0, 3, 'mqbgq', 'Một chú chó quỷ rất dễ thương nhưng lại sinh ra không có thị giác.', '|Mô tả|\\nNhanh chóng tìm kiếm thủ lĩnh quỷ Nicolofia trong Bộ Bài'),
(10338, 'nỗi kinh hoàng đen tối', 'Zombie', 'Ám', 'Không có', 4, 1700, 1500, 'SR', 0, 3, 'hadkb', 'Nỗi kinh hoàng từ bóng tối đột nhiên xuất hiện bên cạnh tôi một cách lặng lẽ.', '|Mô tả|\\n Chống lại Phong Tộc cách cắt bài - tôi không hề yếu đuối chút nào.'),
(10339, 'tuần tra đường cao tốc Địa Tộc ngục', 'Ác Ma', 'Ám', 'Không có', 4, 1600, 1200, 'UR', 0, 3, 'dyglxj', 'Ngay cả trong Địa Tộc ngục cũng cần có trật tự bình thường. Đây là điều mà người tuần tra thích nói mỗi khi uống quá nhiều.', '|Mô tả|\\nCó cả kỹ năng nhắm vào máu của đối phương và kỹ năng kết liễu - rất linh hoạt.'),
(10340, 'Ác ý gia tăng', 'Zombie', 'Ám', 'Không có', 3, 700, 1000, 'SR', 0, 3, 'zfdey', 'Những niệm ác luôn tích lũy.', '|Mô tả|\\nLá bài cốt lõi của Phong Tộc cách cắt lá bài - kết hợp với người điều khiển con rối điều khiển xác sống và Phép Thuật hồi sinh - có thể gây thêm sát thương cho lá bài của đối phương.'),
(10341, 'Necropot', 'Zombie', 'Ám', 'Không có', 3, 1100, 1000, 'UR', 0, 3, 'slh', 'Xác sống ẩn náu trong nồi và thích ăn trộm những lá bài đặt cạnh nồi.', '|Mô tả|\\nKỹ năng của Necronomicon Pot sẽ chỉ được kích hoạt khi đối phương chủ động tấn công lá bài này\\nKỹ năng được kích hoạt bởi Necronomicon Pot sẽ không chỉ gây sát thương lên mạng của đối phương mà còn tấn công thư viện lá bài của đối phương.'),
(10342, 'quỷ hạ đẳng', 'Ác Ma', 'Ám', 'Ác Ma', 5, 2100, 1000, 'SR', 0, 3, 'xwem', 'Tuy hắn là một con quỷ cấp thấp nhưng sức mạnh của hắn không thể coi thường.', '|Mô tả|\\n<Loại trừ> là một trong những kỹ năng mạnh nhất của Quái Thú trong trò chơi. Quái Thú bị loại trừ không thể vào Nghĩa Địa - không thể kích hoạt các kỹ năng đi vào Nghĩa Địa và không thể hồi sinh từ Nghĩa Địa.'),
(10343, 'Người lính quỷ', 'Ác Ma', 'Ám', 'Ác Ma', 4, 1900, 1500, 'UR', 0, 3, 'emsb', 'Các chuyên gia chiến đấu thuộc đội quân tinh nhuệ của quỷ đã được tập hợp. Anh ấy nổi tiếng là người luôn hoàn thành nhiệm vụ được giao một cách trung thực.', '|Mô tả|\\nNhân vật Tapir đã nâng cấp lên cấp 60 để nhận thưởng Quái Thú rất mạnh.'),
(10344, 'Trinh sát bóng tối Ska', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 2, 500, 500, 'SR', 0, 3, 'ahjchsk', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Mô tả|\\nMột lá bài không bị mất lá bài - thường được sử dụng để tìm kiếm Bronn - Green - Khaki và Blau'),
(10345, 'Chiến thuật xanh đậm', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 2, 300, 500, 'SR', 0, 3, 'ahjcsgl', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Giải thích|\\n1 ăn 1 - dùng bài để đổi bài trên sân đối phương. Nếu bạn sử dụng chúng tốt - bạn có thể đạt được lợi thế trong tình huống này.'),
(10346, 'Sát thủ thế giới bóng tối Khaki', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 2, 300, 500, 'SR', 0, 3, 'ahjckkq', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Giải thích|\\n1 ăn 1 - dùng bài để đổi bài trên sân đối phương. Nếu bạn sử dụng chúng tốt - bạn có thể đạt được lợi thế trong tình huống này.'),
(10347, 'Vua bóng tối điên cuồng·Bron', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 4, 1800, 400, 'UR', 0, 3, 'ahjkwbl', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Mô tả|\\nLà lá bài cốt lõi trong Bộ Bài Thế giới bóng tối - nếu bảo vệ Braum tốt - bạn sẽ có khả năng chiến thắng không giới hạn.'),
(10348, 'Thợ săn Blau của Vương quốc bóng tối', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 3, 1400, 800, 'SR', 0, 3, 'ahjsrbl', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Mô tả|\\nKỹ năng kiểm tra lá bài luôn mạnh mẽ và nó càng trở nên mạnh mẽ hơn nếu được đối phương kích hoạt.'),
(10349, 'Chiến đấu với thần bóng tối Latina', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 6, 1500, 2400, 'UR', 0, 3, 'ahjdsltn', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Mô tả|\\nSử dụng các kỹ năng của Braum để nhanh chóng triệu hồi sân và khi bị đối phương kích hoạt - bạn có thể tăng sức mạnh cho Quái Thú quỷ của chính mình.'),
(10350, 'Vương quốc bóng tối Võ thần vàng', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 5, 2300, 1400, 'UR', 0, 3, 'ahjwsged', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Mô tả|\\nSử dụng kỹ năng của Braum để triệu hồi sân đấu nhanh chóng. Khi được đối phương kích hoạt - nó có thể phá hủy hai lá bài của đối phương - gây ra đòn tàn khốc cho đối phương.'),
(10351, 'Thần chiến tranh vương quốc bóng tối Silva', 'Ác Ma', 'Ám', 'Thế Giới Bóng Tối', 5, 2300, 1400, 'UR', 0, 3, 'ahjjsxew', 'Lá bài từ khóa Dark Realm - toàn bộ bộ lá bài xoay quanh chiến lược triệu hồi đặc biệt sau khi được đưa từ tay xuống Nghĩa Địa. Những con Quái Thú được hợp nhất thành những con quỷ thuộc tính bóng tối.', '|Mô tả|\\nSử dụng kỹ năng của Braum để triệu hồi sân đấu nhanh chóng. Nếu bị đối phương kích hoạt - nó có thể gây ra một đòn rất lớn vào tay đối phương.'),
(10352, 'Hoàng đế bóng tối Dilge', 'Pháp Sư', 'Ám', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'addeg', 'Hoàng đế điều khiển nguyên tố bóng tối sử dụng nguyên tố bóng tối để tiêu diệt quân bài.', '|Mô tả|\\nViệc loại trừ các quân bài chủ chốt khỏi mộ của đối phương đôi khi có thể ngăn cản đối phương lội ngược dòng. Ngoài ra - nó còn có thể làm hỏng lá bài thư viện của đối phương.'),
(10353, 'Người giữ chân của Hoàng đế Gió Garum', 'Chim Thú', 'Phong', 'Không có', 3, 800, 1000, 'UR', 0, 3, 'fdjcjlm', 'Thuộc hạ trung thành nhất của Hoàng đế Gió có thể hiến tế mọi thứ vì Hoàng đế Gió.', '|Mô tả|\\nBạn có thể đưa những Quái Thú cấp cao hơn bị chặn của chúng tôi trở lại tay mình để được triệu hồi đặc biệt. Kỹ năng này chỉ có thể được sử dụng khi Quái Thú cấp cao hơn này xuất hiện trong phương thức triệu hồi thông thường\\nKhi bị hiến tế - Người giữ của Hoàng đế Gió cũng có thể lấy Người giữ của Hoàng đế Ngọn lửa từ Bộ Bài.'),
(10354, 'Chân trái của người bị Phong Tộc ấn', 'Pháp Sư', 'Ám', 'Phong Ấn Exodia', 1, 200, 300, 'UR', 0, 1, 'bfyzdzz', 'Khi kết hợp với <Cánh tay phải bị Phong Tộc ấn> - <Cánh tay trái bị Phong Tộc ấn> - <Chân phải bị Phong Tộc ấn> và <Đầu bị Phong Tộc ấn> - bạn sẽ thắng trận đấu.', '|Mô tả|\\nThu thập 5 lá bài này trên tay bạn: <Cánh tay trái của người bị Phong Tộc ấn> - <Cánh tay phải của người bị Phong Tộc ấn> - <Chân trái của người bị Phong Tộc ấn> - <Chân phải của người bị Phong Tộc ấn> để trực tiếp giành chiến thắng trong trận chiến.'),
(10355, 'Chân phải của người bị Phong Tộc ấn', 'Pháp Sư', 'Ám', 'Phong Ấn Exodia', 1, 200, 300, 'UR', 0, 1, 'bfyzdyz', 'Khi kết hợp với <Cánh tay trái bị Phong Tộc ấn> - <Chân trái bị Phong Tộc ấn> - <Cánh tay phải bị Phong Tộc ấn> và <Đầu bị Phong Tộc ấn> - bạn sẽ thắng trận đấu.', '|Mô tả|\\nThu thập 5 lá bài này trên tay bạn: <Cánh tay trái của người bị Phong Tộc ấn> - <Cánh tay phải của người bị Phong Tộc ấn> - <Chân trái của người bị Phong Tộc ấn> - <Chân phải của người bị Phong Tộc ấn> để trực tiếp giành chiến thắng trong trận chiến.'),
(10356, 'Cuộc di cư kín', 'Pháp Sư', 'Ám', 'Phong Ấn Exodia', 3, 1000, 1000, 'UR', 0, 1, 'bfydakzdy', 'Khi kết hợp với <Cánh tay trái bị Phong Tộc ấn> - <Chân trái bị Phong Tộc ấn> - <Cánh tay phải bị Phong Tộc ấn> và <Chân phải bị Phong Tộc ấn> - bạn sẽ thắng trận đấu.', '|Mô tả|\\nThu thập 5 lá bài này trên tay bạn: <Cánh tay trái của người bị Phong Tộc ấn> - <Cánh tay phải của người bị Phong Tộc ấn> - <Chân trái của người bị Phong Tộc ấn> - <Chân phải của người bị Phong Tộc ấn> để trực tiếp giành chiến thắng trong trận chiến.'),
(10357, 'Tượng rào chắn vực thẳm', 'Ác Ma', 'Ám', 'Không có', 4, 1000, 1000, 'R', 0, 3, 'syzjjx', 'Tượng đá thường thấy ở ranh giới vực thẳm. Chỉ những người thân thiết với chúng mới hiểu rằng những bức tượng đá thực sự còn sống.', '0'),
(10358, 'Thần hủy diệt bóng tối', 'Ác Ma', 'Ám', 'Không có', 7, 2300, 1800, 'UR', 0, 3, 'amphs', 'Một con quỷ rất mạnh trong thế giới ngầm với sức tàn phá to lớn.', '|Mô tả|\\nChỉ có thể triệu hồi bình thường bằng cách hiến tế hai Quái Thú - nhưng một khi nó xuất hiện thì mối đe dọa là cực kỳ cao'),
(10359, 'Tối đa sáu', 'Chiến Sĩ', 'Địa', 'Xúc Xắc Speedroid', 6, 1900, 1600, 'UR', 0, 3, 'zdzl', 'Khi chiến đấu - tất cả phụ thuộc vào May mắn của bạn.', '0'),
(10360, 'người đàn ông lập phương', 'Sấm Sét', 'Quang', 'Xúc Xắc Speedroid', 4, 600, 1900, 'UR', 0, 3, 'mfr', 'Ý thức độc lập được sinh ra trong khối Rubik. Nếu bạn ghép khối Rubik thành công - những điều tốt đẹp sẽ xảy ra.', '0'),
(10361, 'Ác quỷ cuồng nộ', 'Ác Ma', 'Ám', 'Ác Ma', 4, 1800, 0, 'SR', 0, 3, 'kbem', 'Con quỷ có vẻ hung dữ chỉ có thể ẩn nấp và thu hoạch trong chiến tranh.', '0'),
(10362, 'Mã thông báo thiên thần nhân tạo', 'Thiên Thần', 'Quang', 'Không có', 1, 300, 300, 'N', 0, 3, 'rztsysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10363, 'Một người đàn ông sáng suốt', 'Pháp Sư', 'Ám', 'Không có', 4, 1600, 1600, 'SR', 0, 3, 'yfydnr', 'Mối nguy hiểm trên chiến trường có thể được phát hiện chính xác thông qua đôi mắt Phép Thuật của anh ta.', '0'),
(10364, 'Khủng long nguyên tố', 'Khủng Long', 'Ám', 'Không có', 4, 1500, 1200, 'UR', 0, 3, 'yskl', 'Những con khủng long ở gần các nguyên tố sẽ có những khả năng khác nhau khi chiến đấu với các nguyên tố khác nhau.', '0'),
(10365, 'Raptor bóng tối', 'Khủng Long', 'Địa', 'Không có', 4, 1800, 300, 'UR', 0, 3, 'ahxml', 'Velociraptor màu đen tuyền nhỏ bé và rất giỏi tấn công lén lút - nhưng nó không có lợi thế khi chiến đấu trực diện.', '0'),
(10366, 'Trái đất cuồng nộ', 'Bò Sát', 'Địa', 'Không có', 7, 2000, 1500, 'SR', 0, 3, 'kndd', 'Con cưng của trái đất - sở hữu sức mạnh vô tận.', '0'),
(10367, 'Hillfield', 'Thiên Thần', 'Phong', 'Không có', 4, 1700, 700, 'UR', 0, 3, 'xefd', 'Được ban phước bởi yếu tố gió - anh ta có thể điều khiển sức mạnh của gió và phá vỡ nhịp điệu của đối phương.', '0'),
(10368, 'tay cờ bạc huyền thoại', 'Pháp Sư', 'Ám', 'Không có', 4, 500, 1400, 'UR', 0, 3, 'csddbs', 'Anh tin rằng May mắn là yếu tố quyết định trong các cuộc đấu tay đôi và thích mọi thứ liên quan đến cờ bạc.', '0'),
(10369, 'Linh mục Phép Thuật đen', 'Pháp Sư', 'Ám', 'Không có', 9, 3200, 2800, 'UR', 0, 3, 'hmfsg', 'Đối với vị linh mục vĩ đại của thế giới bóng tối - không có Cạm Bẫy nào trên chiến trường có thể hoạt động được.', '0'),
(10370, 'Tam giác đen tối Quái Thú chim rồng', 'Khủng Long', 'Địa', 'Không có', 6, 2400, 1500, 'UR', 0, 3, 'ahsjgnl', 'Một loài chim đầy màu sắc và kỳ lạ nhưng thực ra nó là một con khủng long biết bay.', '0'),
(10371, 'oxylon', 'Khủng Long', 'Phong', 'Không có', 4, 1800, 800, 'UR', 0, 3, 'ysl', 'Khủng long được làm hoàn toàn bằng oxy sẽ phát nổ dữ dội khi bị Quái Thú hệ lửa tiêu diệt.', '0'),
(10372, 'Trứng kỷ Jura thần kỳ', 'Khủng Long', 'Địa', 'Không có', 4, 0, 2000, 'UR', 0, 3, 'qjzzljd', 'Trứng khủng long tồn tại trong kỷ Jura vẫn còn tồn tại cho đến ngày nay và không biết chúng có thể nở ra loại khủng long nào.', '0'),
(10373, 'Hỏa Thần Thần Pyro Rex', 'Khủng Long', 'Thủy', 'Không có', 8, 2800, 2200, 'UR', 0, 3, 'ylspllks', 'Anh ta có thể điều khiển Ma PhápgMa Pháp nóng nhất trong lòng trái đất và có tính khí rất xấu.', '0'),
