(10375, 'thằn lằn nhỏ', 'Khủng Long', 'Địa', 'Không có', 2, 500, 500, 'UR', 0, 3, 'xyl', 'Một chú khủng long nhỏ rất dễ thương nhưng được mọi loài khủng long vô cùng yêu quý.', '0'),
(10376, 'rồng nước', 'Khủng Long', 'Hỏa', 'Không có', 8, 2800, 2600, 'UR', 0, 3, 'sl', 'Khủng long được tổng hợp thông qua các phản ứng hóa học - kết hợp hydro và oxy.', '0'),
(10377, 'Hydroxon', 'Khủng Long', 'Hỏa', 'Không có', 4, 1600, 1000, 'SR', 0, 3, 'qsl', 'Khủng long làm hoàn toàn bằng hydro có thể cháy lặng lẽ trong không khí do chúng có độ tinh khiết 100%.', '0'),
(10378, 'Rồng có cánh đen', 'Khủng Long', 'Phong', 'Không có', 3, 1000, 500, 'SR', 0, 3, 'ahyl', 'Nó xuất hiện trong bóng tối - có tốc độ bay cực nhanh và thích giết chết con mồi.', '0'),
(10379, 'vi khuẩn', 'Khủng Long', 'Địa', 'Không có', 2, 500, 500, 'SR', 0, 3, 'xjl', 'Một con khủng long nhỏ rất dễ thương là bạn tốt của loài thằn lằn bay.', '0'),
(10380, 'rùa lãnh đạo', 'Bò Sát', 'Hỏa', 'Không có', 3, 1100, 1200, 'SR', 0, 3, 'slg', 'Tôi rất bị Ám Tộc ảnh bởi bộ phim hoạt hình <Ninja rùa đột biến tuổi teen> - nhưng tôi không bao giờ tìm thấy con rùa thứ tư.', '0'),
(10381, 'hà mã hắt hơi', 'Khủng Long', 'Hỏa', 'Không có', 4, 1700, 1500, 'SR', 0, 3, 'ddptdhml', 'Một con Quái Thú kappa với thân hình to lớn. Một cái hắt hơi từ cơ thể khổng lồ của nó có thể sánh ngang với một cơn bão.', '0'),
(10382, 'Skink điện', 'Bò Sát', 'Hỏa', 'Không có', 4, 1500, 200, 'UR', 0, 3, 'dhlx', 'Một con thằn lằn có năng lượng điện - được cho là có điện áp một trăm nghìn vôn.', '0'),
