(10395, 'Lỗ hổng ManX', 'Ác Ma', 'Ám', 'Không có', 3, 0, 2000, 'UR', 0, 3, 'ldra', 'Yêu tinh lỗi được tạo ra bởi lỗi máy tính tự gọi mình là người lỗi và gây rắc rối ở mọi nơi trong thế giới ảo.', '0'),
(10396, 'Lỗ hổng Man Y', 'Ác Ma', 'Ám', 'Không có', 3, 1400, 1600, 'SR', 0, 3, 'ldrw', 'Yêu tinh lỗi được tạo ra bởi lỗi máy tính tự gọi mình là người lỗi và gây rắc rối ở mọi nơi trong thế giới ảo.', '0'),
(10397, 'gã khốn Z', 'Ác Ma', 'Ám', 'Không có', 3, 0, 1500, 'SR', 0, 3, 'ldrz', 'Yêu tinh lỗi được tạo ra bởi lỗi máy tính tự gọi mình là người lỗi và gây rắc rối ở mọi nơi trong thế giới ảo.', '0'),
(10398, 'người đàn ông siêu lỗi', 'Ác Ma', 'Ám', 'Không có', 4, 0, 3000, 'UR', 0, 3, 'cjldr', 'Yêu tinh lỗi được tạo ra bởi lỗi máy tính tự gọi mình là người lỗi và gây rắc rối ở mọi nơi trong thế giới ảo.', '0'),
(10399, 'kẻ xâm lược mạnh mẽ', 'Ác Ma', 'Ám', 'Không có', 5, 2200, 0, 'UR', 0, 3, 'qlqlz', 'Những kẻ xâm lược từ các hành tinh khác trong vũ trụ được triệu tập bằng một nghi lễ bí ẩn.', '0'),
(10400, 'Phù Thủy tập sự tưởng tượng', 'Pháp Sư', 'Ám', 'Không có', 6, 2000, 1700, 'UR', 0, 3, 'hxzjxmds', 'Người học việc của Phù Thủy đen huyền ảo - mặc dù vẫn đang trong giai đoạn học việc nhưng đã thể hiện tài năng đáng kinh ngạc.', '0'),
(10401, 'Cỏ Phép Thuật·Mandrake', 'Pháp Sư', 'Ám', 'Không có', 2, 500, 200, 'SR', 0, 3, 'hcmdlc', 'Mandrake có thể cảm nhận được các nguyên tố Phép Thuật - nhưng nó không thể giải phóng Phép Thuật mạnh mẽ vì nó tương đối yếu.', '0'),
(10402, 'Người thực hiện Phép Thuật', 'Pháp Sư', 'Ám', 'Không có', 2, 400, 400, 'UR', 0, 3, 'mlszs', 'Một Phù Thủy Phép Thuật có thể giao tiếp với linh hồn của Quái Thú Phù Thủy và hồi sinh chúng một lần nữa.', '0'),
(10403, 'Hoàng đế băng giá Mebius', 'Thủy Tộc', 'Hỏa', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'bdmbws', 'Hoàng đế điều khiển nguyên tố băng sử dụng nguyên tố băng để phá hủy các quân bài.', '0'),
(10404, 'Escher tùy tùng của Hoàng đế băng giá', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 800, 1000, 'UR', 0, 3, 'bdjcase', 'Thuộc hạ trung thành nhất của Băng Đế - người có thể hiến tế mọi thứ vì Băng Đế.', '0'),
(10405, 'Rồng mắt đỏ thật', 'Rồng', 'Ám', 'Mắt Đỏ', 3, 1200, 700, 'UR', 0, 3, 'zhyyl', 'Khi rồng non đạt đến giai đoạn này - nó chắc chắn sẽ phát triển thành một con rồng đen mắt đỏ thực sự mạnh mẽ mà không gặp bất kỳ tai nạn nào.', '0'),
(10406, 'Phù Thủy hỗn loạn', 'Ác Ma', 'Ám', 'Không có', 1, 0, 0, 'UR', 0, 3, 'hdsls', 'Một con quỷ có thể đánh cắp năng lượng của người chết sẽ không thể bị đánh bại nếu không xử lý năng lượng của người chết trước.', '0'),
(10407, 'Tà Thần Thần Hóa Thân', 'Thần Thú', 'Thần', 'Không có', 10, 0, 0, 'UR', 0, 1, 'xsszhs', 'Trong hình dạng ban đầu của ác thần - chưa ai từng nhìn thấy những gì bên trong quả cầu.', '0'),
(10408, 'tinh thần nhẹ nhàng', 'Bò Sát', 'Quang', 'Không có', 7, 2000, 1500, 'SR', 0, 3, 'gmzl', 'Một tập hợp các yếu tố ánh sáng ghét bất kỳ yếu tố nào khác.', '0'),
(10409, 'Tướng quân Địa Tộc ngục Mephistopheles', 'Ác Ma', 'Ám', 'Không có', 5, 1800, 1700, 'UR', 0, 3, 'dyjjmfst', 'Vị tướng ở Địa Tộc ngục - tôi tự hỏi liệu hắn có liên quan gì đến Mephisto không.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10410, 'Người gác đền', 'Ác Ma', 'Ám', 'Không có', 4, 1100, 1900, 'UR', 0, 3, 'sdswz', 'Có những người bảo vệ ngôi đền trong di tích cổ - và bất cứ ai muốn vào ngôi đền đều phải vượt qua bài kiểm tra.', '0'),
(10411, 'Samurai bất tử', 'Chiến Sĩ', 'Ám', 'Không có', 3, 1200, 600, 'SR', 0, 3, 'bsws', 'Không có cách nào để tiêu diệt các chiến binh bất tử.', '0'),
(10412, 'rồng', 'Rồng', 'Phong', 'Không có', 4, 2000, 100, 'UR', 0, 3, 'jl', 'Con rồng đất khổng lồ hiếm khi di chuyển - nhưng mỗi lần nó di chuyển đều là một trận động đất.', '0'),
(10413, 'Kyle Burke', 'Thiên Thần', 'Địa', 'Không có', 4, 1500, 1800, 'UR', 0, 3, 'kebk', 'Nó có thể tạm thời xóa đi ký ức của đối phương - khiến họ quên đi ý định chiến đấu ban đầu và làm gián đoạn nhịp điệu của đối phương.', '0'),
(10414, 'Người chết trong sa mạc', 'Zombie', 'Ám', 'Không có', 5, 0, 0, 'UR', 0, 2, 'hmdsz', 'Những nhà thÁm Tộc hiểm chết trên sa mạc vì lòng oán hận mãnh liệt nên lang thang trong sa mạc và tấn công bất kỳ sinh vật sống nào.', '0'),
(10415, 'Vệ binh Hoàng gia', 'Zombie', 'Địa', 'Không có', 4, 1900, 2000, 'UR', 0, 3, 'wzqwd', 'Hoàng gia Ai Cập được chôn cất cùng nhau khi được chôn cất và họ không quên canh gác lăng mộ ngay cả sau khi chết.', '0'),
(10416, 'Phà tới Hoàng Tuyền', 'Thủy Tộc', 'Hỏa', 'Không có', 3, 800, 1400, 'UR', 0, 3, 'txhqddc', 'Con tàu chỉ có thể được nhìn thấy sau khi chết - có thể được hồi sinh trước khi đi vào thế giới ngầm.', '0'),
(10417, 'Hiền nhân có cánh Falkos', 'Chim Thú', 'Phong', 'Không có', 4, 1700, 1200, 'UR', 0, 3, 'yyxzfeks', 'Sở hữu khả năng kỳ lạ để thao túng đối phương trong tích tắc.', '0'),
(10418, 'game bắn súng âm thanh', 'Chim Thú', 'Phong', 'Không có', 4, 1300, 600, 'SR', 0, 3, 'ysss', 'Một game bắn súng siêu thanh có thể vượt qua Quái Thú của kẻ thù và tấn công trực tiếp vào đối phương.', '0'),
(10419, 'Đơteri', 'Khủng Long', 'Hỏa', 'Không có', 5, 2000, 1400, 'UR', 0, 3, 'dsl', 'Có thể kết hợp hóa học với oxy tạo thành nước nặng.', '0'),
(10420, 'Thiên thần sa ngã Ukobak', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 3, 700, 1000, 'UR', 0, 3, 'dtswkbk', 'Đội tiên Phong Tộc của các thiên thần sa ngã có thể hoàn thành mảng dịch chuyển máy bay để giúp các thiên thần sa ngã khác hạ cánh.', '0'),
(10421, 'chiến binh mặt trời', 'Chiến Sĩ', 'Quang', 'Không có', 5, 2100, 1400, 'SR', 0, 3, 'tyzzs', 'Nó có thể sử dụng năng lượng của mặt trời để tạo ra hiệu ứng kiềm chế mạnh mẽ đối với Quái Thú thuộc tính bóng tối.', '0'),
(10422, 'con hà nhỏ', 'Thủy Tộc', 'Hỏa', 'Không có', 3, 300, 0, 'SR', 0, 3, 'ztth', 'Khi số lần tấn công tăng lên - sát thương gây ra cũng tăng lên.', '0'),
(10423, 'Bộ xương bạch tuộc', 'Thủy Tộc', 'Ám', 'Không có', 3, 600, 1600, 'UR', 0, 3, 'klzy', 'Nó chỉ có thể tồn tại ở vùng biển sâu. Nó cực kỳ tàn nhẫn và có tính khí dễ thay đổi.', '0'),
(10424, 'Cây leo Nghĩa Địa', 'Ác Ma', 'Ám', 'Không có', 1, 0, 0, 'UR', 0, 3, 'mcrdz', 'Những con quỷ hiếm chỉ xuất hiện trong Nghĩa Địa Quỷ. Dù có ít sức tấn công nhưng chúng có thể nguyền rủa đối phương đến chết.', '0'),
(10425, 'cái bóng của geisha', 'Pháp Sư', 'Ám', 'Không có', 4, 1700, 0, 'UR', 0, 3, 'yjzy', 'Được hình thành từ sự oán giận của một geisha - cô trở nên mạnh mẽ bằng cách nuốt chửng linh hồn của người khác.', '0'),
(10426, 'Bậc thầy đường hầm tối Peter', 'Pháp Sư', 'Ám', 'Không có', 3, 500, 1200, 'SR', 0, 3, 'adhsbd', 'Anh ta là đối tác của Phù Thủy kênh bóng tối Zaki - người thường sử dụng Phép Thuật thực sự trong các màn biểu diễn ảo thuật.', '0'),
(10427, 'tướng phòng thủ tuyệt đối', 'Chiến Sĩ', 'Ám', 'Không có', 6, 1550, 2500, 'UR', 0, 3, 'jdfyjj', 'Kỹ năng phòng thủ 360 độ toàn thân khiến kẻ địch không thể tấn công.', '0'),
(10428, 'cỏ Ma Pháp', 'Thực Vật', 'Hỏa', 'Không có', 3, 1000, 1000, 'SR', 0, 3, 'hlc', 'Nó có thể gây ảo giác - số lượng càng lớn thì ảo giác càng chân thực.', '0'),
(10429, 'Rùa từng được gọi là thần', 'Thủy Tộc', 'Hỏa', 'Không có', 1, 0, 1800, 'UR', 0, 3, 'cbcwsdg', 'Con rùa già nhất còn tồn tại đến ngày nay đã chứng kiến ​​nguồn gốc và sự phát triển của nền văn minh nhân loại.', '0'),
(10430, 'Chim lửa chiến binh Phép Thuật', 'Chiến Sĩ', 'Thủy', 'Chiến Binh Ma Thuật', 4, 1700, 1200, 'SR', 0, 3, 'mzzshn', 'Một chiến binh Phép Thuật xuất hiện dưới hình dạng quái thú thần thoại <Suzaku> và có khả năng điều khiển lửa.', '0'),
(10431, 'Inaba no Thỏ Trắng', 'Thú', 'Địa', 'Không có', 3, 700, 500, 'UR', 0, 3, 'yfzbt', 'Thỏ Ngọc có thể bay tự do và chiếc chày trong tay nó thực chất là một vũ khí thần kỳ.', '0'),
(10432, 'trên tay Phép Thuật', 'Pháp Sư', 'Ám', 'Không có', 4, 800, 1600, 'UR', 0, 1, 'mss', 'Nó thường ẩn náu trong những chiếc hộp Phép Thuật và bất ngờ xuất hiện khiến người cầm chiếc hộp phải khiếp sợ.', '0'),
(10433, 'ngọn lửa tay', 'Hỏa Tộc', 'Thủy', 'Không có', 4, 1600, 1000, 'UR', 0, 1, 'hys', 'Những sinh vật sống trong Ma PhápgMa Pháp nhưng nhiệt độ cơ thể của chúng thấp hơn Ma PhápgMa Pháp.', '0'),
(10434, 'tay băng', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1400, 1600, 'UR', 0, 1, 'hbs', 'Những sinh vật sống ở vùng biển sâu đóng băng - trái ngược với Trên tay lửa - có nhiệt độ cơ thể cao hơn vùng biển đóng băng.', '0'),
(10435, 'tay nổi bật', 'Hỏa Tộc', 'Thủy', 'Không có', 4, 600, 2000, 'UR', 0, 1, 'res', 'Những sinh vật đồng hành sẽ tồn tại ở bất cứ nơi nào sinh vật hình trên tay xuất hiện.', '0'),
(10436, 'sư tử thú', 'Chiến Sĩ Thú', 'Địa', 'Không có', 4, 1500, 1600, 'UR', 0, 3, 'rss', 'Anh ta không bao giờ giết một thường dân và không bao giờ tha thứ cho bất kỳ quý tộc nào.', '0'),
(10437, 'máy tuần hoàn không khí', 'Thủy Tộc', 'Phong', 'Không có', 3, 0, 600, 'UR', 0, 3, 'kqxhj', 'Một chiếc máy có thể duy trì sự lưu thông không khí tốt - tiết kiệm và thân thiện với môi trường.', '0'),
(10438, 'Người hầu cận của Hoàng đế Trái đất · Lan Rob', 'Nham Thạch', 'Địa', 'Không có', 4, 800, 1000, 'UR', 0, 3, 'ddjcllb', 'Thuộc hạ trung thành nhất của Thổ Hoàng có thể hiến tế mọi thứ vì Thổ Hoàng.', '0'),
(10439, 'Hà Bồ', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1800, 600, 'UR', 0, 3, 'hb', 'Người bất tử phụ trách dòng sông âm thầm nuôi dưỡng vạn vật.', '0'),
(10440, 'Kẻ hủy diệt song kiếm', 'Chiến Sĩ', 'Ám', 'Không có', 4, 1600, 1000, 'UR', 0, 3, 'sjphz', 'Hai thanh kiếm tấn công như vũ bão - phòng thủ mù quáng chỉ có thể dẫn đến cái chết.', '0'),
(10441, 'Tượng chắn mưa lớn', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1000, 1000, 'R', 0, 3, 'hyzjjx', 'Ngoại trừ yếu tố nước - tất cả các yếu tố khác trong rào chắn sẽ bị ép ra ngoài.', '0'),
(10442, 'Hoàng đế sấm sét Zabolg', 'Sấm Sét', 'Quang', 'Không có', 5, 2400, 1000, 'UR', 0, 3, 'ldzbeg', 'Một vị hoàng đế nắm vững nguyên tố sấm sét có thể dễ dàng tiêu diệt kẻ thù của mình bằng tia sét. Nhưng không biết có phải là ảo giác của chính mình hay không - mà là Lôi Đế luôn cảm thấy mình thấp hơn các hoàng đế khác.', '0'),
(10443, 'Người hầu cận của Hoàng đế độc ác Lucius', 'Ác Ma', 'Ám', 'Không có', 1, 800, 1000, 'UR', 0, 3, 'xdjcljws', 'Thuộc hạ trung thành nhất của Ác hoàng có thể hiến tế mọi thứ vì Ác hoàng.', '0'),
(10444, 'người có tầm nhìn bắt chước', 'Pháp Sư', 'Ám', 'Không có', 1, 0, 0, 'UR', 0, 3, 'mfdhxs', 'Một Phù Thủy có Phép Thuật có thể bắt chước mọi thứ.', '0'),
(10445, 'Một đòn sẽ giết chết người phục vụ', 'Chiến Sĩ', 'Phong', 'Không có', 4, 1200, 1200, 'UR', 0, 3, 'yjbss', 'Bạn có thể nhìn thấu điểm yếu của kẻ thù và tiêu diệt chúng chỉ bằng một đòn - nhưng vẫn cần thời gian để tìm ra điểm yếu.', '0'),
(10446, 'ông già satan', 'Thần Thú', 'Thần', 'Không có', 6, 1200, 2500, 'UR', 0, 1, 'sdlr', 'Anh ấy sẽ xuất hiện vào dịp Giáng sinh và đóng giả ông già Noel - nhưng những món quà anh ấy tặng không thể so sánh được với ông già Noel.', '0'),
(10447, 'rồng pha lê', 'Rồng', 'Quang', 'Không có', 6, 2500, 1000, 'UR', 0, 3, 'sjl', 'Thân máy được cấu tạo từ tinh thể nguyên chất và trở nên hoàn toàn trong suốt khi tiếp xúc trực tiếp với ánh nắng mặt trời.', '0'),
(10448, 'công chúa bão tuyết', 'Pháp Sư', 'Hỏa', 'Không có', 8, 2800, 2100, 'UR', 0, 3, 'xbgz', 'Mặc dù có kích thước nhỏ nhắn nhưng cô ấy sở hữu sức mạnh tuyệt vời và tài năng Phép Thuật của cô ấy vượt xa tài năng thể chất.', '0'),
(10449, 'Sức mạnh của sự bí ẩn·Kẻ ngốc', 'Thiên Thần', 'Quang', 'Sức Mạnh Thần Bí', 1, 0, 0, 'SR', 0, 3, 'myzlyz', 'Những Quái Thú thiên thần thuộc tính ánh sáng dựa trên các lá bài tarot có khả năng tấn công và phòng thủ giống nhau. Hướng tích cực và tiêu cực của các lá bài tarot rất quan trọng trong việc bói toán tarot - và điều tương tự cũng xảy ra với những con Quái Thú có sức mạnh của nghi lễ bí mật.', '0'),
(10450, 'Sức mạnh của sự huyền bí·Phù Thủy', 'Thiên Thần', 'Quang', 'Sức Mạnh Thần Bí', 4, 1100, 1100, 'UR', 0, 3, 'myzlmss', 'Những Quái Thú thiên thần thuộc tính ánh sáng dựa trên các lá bài tarot có khả năng tấn công và phòng thủ giống nhau. Hướng tích cực và tiêu cực của các lá bài tarot rất quan trọng trong việc bói toán tarot - và điều tương tự cũng xảy ra với những con Quái Thú có sức mạnh của nghi lễ bí mật.', '0'),
(10451, 'Sức mạnh của sự huyền bí · Hoàng hậu', 'Thiên Thần', 'Quang', 'Sức Mạnh Thần Bí', 4, 1300, 1300, 'UR', 0, 3, 'myzlnd', 'Những Quái Thú thiên thần thuộc tính ánh sáng dựa trên các lá bài tarot có khả năng tấn công và phòng thủ giống nhau. Hướng tích cực và tiêu cực của các lá bài tarot rất quan trọng trong việc bói toán tarot - và điều tương tự cũng xảy ra với những con Quái Thú có sức mạnh của nghi lễ bí mật.', '0'),
(10452, 'Sức mạnh của sự huyền bí·Hoàng đế', 'Thiên Thần', 'Quang', 'Sức Mạnh Thần Bí', 4, 1400, 1400, 'UR', 0, 3, 'myzlhd', 'Những Quái Thú thiên thần thuộc tính ánh sáng dựa trên các lá bài tarot có khả năng tấn công và phòng thủ giống nhau. Hướng tích cực và tiêu cực của các lá bài tarot rất quan trọng trong việc bói toán tarot - và điều tương tự cũng xảy ra với những con Quái Thú có sức mạnh của nghi lễ bí mật.', '0'),
