(10506, 'Hoàng đế gió Leza', 'Chim Thú', 'Phong', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'fdlz', 'Vị hoàng đế làm chủ được nguyên tố gió có thể dễ dàng dùng gió thổi bay kẻ thù của mình.', '0'),
(10507, 'Phí yêu tinh', 'Chiến Sĩ Thú', 'Địa', 'Ghostrick', 4, 1900, 0, 'UR', 0, 3, 'gblcfbd', 'Vương quốc Goblin chịu trách nhiệm tấn công quân đội - nhưng chỉ có cuộc tấn công đầu tiên mới có hiệu ứng thần kỳ.', '0'),
(10508, 'Halloween·Kỵ sĩ không đầu', 'Zombie', 'Ám', 'Ghostrick', 6, 1600, 2400, 'UR', 0, 3, 'wsjwtqs', 'Vào ngày Halloween - mọi người sẽ từ trên trời rơi xuống và giật kẹo khắp nơi.', '0'),
(10509, 'Thiên thần thiên đường InigMa Pháp', 'Thiên Thần', 'Quang', 'Không có', 4, 1200, 1200, 'UR', 0, 3, 'tdsyngm', 'Sứ giả của Thiên Đế có thể hiến tế tất cả vì Thiên Đế.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10510, 'Halloween·Cải trang', 'Zombie', 'Ám', 'Không có', 1, 0, 0, 'N', 0, 3, 'wsjwz', 'Happy Halloween!', '0'),
(10511, 'Công cụ phái sinh InigMa Pháp', 'Thiên Thần', 'Quang', 'Không có', 4, 0, 0, 'UR', 0, 3, 'tdsyngm', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10512, 'Hoàng đế Gondi GranMa Phápg', 'Nham Thạch', 'Địa', 'Không có', 8, 2800, 1000, 'UR', 0, 3, 'gddglmg', 'Hình thức tối thượng sau quá trình tiến hóa của Thổ Đế.', '0'),
(10513, 'gấu koala Ma Pháp cà rồng', 'Thú', 'Địa', 'Không có', 4, 1800, 1500, 'UR', 0, 3, 'xxsx', 'Gấu túi chỉ xuất hiện vào ban đêm - thích tấn công người và động vật đơn độc.', '0'),
(10514, 'phù Thủy Tộc Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 4, 1500, 1500, 'UR', 0, 3, 'xxgws', 'Phù Thủy của vương quốc Ma Pháp cà rồng có thể sử dụng những kỹ năng bí mật của Ma Pháp cà rồng để triệu hồi những con Quái Thú đáng sợ.', '0'),
(10515, 'Ma cà rồng bị nguyền rủa', 'Zombie', 'Ám', 'Vampire', 6, 2000, 800, 'UR', 0, 3, 'zzzxxg', 'Một Ma Pháp cà rồng bị nguyền rủa với cuộc sống thứ hai.', '0'),
(10516, 'Linh hồn Ma Pháp quỷ và linh hồn Ma Pháp quỷ chấm dứt', 'Thủy Tộc', 'Hỏa', 'Ếch', 1, 0, 0, 'SR', 0, 3, 'ehxkz', 'Một con nòng nọc đến từ vực sâu tối tăm - hoa văn Phép Thuật trên đầu tượng trưng cho phương hướng tiến hóa.', '0'),
(10517, 'ếch quỷ', 'Thủy Tộc', 'Hỏa', 'Ếch', 3, 1200, 800, 'UR', 0, 3, 'emqw', 'Một sinh vật đáng sợ tiến hóa từ linh hồn tà ác - Xie Kuzhi - và không con mồi nào trong phạm vi tấn công được tha.', '0'),
(10519, 'Ếch Xuân Vàng', 'Thủy Tộc', 'Hỏa', 'Ếch', 1, 100, 100, 'SR', 0, 3, 'hqqw', 'Những con Quái Thú lang thang giữa sự sống và cái chết không thể bị tiêu diệt hoàn toàn.', '0'),
(10518, 'thợ săn kiếm chéo', 'Côn Trùng', 'Phong', 'Không có', 4, 1800, 1200, 'UR', 0, 3, 'szjls', 'Những chiếc gai hình chữ thập khổng lồ có thể dễ dàng xuyên thủng hàng phòng ngự của kẻ thù.', '0'),
(10520, 'ếch chết', 'Thủy Tộc', 'Hỏa', 'Ếch', 5, 1900, 0, 'UR', 0, 3, 'swqw', 'Các sinh vật đột biến bị nhiễm virus thích săn con mồi theo nhóm.', '0'),
(10521, 'lỗi cộng hưởng', 'Côn Trùng', 'Địa', 'Không có', 3, 1200, 1300, 'SR', 0, 3, 'gmc', 'Một loài côn trùng không thể tách rời khỏi lỗi cộng hưởng.', '0'),
(10522, 'Bọ rùa chết chóc bốn sao', 'Côn Trùng', 'Phong', 'Không có', 3, 800, 1200, 'SR', 0, 3, 'szsxpc', 'Bọ rùa có bốn ngôi sao trên lưng có sức mạnh đáng kinh ngạc.', '0'),
(10523, 'nữ hoàng côn trùng', 'Côn Trùng', 'Địa', 'Không có', 7, 2200, 2400, 'UR', 0, 3, 'kcnw', 'Nữ hoàng côn trùng có khả năng sinh sản vô cùng mạnh mẽ.', '0'),
(10524, 'Lỗi xẻng quỷ', 'Côn Trùng', 'Địa', 'Không có', 8, 2800, 2600, 'UR', 0, 1, 'emctc', 'Một loài côn trùng khổng lồ với sức mạnh khủng khiếp có thể dễ dàng đào bới dưới lòng đất.', '0'),
(10525, 'kẻ hủy diệt não', 'Côn Trùng', 'Ám', 'Không có', 7, 2400, 1500, 'UR', 0, 1, 'dnphc', 'Ký sinh vào não của sinh vật khác và từ từ kiểm soát sinh vật đó.', '0'),
(10526, 'Muỗi chết', 'Côn Trùng', 'Ám', 'Không có', 3, 500, 500, 'SR', 0, 3, 'sww', 'Một con muỗi cực kỳ rắc rối sống lại ngay khi người ta tưởng nó đã chết.', '0'),
(10527, 'sâu đục đất khổng lồ', 'Côn Trùng', 'Địa', 'Trùng Tộc', 4, 1900, 400, 'UR', 0, 1, 'jdztc', 'Nó chỉ xuất hiện ở sa mạc. Nó thích nhặt những sinh vật đi ngang qua và quan sát biểu hiện hoảng loạn của chúng.', '0'),
(10528, 'người bảo vệ sa mạc', 'Côn Trùng', 'Địa', 'Không có', 4, 800, 1000, 'SR', 0, 3, 'smshz', 'Những người bảo vệ đứng lên khi bộ tộc gặp nguy hiểm thường không biết đến sự tồn tại của họ.', '0'),
(10529, 'nhện hiến tế', 'Côn Trùng', 'Địa', 'Không có', 2, 300, 500, 'SR', 0, 3, 'xszz', 'Con nhện nhỏ đã chết cùng với kẻ thù vào thời điểm quan trọng.', '0'),
(10530, 'nhện gián điệp', 'Côn Trùng', 'Địa', 'Không có', 4, 1500, 1000, 'SR', 0, 3, 'jdzz', 'Một con nhện giỏi ngụy trang và có khả năng phát hiện tuyệt vời.', '0'),
(10531, 'Kỳ lân điện tử', 'Côn Trùng', 'Ám', 'Không có', 4, 1600, 900, 'SR', 0, 3, 'dzdjx', 'Những chiếc sừng trên đầu của nó cực kỳ mạnh mẽ.', '0'),
(10532, 'Bộ cộng hưởng', 'Côn Trùng', 'Ám', 'Không có', 4, 1000, 700, 'SR', 0, 3, 'gzc', 'Côn trùng truyền thông tin qua tần số rung động của cánh.', '0'),
(10533, 'Nàng tiên gai', 'Thực Vật', 'Địa', 'Không có', 4, 300, 2000, 'UR', 0, 3, 'jzyj', 'Mùi độc đáo phát ra có thể gây nhầm lẫn cho mắt và tai - khiến côn trùng không nhìn thấy được.', '0'),
(10534, 'cô gái trồng cây', 'Thực Vật', 'Hỏa', 'Không có', 3, 1300, 1100, 'SR', 0, 3, 'zwsn', 'Cây nữ tính rất đẹp nhưng mỏng Ma Phápnh.', '0'),
(10535, 'Rồng chiến đấu bóng tối', 'Rồng', 'Ám', 'Không có', 3, 900, 600, 'SR', 0, 3, 'qhddl', 'Một loại rồng độc nhất của Hắc Ma Vương - có khả năng chiến đấu siêu mạnh sau khi huấn luyện.', '0'),
(10536, 'Trương Sa', 'Cá', 'Hỏa', 'Không có', 4, 1600, 800, 'UR', 0, 3, 'zs', 'Một con cá mập Ma Phápng hình dạng bạch tuộc chỉ có thể chờ chết sau khi bị vướng vào.', '0'),
(10537, 'Đội quân tấn công của Poseidon', 'Hải Long', 'Hỏa', 'Hải Hoàng', 3, 1400, 0, 'UR', 0, 3, 'hhdtjb', 'Quái Thú bao gồm Quái Thú thuộc tính nước và rồng biển. Hầu hết các hình dạng đều là sinh vật hình rồng huyền thoại sống dưới biển sâu. <Hải Vương Long Posedra> là hoàng đế cầm quyền.', '0'),
(10538, 'Bọ Cạp Thiên Niên Kỷ', 'Côn Trùng', 'Địa', 'Không có', 5, 2000, 1800, 'UR', 0, 3, 'qnx', 'Bọ cạp độc đã tồn tại hàng ngàn năm - ăn thịt con mồi để trở nên mạnh mẽ hơn.', '0'),
(10539, 'Bậc thầy trị liệu bằng hương thơm ·Melissa', 'Thực Vật', 'Thủy', 'Hương Thơm', 6, 2400, 1800, 'UR', 0, 3, 'fxfsxfc', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10540, 'Lò hương liệu', 'Nham Thạch', 'Phong', 'Hương Thơm', 1, 500, 400, 'UR', 0, 3, 'fxl', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10541, 'Chaos Emperor Dragon·Sứ giả của sự kết thúc', 'Rồng', 'Ám', 'Không có', 8, 3000, 2500, 'UR', 0, 2, 'hddlzydsz', 'Một biểu tượng của thời đại.', '0'),
(10542, 'Thành viên F·F·F', 'Pháp Sư', 'Thủy', 'Không có', 3, 1100, 1100, 'SR', 0, 3, 'fffty', 'Họ xuất hiện thành từng đÁm Tộc - và ở đâu có cặp đôi thì ở đó có nhóm.', '0'),
(10543, 'Tay bắn tỉa của Poseidon', 'Hải Long', 'Hỏa', 'Hải Hoàng', 3, 1400, 0, 'UR', 0, 3, 'hhdjjb', 'Quái Thú bao gồm Quái Thú thuộc tính nước và rồng biển. Hầu hết các hình dạng đều là sinh vật hình rồng huyền thoại sống dưới biển sâu. <Hải Vương Long Posedra> là hoàng đế cầm quyền.', '0'),
(10544, 'Cơn thịnh nộ của vực sâu', 'Cá', 'Hỏa', 'Không có', 5, 0, 0, 'UR', 0, 3, 'shzn', 'Con Quái Thú ẩn nấp dưới biển sâu thường hiền lành nhưng khi nó nổi giận thì không ai có thể ngăn cản được.', '0'),
(10545, 'Kiến thú ăn kiến ​​khổng lồ', 'Côn Trùng', 'Địa', 'Không có', 5, 2000, 500, 'UR', 0, 3, 'sdsysy', 'Anh ta cực kỳ bị Ám Tộc ảnh bởi Phép Thuật và Cạm Bẫy và coi chúng là món ăn ngon nhất thế giới.', '0'),
(10546, 'Mã thông báo Nữ hoàng côn trùng', 'Côn Trùng', 'Địa', 'Không có', 1, 100, 100, 'UR', 0, 3, 'kcnwysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10547, 'Mã thông báo quân đội', 'Côn Trùng', 'Địa', 'Không có', 4, 500, 1200, 'UR', 0, 3, 'bdysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10548, 'Bộ đồ điện tử Harpy', 'Chim Thú', 'Phong', 'Harpie', 4, 1800, 1300, 'UR', 0, 3, 'ysnldzjszs', 'Cô gái Harpy mặc một bộ trang phục bó sát điện tử - khả năng tấn công và phòng thủ của cô ấy đã được tăng cường.', '0'),
(10549, 'bọ sừng kiếm', 'Côn Trùng', 'Địa', 'Không có', 6, 2400, 600, 'UR', 0, 3, 'jjjc', 'Chiếc sừng khổng lồ trên đầu được cấu tạo từ các nguyên tố ánh sáng thuần khiết và có hiệu ứng đốt cháy khi tấn công.', '0'),
(10550, 'Hades - Quỷ vương của thế giới ngầm', 'Ác Ma', 'Ám', 'Không có', 6, 2450, 1600, 'UR', 0, 3, 'mjdmwhds', 'Quỷ vương của thế giới ngầm sở hữu dấu ấn máy bay của thế giới ngầm và có thể chỉ huy tất cả sinh vật trong toàn bộ thế giới ngầm.', '0'),
(10551, 'Rùa chiến binh Phép Thuật', 'Chiến Sĩ', 'Hỏa', 'Chiến Binh Ma Thuật', 4, 1400, 900, 'SR', 0, 3, 'mzzssg', 'Một chiến binh Phép Thuật xuất hiện dưới hình dạng quái thú thần thoại <Xuanwu> và có khả năng điều khiển nước.', '0'),
(10552, 'Ruồi quỹ đạo', 'Côn Trùng', 'Địa', 'Không có', 3, 2000, 2000, 'UR', 0, 3, 'jy', 'Khi có bạn đồng hành - bạn sẽ trở nên mạnh mẽ hơn.', '0'),
(10553, 'Đội quân châu chấu', 'Côn Trùng', 'Ám', 'Không có', 3, 1000, 500, 'SR', 0, 3, 'hcdjs', 'Bầy châu chấu đi đến đâu không để lại một hạt lương thực nào.', '0'),
(10554, 'bọ rùa vàng', 'Côn Trùng', 'Quang', 'Không có', 1, 0, 0, 'SR', 0, 3, 'hjpc', 'Toàn thân bọ rùa đang tỏa ra ánh sáng. Khi đến gần nó - bạn có thể cảm thấy cơ thể và tâm trí mình tràn đầy năng lượng.', '0'),
(10555, 'Nhện đen', 'Côn Trùng', 'Ám', 'Không có', 1, 0, 0, 'SR', 0, 3, 'ahzz', 'Nhện ẩn mình trong bóng tối - chờ đợi con mồi đến gần.', '0'),
(10556, 'Tiên hoa hồng', 'Thực Vật', 'Phong', 'Hoa Hồng', 3, 600, 1200, 'SR', 0, 3, 'qwyj', 'Những linh hồn sống trong hoa hồng được cho là sẽ Ma Phápng lại phước lành cho những ai nhìn thấy chúng.', '0'),
(10557, 'Cây xương rồng nhỏ gần hơn', 'Thực Vật', 'Địa', 'Không có', 4, 1800, 300, 'UR', 0, 3, 'xxrzfbz', 'Một cây xương rồng nhỏ dễ thương nhưng đôi mắt lại hung dữ.', '0'),
(10558, 'Phượng Vương Thú Giáp La', 'Chim Thú', 'Phong', 'Không có', 6, 2500, 1200, 'UR', 0, 3, 'fwsjll', 'Một trong ba người hầu của Robin. Con chim khổng lồ kỳ lạ. Nó bay trên bầu trời với tốc độ siêu thanh và có thể phun lửa khi tấn công.', '0'),
(10559, 'Người quen của Hades', 'Ác Ma', 'Ám', 'Không có', 2, 700, 700, 'UR', 0, 3, 'hdsdsm', 'Một cấp dưới trung thành của Hades - người có thể củng cố sức mạnh của những con quỷ khác.', '0'),
(10560, 'Thiên thần sa ngã Geralt', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 8, 2800, 2300, 'UR', 0, 3, 'dtsjlt', 'Thủ lĩnh của các thiên thần sa ngã thường giành chiến thắng trong một cuộc chiến liều lĩnh.', '0'),
(10561, 'Tế bào máu siêu nóng', 'Chiến Sĩ', 'Thủy', 'Không có', 3, 500, 1000, 'SR', 0, 3, 'crxqe', 'Đàn ông máu nóng nên giải phóng hormone trong các trận bóng chày.', '0'),
(10562, 'Phù Thủy Tộc tím', 'Pháp Sư', 'Ám', 'Không có', 4, 1100, 1200, 'SR', 0, 3, 'zllzmn', 'Một Phù Thủy yêu cây cối đã tức giận đến mức những bông hoa tím của cô bị giẫm đạp đến mức cô đã đặt những chiếc Phép & Bẫy quanh nhà mình. Sau này cô được gọi là phù Thủy Tộc.', '0'),
(10563, 'hướng dẫn ảo thuật', 'Pháp Sư', 'Địa', 'Không có', 4, 1700, 1400, 'UR', 0, 3, 'mlydz', 'Với tâm hồn trong sáng - anh có thể đồng bộ với mọi Phù Thủy.', '0'),
(10564, 'Thuyền trưởng biết xử lý mọi việc đúng cách', 'Chiến Sĩ', 'Địa', 'Không có', 3, 1200, 400, 'UR', 0, 3, 'tsllddz', 'Thuyền trưởng là một đầu bếp rất giỏi - các thành viên trong đội đều nói đùa rằng thuyền trưởng sinh ra đã nhầm giới tính.', '0'),
(10565, 'Chim có cánh khiên', 'Chim Thú', 'Phong', 'Không có', 2, 0, 900, 'UR', 0, 3, 'dygn', 'Việc gấp đôi cánh của nó giống như một thành phố kiên cố không ai có thể phá vỡ được.', '0'),
(10566, 'cá mập xúc tu', 'Cá', 'Hỏa', 'Không có', 6, 2400, 2100, 'UR', 0, 3, 'cws', 'Những con Quái Thú ẩn nấp trong chiến hào tối tăm có thể dễ dàng xé xác kẻ thù bằng móng vuốt như những con dao thép.', '0'),
(10567, 'Hiệp sĩ rồng', 'Rồng', 'Thủy', 'Không có', 7, 2800, 2300, 'UR', 0, 3, 'lzqs', 'Là một con rồng khổng lồ sống trong núi lửa - nó sẽ phản công dữ dội khi đồng đội của nó bị kẻ thù giết chết.', '0'),
(10568, 'xác quỷ', 'Chiến Sĩ', 'Ám', 'Không có', 4, 2100, 500, 'UR', 0, 3, 'smx', 'Những bóng Ma Pháp sinh ra từ hận thù tiêu tan sự oán giận của chúng bằng cách giết chóc.', '0'),
(10569, 'Hướng dẫn của Nephthys', 'Pháp Sư', 'Phong', 'Không có', 2, 600, 600, 'UR', 0, 3, 'nftszydz', 'Nhà tiên tri bảo vệ bộ tộc Fire Feather sẵn sàng hiến tế thân xác của mình vì đức tin.', '0'),
(10570, 'Thần Phượng Hoàng Nephthys', 'Chim Thú', 'Thủy', 'Không có', 8, 2400, 1600, 'UR', 0, 3, 'nftszfhs', 'Phượng hoàng bất tử bị tiêu diệt trong lửa - mỗi lần xuất hiện đều kèm theo những chùm lửa khắp bầu trời.', '0'),
(10571, 'linh hồn thánh thiện', 'Thiên Thần', 'Quang', 'Không có', 6, 2000, 1800, 'UR', 0, 3, 'sszh', 'Những linh hồn không rõ nguồn gốc vẫn được người phàm tôn thờ và cầu nguyện sau khi chết.', '0'),
(10572, 'con chuột khổng lồ', 'Thú', 'Địa', 'Không có', 4, 1400, 1450, 'SR', 0, 3, 'jdls', 'Những con chuột khổng lồ đột biến bằng cách ăn trộm thức ăn từ cống rãnh được cho là đến từ khu vực người lùn.', '0'),
(10573, 'Rồng háu ăn', 'Bò Sát', 'Hỏa', 'Không có', 4, 1900, 700, 'UR', 0, 3, 'tsl', 'Bất cứ thứ gì tồn tại đều có thể trở thành thức ăn và biến thành cặn bã dưới răng nanh của nó.', '0'),
(10574, 'Hoàng đế độc ác Gaius', 'Ác Ma', 'Ám', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'xdgws', 'Vị hoàng đế làm chủ được các yếu tố bóng tối có thể dễ dàng tiêu diệt kẻ thù của mình.', '0'),
(10575, 'Rào cản hạn hán', 'Nham Thạch', 'Địa', 'Không có', 4, 1000, 1000, 'R', 0, 3, 'ghzjjx', 'Ngoại trừ nguyên tố đất - tất cả các nguyên tố khác trong rào chắn sẽ bị loại bỏ.', '0'),
(10576, 'Rào chắn băng·Nhóm Phong Tộc ấn quỷ', 'Pháp Sư', 'Hỏa', 'Kết Giới Băng', 4, 1200, 2000, 'UR', 0, 3, 'bjjdfmt', 'Quái Thú hợp nhất thành thuộc tính nước hạn chế hành động của đối phương bằng cách vận hành kết giới băng - thể hiện sự thiêng liêng và ý chí bất khả xâm phạm của băng.', '0'),
(10577, 'Phù Thủy xanh điêu luyện', 'Pháp Sư', 'Quang', 'Không có', 4, 1800, 1800, 'UR', 0, 3, 'sldqmss', 'Có thể trở thành một Phù Thủy chiến đấu cao cấp hơn sau nhiều năm hiểu biết về Phép Thuật.', '0'),
(10578, 'súng lục ổ quay rồng', 'Máy Móc', 'Ám', 'Không có', 7, 2600, 2200, 'UR', 0, 3, 'zlsql', 'Con rồng chưa bao giờ thua một ván roulette nào - và kết quả duy nhất của việc đánh cược mạng sống của mình là cái chết.', '0'),
(10579, 'Thợ săn cơ khí', 'Máy Móc', 'Ám', 'Không có', 4, 1850, 800, 'UR', 0, 3, 'jxls', 'Tuân theo mệnh lệnh của Vua Máy - nó sẽ truy đuổi ráo riết cho đến khi bắt được mục tiêu.', '0'),
(10580, 'Vua cơ khí', 'Máy Móc', 'Địa', 'Không có', 6, 2200, 2000, 'UR', 0, 3, 'jxw', 'Thủ lĩnh của bộ tộc máy móc sẽ trở nên vô cùng mạnh mẽ với sự hỗ trợ của bộ tộc của mình!', '0'),
(10581, 'pháo vệ tinh', 'Máy Móc', 'Quang', 'Không có', 5, 0, 0, 'UR', 0, 3, 'wxjnp', 'Ánh sáng chiếu giữa các vì sao Ma Phápng đến đòn chí mạng cho kẻ thù.', '0'),
(10582, 'Vua máy hoàn hảo', 'Máy Móc', 'Địa', 'Không có', 8, 2700, 1500, 'UR', 0, 3, 'wmjxw', 'Trong những năm dài - trí tuệ thực sự xuất hiện và chỉ huy đội quân máy móc tiến lên!', '0'),
(10583, 'bom tức thời', 'Máy Móc', 'Phong', 'Không có', 3, 1000, 1000, 'SR', 0, 3, 'szzd', 'Tưởng chừng như một cỗ máy yếu đuối nhưng bỏ bê nó sẽ phải trả giá đắt.', '0'),
(10584, 'Phượng hoàng điện tử', 'Máy Móc', 'Thủy', 'Không có', 4, 1200, 1600, 'SR', 0, 3, 'dzfh', 'Là sản phẩm của một nỗ lực thất bại trong việc bắt chước Phượng Hoàng thật - sức mạnh của Phượng Hoàng đã được gắn sẵn trong cơ thể nó.', '0'),
(10585, 'Keel tối điện tử', 'Máy Móc', 'Ám', 'Điện Tử Bóng Tối', 4, 800, 800, 'UR', 0, 3, 'dzahlg', 'Những con sâu đen tối lang thang trong thế giới ngầm và Nghĩa Địa có sức mạnh điều khiển xương rồng.', '0'),
(10586, 'Súng lục nòng đôi rồng', 'Máy Móc', 'Ám', 'Không có', 4, 1700, 200, 'UR', 0, 3, 'sgsql', 'Một sinh vật máy móc chạy xung quanh với khẩu súng lục hai nòng. Mặc dù mạnh mẽ nhưng nó hiếm khi đánh trúng kẻ thù.', '0'),
(10587, 'người đàn ông đi xe đạp một bánh', 'Máy Móc', 'Địa', 'Không có', 1, 100, 100, 'R', 0, 3, 'dlcr', 'Người đàn ông đi xe đạp một bánh là con thứ ba trong gia đình có hai anh em - người đàn ông đi xe ba bánh và người đàn ông đi xe hai bánh.', '0'),
(10588, 'người đàn ông đi xe hai bánh', 'Máy Móc', 'Địa', 'Không có', 2, 200, 200, 'SR', 0, 3, 'elcr', 'Đối mặt với nguy hiểm không chút do dự - anh đã chiến đấu để bảo vệ những đứa em của mình.', '0'),
(10589, 'người đàn ông đi xe ba bánh', 'Máy Móc', 'Địa', 'Không có', 3, 300, 300, 'SR', 0, 3, 'slcr', 'Anh tuy không mạnh mẽ nhưng luôn bảo vệ anh em mình khi nguy hiểm ập đến.', '0'),
(10590, 'robot băm nhỏ', 'Máy Móc', 'Địa', 'Không có', 4, 1600, 1000, 'SR', 0, 3, 'szjqr', 'Tâm trí anh bị mê hoặc bởi sức mạnh bóng tối và anh phát điên. Lưỡi kiếm sắc bén đủ để nghiền nát bất kỳ sinh vật mạnh mẽ nào.', '0'),
(10591, 'Thép Aye-aye', 'Máy Móc', 'Địa', 'Không có', 4, 1600, 1800, 'UR', 0, 3, 'gtzh', 'Nó trông rất khó khăn. Nếu bạn quấn nó lên - bạn sẽ thấy cơ chế bên trong bị hỏng.', '0'),
(10592, 'Di sản thời tiền sử ·Máy Maya', 'Máy Móc', 'Địa', 'Di Sản Tiền Sử', 3, 1500, 700, 'SR', 0, 3, 'xsycmyjq', 'Sau hàng nghìn năm chờ đợi trong khu rừng nhiệt đới ẩm ướt - nó vẫn sáng bóng như mới khi được khai quật.', '0'),
(10593, 'Cày tuyết nhanh', 'Máy Móc', 'Địa', 'Không có', 10, 2500, 3000, 'UR', 0, 3, 'jscxc', 'Nếu nó đang ngủ trong tuyết và bị đóng băng - bạn sẽ dễ dàng đánh thức nó bằng cách làm nứt lớp băng.', '0'),
(10594, 'Chim ưng cơ khí', 'Máy Móc', 'Phong', 'Không có', 4, 1400, 1200, 'SR', 0, 3, 'jxly', 'Được trang bị động cơ phản lực - Eagle có thể bay với tốc độ siêu thanh.', '0'),
(10595, 'đầu nhọn', 'Máy Móc', 'Ám', 'Không có', 4, 1800, 1700, 'UR', 0, 3, 'jdt', 'Những người lính robot do các Phù Thủy Địa ngục tạo ra liên tục tấn công kẻ thù bằng những quả bóng sắt trên tay.', '0'),
(10596, 'Artemis của Feng Rang', 'Thiên Thần', 'Quang', 'Không có', 4, 1600, 1700, 'UR', 0, 1, 'frzaetms', 'Những người tin vào Thần Săn bắt và Thu hoạch tạo ra một hình ảnh sai lệch về đức tin của họ để bảo vệ một nơi khi thời tiết thuận lợi.', '0'),
(10597, 'Con rối Phép Thuật', 'Pháp Sư', 'Ám', 'Không có', 5, 2000, 1000, 'UR', 0, 3, 'mfczro', 'Kéo sợi chỉ vào những góc tối và điều khiển con rối xé nát kẻ thù thành từng mảnh.', '0'),
(10598, 'Vua Chim Alect', 'Chim Thú', 'Phong', 'Không có', 6, 2400, 2000, 'UR', 0, 1, 'sqwylkt', 'Hãy đến nhân danh gió và vỗ cánh để tạo ra những cơn bão.', '0'),
(10602, 'Phù Thủy hỗn loạn', 'Pháp Sư', 'Ám', 'Không có', 6, 2300, 2000, 'UR', 0, 3, 'hdws', 'Công lý là ai? Nó có nhẹ không? Trời có tối không? Hay tôi?', '0'),
(10603, 'Cá thái dương bom kim', 'Cá', 'Hỏa', 'Không có', 3, 1500, 100, 'UR', 0, 3, 'zdfcy', 'Có những chiếc kim cực độc được giấu trong miệng - dùng để phản công chết người đối phương.', '0'),
(10604, 'Thần Sấm', 'Sấm Sét', 'Địa', 'Không có', 4, 2000, 1600, 'UR', 0, 3, 'lds', 'Su Zhanwu Zun (スサノオ) khiến dư ảnh Ma Phápng theo một thanh kiếm gà Lôi Tộc cỏ đến thế gian - sợ rằng trái đất sẽ sụp đổ và phải trở về thiên giới.', '0'),
(10605, 'Ếch vẽ thiệp', 'Thủy Tộc', 'Hỏa', 'Ếch', 2, 100, 100, 'SR', 0, 3, 'ckqw', 'Nó có đôi mắt giống như radar và sử dụng cái lưỡi của mình để Ma Phápng lại sự giàu có mà nó mong muốn cho chủ nhân của mình.', '0'),
(10606, 'Rồng trắng mắt vực thẳm', 'Rồng', 'Quang', 'Không có', 10, 0, 0, 'UR', 0, 3, 'yybl', 'Cô ấy có đôi mắt vô cùng đẹp - chỉ cần nhìn vào chúng cũng sẽ hút hồn.', '0'),
(10607, 'quả bom roulette', 'Máy Móc', 'Quang', 'Xúc Xắc Speedroid', 4, 1000, 2000, 'UR', 0, 3, 'lpzd', 'Roulette quay quyết định số phận - cuộc đời? Có phải là cái chết?', '0'),
(10608, 'chuồn chuồn', 'Côn Trùng', 'Phong', 'Không có', 4, 1400, 900, 'SR', 0, 3, 'qt', 'Chuồn chuồn khổng lồ thậm chí có thể tạo ra lốc xoáy khi vỗ cánh mạnh mẽ.', '0'),
(10609, 'Nuốt gió máu', 'Chim Thú', 'Ám', 'Không có', 4, 1700, 1000, 'UR', 0, 3, 'xfy', 'Trong thời gian tán tỉnh - chim én đực sẽ hót cho đến khi nôn ra máu và rất trân trọng bạn tình của mình.', '0'),
(10610, 'Người sói tổng hợp', 'Chiến Sĩ Thú', 'Địa', 'Không có', 6, 2400, 1800, 'UR', 0, 3, 'hclr', 'Một người sói trốn thoát khỏi phòng thí nghiệm nhưng sở hữu trí thông minh của con người.', '0'),
(10611, 'Cá đuối ăn thịt người bầu trời', 'Hải Long', 'Phong', 'Không có', 3, 600, 300, 'SR', 0, 3, 'tgsrff', 'Cá đuối biết bay - rất thích máu người.', '0'),
(10612, 'Chiến binh Raz', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1600, 1200, 'SR', 0, 3, 'zslz', 'Một người lính luôn đi đầu nhưng hiếm khi bị thương.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10613, 'cung thủ vội vàng', 'Chiến Sĩ', 'Phong', 'Không có', 6, 1200, 1800, 'SR', 0, 3, 'jccgs', 'Tốc độ tấn công và tốc độ di chuyển rất nhanh nhưng sức bền và sức chịu đựng đều là điểm yếu.', '0'),
(10614, 'Rồng biển sâu ẩn nấp dưới đáy biển', 'Hải Long', 'Hỏa', 'Không có', 4, 1700, 1400, 'SR', 0, 3, 'qfhddshl', 'Rồng biển ẩn nấp ở nơi sâu nhất của biển. Nó ở trong trạng thái ngủ quanh năm. Nếu nó bị đánh thức - nó sẽ gây ra thảm họa.', '0'),
(10615, 'Thợ thủ công nổi tiếng·Hổ sắt', 'Chiến Sĩ Thú', 'Thủy', 'Không có', 2, 500, 500, 'SR', 0, 3, 'mjth', 'Anh ấy giỏi chế tạo những thanh kiếm nổi tiếng và mọi người trên khắp thế giới đang yêu cầu một trong những tác phẩm của anh ấy.', '0'),
(10616, 'Cướp một con thằn lằn bay', 'Máy Móc', 'Ám', 'Không có', 4, 1800, 0, 'UR', 0, 3, 'jcyl', 'Những con thằn lằn chỉ xuất hiện dưới vực thẳm có thể điều khiển linh hồn của người chết.', '0'),
(10617, 'Chiến Binh Hỗn Độn', 'Chiến Sĩ', 'Địa', 'Chiến Binh Hỗn Độn', 8, 3000, 2500, 'UR', 0, 3, 'hdzs', 'Một chiến binh huyền thoại có sức chiến đấu ngang ngửa với Rồng Trắng Mắt Xanh.', '0'),
(10618, 'Người đổ xăng', 'Máy Móc', 'Địa', 'Không có', 2, 400, 400, 'UR', 0, 3, 'qyx', 'Một robot phụ trợ siêu mạnh có thể kết hợp hoàn hảo với mọi máy móc.', '0'),
(10619, 'Những con rồng của Poseidon', 'Hải Long', 'Hỏa', 'Hải Hoàng', 4, 1800, 0, 'UR', 0, 3, 'hhdlqd', 'Quái Thú bao gồm Quái Thú thuộc tính nước và rồng biển. Hầu hết các hình dạng đều là sinh vật hình rồng huyền thoại sống dưới biển sâu. <Hải Vương Long Posedra> là hoàng đế cầm quyền.', '0'),
(10620, 'Rồng thép đen', 'Rồng', 'Ám', 'Mắt Đỏ', 1, 600, 600, 'UR', 0, 3, 'hgl', 'Một Bộ Bài được xây dựng với <Red Eyes Black Dragon> làm cốt lõi - có nhiều phương pháp triệu hồi khác nhau. Lá bài yêu thích của Katsuya Jonouchi.', '0'),
(10621, 'Rồng bay mắt đỏ thật', 'Rồng', 'Phong', 'Mắt Đỏ', 4, 1800, 1600, 'UR', 0, 3, 'zhyfl', 'Một Bộ Bài được xây dựng với <Red Eyes Black Dragon> làm cốt lõi - có nhiều phương pháp triệu hồi khác nhau. Lá bài yêu thích của Katsuya Jonouchi.', '0'),
(10622, 'Rồng Bóng Đêm Mắt Đỏ', 'Rồng', 'Ám', 'Mắt Đỏ', 9, 2400, 2000, 'UR', 0, 3, 'zhyal', 'Một Bộ Bài được xây dựng với <Red Eyes Black Dragon> làm cốt lõi - có nhiều phương pháp triệu hồi khác nhau. Lá bài yêu thích của Katsuya Jonouchi.', '0'),
(10623, 'cô gái tuyết', 'Pháp Sư', 'Quang', 'Không có', 4, 1600, 1800, 'UR', 0, 3, 'xn', 'Chỉ có đỉnh núi phủ đầy tuyết xuất hiện - nhìn thấy hình dáng xinh đẹp của nó cũng là dấu hiệu cho thấy cuộc sống sắp kết thúc.', '0'),
(10624, 'Cô gái Phép Thuật hắc Ám Tộc ·Trang phục Giáng sinh', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 6, 2000, 1700, 'UR', 0, 3, 'hmsss', 'Đệ tử đáng tự hào nhất của Phù Thủy bóng tối. Mặc trang phục Giáng sinh.', '|Giải thích|\\nViệc tăng sức tấn công của Cô gái Phép Thuật bóng tối chỉ liên quan đến số lượng Phù Thủy bóng tối trong Nghĩa Địa của cả hai bên và không liên quan gì đến Phù Thủy bóng tối trên sân. Các Phù Thủy Bóng tối bị loại sẽ không được tính vào phần thưởng sức mạnh tấn công\\n\\n|Kết hợp chung|\\nCô gái Phép Thuật bóng tối +Đá quý hiền triết - triệu hồi đặc biệt Phù Thủy bóng tối\\nVòng tròn Phù Thủy - triệu hồi đặc biệt Cô gái Phép Thuật bóng tối+Đá quý hiền nhân - triệu hồi đặc biệt Phù Thủy bóng tối\\nCô gái Phép Thuật bóng tối+Phù Thủy bóng tối+Ma thuật vụ nổ đen\\nCô gái Phép Thuật bóng tối+Ma thuật vụ nổ đen'),
(10625, 'Cây gậy Phù Thủy', 'Pháp Sư', 'Ám', 'Không có', 3, 1600, 100, 'UR', 0, 3, 'msszz', 'Cây trượng yêu thích của Phù Thủy bóng tối đã phát triển ý thức của chính anh ta sau khi theo dõi anh ta trong nhiều năm.', '0'),
(10626, 'Áo choàng phù Thủy Tộc', 'Pháp Sư', 'Ám', 'Không có', 2, 700, 2000, 'UR', 0, 3, 'msszp', 'Chiếc áo choàng yêu thích của Phù Thủy bóng tối đã phát triển ý thức của chính mình sau khi theo dõi anh ta trong nhiều năm.', '0'),
(10627, 'rùa đĩa bay', 'Máy Móc', 'Thủy', 'Không có', 4, 1400, 1200, 'SR', 0, 3, 'fdg', 'Cơ thể khổng lồ có thể chứa được hầu hết các đồ vật và được gọi là <hòm nguyên Thủy Tộc>.', '0'),
(10628, 'Tượng nghiệp chướng lửa', 'Hỏa Tộc', 'Thủy', 'Không có', 4, 1000, 1000, 'R', 0, 3, 'yhzjjx', 'Ngoại trừ yếu tố lửa - tất cả các yếu tố khác trong rào chắn sẽ bị ép ra ngoài.', '0'),
(10629, 'Khủng long bạo chúa tuyết', 'Rồng', 'Hỏa', 'Không có', 4, 1800, 1000, 'UR', 0, 3, 'xbl', 'Nằm trong Con mắt của Vùng Cực - quanh năm có bão tuyết và sóng gió nhưng đây lại là môi trường sống ưa thích của loài Khủng long bạo chúa tuyết.', '0'),
(10630, 'gấu túi chết', 'Thú', 'Ám', 'Không có', 3, 1100, 1800, 'SR', 0, 3, 'swsx', 'Nó thường ngốc nghếch và thích ăn lá cây. Một khi việc ăn uống của nó bị xáo trộn - nó sẽ trở nên cực kỳ cáu kỉnh.', '0'),
(10631, 'Bậc thầy hủy diệt linh hồn Hải Kông', 'Pháp Sư', 'Ám', 'Không có', 4, 1800, 700, 'UR', 0, 3, 'mlsshk', 'Một lá bài dựa trên người sáng lập giáo phái Shingon của Phật giáo Nhật Bản.', '0'),
