(10692, 'rồng ác', 'Rồng', 'Ám', 'Không có', 5, 2000, 2400, 'UR', 0, 3, 'el', 'Một con rồng làm đủ mọi điều ác - câu khẩu hiệu của nó là <Tôi sinh ra để hủy diệt>', '0'),
(10693, 'Hoàng đế băng giá Mebius', 'Thủy Tộc', 'Hỏa', 'Không có', 8, 2800, 1000, 'UR', 0, 3, 'dbdmbws', 'Dạng cuối cùng tiến hóa của Ice King.', '0'),
(10694, 'Rồng Địa Tộc ngục', 'Rồng', 'Thủy', 'Không có', 6, 2400, 1500, 'UR', 0, 3, 'dydwl', 'Áp lực do vị vua chỉ huy tộc rồng trong Địa Tộc ngục tạo ra không phải là thứ mà những sinh vật Địa Tộc ngục bình thường có thể chịu được.', '0'),
(10695, 'Rồng bay cơ học cổ đại', 'Máy Móc', 'Địa', 'Cơ Khí Cổ Đại', 4, 1700, 1200, 'UR', 0, 3, 'gdjxfl', 'Quái Thú bao gồm thuộc tính đất và loại máy móc - và hầu hết Quái Thú đều có hiệu ứng chặn vùng bẫy mạnh mẽ.', '0'),
(10696, 'Chó săn cơ khí cổ đại', 'Máy Móc', 'Địa', 'Cơ Khí Cổ Đại', 3, 1000, 1000, 'UR', 0, 3, 'gdjxlq', 'Quái Thú bao gồm thuộc tính đất và loại máy móc - và hầu hết Quái Thú đều có hiệu ứng chặn vùng bẫy mạnh mẽ.', '0'),
(10697, 'Xe cơ khí cổ', 'Máy Móc', 'Địa', 'Cơ Khí Cổ Đại', 2, 100, 800, 'UR', 0, 3, 'gdjxcc', 'Quái Thú bao gồm thuộc tính đất và loại máy móc - và hầu hết Quái Thú đều có hiệu ứng chặn vùng bẫy mạnh mẽ.', '0'),
(10698, 'Người khổng lồ cơ khí cổ đại', 'Máy Móc', 'Địa', 'Cơ Khí Cổ Đại', 8, 3000, 3000, 'UR', 0, 3, 'gdjxjr', 'Quái Thú bao gồm thuộc tính đất và loại máy móc - và hầu hết Quái Thú đều có hiệu ứng chặn vùng bẫy mạnh mẽ.', '0'),
(10699, 'Hiệp sĩ rồng trắng', 'Rồng', 'Quang', 'Không có', 4, 1900, 1200, 'UR', 0, 3, 'blzsqs', 'Những người rất thân thiết với tộc Rồng Trắng Mắt Xanh có thể có một con rồng trắng làm thú cưỡi.', '0'),
(10700, 'Hiệp sĩ rồng đen', 'Rồng', 'Ám', 'Không có', 4, 1900, 1200, 'UR', 0, 3, 'hlzsqs', 'Chỉ những người rất thân thiết với tộc rồng đen mắt đỏ mới có thể cưỡi rồng đen làm vật cưỡi.', '0'),
(10701, 'Dẫn xuất cơ khí cổ đại', 'Máy Móc', 'Địa', 'Cơ Khí Cổ Đại', 1, 0, 0, 'N', 0, 3, 'gdjxysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10702, 'Các dẫn xuất của Black Feather và Black Crown', 'Chim Thú', 'Ám', 'Kuriboh', 2, 0, 800, 'N', 0, 3, 'gdjxccysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10703, 'Rồng trắng châu Á mắt xanh', 'Rồng', 'Quang', 'Mắt Xanh', 8, 3000, 2500, 'UR', 0, 3, 'qyybl', 'Những con Rồng Trắng Mắt Xanh thỉnh thoảng xuất hiện trong nhóm. Mặc dù có một số khuyết điểm nhưng khả năng chiến đấu của họ mạnh hơn những người khác.', '0'),
(10704, 'Thiên thần sa ngã Lucifer', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 11, 3000, 3000, 'UR', 0, 3, 'dtslxf', 'Cựu tổng lãnh thiên thần - người sau này rơi xuống Địa Tộc ngục - là tổng chỉ huy của các thiên thần sa ngã.', '0'),
(10705, 'hiền nhân mắt xanh', 'Pháp Sư', 'Quang', 'Mắt Xanh', 1, 0, 1500, 'UR', 0, 3, 'qsyjdxs', 'Một nhóm người có cùng màu mắt với Rồng Trắng Mắt Xanh - linh hồn cư trú trong cơ thể họ.', '0'),
(10706, 'Linh mục với đôi mắt xanh', 'Pháp Sư', 'Quang', 'Mắt Xanh', 1, 300, 1200, 'UR', 0, 3, 'qsyjdjs', 'Một nhóm người có cùng màu mắt với Rồng Trắng Mắt Xanh - linh hồn cư trú trong cơ thể họ.', '0'),
(10707, 'Hiệp sĩ bóng đêm tốc độ Gaia', 'Chiến Sĩ', 'Quang', 'Kỵ Sĩ Gaia', 7, 2300, 2100, 'UR', 0, 3, 'jzdahqsgy', 'Đối thủ của <Hayate\'s Dark Knight Gaia> - cả hai sẽ cạnh tranh không ngừng nghỉ một khi gặp nhau.', '0'),
(10710, 'Balon Quái Thú Hỏa Vương', 'Chiến Sĩ Thú', 'Thủy', 'Thú Vua Lửa', 4, 1800, 200, 'UR', 0, 3, 'ywsbl', '<Fire King> Quái thú này có khả năng được triệu hồi từ tay khi đồng minh của nó bị tiêu diệt bởi hiệu ứng bài. Các hiệu ứng khác nhau cũng có thể được kích hoạt khi nó bị phá hủy và đưa đến Nghĩa Địa.', '0'),
(10711, 'Hỏa Vương Thú · Dạ Xoa', 'Chiến Sĩ Thú', 'Thủy', 'Thú Vua Lửa', 4, 1800, 200, 'UR', 0, 3, 'ywsyc', '<Fire King> Quái thú này có khả năng được triệu hồi từ tay khi đồng minh của nó bị tiêu diệt bởi hiệu ứng bài. Các hiệu ứng khác nhau cũng có thể được kích hoạt khi nó bị phá hủy và đưa đến Nghĩa Địa.', '0'),
(10712, 'Hỏa Vương Thú · Đại Bằng Phượng Hoàng', 'Chim Thú', 'Thủy', 'Thú Vua Lửa', 3, 700, 1700, 'SR', 0, 3, 'ywsdpbsn', '<Fire King> Quái thú này có khả năng được triệu hồi từ tay khi đồng minh của nó bị tiêu diệt bởi hiệu ứng bài. Các hiệu ứng khác nhau cũng có thể được kích hoạt khi nó bị phá hủy và đưa đến Nghĩa Địa.', '0'),
(10715, 'Anh hùng nguyên tố · Cô gái lửa', 'Hỏa Tộc', 'Thủy', 'Anh Hùng Nguyên Tố', 4, 1300, 1000, 'SR', 0, 3, 'ysyxhynl', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10716, 'Hoàng đế độc ác Gaius', 'Ác Ma', 'Ám', 'Không có', 8, 2800, 1000, 'UR', 0, 3, 'yxdgws', 'Hình thức tiến hóa tối thượng của Hoàng đế Ác Ma Pháp.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10717, 'Chiến binh rồng gió Phép Thuật', 'Chiến Sĩ', 'Phong', 'Chiến Binh Ma Thuật', 5, 2000, 800, 'UR', 0, 3, 'mzzsfl', 'Một chiến binh Phép Thuật xuất hiện dưới hình dạng quái thú thần thoại <Rồng xanh> và có khả năng điều khiển gió.', '0'),
(10718, 'Anh hùng nguyên tố · Người đại dương', 'Chiến Sĩ', 'Hỏa', 'Anh Hùng Nguyên Tố', 4, 1500, 1200, 'SR', 0, 3, 'ysyxhyx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10719, 'Chiến binh Phép Thuật Dihu', 'Chiến Sĩ', 'Địa', 'Chiến Binh Ma Thuật', 4, 1800, 1200, 'UR', 0, 3, 'mzzsdh', 'Một chiến binh Phép Thuật xuất hiện dưới hình dạng quái thú thần thoại <Bạch Hổ> và có khả năng thao túng trái đất.', '0'),
(10720, 'Người bảo vệ đôi mắt xanh', 'Pháp Sư', 'Quang', 'Mắt Xanh', 1, 800, 1300, 'UR', 0, 3, 'qsyjdhr', 'Một nhóm người có cùng màu mắt với Rồng Trắng Mắt Xanh - linh hồn cư trú trong cơ thể họ.', '0'),
(10721, 'Thần có ngàn tay', 'Thiên Thần', 'Quang', 'Không có', 4, 1400, 1000, 'SR', 0, 3, 'qss', 'Vị thần có nghìn tay.', '0'),
(10722, 'Côn trùng tối thượng·LV1', 'Côn Trùng', 'Phong', 'LV', 1, 0, 0, 'R', 0, 3, 'jjkcy', 'Côn trùng có thể tiến hóa liên tục.', '0'),
(10723, 'Côn trùng tối thượng·LV3', 'Côn Trùng', 'Phong', 'LV', 3, 1400, 900, 'SR', 0, 3, 'jjkcs', 'Côn trùng có thể tiến hóa liên tục.', '0'),
(10724, 'Côn trùng tối thượng·LV5', 'Côn Trùng', 'Phong', 'LV', 5, 2300, 900, 'UR', 0, 3, 'jjkcw', 'Côn trùng có thể tiến hóa liên tục.', '0'),
(10725, 'Côn trùng tối thượng·LV7', 'Côn Trùng', 'Phong', 'LV', 7, 2600, 1200, 'UR', 0, 3, 'jjkcq', 'Sự tiến hóa hoàn chỉnh của loài côn trùng tối thượng.', '0'),
(10726, 'Người rừng anh hùng nguyên tố', 'Chiến Sĩ', 'Địa', 'Anh Hùng Nguyên Tố', 4, 1000, 2000, 'UR', 0, 3, 'ysyxslx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10727, 'Rồng quỷ Zahak', 'Rồng', 'Ám', 'Linh Hồn Nhập', 4, 1850, 850, 'UR', 0, 3, 'rmylzhk', 'Một Bộ Bài thuộc tính bóng tối có chiến thuật chính là hạn chế Quái Thú từ 5 sao trở lên và ngăn chặn đối phương mở rộng thêm.', '0'),
(10728, 'Quá muộn rồi Orc', 'Ác Ma', 'Ám', 'Không có', 4, 2200, 0, 'UR', 0, 3, 'gcdsr', 'Orc phản ứng chậm nhưng cực kỳ tàn phá.', '0'),
(10729, 'Kỵ binh quỷ', 'Ác Ma', 'Ám', 'Ác Ma', 4, 1900, 0, 'UR', 0, 3, 'emqb', 'Đội tiên Phong Tộc của quân đội quỷ có hiệu quả chiến đấu rất mạnh và có thể tiếp tục ảnh hưởng đến tình hình trận chiến ngay cả khi họ chết.', '0'),
(10730, 'Sao quỷ', 'Ác Ma', 'Ám', 'Ác Ma', 6, 2500, 1200, 'UR', 0, 3, 'emjx', 'Các tướng trong quân đội quỷ có thể triệu hồi những con quỷ mạnh mẽ.', '0'),
(10731, 'Hoàng đế hung dữ run rẩy: Ác Ma Pháp tổ tiên', 'Ác Ma', 'Ám', 'Ác Ma', 8, 3000, 2000, 'UR', 0, 3, 'zlzxhszem', 'Chỉ huy tối cao của quân đoàn quỷ sở hữu sức mạnh vô cùng mạnh mẽ.', '0'),
(10732, 'Phong cách tà ác Quái Thú mực gió Ma Pháp quái', 'Thủy Tộc', 'Hỏa', 'Di Sản Tinh Tú', 6, 2400, 1000, 'UR', 0, 3, 'xysyfwzg', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(10733, 'Siêu chiến binh·Chiến binh hỗn loạn', 'Chiến Sĩ', 'Địa', 'Chiến Binh Hỗn Độn', 8, 3000, 2500, 'UR', 0, 3, 'czshdzs', 'Khi một Chiến binh hỗn loạn đánh thức Linh hồn siêu chiến binh - anh ta có thể trở thành một chiến binh mạnh mẽ hơn.', '0'),
(10734, 'chim âm thanh', 'Chim Thú', 'Phong', 'Không có', 4, 1400, 1000, 'SR', 0, 3, 'ysn', 'Loài chim bay với tốc độ âm thanh nhưng thực chất là nhờ sự trợ giúp của khoa học.', '0'),
(10735, 'Protoceratops kỷ Jura', 'Khủng Long', 'Thủy', 'Jurrac', 4, 1700, 1200, 'UR', 0, 3, 'zljyjl', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(10736, 'người điều phối vật liệu', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1300, 800, 'SR', 0, 3, 'wzddy', 'Những người điều phối cân bằng vật liệu thường đi khắp thế giới.', '0'),
(10737, 'Giun khiên', 'Côn Trùng', 'Địa', 'Trùng Tộc', 4, 800, 2000, 'UR', 0, 3, 'dc', 'Một loài côn trùng có thân hình khỏe mạnh khác thường không có không gian chết khi cuộn tròn.', '0'),
(10738, 'hiệp sĩ chỉ huy', 'Chiến Sĩ', 'Thủy', 'Không có', 4, 1200, 1900, 'UR', 0, 3, 'zhqs', 'Mặc dù với tư cách là một người chỉ huy - tài năng chiến đấu thực tế vẫn quan trọng hơn khả năng chỉ huy.', '|Mô tả|\\nKhông giống như Magic Valkyrie - sự hiện diện của hai hiệp sĩ chỉ huy của riêng mình sẽ không gây ra những lời chế nhạo kép và đối phương vẫn có thể tấn công hiệp sĩ chỉ huy. \\nKhi hiệp sĩ chỉ huy của bạn được trang bị bánh xe từ tính - nếu có quái thú khác trên sân phe ta - đối phương không thể tấn công hiệp sĩ chỉ huy của bạn và không thể tấn công Quái Thú khác.'),
(10739, 'Chiến hạm khổng lồ · lõi khổng lồ', 'Máy Móc', 'Ám', 'Chiến Hạm Khổng Lồ', 6, 2300, 1100, 'SR', 0, 3, 'jdzjjh', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10740, 'hiệp sĩ đồ chơi', 'Máy Móc', 'Địa', 'Không có', 4, 200, 1200, 'SR', 0, 3, 'wjqs', 'Toàn thân đều làm bằng đồ chơi - không biết ai đã cho nó sự sống.', '0'),
(10741, 'Cổng Địa Tộc ngục Brad', 'Zombie', 'Ám', 'Không có', 6, 2100, 800, 'UR', 0, 3, 'dydmfbld', 'Người gác cổng Địa Tộc ngục có thể mở cổng Địa Tộc ngục từ bên trong cơ thể.', '0'),
(10742, 'triệu hồi quỷ', 'Pháp Sư', 'Ám', 'Không có', 6, 2400, 2000, 'UR', 0, 3, 'mzzhs', 'Một Phù Thủy đã ký một hợp đồng bí ẩn với lũ quỷ - nhưng dưới sự ảnh hưởng của lũ quỷ - anh ta trông không còn giống con người nữa.', '0'),
(10743, 'Quái Thú hoang dã từ không gian khác', 'Thú', 'Địa', 'Không có', 3, 1400, 1400, 'SR', 0, 3, 'ycydks', 'Một con Quái Thú có thể di chuyển giữa các chiều không gian.', '0'),
(10744, 'Phù Thủy', 'Pháp Sư', 'Ám', 'Không có', 3, 600, 700, 'SR', 0, 3, 'hymss', 'Một Phù Thủy cải trang thành bất cứ ai thông qua ảo ảnh.', '0'),
(10745, 'bức tường tự nhiên', 'Nham Thạch', 'Địa', 'Tự Nhiên', 4, 1500, 1000, 'SR', 0, 3, 'zrb', 'Bao gồm nhiều chủng tộc khác nhau gần gũi với thiên nhiên - họ là những tinh linh thiên nhiên vô cùng dễ thương.', '0'),
(10746, 'người bảo vệ thiên nhiên', 'Thực Vật', 'Địa', 'Tự Nhiên', 4, 1600, 400, 'SR', 0, 3, 'zrshz', 'Bao gồm nhiều chủng tộc khác nhau gần gũi với thiên nhiên - họ là những tinh linh thiên nhiên vô cùng dễ thương.', '0'),
(10747, 'Chola Ji Gua Balong', 'Khủng Long', 'Thủy', 'Jurrac', 4, 1700, 400, 'SR', 0, 3, 'zljgbl', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(10748, 'cô gái Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 4, 1550, 1550, 'SR', 0, 3, 'xxgnl', 'Một nữ Ma Pháp cà rồng đi lại giữa các quý tộc và chơi đùa với họ.', '0'),
(10749, 'Cô gái Phép Thuật Berry', 'Pháp Sư', 'Địa', 'Nữ Phù Thủy', 1, 400, 400, 'UR', 0, 3, 'jgmfsn', 'Lá bài độc quyền cho Muto Games. Mỗi cô gái Phép Thuật được đặt tên theo một loại trái cây. Theo thứ tự cấp độ - các chữ cái đầu tiên trong tên tiếng Anh của họ có dạng <BLACK>.', '0'),
(10750, 'cô gái Phép Thuật chanh', 'Pháp Sư', 'Quang', 'Nữ Phù Thủy', 2, 800, 600, 'UR', 0, 3, 'nmmfsn', 'Lá bài độc quyền cho Muto Games. Mỗi cô gái Phép Thuật được đặt tên theo một loại trái cây. Theo thứ tự cấp độ - các chữ cái đầu tiên trong tên tiếng Anh của họ có dạng <BLACK>.', '0'),
(10751, 'Cô gái Phép Thuật Kiwi', 'Pháp Sư', 'Phong', 'Nữ Phù Thủy', 5, 1800, 1200, 'UR', 0, 3, 'qygmfsn', 'Lá bài độc quyền cho Muto Games. Mỗi cô gái Phép Thuật được đặt tên theo một loại trái cây. Theo thứ tự cấp độ - các chữ cái đầu tiên trong tên tiếng Anh của họ có dạng <BLACK>.', '0'),
(10752, 'Cô gái Phép Thuật sô cô la', 'Pháp Sư', 'Hỏa', 'Nữ Phù Thủy', 4, 1600, 1000, 'UR', 0, 3, 'qklmfsn', 'Lá bài độc quyền cho Muto Games. Mỗi cô gái Phép Thuật được đặt tên theo một loại trái cây. Theo thứ tự cấp độ - các chữ cái đầu tiên trong tên tiếng Anh của họ có dạng <BLACK>.', '0'),
(10753, 'Cô gái Phép Thuật táo', 'Pháp Sư', 'Thủy', 'Nữ Phù Thủy', 3, 1200, 800, 'UR', 0, 3, 'pgmfsn', 'Lá bài độc quyền cho Muto Games. Mỗi cô gái Phép Thuật được đặt tên theo một loại trái cây. Theo thứ tự cấp độ - các chữ cái đầu tiên trong tên tiếng Anh của họ có dạng <BLACK>.', '0'),
(10754, 'Cuộc thập tự chinh của Endymion', 'Pháp Sư', 'Quang', 'Không có', 4, 1900, 1200, 'UR', 0, 3, 'edmfdszj', 'Grand Crusaders của Endymion City - một Phù Thủy cấp chiến lược là yêu cầu tối thiểu để gia nhập quân đoàn này.', '0'),
(10755, 'nhà thơ Địa Tộc ngục', 'Ác Ma', 'Ám', 'Không có', 5, 2000, 1400, 'UR', 0, 1, 'dysr', 'Có một nhà thơ mà linh hồn vô tình bị đọa vào Địa Tộc ngục - và nhiều câu châm ngôn khác nhau bắt đầu xuất hiện trong Địa Tộc ngục.', '0'),
(10756, 'Rồng nứt', 'Máy Móc', 'Ám', 'Không có', 8, 3000, 0, 'UR', 0, 1, 'pjl', 'Bất cứ thứ gì ở phía trước nó sẽ tiết lộ tất cả bí mật của nó mà không cần đặt trước.', '0'),
(10757, 'Nữ hoàng côn trùng đột biến cuối cùng', 'Côn Trùng', 'Địa', 'Không có', 7, 2800, 2400, 'UR', 0, 1, 'jjbytkcnw', 'Hình thức tiến hóa cuối cùng của nữ hoàng côn trùng.', '|Mô tả|\\nBạn có thể sử dụng kỹ thuật ấp để ấp côn trùng 6 sao để ấp ra nữ hoàng côn trùng đột biến cuối cùng\\nBạn cũng có thể sử dụng nhện đen để nuôi côn trùng 4 sao lên 6 sao và sau đó ấp ra nữ hoàng côn trùng đột biến cuối cùng.'),
(10758, 'Anh hùng nguyên tố·Xinyuxia chân thành', 'Chiến Sĩ', 'Quang', 'Anh Hùng Nguyên Tố', 7, 2500, 2000, 'UR', 0, 3, 'ysyxzcxyx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10759, 'Xương', 'Zombie', 'Ám', 'Bộ Xương', 1, 300, 200, 'N', 0, 3, 'bg', 'Quái Thú xương xuất hiện ở khắp mọi nơi. Công kích tuy yếu nhưng tập hợp lại không phải là chuyện nhỏ.', '0'),
(10760, 'Vua xương', 'Zombie', 'Ám', 'Bộ Xương', 1, 0, 0, 'UR', 0, 3, 'bgw', 'Những mảnh xương được tập hợp trong nghĩa trang có thể trở thành một thế lực mạnh mẽ.', '0'),
(10761, 'Hoàng tử xương', 'Zombie', 'Ám', 'Bộ Xương', 1, 0, 0, 'UR', 0, 3, 'bgwz', 'Những mảnh xương được tập hợp trong nghĩa trang có thể trở thành một thế lực mạnh mẽ.', '0'),
(10762, 'Bà Xương', 'Zombie', 'Ám', 'Bộ Xương', 3, 0, 2200, 'UR', 0, 3, 'bgfr', 'Những mảnh xương được tập hợp trong nghĩa trang có thể trở thành một thế lực mạnh mẽ.', '0'),
(10763, 'Dực Thần Long Ra', 'Thần Thú', 'Thần', 'Không có', 10, 0, 0, 'UR', 0, 1, 'tyszysl', 'ラーのWing Shenlong - một trong ba vị Thần Ảo - Malik Isudar sở hữu tấm lá bài này và sau đó đưa nó cho Muto Yugi.', '0'),
(10764, 'Velociraptor', 'Khủng Long', 'Thủy', 'Jurrac', 4, 1700, 1000, 'UR', 0, 3, 'zljxml', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(10765, 'Khủng long bạo chúa kỷ Jura', 'Khủng Long', 'Thủy', 'Jurrac', 7, 2500, 1400, 'UR', 0, 3, 'zljbl', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(10766, 'Y tá thiên thần sa ngã', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 4, 1400, 600, 'SR', 0, 3, 'dtshslfke', 'Trước khi sa ngã - anh phụ trách sức mạnh chữa bệnh. Sau khi sa ngã - anh vô cùng chán ghét năng lượng sống.', '0'),
(10767, 'họ đậu tự nhiên', 'Thực Vật', 'Địa', 'Tự Nhiên', 2, 100, 1200, 'UR', 0, 3, 'zrdyz', 'Bao gồm nhiều chủng tộc khác nhau gần gũi với thiên nhiên - họ là những tinh linh thiên nhiên vô cùng dễ thương.', '0'),
(10768, 'Ngọn lửa quỷ bướm Wilpus', 'Côn Trùng', 'Thủy', 'Không có', 4, 1500, 1500, 'UR', 0, 3, 'yydweps', 'Toàn bộ cơ thể được bao phủ bởi năng lượng Ma Pháp quỷ đang cháy. Dù vô cùng xinh đẹp nhưng không ai đến gần nó có thể sống sót.', '0'),
(10769, 'đom đóm nguyên tử', 'Côn Trùng', 'Quang', 'Không có', 1, 100, 200, 'SR', 0, 3, 'yzyhc', 'Một dạng sống nhân tạo nhưng lại chứa đựng sức mạnh hủy diệt.', '0'),
(10770, 'Hiệp sĩ khai mạc', 'Chiến Sĩ', 'Quang', 'Không có', 4, 500, 2000, 'UR', 0, 3, 'kpzqs', 'Anh ta chịu trách nhiệm phòng thủ trong gia đình Chaos Warrior - và chiếc khiên khổng lồ dường như chẳng là gì trong tay anh ta.', '0'),
(10771, 'Hiệp sĩ bóng đêm thức tỉnh Gaia', 'Chiến Sĩ', 'Ám', 'Kỵ Sĩ Gaia', 7, 2300, 2100, 'UR', 0, 3, 'jxdahqsgy', 'Hiệp sĩ bóng đêm Gaia nhận ra sức mạnh lớn hơn của chính mình khi chiến đấu với các Chiến binh Hỗn loạn.', '0'),
(10772, 'Tâm hồn siêu chiến binh', 'Chiến Sĩ', 'Địa', 'Không có', 1, 0, 0, 'UR', 0, 3, 'czszh', 'Chỉ khi linh hồn được gắn vào áo giáp và gặp một chiến binh Chaos Ma Phápng năng lượng Chaos thì hắn mới xuất hiện và dạy cho anh ta kỹ năng chiến đấu.', '0'),
(10773, 'Chiến binh hỗn loạn·Sứ giả bóng tối', 'Chiến Sĩ', 'Ám', 'Chiến Binh Hỗn Độn', 8, 3000, 2500, 'UR', 0, 3, 'hdzsxadsz', 'Chỉ những chiến binh Chaos đã vượt qua vòng xoáy năng lượng ánh sáng và bóng tối mới có thể thức tỉnh để trở thành những chiến binh cao cấp hơn.', '0'),
(10774, 'Hỏa Vương Thần Thú · Dapeng Phoenix', 'Chim Thú', 'Thủy', 'Vua Lửa', 8, 2700, 1700, 'UR', 0, 2, 'ywssdpbsn', '<Fire King> Quái thú này có khả năng được triệu hồi từ tay khi đồng minh của nó bị tiêu diệt bởi hiệu ứng bài. Các hiệu ứng khác nhau cũng có thể được kích hoạt khi nó bị phá hủy và đưa đến Nghĩa Địa.', '0'),
(10775, 'Kiếm sĩ thầm lặng·LV7', 'Chiến Sĩ', 'Quang', 'LV', 7, 2800, 1000, 'UR', 0, 3, 'cmjslvq', 'Kiếm sĩ thầm lặng cấp cao nhất.', '0'),
(10776, 'Kiếm sĩ thầm lặng·LV5', 'Chiến Sĩ', 'Quang', 'LV', 5, 2300, 1000, 'SR', 0, 3, 'cmjslvw', 'Có thể tiến hóa thành kiếm sĩ thầm lặng cao cấp hơn.', '0'),
(10777, 'Kiếm sĩ thầm lặng·LV3', 'Chiến Sĩ', 'Quang', 'LV', 3, 1000, 1000, 'R', 0, 3, 'cmjslvy', 'Có thể tiến hóa thành kiếm sĩ thầm lặng cao cấp hơn.', '0'),
(10778, 'Thần vạn tay', 'Thiên Thần', 'Quang', 'Không có', 4, 1400, 1000, 'UR', 0, 3, 'wss', 'Nó mạnh hơn Thần ngàn tay. Người ta nói rằng Thần ngàn tay sẽ có thêm một ngàn tay sau mỗi lần tái sinh.', '0'),
(10779, 'Truyện cổ tích Công chúa Kaguya', 'Pháp Sư', 'Quang', 'Công Chúa Cổ Tích', 4, 1850, 1000, 'UR', 0, 3, 'yjcjhy', 'Là một con Quái Thú được đặt tên theo nhân vật chính trong truyện cổ tích - Kaguya được dựa trên Công chúa Nhật Bản Kaguya.', '0'),
(10780, 'Rồng bão tối', 'Rồng', 'Ám', 'Không có', 8, 2700, 2500, 'UR', 0, 3, 'ahbfl', 'Có thể tách và hấp thụ chính xác các yếu tố tối từ không khí.', '0'),
(10781, 'em bé Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 3, 700, 1000, 'UR', 0, 3, 'xxgye', 'Đối với tuổi của Ma Pháp cà rồng - anh ta là một đứa trẻ sơ sinh và vẫn chưa thể che giấu được ham muốn máu của mình.', '0'),
(10782, 'kẻ giết Ma Pháp cà rồng', 'Chiến Sĩ', 'Ám', 'Vampire', 4, 1600, 1600, 'UR', 0, 3, 'xxgss', 'Dựa trên nhân vật chính trong Castlevania - anh chiến đấu với tổ tiên thực sự của Ma Pháp cà rồng trong suốt cuộc đời của mình.', '0'),
(10783, 'trinh sát aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 3, 800, 1200, 'UR', 0, 3, 'ymxch', 'Các chiến binh Amazoness chịu trách nhiệm cảnh giác và trinh sát Ma Phápng theo ít vũ khí để có thể nhanh nhẹn.', '0'),
(10784, 'Công chúa Amazoness', 'Chiến Sĩ', 'Địa', 'Amazoness', 3, 1200, 900, 'UR', 0, 3, 'ymxwn', 'Hậu duệ của Nữ hoàng Amazoness - kế thừa trí tuệ và sức mạnh của Nữ hoàng.', '0'),
(10785, 'Hổ cưng Amazoness', 'Thú', 'Địa', 'Amazoness', 2, 500, 500, 'UR', 0, 3, 'ymxcwzh', 'Những chú hổ con của Amazoness vẫn chưa cai sữa hoàn toàn.', '0'),
(10786, 'Hướng đạo Amazoness', 'Chiến Sĩ', 'Địa', 'Amazoness', 2, 500, 1100, 'UR', 0, 3, 'ymxtj', 'Chiến binh Amazoness trẻ tuổi đã thiết lập mối quan hệ sâu sắc với những người bạn đồng hành của mình từ khi còn nhỏ.', '0'),
(10787, 'vua đỏ đích thực', 'Rồng', 'Thủy', 'Mắt Đỏ', 8, 2400, 2100, 'UR', 0, 3, 'zhw', 'Vua của loài rồng đen mắt đỏ đã có thể Ma Phápng hình dạng con người.', '0'),
(10788, 'Chúa tể bóng tối Zork', 'Ác Ma', 'Ám', 'Xúc Xắc Speedroid', 8, 2700, 1500, 'UR', 0, 3, 'azzpzzk', 'Sở hữu sức mạnh điều khiển thuộc tính bóng tối - anh có thể dễ dàng tiêu diệt kẻ thù của mình chỉ bằng một chút năng lượng bóng tối.', '0'),
(10789, 'Công chúa xương', 'Zombie', 'Quang', 'Bộ Xương', 3, 1600, 0, 'UR', 0, 3, 'bggz', 'Là Quái Thú thuộc tính ánh sáng duy nhất trong gia đình Bone - bà Bone thường xuyên nhận được những lá thư lạ vì lý do này.', '0'),
(10790, 'Harmon - Hoàng đế sấm sét', 'Sấm Sét', 'Quang', 'Ma Thuật', 10, 4000, 4000, 'UR', 0, 3, 'jlhhm', 'Một trong ba bóng Ma Pháp - hình dạng của nó tương ứng với Rồng có cánh của Thần Mặt trời.', '0'),
(10791, 'Tổng lãnh thiên thần Glem', 'Thiên Thần', 'Quang', 'Thiên Không Thánh Vực', 8, 2800, 2300, 'UR', 0, 3, 'dtsjlt', 'Các chiến binh của Jera chấp nhận nguồn ánh sáng và trở thành tổng lãnh thiên thần.', '0'),
(10792, 'Thủy Tộc triều Thủy Tộc triều', 'Hải Long', 'Hỏa', 'Không có', 7, 2600, 1500, 'UR', 0, 3, 'hltdls', 'Chỉ cần ở trong biển - về cơ bản là bất khả chiến bại.', '0'),
(10793, 'Hợp xướng Rồng Thập Tự Phương Nam', 'Khủng Long', 'Thủy', 'Jurrac', 2, 500, 400, 'UR', 0, 3, 'zljnszl', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(10794, 'măng tre tự nhiên', 'Thực Vật', 'Địa', 'Tự Nhiên', 5, 2000, 2000, 'UR', 0, 3, 'zrzs', 'Bao gồm nhiều chủng tộc khác nhau gần gũi với thiên nhiên - họ là những tinh linh thiên nhiên vô cùng dễ thương.', '0'),
(10795, 'Cốc hộ mệnh', 'Khủng Long', 'Địa', 'Người Bảo Hộ', 5, 2500, 1000, 'UR', 0, 3, 'shzgle', 'Nó là một Bộ Bài chủ yếu dựa trên sự kết hợp giữa trang bị và Phép Thuật. Người dùng là Rafilu - một trong ba kiếm sĩ của DoMa Pháp.', '0'),
(10796, 'Chuỗi Rồng kế thừa', 'Thủy Tộc', 'Hỏa', 'Di Sản Tinh Tú', 4, 1800, 1000, 'UR', 0, 3, 'yssll', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(10797, 'Valkyrie bóng tối', 'Thiên Thần', 'Ám', 'Không có', 4, 1800, 1050, 'UR', 0, 3, 'ahnws', 'Thiên thần bóng tối giỏi chiến đấu lại càng khó đoán hơn do lợi thế về đôi cánh.', '0'),
(10798, 'Cưỡi rồng', 'Rồng', 'Ám', 'Không có', 5, 2000, 1500, 'UR', 0, 3, 'ql', 'Một thú cưỡi khác của Dark Sword - có sức tấn công mạnh hơn.', '0'),
(10799, 'Chúa gọi ngôi sao mới', 'Thiên Thần', 'Quang', 'Thiên Không Thánh Vực', 4, 1400, 800, 'SR', 0, 3, 'szxx', 'Bộ tộc thiên thần giỏi nhất trong việc triệu tập những người bạn đồng hành của họ - những thiên thần nhỏ và họ thậm chí còn có mối quan hệ chặt chẽ hơn với các Sky Knight.', '0'),
(10800, 'Milidis Zerg', 'Bò Sát', 'Quang', 'Trùng Tộc', 4, 400, 1600, 'SR', 0, 3, 'mldsyc', 'Quái Thú được thống nhất thành loại thuộc tính ánh sáng và loại bò sát - với tổng số là 26. Những cái tên này chứa chính xác 26 chữ cái tiếng Anh.', '0'),
(10801, 'Chất nhờn Phép Thuật', 'Thủy Tộc', 'Hỏa', 'Không có', 3, 700, 1200, 'SR', 0, 3, 'mfslm', 'Vì nuốt nhầm một số lượng lớn cuộn giấy Phép Thuật - hình dạng của con slime này đã thay đổi rất nhiều.', '0'),
(10802, 'Fedeleza', 'Pháp Sư', 'Phong', 'Không có', 2, 700, 1100, 'SR', 0, 3, 'fdlz', 'Vô cùng sùng bái Phong Vương.', '0'),
(10803, 'Gogol khổng lồ', 'Nham Thạch', 'Địa', 'Không có', 4, 1500, 500, 'SR', 0, 3, 'jrgge', 'Được làm bằng đá - nó cực kỳ linh hoạt.', '0'),
(10804, 'Người sống trong mạch máu rồng', 'Rồng', 'Địa', 'Không có', 3, 1500, 700, 'SR', 0, 3, 'lmxxz', 'Nó quanh năm sống gần long mạch - được lợi từ long mạch - tự phát đóng vai trò là người bảo vệ long mạch.', '0'),
(10805, 'Các dẫn xuất của hợp xướng', 'Khủng Long', 'Thủy', 'Jurrac', 1, 0, 0, 'N', 0, 3, 'zljysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(10806, 'Người triệu hồi đôi', 'Pháp Sư', 'Hỏa', 'Không có', 4, 1500, 0, 'UR', 0, 3, 'eczhs', 'Bạn có thể trực tiếp vượt qua các mặt phẳng và triệu tập các sinh vật thứ cấp từ mặt phẳng thứ cấp.', '0'),
(10807, 'Chiến hạm khổng lồ · Bốn cánh tay', 'Máy Móc', 'Phong', 'Chiến Hạm Khổng Lồ', 6, 1800, 2300, 'UR', 0, 3, 'jdzjsw', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10808, 'Chiến hạm khổng lồ·Lõi pha lê', 'Máy Móc', 'Hỏa', 'Chiến Hạm Khổng Lồ', 5, 2100, 1000, 'UR', 0, 3, 'jdzjjh', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10809, 'Chiến hạm khổng lồ · Lõi bao phủ', 'Máy Móc', 'Địa', 'Chiến Hạm Khổng Lồ', 7, 2500, 800, 'UR', 0, 3, 'jdzjgh', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10810, 'Chiến hạm khổng lồ·MK2', 'Máy Móc', 'Thủy', 'Chiến Hạm Khổng Lồ', 6, 2400, 1100, 'UR', 0, 3, 'jdzjmke', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10811, 'Chiến hạm khổng lồ·MK3', 'Máy Móc', 'Quang', 'Chiến Hạm Khổng Lồ', 8, 2700, 1900, 'UR', 0, 3, 'jdzjmks', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10812, 'Chiến hạm khổng lồ·Lõi tấn công', 'Máy Móc', 'Quang', 'Chiến Hạm Khổng Lồ', 4, 1300, 2000, 'UR', 0, 3, 'jdzjqxhx', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(10813, 'Chim lửa bất tử', 'Chim Thú', 'Thủy', 'Không có', 4, 1200, 0, 'UR', 0, 3, 'bszyn', 'Toàn thân anh ta được bao phủ bởi ngọn lửa thiêu đốt - và anh ta sẽ không chết miễn là ngọn lửa chưa bị dập tắt.', '0'),
(10814, 'Miko với đôi mắt xanh', 'Pháp Sư', 'Quang', 'Mắt Xanh', 1, 0, 0, 'UR', 0, 3, 'qsyjdwn', 'Một nhóm người có cùng màu mắt với Rồng Trắng Mắt Xanh - linh hồn cư trú trong cơ thể họ.', '0'),
(10815, 'Rồng thép đen mắt đỏ đích thực', 'Rồng', 'Ám', 'Mắt Đỏ', 10, 2800, 2400, 'UR', 0, 3, 'zhyagl', 'Một Bộ Bài được xây dựng với <Red Eyes Black Dragon> làm cốt lõi - có nhiều phương pháp triệu hồi khác nhau. Lá bài yêu thích của Katsuya Jonouchi.', '0'),
(10816, 'Phù Thủy thầm lặng·LV8', 'Pháp Sư', 'Quang', 'LV', 8, 3500, 1000, 'UR', 0, 3, 'cmmsslvb', 'Phù Thủy thầm lặng cấp cao nhất.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(10817, 'Phù Thủy thầm lặng·LV4', 'Pháp Sư', 'Quang', 'LV', 4, 1000, 1000, 'SR', 0, 3, 'cmmsslvw', 'Một Phù Thủy thầm lặng có thể tiến hóa.', '0'),
(10818, 'Kiếm sĩ Phép Thuật thầm lặng', 'Thiên Thần', 'Quang', 'Không có', 4, 500, 1500, 'SR', 0, 3, 'cmmdjs', 'Một thiên thần xinh đẹp có thể truyền cảm hứng cho ý chí chiến đấu của một kiếm sĩ thầm lặng hoặc một Phù Thủy thầm lặng.', '0'),
(10819, 'Truyện Cổ Tích Công Chúa Bạch Tuyết', 'Pháp Sư', 'Quang', 'Công Chúa Cổ Tích', 4, 1850, 1000, 'UR', 0, 3, 'yjcjbx', 'Một con Quái Thú được đặt theo tên nhân vật chính trong truyện cổ tích - Bạch Tuyết dựa trên Bạch Tuyết.', '0'),
(10820, 'Sự kết hợp của sinh vật bị nguyền rủa · bóng tối', 'Nham Thạch', 'Ám', 'Không có', 3, 1000, 1600, 'UR', 0, 3, 'rhzyswa', 'Một cuộc sống kỳ diệu được tạo ra đặc biệt cho sự hợp nhất.', '0'),
(10821, 'Chiến binh năng lượng', 'Chiến Sĩ', 'Quang', 'Không có', 4, 1700, 1200, 'SR', 0, 3, 'nlys', 'Nó có thể cung cấp sự bảo vệ trường năng lượng cho Quái Thú kép.', '0'),
(10822, 'Hiệp sĩ đích thực', 'Chiến Sĩ', 'Thủy', 'Không có', 4, 1900, 900, 'UR', 0, 3, 'jhkjqsxwla', 'Việc nắm vững các đặc tính của thiết bị thậm chí có thể Ma Phápng lại cho thiết bị những sức mạnh mới.', '0'),
(10823, 'Neptune Dragon Posedra', 'Hải Long', 'Hỏa', 'Hải Hoàng', 7, 2800, 1600, 'UR', 0, 3, 'hhlbsdl', 'Kẻ thống trị tối cao trong số những con rồng biển.', '0'),
(10824, 'người đá lớn', 'Nham Thạch', 'Địa', 'Không có', 5, 2100, 0, 'UR', 0, 3, 'dksr', 'Người đá có thể kết hợp theo ý muốn.', '0'),
(10825, 'Người nhân tạo·Người đánh chặn tâm linh', 'Máy Móc', 'Ám', 'Người Nhân Tạo Jinzo', 4, 800, 2000, 'UR', 0, 3, 'rzrnlckz', 'Người nhân tạo có khả năng điều khiển từ xa mạnh mẽ và có thể tác động đến các lá bài bẫy trên chiến trường để kiểm soát tình hình chiến đấu.', '0'),
(10826, 'Ác di sản song hồn rồng biển', 'Thủy Tộc', 'Hỏa', 'Di Sản Tinh Tú', 8, 2700, 1500, 'UR', 0, 3, 'xysshhl', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(10827, 'Yêu tinh linh hồn kế thừa', 'Thủy Tộc', 'Hỏa', 'Di Sản Tinh Tú', 8, 2800, 2800, 'UR', 0, 3, 'xyslhsrm', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(10828, 'Anh hùng nguyên tố · Người băng giá', 'Chiến Sĩ', 'Hỏa', 'Anh Hùng Nguyên Tố', 3, 800, 900, 'SR', 0, 3, 'ysyxblx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(10829, 'Giun kim', 'Côn Trùng', 'Địa', 'Trùng Tộc', 2, 750, 600, 'SR', 0, 3, 'zc', 'Toàn thân phủ đầy gai côn trùng - cực kỳ đáng sợ.', '0'),
(10830, 'Liên kết Zerg', 'Côn Trùng', 'Quang', 'Trùng Tộc', 2, 300, 1000, 'SR', 0, 3, 'lksyc', 'Quái Thú được thống nhất thành loại thuộc tính ánh sáng và loại bò sát - với tổng số là 26. Những cái tên này chứa chính xác 26 chữ cái tiếng Anh.', '0'),
(10831, 'Hoàng đế biển thật Tridon', 'Hải Long', 'Hỏa', 'Hải Hoàng', 3, 1600, 800, 'SR', 0, 3, 'zhhtld', 'Cô ấy có mối quan hệ rất tốt với <Hải Hoàng Long Poseidra>.', '0'),
(10832, 'người đàn ông đá vừa', 'Nham Thạch', 'Địa', 'Không có', 4, 1600, 0, 'SR', 0, 3, 'zksr', 'Người đá có thể kết hợp theo ý muốn.', '0'),
(10833, 'người đá nhỏ', 'Nham Thạch', 'Địa', 'Không có', 3, 1100, 0, 'SR', 0, 3, 'xksr', 'Người đá có thể kết hợp theo ý muốn.', '0'),
(10834, 'Người nhân tạo ·Người trở lại bệnh thái nhân cách', 'Máy Móc', 'Ám', 'Người Nhân Tạo Jinzo', 3, 600, 1400, 'SR', 0, 3, 'rzrnlglz', 'Người nhân tạo có khả năng điều khiển từ xa mạnh mẽ và có thể tác động đến các lá bài bẫy trên chiến trường để kiểm soát tình hình chiến đấu.', '0'),
(10835, 'Người phù Thủy Tộc canh giữ ngôi mộ', 'Pháp Sư', 'Ám', 'Thủ Mộ', 3, 800, 800, 'SR', 0, 3, 'smdzss', 'Nguyên mẫu xuất phát từ bối cảnh của gia tộc canh giữ lăng mộ trong <Yu-Gi-Oh!>', '0'),
