(10837, 'Cô Gái Định Mệnh·Wendy', 'Pháp Sư', 'Phong', 'Cô Gái Vận Mệnh', 3, 0, 0, 'UR', 0, 3, 'mynlwd', 'Sức mạnh tấn công và sức mạnh phòng thủ của Quái Thú có thể thay đổi theo cấp độ và cấp độ của Quái Thú sẽ thay đổi theo thời gian nó ở trên sân.', '0'),
(10838, 'cô gái định mệnh Urshe', 'Pháp Sư', 'Địa', 'Cô Gái Vận Mệnh', 6, 0, 0, 'UR', 0, 3, 'mynlex', 'Sức mạnh tấn công và sức mạnh phòng thủ của Quái Thú có thể thay đổi theo cấp độ và cấp độ của Quái Thú sẽ thay đổi theo thời gian nó ở trên sân.', '0'),
(10839, 'Viên ngọc đơn nhỏ phù Thủy Tộc nhỏ', 'Pháp Sư', 'Quang', 'Không có', 4, 1600, 1300, 'UR', 0, 3, 'dbsxmn', 'Cô ấy có mối quan hệ rất tốt với Destiny.', '0'),
(10840, 'Tiểu thư định mệnh Letty', 'Pháp Sư', 'Quang', 'Cô Gái Vận Mệnh', 1, 0, 0, 'UR', 0, 3, 'mynlld', 'Sức mạnh tấn công và sức mạnh phòng thủ của Quái Thú có thể thay đổi theo cấp độ và cấp độ của Quái Thú sẽ thay đổi theo thời gian nó ở trên sân.', '0'),
(10841, 'Cô gái định mệnh Whatley', 'Pháp Sư', 'Hỏa', 'Cô Gái Vận Mệnh', 4, 0, 0, 'UR', 0, 3, 'mynlwtl', 'Sức mạnh tấn công và sức mạnh phòng thủ của Quái Thú có thể thay đổi theo cấp độ và cấp độ của Quái Thú sẽ thay đổi theo thời gian nó ở trên sân.', '0'),
(10842, 'Cô gái định mệnh Philly', 'Pháp Sư', 'Thủy', 'Cô Gái Vận Mệnh', 2, 0, 0, 'UR', 0, 3, 'mynlfl', 'Sức mạnh tấn công và sức mạnh phòng thủ của Quái Thú có thể thay đổi theo cấp độ và cấp độ của Quái Thú sẽ thay đổi theo thời gian nó ở trên sân.', '0'),
(10843, 'Cô gái định mệnh ·Daqi', 'Pháp Sư', 'Ám', 'Cô Gái Vận Mệnh', 5, 0, 0, 'UR', 0, 3, 'mynldq', 'Sức mạnh tấn công và sức mạnh phòng thủ của Quái Thú có thể thay đổi theo cấp độ và cấp độ của Quái Thú sẽ thay đổi theo thời gian nó ở trên sân.', '0'),
(10844, 'Sứ giả của thế giới ngầm', 'Ác Ma', 'Ám', 'Không có', 3, 1600, 600, 'SR', 0, 3, 'mjdsz', 'Những linh hồn có thể nô dịch và điều khiển những sinh vật yếu hơn.', '0'),
(10845, 'Tinh thần của Pharaoh', 'Zombie', 'Quang', 'Không có', 6, 2500, 2000, 'UR', 0, 3, 'flzl', 'Tâm hồn của Pharaoh tràn ngập ánh sáng và ông là một Pharaoh rất tốt bụng trong suốt cuộc đời của mình.', '0'),
(10846, 'bọ lao', 'Côn Trùng', 'Địa', 'Không có', 8, 2450, 2550, 'UR', 0, 3, 'bqjc', 'Một chiến binh bọ cánh cứng cấp cao với khả năng triệu tập đồng đội của mình.', '0'),
(10847, 'amip', 'Thủy Tộc', 'Hỏa', 'Không có', 1, 300, 350, 'SR', 0, 3, 'amb', 'Không được chạm vào dạng sống Phép Thuật chỉ có thể tìm thấy trong đầm lầy độc.', '0'),
(10848, 'Rồng Ác Tinh Mắt Đỏ·Rồng Sao Băng', 'Rồng', 'Ám', 'Mắt Đỏ', 6, 1800, 2000, 'UR', 0, 3, 'zhyydxxllxzl', 'Một Bộ Bài được xây dựng với <Red Eyes Black Dragon> làm cốt lõi - có nhiều phương pháp triệu hồi khác nhau. Lá bài yêu thích của Katsuya Jonouchi.', '0'),
(10849, 'Hiệp sĩ Artoris', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1800, 1800, 'UR', 0, 3, 'sqsatls', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(10850, 'Hiệp sĩ Galahad', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1500, 1800, 'UR', 0, 3, 'sqsjlhd', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(10851, 'Sứ giả của bầu trời Geradias', 'Thiên Thần', 'Quang', 'Thiên Không Thánh Vực', 4, 2100, 800, 'UR', 0, 3, 'tkdszjldys', 'Câu thần chú yêu thích của người bảo vệ Sky Sanctuary là <tòa tháp là nơi có người>.', '0'),
(10852, 'Bầu trời Thánh Mortius', 'Thiên Thần', 'Quang', 'Thiên Không Thánh Vực', 4, 1600, 1200, 'UR', 0, 3, 'tkszmtws', 'Saint of the Sky Sanctuary là người yêu chuộng hòa bình nhưng có khả năng chiến đấu đáng kinh ngạc khi tức giận.', '0'),
(10853, 'rết Địa Tộc ngục', 'Côn Trùng', 'Ám', 'Không có', 7, 2600, 1300, 'SR', 0, 3, 'dydbz', 'Con rết khổng lồ - đặc sản của Địa ngục - tạo ra sự hỗn loạn ở bất cứ nơi nào nó đi qua.', '0'),
(10854, 'Con cháu canh giữ lăng mộ', 'Pháp Sư', 'Ám', 'Thủ Mộ', 4, 1500, 1200, 'SR', 0, 3, 'smdmy', 'Nguyên mẫu xuất phát từ bối cảnh của gia tộc canh giữ lăng mộ trong <Yu-Gi-Oh!>', '0'),
(10855, 'Xạ thủ hạng nặng canh giữ lăng mộ', 'Pháp Sư', 'Ám', 'Thủ Mộ', 4, 1400, 1200, 'SR', 0, 3, 'smdzps', 'Nguyên mẫu xuất phát từ bối cảnh của gia tộc canh giữ lăng mộ trong <Yu-Gi-Oh!>', '0'),
(10856, 'hy vọng Zerg', 'Bò Sát', 'Quang', 'Trùng Tộc', 1, 800, 1500, 'SR', 0, 3, 'hpyc', 'Quái Thú được thống nhất thành loại thuộc tính ánh sáng và loại bò sát - với tổng số là 26. Những cái tên này chứa chính xác 26 chữ cái tiếng Anh.', '0'),
(10857, 'Tengu vĩ đại', 'Chiến Sĩ Thú', 'Ám', 'Không có', 5, 1900, 1700, 'UR', 0, 3, 'wdtg', 'Một con Quái Thú dựa trên thần núi huyền thoại Tengu của Nhật Bản.', '0'),
(10858, 'Nước hoa Seraph Angelica dahurica', 'Thực Vật', 'Quang', 'Hương Thơm', 1, 0, 0, 'UR', 0, 3, 'fxztsobz', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10859, 'Bậc thầy hương thơm ·Hoa nhài', 'Thực Vật', 'Quang', 'Hương Thơm', 2, 100, 1900, 'UR', 0, 3, 'fxfsml', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10860, 'Bậc thầy hương thơm ·Ylang-ylang', 'Thực Vật', 'Địa', 'Hương Thơm', 3, 1400, 1000, 'UR', 0, 3, 'fxfsyl', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10861, 'Bậc thầy trị liệu bằng hương thơm · Hương thảo', 'Thực Vật', 'Hỏa', 'Hương Thơm', 4, 1800, 700, 'UR', 0, 3, 'fxfsmdx', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10862, 'Bậc thầy trị liệu bằng hương thơm ·Hoa hồng trắng', 'Thực Vật', 'Quang', 'Hương Thơm', 5, 2200, 1700, 'UR', 0, 3, 'fxfsbqw', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(10863, 'Hiệp sĩ bóng đêm', 'Chiến Sĩ', 'Ám', 'Không có', 4, 500, 2000, 'UR', 0, 3, 'xazqs', 'Anh ta chịu trách nhiệm phòng thủ trong gia đình Chaos Warrior - và chiếc khiên khổng lồ dường như chẳng là gì trong tay anh ta.', '0'),
(10864, 'người hầu của pharaoh', 'Zombie', 'Ám', 'Không có', 2, 900, 0, 'SR', 0, 3, 'fldpr', 'Người ta cho rằng đó là linh hồn của những người từng phục vụ Pharaoh. Có một trái tim trung thành sẽ không bao giờ dao động.', '0'),
(10865, 'Quỷ nghi thức và người sắp xếp', 'Ác Ma', 'Ám', 'Ác Quỷ Nghi Thức', 1, 200, 200, 'SR', 0, 3, 'ysmrbzz', 'Hiệu Ứng chung là loại bỏ Quái Thú này khỏi Nghĩa Địa thay cho Quái Thú cần thiết cho nghi lễ hiến tế.', '0'),
(10866, 'Chủ tịch nghi lễ quỷ · Chủ tịch', 'Ác Ma', 'Ám', 'Ác Quỷ Nghi Thức', 4, 1800, 1400, 'UR', 0, 3, 'ysmrzcz', 'Hiệu Ứng chung là loại bỏ Quái Thú này khỏi Nghĩa Địa thay cho Quái Thú cần thiết cho nghi lễ hiến tế.', '0'),
(10867, 'Hiệp sĩ Tristan', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1800, 800, 'UR', 0, 3, 'sqscst', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(10868, 'Lắp đặt bọ cánh cứng·Kiến', 'Côn Trùng', 'Ám', 'Bọ Cánh Cứng Inzektor', 3, 200, 600, 'SR', 0, 3, 'jczjmy', 'Họ có khả năng biến đổi trang bị của nhau thành trang bị của nhau và hợp nhất thành Quái Thú côn trùng thuộc tính bóng tối.', '0'),
(10869, 'Lắp đặt bọ cánh cứng·Bumblebee', 'Côn Trùng', 'Ám', 'Bọ Cánh Cứng Inzektor', 3, 500, 200, 'SR', 0, 3, 'jczjdhf', 'Họ có khả năng biến đổi trang bị của nhau thành trang bị của nhau và hợp nhất thành Quái Thú côn trùng thuộc tính bóng tối.', '0'),
(10870, 'Lắp đặt bọ · rết', 'Côn Trùng', 'Ám', 'Bọ Cánh Cứng Inzektor', 3, 1600, 1200, 'UR', 0, 3, 'jczjwg', 'Họ có khả năng biến đổi trang bị của nhau thành trang bị của nhau và hợp nhất thành Quái Thú côn trùng thuộc tính bóng tối.', '0'),
(10871, 'Lắp đặt bọ cánh cứng·Dế chũi Jika', 'Côn Trùng', 'Ám', 'Bọ Cánh Cứng Inzektor', 5, 2000, 1300, 'UR', 0, 3, 'jczjjjlg', 'Họ có khả năng biến đổi trang bị của nhau thành trang bị của nhau và hợp nhất thành Quái Thú côn trùng thuộc tính bóng tối.', '0'),
(10872, 'cà tím tự nhiên', 'Thực Vật', 'Địa', 'Tự Nhiên', 2, 1000, 700, 'SR', 0, 3, 'zrqz', 'Bao gồm nhiều chủng tộc khác nhau gần gũi với thiên nhiên - họ là những tinh linh thiên nhiên vô cùng dễ thương.', '0'),
(10873, 'Khủng long Brachiosaurus kỷ Jura', 'Khủng Long', 'Thủy', 'Jurrac', 3, 1000, 1000, 'SR', 0, 3, 'zljwl', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(10874, 'Hợp xướng Quái Thú khổng lồ', 'Khủng Long', 'Thủy', 'Jurrac', 9, 3000, 2800, 'UR', 0, 3, 'zljjss', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
