(10953, 'người đi đường nhỏ', 'Chim Thú', 'Địa', 'Không có', 1, 300, 300, 'R', 0, 3, 'xzj', 'Nguyên mẫu là một con vật được gọi là <roadrunner> - sống ở Texas và New Mexico ở Hoa Kỳ.', '0'),
(10954, 'con nhím vít', 'Máy Móc', 'Địa', 'Không có', 2, 800, 800, 'SR', 0, 3, 'lscw', 'Những Quái Thú mà Fudo Yusei thường sử dụng có thể được đồng bộ trực tiếp với <Waste Synchronizer> để tạo ra <Waste Warrior>.', '0'),
(10955, 'chiến binh khiên', 'Chiến Sĩ', 'Địa', 'Không có', 3, 800, 1600, 'SR', 0, 3, 'hdzs', 'Chiếc khiên khổng lồ có thể chịu được mọi thiệt hại.', '0'),
(10956, 'Rồng sao', 'Rồng', 'Quang', 'Không có', 4, 1900, 1000, 'UR', 0, 3, 'xhl', 'Bạn có thể sử dụng năng lượng của Starlight để tăng xếp hạng sao của mình trong thời gian ngắn.', '0'),
(10957, 'Rồng bụi sao', 'Rồng', 'Quang', 'Bụi Sao', 1, 100, 100, 'UR', 0, 3, 'xcxl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một Bộ Bài dựa trên Quái Thú Synchro được nhân vật chính Yusei Fudo sử dụng trong <Yu-Gi-Oh 5D\'s>.', '0'),
(10958, 'người đàn ông cuộn dây xích', 'Máy Móc', 'Địa', 'Xích Sắt', 3, 1100, 1600, 'UR', 0, 3, 'lxqr', 'Nó có thể được sử dụng như một mối liên kết giữa các Quái Thú - liên kết chúng để đạt được sức mạnh lớn hơn.', '0'),
(10959, 'Dây chuyền·Thợ sửa chữa', 'Máy Móc', 'Địa', 'Xích Sắt', 4, 1600, 1200, 'UR', 0, 3, 'lxlg', 'Các chuyên gia sửa chữa có thể tái sử dụng những vật liệu bỏ đi.', '0'),
(10960, 'rắn bò sát', 'Bò Sát', 'Ám', 'Bò Sát', 2, 0, 0, 'UR', 0, 3, 'pcys', 'Một trong những Bộ Bài Yu-Gi-Oh. Đặc điểm của bộ truyện là giảm sức tấn công của Quái Thú đối phương xuống 0 và sử dụng điều này để can thiệp.', '0'),
