(10996, 'Vũ khí của Trung đoàn Dragoon·Kiếm tai họa', 'Rồng', 'Phong', 'Rồng Khổng Lồ Felgrand', 8, 2600, 1200, 'UR', 0, 3, 'lqbtwqzmj', 'Quái Thú <Trung đoàn Dragoon> bao gồm gia đình Bird Beast và gia đình Dragon. Các Quái Thú họ Rồng được huấn luyện và Bird Beast chịu trách nhiệm chỉ huy. Và sau đó hình thành một hiệu quả chiến đấu mạnh mẽ.', '0'),
(10997, 'Người hầu phế liệu', 'Chiến Sĩ', 'Địa', 'Phế Liệu', 4, 1500, 1000, 'SR', 0, 3, 'fpcz', 'Một trong những Bộ Bài Yu-Gi-Oh. Bộ Bài chủ đề được nhân vật chính Yusei Fudo sử dụng trong <Yu-Gi-Oh 5D\'s>. Sử dụng <Descrap Synchronizer> để điều chỉnh - Synchro sẽ triệu hồi nhiều Quái Thú được Synchro <Descrap> khác nhau.', '0'),
(10998, 'Ma thú·Chim chéo cánh', 'Chiến Sĩ Thú', 'Quang', 'Ma Thú', 4, 1300, 1300, 'SR', 0, 3, 'hsszyn', 'Được các nguyên tố phù hộ Ma Phápng đến cho bạn sức mạnh vô song.', '0'),
(10999, 'Ma thú · Pegasus sấm sét', 'Chiến Sĩ Thú', 'Quang', 'Ma Thú', 4, 700, 2000, 'UR', 0, 3, 'hsltfm', 'Được các nguyên tố phù hộ Ma Phápng đến cho bạn sức mạnh vô song.', '0'),
(11000, 'Ma thú·Thằn lằn đá khổng lồ', 'Chiến Sĩ Thú', 'Ám', 'Ma Thú', 7, 2200, 2000, 'UR', 0, 3, 'hsjyx', 'Được các nguyên tố phù hộ Ma Phápng đến cho bạn sức mạnh vô song.', '0'),
(11001, 'Quái thú tưởng tượng · Nai sừng tấm hoang dã', 'Chiến Sĩ Thú', 'Địa', 'Ma Thú', 4, 1700, 0, 'UR', 0, 3, 'hsyjtl', 'Được các nguyên tố phù hộ Ma Phápng đến cho bạn sức mạnh vô song.', '0'),
(11002, 'chiến binh song trùng', 'Chiến Sĩ', 'Ám', 'Không có', 2, 800, 800, 'SR', 0, 3, 'ecszs', 'Sở hữu đa nhân cách nên mối quan hệ giữa các nhân cách rất thân thiện.', '0'),
(11003, 'X Kiếm Sĩ Anna Pereira', 'Chiến Sĩ', 'Địa', 'Kiếm Sĩ X', 4, 1800, 1100, 'UR', 0, 3, 'xjsanprl', 'Nữ chiến binh X-SwordsMa Phápn bay qua chiến trường với những đòn tấn công lộng lẫy và khả năng phán đoán bình tĩnh. Những đòn tấn công đôi khi tàn nhẫn khiến kẻ địch phải khiếp sợ.', '0'),
(11004, 'Kiếm sĩ X Alborn', 'Thú', 'Địa', 'Kiếm Sĩ X', 3, 1600, 200, 'SR', 0, 3, 'xjsaebe', 'Dòng <X SwordsMa Phápn> bao gồm các Quái Thú thuộc tính thổ. Các chủng tộc bao gồm nhiều chủng tộc phổ biến như chủng tộc chiến binh và chủng tộc chiến binh quái thú - với chủ đề là Triệu Hồi Synchro.', '0'),
(11005, 'Axel kiếm sĩ X', 'Chiến Sĩ Thú', 'Địa', 'Kiếm Sĩ X', 1, 400, 100, 'SR', 0, 3, 'xjsakse', 'Dòng <X SwordsMa Phápn> bao gồm các Quái Thú thuộc tính thổ. Các chủng tộc bao gồm nhiều chủng tộc phổ biến như chủng tộc chiến binh và chủng tộc chiến binh quái thú - với chủ đề là Triệu Hồi Synchro.', '0'),
(11006, 'Nhân vật kiếm sĩ X', 'Chiến Sĩ', 'Địa', 'Kiếm Sĩ X', 2, 100, 0, 'SR', 0, 3, 'xjspxe', 'Dòng <X SwordsMa Phápn> bao gồm các Quái Thú thuộc tính thổ. Các chủng tộc bao gồm nhiều chủng tộc phổ biến như chủng tộc chiến binh và chủng tộc chiến binh quái thú - với chủ đề là Triệu Hồi Synchro.', '0'),
(11007, 'Thư viện Phép Thuật Vương Li', 'Pháp Sư', 'Quang', 'Không có', 4, 0, 2000, 'UR', 0, 3, 'wlmftsg', 'Một thư viện Phép Thuật với những cuốn sách lơ lửng trong không trung.', '0'),
(11008, 'Thầy Phong Tộc Thủy Tộc trong ranh giới băng', 'Pháp Sư', 'Hỏa', 'Kết Giới Băng', 3, 800, 1200, 'SR', 0, 3, 'bjjdfss', 'Quái Thú hợp nhất thành thuộc tính nước hạn chế hành động của đối phương bằng cách vận hành kết giới băng - thể hiện sự thiêng liêng và ý chí bất khả xâm phạm của băng.', '0'),
(11009, 'Tongtiaoshi của vua', 'Máy Móc', 'Quang', 'Tuner', 4, 1600, 800, 'SR', 0, 3, 'wdtts', 'Một trong những Bộ Bài <Yu-Gi-Oh>. <Yu-Gi-Oh 5D\'s> là phần quan trọng nhất trong Bộ Bài của nhân vật chính Fudo Yusei - hỗ trợ một số lượng lớn Quái Thú Synchro <Warrior> và <Trash>.', '0'),
(11010, 'Hỏa Thần Sita', 'Pháp Sư', 'Thủy', 'Gusto', 3, 500, 1500, 'SR', 0, 3, 'hlsxt', '<Spirit Envoy> có thể giành quyền kiểm soát quái thú của đối phương với thuộc tính tương ứng.', '0'),
(11011, 'Herrerasaurus', 'Khủng Long', 'Thủy', 'Jurrac', 6, 2300, 1500, 'UR', 0, 3, 'zljalll', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(11012, 'Quái Thú hợp xướng', 'Khủng Long', 'Thủy', 'Jurrac', 3, 1700, 800, 'UR', 0, 3, 'zljks', 'Các lá bài Quái Thú đều là khủng long thuộc tính lửa. Trong môi trường và đấu tranh tàn khốc - họ đã thành công bao phủ mình bằng ngọn lửa và leo lên đỉnh chuỗi thức ăn bằng sức mạnh này.', '0'),
(11013, 'Rồng lửa đen mắt đỏ thật sự', 'Rồng', 'Ám', 'Mắt Đỏ', 7, 2400, 2000, 'UR', 0, 3, 'zhyhyl', 'Một Bộ Bài được xây dựng với <Red Eyes Black Dragon> làm cốt lõi - có nhiều phương pháp triệu hồi khác nhau. Lá bài yêu thích của Katsuya Jonouchi.', '0'),
(11014, 'Mã thông báo song trùng', 'Chiến Sĩ', 'Ám', 'Không có', 1, 0, 400, 'N', 0, 3, 'ecsysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11015, 'Cô gái chiến hạm · Bốn cổ tay', 'Máy Móc', 'Phong', 'Chiến Hạm Khổng Lồ', 6, 1800, 2300, 'UR', 0, 3, 'jdzjsw', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0'),
(11016, 'Cô gái chiến hạm·Lõi pha lê', 'Máy Móc', 'Hỏa', 'Chiến Hạm Khổng Lồ', 5, 2100, 1000, 'UR', 0, 3, 'jdzjjh', 'Những con Quái Thú trong loạt phim này là kiệt tác bắn súng <Space Cruiser> của chính K Club. Tất cả Quái Thú trong loạt phim này đều là thiết giáp hạm BOSS xuất hiện trong trò chơi này.', '0');
