(11026, 'rồng sừng trắng', 'Rồng', 'Ám', 'Không có', 6, 2200, 1400, 'UR', 0, 3, 'bjl', 'Chiếc sừng sắc nhọn với sức mạnh Phép Thuật có thể hấp thụ sức mạnh Phép Thuật để tăng cường sức mạnh cho bản thân.', '0'),
(11027, 'XX Kiếm Sĩ Fordroll', 'Chiến Sĩ', 'Địa', 'Kiếm Sĩ X', 6, 2400, 1800, 'UR', 0, 3, 'xxjsftle', 'Dòng <X SwordsMa Phápn> bao gồm các Quái Thú thuộc tính thổ. Các chủng tộc bao gồm nhiều chủng tộc phổ biến như chủng tộc chiến binh và chủng tộc chiến binh quái thú - với chủ đề là Triệu Hồi Synchro.', '0'),
(11028, 'Hoàng đế sấm sét Zabolg', 'Sấm Sét', 'Quang', 'Không có', 8, 2800, 1000, 'UR', 0, 3, 'hldzbeg', 'Hình thức tối thượng sau quá trình tiến hóa của Hoàng đế Sấm sét.', '0'),
(11029, 'Người hầu cận của Hoàng đế Sấm sét Mithras', 'Sấm Sét', 'Quang', 'Không có', 2, 800, 1000, 'UR', 0, 3, 'ldjcmtl', 'Người hầu cận trung thành nhất của Hoàng đế Sấm sét - người có thể hiến tế mọi thứ vì Hoàng đế Sấm sét.', '0'),
(11030, 'Thiên thần sa ngã Diesel', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 10, 3000, 2800, 'UR', 0, 3, 'dtsdse', 'Các thiên thần có thể được bố trí để đạt được hiệu quả lao xuống nhanh chóng - tấn công đối phương một cách bất ngờ.', '0'),
(11031, 'Thiên thần sa ngã Asmodeus', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 8, 3000, 2500, 'UR', 0, 3, 'dtsasmds', 'Thiên thần sa ngã cực kỳ khó đối phó và sẽ để lại rất nhiều rắc rối ngay cả khi họ chết trong trận chiến.', '0'),
(11032, 'Thiên thần sa ngã Anducias', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 6, 1800, 2800, 'UR', 0, 3, 'dtsadxys', 'Nó có thể được sử dụng với các thiên thần sa ngã khác nhau để kích hoạt các phương pháp phối hợp khác nhau và nó cực kỳ mạnh mẽ trong việc kiểm soát tình hình chiến đấu.', '0'),
(11033, 'Thiên thần sa ngã Ishtab', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 10, 2500, 2900, 'UR', 0, 3, 'dtsyxtb', 'Một thiên thần sa ngã có thể hỗ trợ nhanh chóng.', '0'),
(11034, 'Mã thông báo giữ lại', 'Sấm Sét', 'Quang', 'Không có', 1, 800, 1000, 'N', 0, 3, 'jcysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11035, 'Dẫn xuất của Asmon', 'Thiên Thần', 'Ám', 'Không có', 5, 1800, 1300, 'UR', 0, 3, 'asmysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11036, 'Công cụ phái sinh Thies', 'Thiên Thần', 'Ám', 'Không có', 3, 1200, 1200, 'UR', 0, 3, 'dsysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11037, 'họa sĩ đau đớn', 'Zombie', 'Ám', 'Không có', 2, 400, 200, 'SR', 0, 3, 'tkyqg', 'Favorite thêm các loại virus đặc biệt vào sơn để sơn không bao giờ khô.', '0'),
(11038, 'chúa tể zombie', 'Zombie', 'Ám', 'Không có', 4, 1800, 0, 'UR', 0, 3, 'jszz', 'Vô số thây Ma Pháp có thể được triệu tập để Ma Phápng đến cái chết và sự hủy diệt.', '0'),
