(11092, 'Trung đoàn Dragoon·Rồng dao găm', 'Rồng', 'Phong', 'Rồng Khổng Lồ Felgrand', 2, 1000, 200, 'UR', 0, 3, 'lqbtcbddl', 'Quái Thú <Trung đoàn Dragoon> bao gồm gia đình Bird Beast và gia đình Dragon. Các Quái Thú họ Rồng được huấn luyện và Bird Beast chịu trách nhiệm chỉ huy. Và sau đó hình thành một hiệu quả chiến đấu mạnh mẽ.', '0'),
(11093, 'Viên đá đen huyền thoại', 'Rồng', 'Ám', 'Mắt Đỏ', 1, 0, 0, 'UR', 0, 3, 'csdhs', 'Một loại đá đặc biệt từng xuất hiện ở nơi tập trung của những con rồng đen mắt đỏ. Người ta nói rằng những con rồng đen mắt đỏ có thể cảm nhận được năng lượng phát ra từ nó.', '0'),
(11094, 'Gấu trúc điện tử', 'Tâm Linh', 'Hỏa', 'Không có', 4, 1700, 1400, 'UR', 0, 3, 'dzxm', 'Được làm theo hình dáng của một chú gấu trúc - vẫn phải mất rất nhiều thời gian để tạo ra hiệu ứng quầng thâm.', '0'),
(11095, 'Đầu phun điện', 'Tâm Linh', 'Địa', 'Không có', 4, 1300, 1400, 'SR', 0, 3, 'llzss', 'Bạn có thể tiêm năng lượng đặc biệt vào Quái Thú điều khiển từ xa để khiến chúng trở nên hung bạo.', '0'),
(11096, 'nữ chiến binh di truyền', 'Tâm Linh', 'Phong', 'Không có', 4, 1700, 1400, 'UR', 0, 3, 'jynzs', 'Mặc dù cánh tay đã được tăng cường - nhưng khuôn mặt thực sự phải được tăng cường nhiều hơn.', '0'),
(11097, 'siêu tàu khu trục', 'Tâm Linh', 'Địa', 'Không có', 4, 1600, 400, 'SR', 0, 3, 'cnphz', 'Nó phá hủy bằng cách giải phóng sóng điều khiển từ xa nên phần đỡ ở tấm đáy cần phải cực kỳ ổn định.', '0'),
(11098, 'khả năng thấu thị', 'Tâm Linh', 'Ám', 'Không có', 2, 1200, 400, 'SR', 0, 3, 'tyt', 'Bạn có thể tạm thời nhìn vào tương lai và bằng cách nhìn trộm - bạn có thể chuẩn bị trước cho trận chiến để bảo vệ bản thân.', '0'),
(11099, 'Yêu tinh ngoại cảm cuối cùng', 'Tâm Linh', 'Địa', 'Không có', 5, 2200, 1700, 'UR', 0, 3, 'zznlsrm', 'Những con yêu tinh được biến đổi bởi telekinesis đã học được cách hợp tác trong chiến đấu.', '0'),
(11100, 'người bảo vệ tinh thần', 'Tâm Linh', 'Quang', 'Không có', 3, 0, 2200, 'UR', 0, 3, 'jsfhz', 'Một lá chắn tinh thần không thể phá hủy.', '0'),
(11101, 'Nghệ sĩ sáng tác Lesbelt', 'Tâm Linh', 'Phong', 'Không có', 3, 800, 800, 'SR', 0, 3, 'txslsbet', 'Bạn có thể thay đổi xếp hạng sao Quái Thú theo ý muốn - nhưng nó không ổn định lắm và đôi khi bạn có thể mắc sai lầm.', '0'),
(11102, 'Quái Thú điều khiển từ xa', 'Tâm Linh', 'Địa', 'Không có', 2, 700, 500, 'UR', 0, 3, 'ndls', 'Con Quái Thú điều khiển từ xa khổng lồ có thể xác định chính xác các biến động của điều khiển từ xa.', '0'),
(11103, 'kinh thánh tái sinh', 'Tâm Linh', 'Địa', 'Không có', 1, 700, 300, 'SR', 0, 3, 'zssj', 'Kinh thánh - có khả năng tái sinh - được cho là đã tồn tại hàng trăm triệu năm.', '0'),
(11104, 'người huyền bí', 'Tâm Linh', 'Địa', 'Không có', 1, 100, 100, 'SR', 0, 3, 'mxj', 'Anh ta bí mật nghiên cứu mối quan hệ giữa bộ não và khả năng điều khiển từ xa - đồng thời không ngần ngại tiến hành các thí nghiệm trên chính mình.', '0'),
(11105, 'chỉ huy điều khiển từ xa', 'Tâm Linh', 'Địa', 'Không có', 3, 1400, 800, 'SR', 0, 3, 'nlslg', 'Tổng tư lệnh chiến trường quan sát hướng chiến trường từ tàu vũ trụ tàng hình.', '0'),
(11106, 'Phế liệu khổng lồ', 'Máy Móc', 'Địa', 'Phế Liệu', 6, 2000, 2400, 'UR', 0, 3, 'fpjr', 'Một trong những Bộ Bài Yu-Gi-Oh. Bộ Bài chủ đề được nhân vật chính Yusei Fudo sử dụng trong <Yu-Gi-Oh 5D\'s>. Sử dụng <Descrap Synchronizer> để điều chỉnh - Synchro sẽ triệu hồi nhiều Quái Thú được Synchro <Descrap> khác nhau.', '0'),
(11107, 'bẫy biến tần', 'Chiến Sĩ', 'Ám', 'Không có', 2, 600, 600, 'SR', 0, 3, 'xjddz', 'Anh ta có thể du hành xuyên không gian và thích chơi khăm.', '0'),
(11108, 'Quái Thú răng xích đen', 'Ác Ma', 'Ám', 'Không có', 1, 400, 0, 'UR', 0, 3, 'ahlcg', 'Một ý nghĩ xấu xa sống trong các bánh răng cơ khí và thích trêu chọc con người bằng những sợi dây xích gắn liền.', '0'),
(11109, 'Vua Phùng Lai·Diệp Phong', 'Ác Ma', 'Ám', 'Không có', 4, 1700, 1300, 'UR', 0, 3, 'flwyf', 'Nó có thể tạm thời điều khiển những cơn gió lớn trong bán kính mười dặm - đồng thời có thể sơ tán toàn bộ không khí để tạm thời hình thành một vùng chân không.', '0'),
(11110, 'Bộ cộng hưởng tối', 'Ác Ma', 'Ám', 'Cộng Hưởng Resonator', 3, 1300, 300, 'UR', 0, 3, 'ahgmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
(11111, 'Bộ cộng hưởng sen đỏ', 'Ác Ma', 'Thủy', 'Cộng Hưởng Resonator', 2, 600, 200, 'UR', 0, 3, 'hlgmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
(11112, 'Sói sen đỏ', 'Ác Ma', 'Thủy', 'Không có', 6, 1400, 2200, 'UR', 0, 3, 'hll', 'Synchro hai sao (sử dụng hai quái thú Tuner để Synchro với các Quái Thú khác) là một tính năng của Bộ Bài của nó.', '0'),
(11113, 'Tạo tiếng vang', 'Ác Ma', 'Phong', 'Cộng Hưởng Resonator', 3, 800, 600, 'UR', 0, 3, 'czgmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
(11114, 'Bộ cộng hưởng lá chắn', 'Ác Ma', 'Quang', 'Cộng Hưởng Resonator', 1, 300, 800, 'UR', 0, 3, 'hzgmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
(11115, 'Bộ cộng hưởng chuỗi', 'Ác Ma', 'Quang', 'Cộng Hưởng Resonator', 1, 100, 100, 'UR', 0, 3, 'slgmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
(11116, 'Người bảo vệ hoa sen đỏ', 'Ác Ma', 'Thủy', 'Không có', 4, 0, 2000, 'UR', 0, 3, 'hlswz', 'Synchro hai sao (sử dụng hai quái thú Tuner để Synchro với các Quái Thú khác) là một tính năng của Bộ Bài của nó.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(11117, 'Giả vờ cải trang ·Wei Yin', 'Pháp Sư', 'Phong', 'Cơ Xảo Karakuri', 4, 1850, 1500, 'UR', 0, 3, 'pyzzwy', 'Sứ thần Gió thăng cấp lên Sứ giả Tinh linh cấp cao hơn thông qua giao tiếp sâu hơn với nguyên tố gió.', '0'),
(11118, 'bướm bản Địa Tộc', 'Côn Trùng', 'Phong', 'Không có', 5, 1200, 900, 'UR', 0, 3, 'yshd', 'Những con bướm chỉ có thể được nhìn thấy vào đầu mùa hè - vô cùng đẹp.', '0'),
(11119, 'dẫn xuất màu đỏ thẫm', 'Ác Ma', 'Thủy', 'Không có', 1, 0, 0, 'N', 0, 3, 'fhysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11120, 'Ác quỷ đang đến', 'Ác Ma', 'Ám', 'Ác Ma', 6, 2500, 1200, 'UR', 0, 3, 'emjl', 'Một con Quái Thú nghi lễ được triệu hồi bởi Ma Pháp quỷ.', '0'),
(11121, 'Sự im lặng của Xunfeng·Kam', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 4, 1700, 1100, 'UR', 0, 3, 'xfdjjkm', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11122, 'Sóc', 'Sấm Sét', 'Phong', 'Gió Lốc Windwitch', 2, 0, 1800, 'UR', 0, 3, 'xfss', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11123, 'Niềm hy vọng và sức mạnh thần thánh của Xunfeng', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 2, 200, 1000, 'UR', 0, 3, 'xfdxwsw', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11124, 'Nhà hiền triết Xunfeng - Wendal', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 6, 2000, 1000, 'UR', 0, 3, 'xfdxzwde', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11125, 'Xunfengying', 'Chim Thú', 'Phong', 'Gió Lốc Windwitch', 1, 200, 400, 'UR', 0, 3, 'xfy', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11126, 'Phù Thủy Tộc gió: Veinda', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 2, 1000, 400, 'UR', 0, 3, 'xfdwnwyd', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11127, 'Xunfengpeng', 'Chim Thú', 'Phong', 'Gió Lốc Windwitch', 3, 500, 500, 'UR', 0, 3, 'xfp', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11128, 'Xunfeng Falcon', 'Chim Thú', 'Phong', 'Gió Lốc Windwitch', 2, 600, 1400, 'UR', 0, 3, 'xfs', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11129, 'Xunfeng\'s Gale·Liz', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 5, 1900, 1400, 'UR', 0, 2, 'xfdjflz', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11130, 'Linh mục của Xunfeng - Musto', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 4, 1800, 900, 'UR', 0, 3, 'xfdsgmst', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11131, 'Vua rễ độc', 'Thực Vật', 'Hỏa', 'Không có', 4, 1500, 1000, 'UR', 0, 3, 'dgw', 'Rễ có đặc tính độc hại cao sẽ không xuất hiện ở cùng một nơi vào cùng một thời điểm.', '0'),
(11132, 'Sakurahime Thalia', 'Thực Vật', 'Hỏa', 'Không có', 8, 2800, 1200, 'UR', 0, 3, 'yjtly', 'Một trong những nữ hoàng hoa - nguyên mẫu là nữ thần trong thần thoại Hy Lạp và là một trong ba nữ thần sắc đẹp.', '0'),
(11133, 'Bến du thuyền Ji Kui', 'Thực Vật', 'Thủy', 'Không có', 8, 2800, 1600, 'UR', 0, 3, 'jkmln', 'Một trong những nữ hoàng hoa - nguyên mẫu là nữ thần mặt trời trong thần thoại Inuit.', '0'),
(11134, 'cảnh sát Địa Tộc ngục', 'Ác Ma', 'Ám', 'Không có', 1, 100, 600, 'SR', 0, 3, 'dyzajc', 'Một thành viên của Đội An ninh Địa ngục sống một cuộc sống bận rộn và trọn vẹn mỗi ngày.', '0'),
(11135, 'gấu Địa Tộc ngục', 'Thú', 'Ám', 'Không có', 4, 1300, 1800, 'SR', 0, 3, 'dydfx', 'Những con Quái Thú trong Địa Tộc ngục thường di chuyển xung quanh Sảnh Quỷ.', '0'),
(11136, 'Wei Yin thổi mạnh', 'Pháp Sư', 'Phong', 'Không có', 4, 800, 1500, 'SR', 0, 3, 'mczwy', 'Sức mạnh của Wind Spiritist đã gây ra một cuộc bạo loạn.', '0'),
(11137, 'Ossi hoang dã và điên rồ', 'Pháp Sư', 'Địa', 'Không có', 4, 800, 1500, 'SR', 0, 3, 'hkzas', 'Sức mạnh của các sứ thần trái đất đã gây ra một cuộc bạo loạn.', '0'),
(11138, 'Thủy Thần Arya', 'Pháp Sư', 'Hỏa', 'Gusto', 4, 500, 1500, 'SR', 0, 3, 'slsaly', '<Spirit Envoy> có thể giành quyền kiểm soát quái thú của đối phương với thuộc tính tương ứng.', '0'),
(11139, 'Quỷ não tâm thần', 'Tâm Linh', 'Quang', 'Không có', 1, 100, 200, 'SR', 0, 3, 'jsnm', 'Cơ thể ban đầu đã bị hiến tế để tăng cường sức mạnh cho bộ não hơn nữa.', '0'),
(11140, 'Vua Jig', 'Tâm Linh', 'Địa', 'Không có', 8, 2600, 1400, 'UR', 0, 3, 'jgdw', 'Một đất nước có thể bị phá hủy chỉ bằng một ý nghĩ.', '0'),
(11141, 'Tâm lý con người được nâng cao', 'Tâm Linh', 'Địa', 'Không có', 4, 1500, 800, 'UR', 0, 3, 'qhrlsk', 'Do bị biến đổi quá mức - chúng sẽ săn lùng và ăn thịt những dạng sống sử dụng khả năng điều khiển từ xa một cách điên cuồng.', '0'),
(11142, 'Cá mập vực thẳm kế thừa', 'Cá', 'Hỏa', 'Di Sản Tinh Tú', 2, 800, 500, 'SR', 0, 3, 'yssys', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(11143, 'Quỷ Vệ Quang', 'Ác Ma', 'Quang', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'wgmr', 'Những người sử dụng năng lực sinh ra từ ánh sáng hùng vĩ có thể Phong Tộc ấn các con đường năng lượng.', '0'),
