(11199, 'côn trùng lưỡi điện', 'Côn Trùng', 'Địa', 'Không có', 4, 2400, 0, 'UR', 0, 3, 'ddrc', 'Mặc dù có sức tàn phá rất lớn nhưng cũng không dễ gì che giấu được.', '0'),
(11200, 'hoa sen hiến tế', 'Thực Vật', 'Ám', 'Không có', 1, 0, 0, 'SR', 0, 3, 'xjzl', 'Để tế hoa sen đã ra đời - những cánh hoa sen tái sinh sẽ nhiều hơn trước một cánh.', '0'),
(11201, 'Thần ánh sáng Thetis', 'Thiên Thần', 'Quang', 'Không có', 5, 2400, 1800, 'UR', 0, 3, 'gstts', 'Vị thần đại diện cho ánh sáng sẽ không bao giờ bị ham muốn lay chuyển.', '0'),
(11202, 'Tiên Phong Tộc kế thừa', 'Pháp Sư', 'Hỏa', 'Di Sản Tinh Tú', 4, 1500, 800, 'SR', 0, 3, 'ysxf', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(11203, 'Linh hồn di sản tà ác djinn', 'Thủy Tộc', 'Hỏa', 'Di Sản Tinh Tú', 10, 3200, 0, 'UR', 0, 3, 'xyshpjl', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(11204, 'Phù Thủy kế thừa Arial', 'Pháp Sư', 'Hỏa', 'Di Sản Tinh Tú', 4, 1000, 1800, 'UR', 0, 3, 'ysssalye', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(11205, 'Quái Thú kế thừa', 'Thú', 'Hỏa', 'Di Sản Tinh Tú', 4, 1500, 1300, 'UR', 0, 3, 'yss', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(11206, 'chuyển phát nhanh chuyển phát nhanh', 'Máy Móc', 'Địa', 'Tuner', 2, 0, 1000, 'SR', 0, 3, 'ttsysz', 'Một trong những Bộ Bài <Yu-Gi-Oh>. <Yu-Gi-Oh 5D\'s> là phần quan trọng nhất trong Bộ Bài của nhân vật chính Fudo Yusei - hỗ trợ một số lượng lớn Quái Thú Synchro <Warrior> và <Trash>.', '0'),
(11207, 'Nhân viên hỗ trợ điều phối', 'Máy Móc', 'Quang', 'Không có', 1, 100, 300, 'SR', 0, 3, 'thzys', 'Tại sao họ lại nhìn tôi háo hức khi nói rằng tôi sẽ không chịu trách nhiệm?', '0'),
(11208, 'Xương rồng sao', 'Rồng', 'Phong', 'Không có', 4, 1000, 2000, 'UR', 0, 3, 'xhl', 'Có sức mạnh dễ dàng phá hủy các hành tinh.', '0'),
(11209, 'Máy lọc', 'Pháp Sư', 'Quang', 'Không có', 2, 0, 900, 'SR', 0, 3, 'jhsxz', 'Dù biết mình phải hiến tế nhưng bạn vẫn dâng lời chúc phúc cho tân sinh: Mong bạn có thể nhìn thấy cầu vồng mà không gặp gió mưa.', '0'),
(11210, 'Thánh ấn của vua rồng', 'Rồng', 'Quang', 'Hieratic', 6, 0, 0, 'UR', 0, 3, 'lwzsky', 'Không giống như <Thánh Ấn Của Rồng> - nó chỉ thể hiện sức mạnh trong bóng tối.', '0'),
(11211, 'bí ngô tự nhiên', 'Thực Vật', 'Địa', 'Tự Nhiên', 4, 1400, 800, 'SR', 0, 3, 'zrng', 'Bao gồm nhiều chủng tộc khác nhau gần gũi với thiên nhiên - họ là những tinh linh thiên nhiên vô cùng dễ thương.', '0'),
(11212, 'cây rối', 'Thực Vật', 'Địa', 'Không có', 3, 1000, 1000, 'UR', 0, 3, 'klzw', 'Hạt giống có thể ký sinh trong cơ thể con người và có thể gây tử vong nếu không được loại bỏ kịp thời.', '0'),
(11213, 'Thiên thần Phép Thuật·Phù Thủy hoa hồng', 'Thực Vật', 'Địa', 'Hoa Hồng', 7, 2400, 1300, 'UR', 0, 3, 'mtsqwzws', 'Nàng tiên hoa hồng tím cầm một chiếc roi hoa hồng tím.', '0'),
(11214, 'Đại quỷ thiên thần·Hoa hồng tiên', 'Thực Vật', 'Địa', 'Hoa Hồng', 8, 2900, 2400, 'UR', 0, 3, 'dlmtsqwx', 'Đợi đã - tại sao phiên bản kết hợp của Rose Fairy lại là đàn ông?', '0'),
(11215, 'Thiên thần lạnh lùng · Nữ hoàng hoa hồng', 'Thực Vật', 'Địa', 'Hoa Hồng', 7, 2400, 1300, 'UR', 0, 3, 'ltsqwznw', 'Nàng tiên hoa hồng đỏ cầm một thanh kiếm hoa hồng đỏ.', '0'),
(11216, 'Mã thông báo đồng bộ', 'Máy Móc', 'Địa', 'Tuner', 2, 1000, 0, 'N', 0, 3, 'ttsysw', 'Lá bài này có thể được sử dụng làm token.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(11217, 'Giả vờ ăn mặc như Sita', 'Pháp Sư', 'Thủy', 'Cơ Xảo Karakuri', 4, 1850, 1500, 'UR', 0, 3, 'pyzzxt', 'Phái viên Tinh linh Ngọn lửa thăng tiến lên các Sứ giả Tinh linh cấp cao hơn thông qua giao tiếp sâu hơn với nguyên tố lửa.', '0'),
(11218, 'Vua của sự kết thúc Demis', 'Ác Ma', 'Ám', 'Không có', 8, 2400, 2000, 'UR', 0, 3, 'zyzwdms', 'Quỷ vương Ma Phápng đến sự kết thúc thường hợp tác với <Nữ thần hủy diệt Luin> để tạo ra thảm họa.', '0'),
(11219, 'Liếm con chó ba lưỡi', 'Tâm Linh', 'Địa', 'Không có', 3, 0, 1800, 'UR', 0, 3, 'ttssq', 'Chỉ cần một cái xẻng xúc được một cứt - nhưng nó có thể Ma Phápng lại hạnh phúc gấp ba lần.', '0'),
(11220, 'X kiếm sĩ Urd', 'Chiến Sĩ Thú', 'Địa', 'Kiếm Sĩ X', 4, 1600, 1000, 'UR', 0, 3, 'xjswed', 'Dòng <X SwordsMa Phápn> bao gồm các Quái Thú thuộc tính thổ. Các chủng tộc bao gồm nhiều chủng tộc phổ biến như chủng tộc chiến binh và chủng tộc chiến binh quái thú - với chủ đề là Triệu Hồi Synchro.', '0'),
(11221, 'Phim hoạt hình rồng mắt đỏ thật', 'Rồng', 'Ám', 'Mắt Đỏ', 7, 2400, 2000, 'UR', 0, 3, 'zhyktl', 'Một Quái Thú yêu cầu lá bài Phép Thuật then chốt <Cartoon World> để được triệu hồi. Bekas thích sử dụng Bộ Bài này.', '0'),
(11222, 'Địa ngục Erebus', 'Zombie', 'Ám', 'Không có', 8, 2800, 1000, 'UR', 0, 3, 'mderbs', 'Hoàng đế vĩ đại của Địa ngục đảm nhiệm mọi việc trong Địa ngục từ ngai vàng của Địa ngục - và thỉnh thoảng cử các hiệp sĩ của mình đi gây rắc rối ở các cõi khác.', '0'),
(11223, 'Hoàng đế Kreis', 'Chiến Sĩ', 'Quang', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'gdkls', 'Hoàng đế điều khiển nguyên tố ánh sáng - ánh sáng thuần khiết có thể Ma Phápng lại sự chữa lành và bỏng rát.', '0'),
(11224, 'Hậu duệ của Xunfeng - Pilijia', 'Tâm Linh', 'Phong', 'Gió Lốc Windwitch', 3, 1000, 1500, 'UR', 0, 3, 'xfdsyplj', 'Chiến thuật của Xunfeng chủ yếu dựa vào đồng đội đã ngã xuống để triệu hồi một đồng đội khác. Với việc triệu hồi nhiều lần như thế này - cùng với nhiều lần hồi phục khác nhau - Xunfeng đã trở thành một trong những loại lá bài có tính phòng thủ cao nhất.', '0'),
(11225, 'Phù Thủy bóng tối Mahad', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 7, 2500, 2100, 'UR', 0, 1, 'ahmfsmhd', 'Phù Thủy hắc Ám Tộc đánh thức ký ức từ 3.000 năm trước.', '0'),
(11226, 'Victoria', 'Thiên Thần', 'Quang', 'Không có', 4, 1800, 1500, 'UR', 0, 2, 'wdly', 'Một thiên sứ có thể cộng hưởng tinh thần với long tộc - vương trượng trong tay có sự phù hộ của long thần.', '0'),
(11227, 'Anh hùng nguyên tố · Lính cứu hỏa', 'Chiến Sĩ', 'Thủy', 'Anh Hùng Nguyên Tố', 4, 1200, 1800, 'UR', 0, 3, 'ysyxlyx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(11228, 'Tội lỗi·Rồng đen mắt đỏ thật sự', 'Rồng', 'Ám', 'Tội Ác Malefic', 7, 2400, 2000, 'UR', 0, 3, 'zzhyhl', 'Quái Thú <Sin> phụ thuộc rất nhiều vào Địa Tộc điểm. Một khi Địa Tộc điểm bị phá hủy - Quái Thú <Sin> không thể tồn tại - vì vậy hãy cẩn thận để bảo vệ Địa Tộc điểm khỏi bị ảnh hưởng.', '0'),
(11229, 'Đội trưởng chiến binh của Vương quốc quỷ bóng tối·Thanh kiếm bóng tối', 'Chiến Sĩ', 'Ám', 'Không có', 4, 1800, 1500, 'UR', 0, 3, 'amjdzszahzj', '<Dark Sword> được thăng chức đội trưởng chiến binh sau khi trải qua Chiến tranh Vương quốc Quỷ.', '0'),
(11230, 'Trình điều khiển bộ xương PSY', 'Tâm Linh', 'Quang', 'Khung Xương PSY', 6, 2500, 0, 'UR', 0, 3, 'psygjqdz', 'Quái Thú bao gồm thuộc tính ánh sáng và loại điều khiển từ xa - đồng thời là một Bộ Bài có chủ đề Triệu Hồi Synchro. Tính năng là bạn có thể triệu hồi đặc biệt các quái thú <PSY Skeleton Equipment> và <PSY Skeleton Driver> khác nhau để đáp lại hoạt động của đối phương khi bạn ở trước sân để can thiệp vào hoạt động của đối phương hoặc mở rộng bản thân.', '0'),
(11231, 'Bộ xương người nhiều đường PSY', 'Tâm Linh', 'Quang', 'Khung Xương PSY', 6, 0, 2500, 'UR', 0, 3, 'psygjdxr', 'Quái Thú bao gồm thuộc tính ánh sáng và loại điều khiển từ xa - đồng thời là một Bộ Bài có chủ đề Triệu Hồi Synchro. Tính năng là bạn có thể triệu hồi đặc biệt các quái thú <PSY Skeleton Equipment> và <PSY Skeleton Driver> khác nhau để đáp lại hoạt động của đối phương khi bạn ở trước sân để can thiệp vào hoạt động của đối phương hoặc mở rộng bản thân.', '0'),
(11232, 'Thiết bị bộ xương PSY·A', 'Tâm Linh', 'Quang', 'Khung Xương PSY', 1, 500, 0, 'UR', 0, 3, 'psygjzba', 'Quái Thú bao gồm thuộc tính ánh sáng và loại điều khiển từ xa - đồng thời là một Bộ Bài có chủ đề Triệu Hồi Synchro. Tính năng là bạn có thể triệu hồi đặc biệt các quái thú <PSY Skeleton Equipment> và <PSY Skeleton Driver> khác nhau để đáp lại hoạt động của đối phương khi bạn ở trước sân để can thiệp vào hoạt động của đối phương hoặc mở rộng bản thân.', '0'),
(11233, 'Thiết bị bộ xương PSY·B', 'Tâm Linh', 'Quang', 'Khung Xương PSY', 1, 700, 0, 'UR', 0, 3, 'psygjzbb', 'Quái Thú bao gồm thuộc tính ánh sáng và loại điều khiển từ xa - đồng thời là một Bộ Bài có chủ đề Triệu Hồi Synchro. Tính năng là bạn có thể triệu hồi đặc biệt các quái thú <PSY Skeleton Equipment> và <PSY Skeleton Driver> khác nhau để đáp lại hoạt động của đối phương khi bạn ở trước sân để can thiệp vào hoạt động của đối phương hoặc mở rộng bản thân.', '0'),
(11234, 'Thiết bị bộ xương PSY·D', 'Tâm Linh', 'Quang', 'Khung Xương PSY', 2, 1200, 0, 'UR', 0, 3, 'psygjzbx', 'Quái Thú bao gồm thuộc tính ánh sáng và loại điều khiển từ xa - đồng thời là một Bộ Bài có chủ đề Triệu Hồi Synchro. Tính năng là bạn có thể triệu hồi đặc biệt các quái thú <PSY Skeleton Equipment> và <PSY Skeleton Driver> khác nhau để đáp lại hoạt động của đối phương khi bạn ở trước sân để can thiệp vào hoạt động của đối phương hoặc mở rộng bản thân.', '0'),
(11235, 'Thiết bị bộ xương PSY·E', 'Tâm Linh', 'Quang', 'Khung Xương PSY', 2, 1500, 0, 'UR', 0, 3, 'psygjzbe', 'Quái Thú bao gồm thuộc tính ánh sáng và loại điều khiển từ xa - đồng thời là một Bộ Bài có chủ đề Triệu Hồi Synchro. Tính năng là bạn có thể triệu hồi đặc biệt các quái thú <PSY Skeleton Equipment> và <PSY Skeleton Driver> khác nhau để đáp lại hoạt động của đối phương khi bạn ở trước sân để can thiệp vào hoạt động của đối phương hoặc mở rộng bản thân.', '0'),
(11236, 'Lỗi đánh cắp cấp độ', 'Côn Trùng', 'Ám', 'Không có', 1, 600, 0, 'UR', 0, 1, 'djtqc', 'Do kể chuyện quá nhiều nên tôi vĩnh viễn vào phòng tối.', '0'),
(11237, 'Giả vờ ăn diện ·Lena', 'Pháp Sư', 'Quang', 'Cơ Xảo Karakuri', 4, 1850, 1500, 'UR', 0, 3, 'pyzzln', 'Đặc sứ ánh sáng thăng tiến lên sứ giả cấp cao hơn thông qua việc liên lạc sâu hơn với các nguyên tố ánh sáng.', '0'),
(11238, 'cô gái xinh đẹp bất hạnh', 'Pháp Sư', 'Quang', 'Không có', 1, 0, 100, 'SR', 0, 3, 'bxdmsn', 'Bạn có muốn một gói diêm không?', '0'),
(11239, 'Thiền sư·Viên Đạo', 'Pháp Sư', 'Hỏa', 'Không có', 4, 300, 1800, 'UR', 0, 3, 'xcsyd', 'Một nhà sư và thầy phù Thủy Tộc dựa trên người sáng lập Giáo phái Soto của Phật giáo Nhật Bản.', '0'),
(11240, 'kẻ tấn công Phép Thuật', 'Chiến Sĩ', 'Địa', 'Không có', 4, 1800, 600, 'UR', 0, 3, 'mfjjz', 'Vũ khí trong tay có khả năng phá Phép Thuật.', '0'),
(11241, 'Congqi Aditya của Hoàng đế', 'Chiến Sĩ', 'Quang', 'Không có', 1, 800, 1000, 'UR', 0, 3, 'tdcqady', 'Hiệp sĩ trung thành nhất của Thiên Đế - người có thể cống hiến mọi thứ cho Thiên Hoàng.', '0'),
(11242, 'Thánh chiến binh hỗn loạn chiến binh', 'Chiến Sĩ', 'Quang', 'Chiến Binh Hỗn Độn', 8, 3000, 2500, 'UR', 0, 3, 'szshdzs', 'Những chiến binh hỗn loạn được thần thánh ban phước sẽ tỏa sáng với ánh sáng thần thánh khi giải phóng kỹ năng của mình.', '0'),
(11243, 'Hunyuanlong·Vòng xoáy khổng lồ tổ thần', 'Rồng', 'Ám', 'Không có', 8, 3000, 0, 'UR', 0, 3, 'hyljwszs', 'Con rồng sinh ra ở nguồn gốc của sự hỗn loạn có thể điều khiển dòng chảy của các yếu tố ánh sáng và bóng tối theo ý muốn.', '0'),
(11244, 'cai trị rồng', 'Pháp Sư', 'Ám', 'Không có', 4, 1200, 1100, 'UR', 0, 3, 'lztzz', '<Dragon Ruler> gần đây đã bị Ám Tộc ảnh bởi âm nhạc và việc thổi sáo không còn đủ nữa.', '0'),
(11245, 'Anh hùng định mệnh · Kẻ hủy diệt', 'Chiến Sĩ', 'Ám', 'Anh Hùng Định Mệnh', 4, 1000, 1000, 'UR', 0, 3, 'myyxpmr', 'Một trong những Bộ Bài Yu-Gi-Oh. Thuộc một trong sáu Bộ Bài <Hero>. Một loạt Bộ Bài được đấu sĩ Ed Phoenix sử dụng trong <Yu-Gi-Oh GX> và <Yu-Gi-Oh ARC-V>.', '0'),
(11246, 'Anh hùng định mệnh · Người đàn ông xứ sở mộng mơ', 'Chiến Sĩ', 'Ám', 'Anh Hùng Định Mệnh', 1, 0, 600, 'UR', 0, 3, 'myyxmxr', 'Một trong những Bộ Bài Yu-Gi-Oh. Thuộc một trong sáu Bộ Bài <Hero>. Một loạt Bộ Bài được đấu sĩ Ed Phoenix sử dụng trong <Yu-Gi-Oh GX> và <Yu-Gi-Oh ARC-V>.', '0'),
(11247, 'Anh hùng định mệnh · Người khoan', 'Chiến Sĩ', 'Ám', 'Anh Hùng Định Mệnh', 4, 1600, 1200, 'UR', 0, 3, 'myyxztr', 'Một trong những Bộ Bài Yu-Gi-Oh. Thuộc một trong sáu Bộ Bài <Hero>. Một loạt Bộ Bài được đấu sĩ Ed Phoenix sử dụng trong <Yu-Gi-Oh GX> và <Yu-Gi-Oh ARC-V>.', '0'),
(11248, 'Anh hùng định mệnh · Thần nhân', 'Chiến Sĩ', 'Ám', 'Anh Hùng Định Mệnh', 4, 1600, 1400, 'UR', 0, 3, 'myyxsxr', 'Một trong những Bộ Bài Yu-Gi-Oh. Thuộc một trong sáu Bộ Bài <Hero>. Một loạt Bộ Bài được đấu sĩ Ed Phoenix sử dụng trong <Yu-Gi-Oh GX> và <Yu-Gi-Oh ARC-V>.', '0'),
