(11300, 'Boss hiệp sĩ', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1700, 900, 'UR', 0, 3, 'sqsbs', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(11301, 'Hiệp sĩ Percival', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1900, 300, 'UR', 0, 3, 'sqspxwe', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(11302, 'Hiệp sĩ quỷ dữ Lancelot', 'Chiến Sĩ', 'Ám', 'Hiệp Sĩ', 5, 2000, 800, 'UR', 0, 3, 'msqslslt', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(11303, 'Hiệp sĩ Ivan', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1700, 1600, 'UR', 0, 3, 'sqsyw', 'Quái Thú <Paladin> đều là loại chiến binh và chúng được tổ chức xung quanh các lá bài Phép Thuật trang bị có <Holy Sword> trong tên của chúng.', '0'),
(11304, 'Chiến binh tê giác Warcraft', 'Ác Ma', 'Địa', 'Không có', 3, 1400, 900, 'UR', 0, 3, 'msxzs', 'Tại sao lần nào anh cũng phải đánh tôi trước? Tôi yếu đuối và bất lực.', '0'),
(11305, 'Vệ sĩ tấn công búa', 'Chiến Sĩ', 'Địa', 'Không có', 6, 2300, 2000, 'UR', 0, 3, 'zctjbb', 'Để bảo vệ em - anh thậm chí còn biến đôi tay mình thành vũ khí nhưng anh không thể ôm em được nữa.', '0'),
(11306, 'người khổng lồ mạnh mẽ', 'Nham Thạch', 'Địa', 'Không có', 6, 2200, 0, 'UR', 0, 3, 'qljr', 'Để thuận tiện cho việc vận chuyển - đôi khi bạn có thể làm nó thật nhỏ.', '0'),
(11307, 'Vua Phép Thuật học·Yuexing', 'Ác Ma', 'Ám', 'Không có', 3, 900, 600, 'UR', 0, 3, 'qswyx', 'Ta muốn đại biểu cho mặt trăng - à không - ta muốn tiêu diệt ngươi!', '0'),
(11308, 'Phù Thủy tập sự tưởng tượng', 'Pháp Sư', 'Ám', 'Không có', 6, 2000, 1700, 'UR', 0, 1, 'hxdjxmds', 'Người học việc của Phù Thủy đen huyền ảo - mặc dù vẫn đang trong giai đoạn học việc nhưng đã thể hiện tài năng đáng kinh ngạc.', '0'),
(11309, 'Mã thông báo hiệp sĩ', 'Chiến Sĩ', 'Quang', 'Hiệp Sĩ', 4, 1000, 1000, 'UR', 0, 3, 'sqsysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11310, 'Rồng sao đen', 'Rồng', 'Ám', 'Không có', 5, 2400, 1200, 'UR', 0, 3, 'ahyxl', 'Sinh ra cùng với <Light Pulsar Dragon> - có thể nói rằng họ là những người yêu nhau thời thơ ấu... vi - rồng?', '0'),
(11311, 'Rồng sao xung ánh sáng', 'Rồng', 'Quang', 'Không có', 6, 2500, 1500, 'UR', 0, 3, 'gmcxl', 'Sinh ra cùng với <Dark Star Dragon> - có thể nói rằng họ là những người yêu nhau thời thơ ấu... vi - rồng?', '0'),
(11312, 'Cơn ác mộng về xương', 'Zombie', 'Ám', 'Bộ Xương', 1, 300, 200, 'UR', 0, 3, 'bgmy', 'Những mảnh xương được tập hợp trong nghĩa trang có thể trở thành một thế lực mạnh mẽ.', '0'),
(11313, 'Thiên thần sa ngã Ukobak', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 3, 700, 1000, 'UR', 0, 3, 'dltswkbk', 'Đội tiên Phong Tộc của các thiên thần sa ngã có thể hoàn thành mảng dịch chuyển máy bay để giúp các thiên thần sa ngã khác hạ cánh.', '0'),
(11314, 'Hắc Long·Thu gọn Tinh Xà', 'Rồng', 'Ám', 'Không có', 4, 1800, 1700, 'UR', 0, 3, 'ahltsxs', 'Họ đã nói với tôi rằng tôi là một con rồng!', '0'),
(11315, 'Hui Bailong·Thằn lằn bay Bảo Nguyên', 'Rồng', 'Quang', 'Không có', 4, 1700, 1800, 'UR', 0, 3, 'hblbyyl', 'Con rắn nhỏ - con rắn nhỏ - hãy nhìn quả cầu năng lượng của tôi - nó to và tròn.', '0'),
(11316, 'Hiệu ứng tiêu diệt Quái Thú', 'Rồng', 'Ám', 'Không có', 4, 1800, 1700, 'UR', 0, 3, 'xgphgs', 'Họ đã nói với tôi rằng tôi là một con rồng!', '0');
