(11398, 'phù Thủy Tộc Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 7, 2000, 2000, 'UR', 0, 1, 'xxgyn', 'Sở hữu sức quyến rũ chết người - bất cứ ai cũng sẽ khuất phục trước đôi mắt đỏ như máu của cô (kể cả Billy).', '0'),
(11399, 'nam tước đỏ Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 6, 2400, 1000, 'UR', 0, 3, 'xxghnj', 'Thế hệ Ma Pháp cà rồng mới Ma Phápng trong mình dòng máu của tổ tiên thực sự có khả năng điều khiển mục tiêu mà chúng tiêu diệt.', '0'),
(11400, 'Đại Phù Thủy Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 4, 1500, 1500, 'UR', 0, 3, 'xxgdws', 'Phù Thủy Ma Pháp cà rồng đánh thức sức mạnh của mình sau khi nhận được một giọt máu của tổ tiên thực sự.', '0'),
(11401, 'cái chết đỏ của Ma Pháp cà rồng', 'Zombie', 'Ám', 'Vampire', 5, 2000, 1400, 'UR', 0, 1, 'xxghss', 'Nguyên mẫu là Thần Chết ở Castlevania - người sử dụng liềm làm vũ khí và trung thành phục vụ Dracula.', '0'),
(11402, 'Rồng ba chiều mắt xanh', 'Rồng', 'Quang', 'Mắt Xanh', 8, 2500, 2000, 'UR', 0, 1, 'qyltl', 'Thành viên mới của gia đình <Mắt Xanh>.', '0'),
(11403, 'Tân hoàng đế gió rồng', 'Rồng', 'Quang', 'Không có', 6, 2400, 2200, 'UR', 0, 3, 'xdwxfl', '<Hoàng Long Phong Long> đã tiến hóa.', '0'),
(11404, 'Con rối cơ khí · Quả trứng nhỏ', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 4, 0, 100, 'UR', 0, 3, 'jgklxad', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11405, 'Cơ chế Con rối·Cánh tay cắt kéo', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 4, 1200, 600, 'UR', 0, 3, 'jgkljdb', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11406, 'Con rối máy móc ·Búp bê NecroMa Phápncer', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 8, 0, 0, 'UR', 0, 3, 'jgklslro', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11407, 'Con rối cơ khí · Con rối từ tính', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 8, 1000, 1000, 'UR', 0, 3, 'jgklclro', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11408, 'Con rối máy ·Bù nhìn', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 4, 800, 2000, 'UR', 0, 3, 'jgkldcr', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11409, 'Con rối máy móc · Em bé kinh dị', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 4, 500, 0, 'UR', 0, 3, 'jgklkbye', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11410, 'Vua Quái Thú trong đầm lầy', 'Thủy Tộc', 'Hỏa', 'Không có', 4, 1000, 1100, 'UR', 0, 3, 'zddmsw', 'Người tiền nhiệm của <Quỷ Vương Đầm Lầy> vẫn có sức mạnh tương đối yếu.', '0'),
(11411, 'Hộp rối cơ chế', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 8, 0, 0, 'UR', 0, 3, 'jgklh', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(11412, 'Nữ yêu tinh tâm linh độc ác', 'Thủy Tộc', 'Hỏa', 'Di Sản Tinh Tú', 6, 2500, 2000, 'UR', 0, 3, 'xysxlnsrm', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(11413, 'Bậc thầy trị liệu bằng hương thơm ·Lá nguyệt quế', 'Thực Vật', 'Phong', 'Hương Thơm', 1, 800, 0, 'UR', 0, 3, 'fxfsygy', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(11414, 'Bậc thầy trị liệu bằng hương thơm · Kinh giới', 'Thực Vật', 'Ám', 'Hương Thơm', 5, 2000, 1600, 'UR', 0, 3, 'fxfsmyl', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(11415, 'Sứ giả ánh sáng·Lena vinh Quang Tộc', 'Pháp Sư', 'Quang', 'Gusto', 6, 500, 2400, 'UR', 0, 3, 'glsghzln', 'Nhà tâm linh ánh sáng nhận ra sức mạnh mới.', '0'),
(11416, 'Anh hùng nguyên tố · Người đàn ông hiện tại', 'Sấm Sét', 'Quang', 'Anh Hùng Nguyên Tố', 4, 1000, 1500, 'UR', 0, 3, 'ysyxdlx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0');
