(11621, 'Shiranui-ryu·Gặp quỷ kiếm của quỷ', 'Zombie', 'Thủy', 'Bất Tri Hỏa Shiranui', 3, 800, 0, 'UR', 0, 3, 'fmzydbzh', '<Quỷ kiếm: Shiranui> nhuốm máu của <Shiranui no Bubu> - và sức mạnh của nó còn được tăng cường hơn nữa.', '0'),
(11622, 'Lông đen ·Abel Lohoros gây sốc', 'Chim Thú', 'Ám', 'Kuriboh', 7, 2600, 1800, 'UR', 0, 3, 'hyjzzyblhl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một Bộ Bài có chủ đề Triệu Hồi Synchro được sử dụng bởi Crow Hogan - nhân vật chính của <Yu-Gi-Oh 5D\'s> và <Yu-Gi-Oh ARC-V>.', '0'),
(11623, 'Đội quân hạng nặng của Poseidon', 'Hải Long', 'Hỏa', 'Hải Hoàng', 2, 0, 1600, 'SR', 0, 3, 'hhdzzb', 'Quái Thú bao gồm Quái Thú thuộc tính nước và rồng biển. Hầu hết các hình dạng đều là sinh vật hình rồng huyền thoại sống dưới biển sâu. <Hải Vương Long Posedra> là hoàng đế cầm quyền.', '0'),
(11624, 'Hoàng tử biển·Vua của Nip Abyss', 'Hải Long', 'Hỏa', 'Hải Hoàng', 1, 800, 0, 'UR', 0, 3, 'hhznpsyw', 'Quái Thú bao gồm Quái Thú thuộc tính nước và rồng biển. Hầu hết các hình dạng đều là sinh vật hình rồng huyền thoại sống dưới biển sâu. <Hải Vương Long Posedra> là hoàng đế cầm quyền.', '0'),
(11625, 'Ác anh hùng · Ác quỷ xác chết', 'Ác Ma', 'Ám', 'Anh Hùng Tà Ác', 5, 1600, 1800, 'UR', 0, 3, 'xxyxxlsm', 'Một trong những Bộ Bài Yu-Gi-Oh. Nó thuộc về một trong sáu Bộ Bài <HERO>. Đây là Bộ Bài được sử dụng bởi Yujo Judai - nhân vật chính của anime <Yu-Gi-Oh GX> - khi anh ngã xuống và trở thành Overlord.', '0'),
(11626, 'Anh Hùng Ác Tâm · Ám Tinh Kim Tinh', 'Ác Ma', 'Quang', 'Anh Hùng Tà Ác', 4, 2100, 800, 'SR', 0, 3, 'xxyxaxjm', 'Một trong những Bộ Bài Yu-Gi-Oh. Nó thuộc về một trong sáu Bộ Bài <HERO>. Đây là Bộ Bài được sử dụng bởi Yujo Judai - nhân vật chính của anime <Yu-Gi-Oh GX> - khi anh ngã xuống và trở thành Overlord.', '0'),
(11627, 'Ác anh hùng · Ác quỷ kiếm', 'Ác Ma', 'Địa', 'Anh Hùng Tà Ác', 7, 2600, 1800, 'SR', 0, 3, 'xxyxerm', 'Một trong những Bộ Bài Yu-Gi-Oh. Nó thuộc về một trong sáu Bộ Bài <HERO>. Đây là Bộ Bài được sử dụng bởi Yujo Judai - nhân vật chính của anime <Yu-Gi-Oh GX> - khi anh ngã xuống và trở thành Overlord.', '0'),
(11628, 'Chúa tể bóng tối Belial', 'Ác Ma', 'Ám', 'Không có', 8, 2800, 2400, 'UR', 0, 3, 'azhjbl', '<Hoàng hậu Ác Ma Pháp> Con quỷ đáng tin cậy nhất.', '0'),
(11629, 'Ngày Haputo', 'Thiên Thần', 'Quang', 'Địa Đáy Subterror', 4, 1800, 800, 'UR', 0, 3, 'hptdr', 'Quái Thú bao gồm các thuộc tính ánh sáng. Các chủng tộc bao gồm chủng tộc cơ khí - chủng tộc thiên thần và chủng tộc sấm sét. Chúng được đặt tên theo nhiều hình ba chiều hoặc chữ cái Hy Lạp. Đặc điểm là chiến thuật được phát triển xoay quanh lá bài trang bị.', '0'),
