(11631, 'Cordalus', 'Hải Long', 'Hỏa', 'Không có', 4, 1400, 1200, 'UR', 0, 3, 'kdls', 'Những người hoàn thành Cửu Hải Thần khảo thí có thể trở thành Hải Long Thần.', '0'),
(11632, 'Lông vũ đen·Thùng giáo đen', 'Chim Thú', 'Ám', 'Kuriboh', 4, 1700, 800, 'UR', 0, 3, 'hyhqzblst', 'Một trong những Bộ Bài Yu-Gi-Oh. Một Bộ Bài có chủ đề Triệu Hồi Synchro được sử dụng bởi Crow Hogan - nhân vật chính của <Yu-Gi-Oh 5D\'s> và <Yu-Gi-Oh ARC-V>.', '0'),
(11633, 'Lông đen·Zephyros tinh nhuệ', 'Chim Thú', 'Ám', 'Kuriboh', 4, 1600, 1000, 'UR', 0, 3, 'hyjrzzfls', 'Một trong những Bộ Bài Yu-Gi-Oh. Một Bộ Bài có chủ đề Triệu Hồi Synchro được sử dụng bởi Crow Hogan - nhân vật chính của <Yu-Gi-Oh 5D\'s> và <Yu-Gi-Oh ARC-V>.', '0'),
(11634, 'đứa trẻ yashiki', 'Zombie', 'Địa', 'Không có', 3, 0, 1800, 'UR', 0, 3, 'wft', 'Do cái chết bất ngờ - linh hồn không thể lên thiên đàng và bị trói trong một căn phòng nhỏ tối tăm.', '0'),
(11635, 'vẻ đẹp dòng chảy màu xÁm Tộc', 'Zombie', 'Thủy', 'Không có', 3, 0, 1800, 'UR', 0, 3, 'hll', 'Con vật nhỏ bị chôn vùi dưới gốc cây hoa anh đào đã biến thành linh hồn của cô gái tai thú - nhưng nó không thể rời khỏi cây hoa anh đào quá xa.', '0'),
(11636, 'Mã thông báo trái tim ác quỷ', 'Ác Ma', 'Ám', 'Không có', 7, 2500, 2500, 'N', 0, 3, 'xxysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11637, 'Sự chấn động của Tử Long·Rồng Tử Thần', 'Rồng', 'Ám', 'Không có', 7, 1000, 3000, 'UR', 0, 3, 'wlzzlsyl', 'Con rồng trở về từ thế giới ngầm - có được bộ xương siêu cường với cái giá phải trả là từ bỏ cơ thể vật chất của mình.', '0'),
(11638, 'tàu hộ tống linh hồn', 'Ác Ma', 'Quang', 'Không có', 5, 1900, 1000, 'UR', 0, 3, 'lhhsc', 'Con tàu hộ tống tâm hồn chứa đầy năng lượng ấm áp xoa dịu tâm hồn.', '0'),
(11639, 'Ô hoa lan sao chổi tình yêu', 'Pháp Sư', 'Hỏa', 'Không có', 3, 500, 1500, 'UR', 0, 3, 'xazhxls', 'Người ta nói rằng nếu khắc tên hai người dưới chiếc ô thì họ có thể ở bên nhau mãi mãi.', '0'),
(11640, 'Nhà sư phạm giới·Luanqin', 'Pháp Sư', 'Địa', 'Không có', 4, 1800, 100, 'UR', 0, 3, 'pjslq', 'Tục ngữ có câu - rượu thịt đi qua ruột nhưng vẫn ở trong tâm Phật.', '0'),
(11641, 'Vua rác', 'Ác Ma', 'Ám', 'Không có', 5, 0, 2400, 'UR', 0, 3, 'ljw', 'Vua rác có chuyện gì vậy? Ông ấy cũng là vua phải không?', '0'),
(11642, 'Ác anh hùng·Quỷ Địa Tộc ngục', 'Ác Ma', 'Địa', 'Anh Hùng Tà Ác', 4, 1600, 0, 'UR', 0, 3, 'xxyxdylm', 'Một trong những Bộ Bài Yu-Gi-Oh. Nó thuộc về một trong sáu Bộ Bài <HERO>. Đây là Bộ Bài được sử dụng bởi Yujo Judai - nhân vật chính của anime <Yu-Gi-Oh GX> - khi anh ngã xuống và trở thành Overlord.', '0'),
(11643, 'Sen đỏ thật sự quen thuộc', 'Ác Ma', 'Ám', 'Không có', 4, 1600, 0, 'UR', 0, 3, 'zhlsm', 'Synchro hai sao (sử dụng hai quái thú Tuner để Synchro với các Quái Thú khác) là một tính năng của Bộ Bài của nó.', '0'),
(11644, 'Bộ cộng hưởng màu đỏ thẫm', 'Ác Ma', 'Ám', 'Cộng Hưởng Resonator', 2, 800, 300, 'UR', 0, 3, 'shhmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
(11645, 'Rồng ánh sáng mắt thiên hà', 'Rồng', 'Quang', 'Ngân Hà Galaxy', 8, 3000, 2500, 'UR', 0, 2, 'yhycgl', 'Phần chính trong Bộ Bài của AMa Phápgi Kaito trong anime <Yu-Gi-Oh! ZEXAL> là Bộ Bài thuộc tính ánh sáng với <Galaxy Eyes Photon Dragon> làm cốt lõi.', '0'),
(11646, 'Điều chỉnh Rat Rider', 'Chiến Sĩ', 'Thủy', 'Không có', 1, 500, 500, 'UR', 0, 3, 'tzsqs', 'Chúc May mắn trong năm con chuột!', '0'),
