(11818, 'Tia gai trắng', 'Cá', 'Hỏa', 'Không có', 4, 1400, 1000, 'UR', 0, 3, 'bjh', 'Một loại cá đuối hay còn gọi là cá quỷ sẽ làm những điều không ngờ khi được đặt trên nền đất nhẵn.', '0'),
(11819, 'chiến binh cứu hộ', 'Chiến Sĩ', 'Hỏa', 'Không có', 5, 1900, 1600, 'UR', 0, 3, 'dlzs', 'Nhiều năm làm bài tập đã khiến cơ thể anh trở nên vô cùng cường tráng.', '0'),
(11820, 'Lá bài Anh Linh', 'Chiến Sĩ', 'Địa', 'Cực Tinh Nordic', 4, 1000, 1000, 'UR', 0, 3, 'ylysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11821, 'Dẫn xuất của quái thú vùng cực', 'Thú', 'Địa', 'Cực Tinh Nordic', 3, 0, 0, 'UR', 0, 3, 'jxsysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
