(11842, 'Công chúa hoa hồng', 'Thực Vật', 'Địa', 'Hoa Hồng', 3, 1200, 800, 'UR', 0, 3, 'qwzgz', 'Công chúa của Vương quốc Hoa hồng vô cùng xinh đẹp.', '0'),
(11843, 'mạng rồng', 'Cyberse', 'Ám', 'Không có', 3, 1400, 1200, 'UR', 0, 3, 'wlxl', 'Một sinh vật huyền bí được sinh ra trong thế giới điện tử thông qua việc xây dựng mạng ảo.', '0'),
(11844, 'hơi thông minh', 'Cyberse', 'Địa', 'Không có', 2, 200, 2000, 'SR', 0, 3, 'btjl', 'Loài mới được phát hiện trong không gian điện tử Nó có rất ít thông tin.', '0'),
(11845, 'công cụ điện tử', 'Cyberse', 'Quang', 'Không có', 4, 1400, 300, 'UR', 0, 3, 'dzjgj', 'Tham gia vào công việc duy trì hoạt động bình thường của các hệ thống trong cộng đồng điện tử.', '0'),
(11846, 'Công cụ phái sinh', 'Cyberse', 'Quang', 'Không có', 2, 0, 0, 'UR', 0, 3, 'gjysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(11847, 'Nàng tiên kỳ lạ Elphebia', 'Tâm Linh', 'Phong', 'Không có', 3, 900, 500, 'UR', 0, 1, 'ygzyjaefby', 'Đừng tin tôi chỉ vì tôi quá dễ thương mà có thể đánh tÁm Tộc người như Pharaoh.', '|Mô tả|\\nSau khi kích hoạt thì thầm Quang Tộc sai - chỉ có thể kích hoạt hiệu ứng của Quái Thú đối phương vào sân - và các hiệu ứng sau khi vào sân không thể được kích hoạt\\nQuái Thú có <Monster Barrier·Monster Shield> trên sân đối phương sẽ không bị vô hiệu hóa - nhưng chúng vẫn không thể tấn công\\nQuái Thú có xếp hạng sao và cấp độ nhỏ hơn hoặc bằng tổng số <bộ đếm bất thường> sẽ không bị vô hiệu hóa và có thể tấn công'),
(11848, 'Thiên thần sa ngã vui vẻ', 'Thiên Thần', 'Ám', 'Thiên Thần Sa Ngã', 4, 1600, 0, 'UR', 0, 1, 'ylddts', 'Anh từng là người hầu cận nhất của Chúa - nhưng sau khi sa ngã - anh chỉ còn một cánh.', '0'),
(11849, 'Rồng hộ mệnh Justia', 'Rồng', 'Hỏa', 'Không có', 2, 0, 2100, 'UR', 0, 3, 'shlzsty', 'Star Key đã rơi những giọt nước mắt không rơi để hoàn thành sứ mệnh của mình. Cánh cổng thần thánh sụp đổ - miệng rắn nuốt chửng giấc mơ của người bảo vệ. Linh hồn của anh ấy ở vị trí ban đầu và linh hồn của anh ấy ở vị trí cuối cùng.', '0'),
(11850, 'Flash Lancer', 'Chiến Sĩ', 'Địa', 'Không có', 6, 2200, 800, 'UR', 0, 3, 'ssqb', 'Nói chung - những người đấu tay đôi sẽ yêu cầu đấu tay đôi ngoài trời - điều chỉnh góc của tấm đấu tay đôi để làm rung chuyển đối phương và đặt 3 lá bài trực tiếp lên đối phương khi họ chưa chuẩn bị sẵn sàng.', '0'),
(11851, 'Hecateris', 'Thiên Thần', 'Quang', 'Không có', 4, 1500, 1100, 'UR', 0, 3, 'hktls', 'Thư giãn cơ thể và tâm trí của bạn và bạn sẽ trải nghiệm khung cảnh thiên đường.', '0'),
(11852, 'thỏ Ma Pháp', 'Tâm Linh', 'Quang', 'Không có', 3, 0, 1800, 'UR', 0, 3, 'ygt', 'Chắc là con trai nên dễ thương lắm.', '0'),
(11853, 'Thiên Long của Osiris', 'Thần Thú', 'Thần', 'Không có', 10, 0, 0, 'UR', 0, 1, 'axlsdtkl', '<Thiên Long Osiris> đã đánh thức một sức mạnh mới.', '0'),
(11854, 'thuyền trưởng tức giận', 'Chiến Sĩ', 'Địa', 'Không có', 1, 400, 1200, 'UR', 0, 3, 'nqccddz', 'Hãy đứng dậy - lũ thua cuộc!', '0'),
(11855, 'Chú chim kỳ lạ của thung lũng Kasumi', 'Chim Thú', 'Phong', 'Thung Lũng Sương Mù', 2, 400, 600, 'UR', 0, 3, 'xzgdygn', 'Chú chim con sinh ra ở Thung lũng Kasumi đã nỗ lực rất nhiều để lớn lên.', '0'),
(11856, 'Lam Chính Long·Biểu Long', 'Rồng', 'Phong', 'Không có', 7, 2400, 2200, 'UR', 0, 3, 'lzlbl', 'Long Đỉnh tuy không giàu có nhưng vẫn thường gặp nhau trong căn phòng nhỏ tối tăm.', '0'),
(11857, 'Chiến binh thừa cân·Trống', 'Máy Móc', 'Địa', 'Siêu Trọng Kiếm Sĩ', 1, 300, 300, 'UR', 0, 3, 'czwzg', 'Một trong những Bộ Bài Yu-Gi-Oh. Được sử dụng bởi Noboru Gongenzaka - được biết đến với biệt danh <Fudo Duelist> trong anime <Yu-Gi-Oh! ARC-V> - chiến thuật chính là tấn công ở vị trí phòng thủ.', '0'),
