(11997, 'Halloween·Người sói', 'Thú', 'Địa', 'Ghostrick', 5, 2800, 1000, 'UR', 0, 3, 'wsylr', 'Mặc dù tôi không biết tại sao - khi tôi nghe thấy tiếng sói tru! ! !', '0'),
(11998, 'Người lính của mặt trời', 'Máy Móc', 'Quang', 'Địa Đáy Subterror', 4, 1700, 1000, 'UR', 0, 3, 'drsb', 'Quái Thú bao gồm các thuộc tính ánh sáng. Các chủng tộc bao gồm chủng tộc cơ khí - chủng tộc thiên thần và chủng tộc sấm sét. Chúng được đặt tên theo nhiều hình ba chiều hoặc chữ cái Hy Lạp. Đặc điểm là chiến thuật được phát triển xoay quanh lá bài trang bị.', '0'),
(11999, 'khối mặt trời lớn', 'Máy Móc', 'Quang', 'Địa Đáy Subterror', 3, 800, 800, 'UR', 0, 3, 'drlft', 'Quái Thú bao gồm các thuộc tính ánh sáng. Các chủng tộc bao gồm chủng tộc cơ khí - chủng tộc thiên thần và chủng tộc sấm sét. Chúng được đặt tên theo nhiều hình ba chiều hoặc chữ cái Hy Lạp. Đặc điểm là chiến thuật được phát triển xoay quanh lá bài trang bị.', '0'),
(12000, 'Người Ma Phápng ánh sáng·Phù Thủy', 'Pháp Sư', 'Quang', 'Không có', 6, 2300, 2000, 'UR', 0, 3, 'gmszws', '<Phù Thủy hỗn loạn> Yazi sau khi trở thành Người Ma Phápng ánh sáng.', '0'),
(12001, 'Người Ma Phápng ánh sáng·Phù Thủy', 'Pháp Sư', 'Quang', 'Không có', 6, 1200, 3000, 'UR', 0, 3, 'gmszmds', '<Phù Thủy nước mới> Yazi sau khi trở thành Sứ giả ánh sáng.', '0'),
(12002, 'Người Ma Phápng ánh sáng Diablos', 'Rồng', 'Quang', 'Không có', 7, 2800, 1000, 'UR', 0, 3, 'gmszdybls', '<Chúa Quỷ Diablos> Ako sau khi trở thành người Ma Phápng ánh sáng.', '0'),
(12003, 'Người Ma Phápng ánh sáng Kea Freed', 'Chiến Sĩ', 'Quang', 'Không có', 8, 2800, 2200, 'UR', 0, 3, 'gmszdyfld', '<Phoenix Sword Master Kya Freed> Ako sau khi trở thành người Ma Phápng ánh sáng.', '0'),
(12004, 'Hoàng đế bóng Ma Pháp·Rabiel·Nắm đấm tàn phá thiên thể', 'Ác Ma', 'Ám', 'Ma Thuật', 10, 4000, 4000, 'UR', 0, 1, 'hmhlbaetjrlq', 'Người ta nói rằng <Phantom Demon King Rabiel> đã học được một chiêu thức mới sau khi bị một người đàn ông đầu trọc đấm.', '0'),
(12005, 'lõi hỗn loạn', 'Ác Ma', 'Ám', 'Ma Thuật', 3, 0, 0, 'UR', 0, 3, 'hdhmss', 'Bộ Bài xoay quanh <Thần Viêm Ma Hoàng Uria> - <Thunder King Harmon> và <Phantom Demon King Rabiel> làm cốt lõi.', '0'),
(12006, 'Thần Viêm Ma Hoàng Uria', 'Hỏa Tộc', 'Thủy', 'Ma Thuật', 10, 0, 0, 'UR', 0, 1, 'symhwly', '<Thần Viêm Ma Hoàng Uria> đã đánh thức một sức mạnh mới.', '0'),
(12007, 'Vua nướng xương', 'Zombie', 'Ám', 'Bộ Xương', 1, 300, 200, 'UR', 0, 3, 'bgkw', 'Nào em gái - hái tỏi cho anh nhé.', '0'),
(12008, 'EHERO·Xinyuxia chân thành', 'Chiến Sĩ', 'Quang', 'Anh Hùng Nguyên Tố', 7, 2500, 2000, 'UR', 0, 3, 'ezcxyx', '<Anh hùng nguyên tố·Xinyuxia chân thành> cuối cùng đã trở thành máy điều hòa không khí trung tâm với sự chúc phúc của mọi người.', '0'),
(12009, 'Người đá đứng vững', 'Nham Thạch', 'Địa', 'Không có', 2, 800, 800, 'UR', 0, 3, 'tssr', '[Để tôi xem] [Để tôi xem] [Để tôi xem]', '0'),
(12010, 'Mã thông báo Tử đạo của Phantom', 'Ác Ma', 'Ám', 'Ma Thuật', 1, 0, 0, 'N', 0, 3, 'hmdxjzysw', 'Lá bài này có thể được sử dụng làm token.', '0'),
(12011, 'Móng Vuốt Hoa Vàng', 'Thực Vật', 'Địa', 'Không có', 4, 1800, 100, 'UR', 0, 3, 'hhxmz', 'Hãy ôm lấy anh và để anh đưa em vào giấc ngủ vĩnh hằng.', '0'),
(12012, 'cánh đột kích', 'Chim Thú', 'Ám', 'Chim Săn Mồi Raidraptor', 4, 0, 2000, 'UR', 0, 3, 'xjdfy', 'Linh hồn của <Phantom Knights> được gắn vào <Rapid Bird of Prey> và một vũ khí chiến đấu mới ra đời.', '0'),
(12013, 'Thương gia bóng tối huyền diệu', 'Pháp Sư', 'Ám', 'Không có', 3, 1500, 200, 'UR', 0, 3, 'mdasr', 'Got some rare things on sale，stranger！', '0'),
(12014, 'khủng long Brontosaurus', 'Sấm Sét', 'Quang', 'Rồng Sấm Sét', 5, 1600, 1500, 'UR', 0, 3, 'll', 'Lá bài đầu tiên trong loạt Bộ Bài <Thunder Dragon>.', '0'),
(12015, 'Rồng Sấm · Brontosaurus', 'Sấm Sét', 'Quang', 'Rồng Sấm Sét', 1, 0, 2000, 'UR', 0, 3, 'lylll', 'Được mở rộng từ các lá bài cũ <Rồng Sấm> và <Rồng Sấm Hai Đầu> - Quái Thú đều là Quái Thú thuộc loại Sấm sét với thuộc tính ánh sáng hoặc bóng tối. Về cơ bản - chúng có các hiệu ứng được kích hoạt bằng cách loại bỏ các lá bài khỏi tay và các hiệu ứng gây ra khi bị đưa ra khỏi sân hoặc đưa đến Nghĩa Địa.', '0'),
(12016, 'Rồng Sấm · Brontosaurus', 'Sấm Sét', 'Ám', 'Rồng Sấm Sét', 5, 1600, 1500, 'UR', 0, 3, 'ldlll', 'Được mở rộng từ các lá bài cũ <Rồng Sấm> và <Rồng Sấm Hai Đầu> - Quái Thú đều là Quái Thú thuộc loại Sấm sét với thuộc tính ánh sáng hoặc bóng tối. Về cơ bản - chúng có các hiệu ứng được kích hoạt bằng cách loại bỏ các lá bài khỏi tay và các hiệu ứng gây ra khi bị đưa ra khỏi sân hoặc đưa đến Nghĩa Địa.', '0');
