(12025, 'Những người lính của ngọn lửa vĩnh cửu', 'Ác Ma', 'Ám', 'Lửa Vĩnh Cửu Infernity', 1, 0, 0, 'UR', 0, 3, 'yhbz', 'Không giống như hầu hết các Bộ Bài theo đuổi chiến lược tích lũy thêm tài nguyên lá bài trong tay - hầu hết các quái thú <Eternal Fire> và các lá bài Phép & Bẫy chỉ bộc lộ sức mạnh thực sự của chúng khi có 0 lá bài trên tay.', '0'),
(12026, 'mèo rừng vĩnh cửu', 'Ác Ma', 'Ám', 'Lửa Vĩnh Cửu Infernity', 3, 1400, 0, 'UR', 0, 3, 'yhym', 'Không giống như hầu hết các Bộ Bài theo đuổi chiến lược tích lũy thêm tài nguyên lá bài trong tay - hầu hết các quái thú <Eternal Fire> và các lá bài Phép & Bẫy chỉ bộc lộ sức mạnh thực sự của chúng khi có 0 lá bài trên tay.', '0'),
(12027, 'Quỷ lửa luyện ngục vĩnh cửu', 'Ác Ma', 'Ám', 'Lửa Vĩnh Cửu Infernity', 4, 1800, 1200, 'UR', 0, 3, 'yhem', '<Quỷ lửa vĩnh cửu> đã vượt qua cấp độ cuối cùng của <Địa ngục lửa vĩnh cửu> và bước vào luyện ngục vô tận.', '0'),
(12028, 'Bộ điều chỉnh đạn', 'Rồng', 'Ám', 'Đạn Pháo', 1, 0, 0, 'UR', 0, 3, 'dwtts', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12029, 'Rồng đánh dấu đạn', 'Rồng', 'Ám', 'Đạn Pháo', 4, 1600, 1000, 'UR', 0, 3, 'dwygl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12030, 'Pillosaurus gây mê', 'Rồng', 'Ám', 'Đạn Pháo', 1, 0, 2200, 'UR', 0, 3, 'mzdwl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12031, 'súng lục tự động viên rồng', 'Rồng', 'Ám', 'Đạn Pháo', 3, 1600, 1000, 'UR', 0, 3, 'zdsqdwl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12032, 'Rồng đạn Magnum', 'Rồng', 'Ám', 'Đạn Pháo', 4, 1800, 1200, 'UR', 0, 3, 'mgnmdwl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12033, 'rồng viên bạc', 'Rồng', 'Ám', 'Đạn Pháo', 4, 1900, 100, 'UR', 0, 3, 'ysdwl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12034, 'Rồng định tuyến tuyệt đối', 'Rồng', 'Ám', 'Đạn Pháo', 7, 1200, 2800, 'UR', 0, 3, 'jdlyl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12035, 'Rồng đạn nổ', 'Rồng', 'Ám', 'Đạn Pháo', 7, 2000, 2000, 'UR', 0, 3, 'bzdwl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12036, 'Máy bay chiến đấu điều khiển từ xa bằng điện', 'Tâm Linh', 'Quang', 'Không có', 3, 1500, 300, 'UR', 0, 3, 'dqnlds', 'Sau đó chơi nhạc - rồi nhảy.', '0'),
(12037, 'Rồng đen mắt đỏ thật sự mới nở', 'Rồng', 'Ám', 'Mắt Đỏ', 1, 800, 500, 'UR', 0, 3, 'zhyhlzc', 'Những dị nhân xuất hiện trong <Black Dragon Hatchling> đã đánh thức dòng máu của True Red Eye trước khi chúng được sinh ra.', '0'),
(12038, 'đèn lồng rồng gấu trúc', 'Ảo Tưởng', 'Thủy', 'Không có', 4, 500, 2000, 'UR', 0, 3, 'lld', 'Anh ta chỉ ra ngoài vào ban đêm để hù dọa bọn trẻ để kiếm sống.', '0'),
(12039, 'Võ Thần·Tàu chim', 'Chiến Sĩ Thú', 'Quang', 'Chiến Thần Bujin', 4, 1500, 500, 'UR', 0, 3, 'wsnc', 'Các Quái Thú <Võ Thần> đều có nguồn gốc từ thần thoại Nhật Bản. Quái Thú <Võ Thần> của tộc Chiến binh Quái thú là những nhân vật thần thánh trong câu chuyện - và Quái Thú <Vũ khí Thần> là những tạo tác và kho báu mà họ sử dụng.', '0'),
(12040, 'Võ khí · Năm trăm bảo vật', 'Chim Thú', 'Quang', 'Chiến Thần Bujin', 4, 1700, 800, 'UR', 0, 3, 'wsqwbg', 'Các Quái Thú <Võ Thần> đều có nguồn gốc từ thần thoại Nhật Bản. Quái Thú <Võ Thần> của tộc Chiến binh Quái thú là những nhân vật thần thánh trong câu chuyện - và Quái Thú <Vũ khí Thần> là những tạo tác và kho báu mà họ sử dụng.', '0'),
(12041, 'Phế liệu Ironraptor', 'Khủng Long', 'Địa', 'Phế Liệu Sắt', 4, 1400, 1000, 'UR', 0, 3, 'ftdl', 'Một Bộ Bài tập trung vào việc Triệu Hồi Synchro các Quái Thú thuộc tính hệ đất. Tính năng của series là sử dụng hiệu ứng của lá bài <Scrap> để tiêu diệt lá bài <Scrap> nhằm kích hoạt hiệu ứng của nó để khởi động chiến thuật.', '0'),
(12042, 'Anh hùng nguyên tố·Người lỏng', 'Chiến Sĩ', 'Hỏa', 'Anh Hùng Nguyên Tố', 4, 1400, 1300, 'UR', 0, 3, 'ysyxytx', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(12043, 'Lông đen·Chim dao găm đêm trắng', 'Chim Thú', 'Ám', 'Kuriboh', 3, 800, 1500, 'UR', 0, 3, 'hybyzdjn', 'Một trong những Bộ Bài Yu-Gi-Oh. Một Bộ Bài có chủ đề Triệu Hồi Synchro được sử dụng bởi Crow Hogan - nhân vật chính của <Yu-Gi-Oh 5D\'s> và <Yu-Gi-Oh ARC-V>.', '0'),
(12044, 'kiểm tra Ma Phápjin', 'Ác Ma', 'Ám', 'Không có', 6, 2400, 1200, 'UR', 0, 1, 'csmr', 'Một người có khả năng sinh ra từ hư vô có thể Phong Tộc ấn lối đi của không gian.', '0'),
(12045, 'cô gái pha lê', 'Pháp Sư', 'Hỏa', 'Không có', 1, 200, 100, 'UR', 0, 1, 'jjsn', 'Một cô gái sinh ra từ sự kết tinh của tinh chất nước tinh khiết.', '0'),
(12046, 'Phù Thủy Tộc hạnh phúc', 'Thiên Thần', 'Ám', 'Không có', 4, 100, 2000, 'UR', 0, 3, 'slzmn', '<The Joyless Saint> đã sa sút hơn nữa.', '0'),
(12047, 'Hồn Giang Long·Lý Quân', 'Chiến Sĩ Thú', 'Thủy', 'Công Chúa Biển Marincess', 5, 2100, 400, 'UR', 0, 3, 'hjllj', 'Quái Thú đều thuộc loại Quái Thú chiến binh và Quái Thú thuộc tính lửa. Hầu hết các Quái Thú có thể được sử dụng kết hợp với Phép Thuật <Thủy hử> và các lá bài bẫy để xây dựng và triển khai chiến thuật.', '0'),
(12048, 'Con trai hoang đàng Yan Qing', 'Chiến Sĩ Thú', 'Thủy', 'Công Chúa Biển Marincess', 6, 2400, 2000, 'UR', 0, 3, 'lzyq', 'Quái Thú đều thuộc loại Quái Thú chiến binh và Quái Thú thuộc tính lửa. Hầu hết các Quái Thú có thể được sử dụng kết hợp với Phép Thuật <Thủy hử> và các lá bài bẫy để xây dựng và triển khai chiến thuật.', '0'),
