(12140, 'con quỷ kì lạ', 'Ác Ma', 'Quang', 'Ác Ma', 3, 800, 1000, 'UR', 0, 3, 'ggem', 'Ngay cả khi bạn nhìn vào kích thước của tôi - bạn cũng biết tôi là chị gái của bạn - phải không ~', '0'),
(12141, 'Bằng chứng của Pruflas', 'Ác Ma', 'Ám', 'Không có', 3, 100, 100, 'UR', 0, 3, 'plflszz', 'Làm đồ ăn nhẹ 778~', '0'),
(12142, 'Hiện thân của ác thần·thần', 'Thần Thú', 'Thần', 'Không có', 10, 0, 0, 'UR', 0, 1, 'xssdhs', '<Ác Thần·Sự nhập thể của Thần> đã đánh thức sức mạnh tối thượng.', '0'),
(12143, 'Halloween·Cô gái băng giá', 'Zombie', 'Ám', 'Ghostrick', 1, 0, 0, 'UR', 0, 3, 'wsyhy', 'Tôi không muốn những ký ức đó nữa! ! Vì vậy - tôi cũng muốn chiến đấu - xin vui lòng!', '0'),
(12144, 'Halloween·Ma cà rồng', 'Zombie', 'Ám', 'Ghostrick', 5, 2600, 1000, 'UR', 0, 3, 'wsyxxg', 'Trang bị tồi của Ma Pháp cà rồng thì liên quan gì đến tôi?', '0'),
(12145, 'Dụng cụ chỉnh hình DD', 'Ác Ma', 'Ám', 'DD', 4, 600, 1800, 'UR', 0, 3, 'ddeets', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được Reiji AkaMa Pháp - chủ tịch <LDS> sử dụng trong <Yu-Gi-Oh ARC-V>. Sê-ri Bộ Bài đầu tiên bao gồm 4 <Phương pháp triệu hồi đặc biệt của Bộ Bài bổ sung> bao gồm Fusion - Synchro - XYZ - Pendulum và Link - và 1 <Phương pháp triệu hồi đặc biệt bằng lá bài tay cho Bộ Bài phụ>.', '|Mô tả|\\nLá bài này có thể được sử dụng làm nguyên liệu Dung Hợp'),
(12146, 'Người chọn rồng mặt trăng', 'Rồng', 'Quang', 'Không có', 6, 2400, 1000, 'UR', 0, 3, 'xylslgle', 'Bạn đang nhìn lên tôi - thực ra bạn cũng vậy - đang nhìn lên mặt trăng 0 0 - yo~yo~', '0'),
(12147, 'Tiên Rồng MahaMa Pháp', 'Rồng', 'Quang', 'Không có', 5, 0, 2500, 'UR', 0, 3, 'yjlmhm', 'Xin đừng gọi nhầm tên tôi. Tên tôi không phải MaMa Phápha chứ đừng nói đến MaMa Pháphaha!', '0'),
(12148, 'nhịp tim rồng', 'Rồng', 'Thủy', 'Không có', 4, 2000, 1500, 'UR', 0, 3, 'xtl', 'Em lại khóc - anh không thể an ủi em - anh lại lắc đầu - anh có chút tiếc nuối ~', '0'),
(12149, 'Máy quét lưới', 'Cyberse', 'Quang', 'Không có', 4, 100, 2000, 'UR', 0, 3, 'wgscj', 'Xin lưu ý - xin lưu ý - Ồ - không - Internet không phải là nơi bất hợp pháp! ! !', '0'),
(12150, 'Vua máy thần thú Barbaros Ur', 'Chiến Sĩ Thú', 'Địa', 'Barbaros', 8, 3800, 1200, 'UR', 0, 3, 'ssjwbblswe', 'Không ai có thể từ chối một chiếc máy được thiết kế riêng cho họ!', '0'),
(12151, 'Rồng phản lực mắt xanh', 'Rồng', 'Quang', 'Mắt Xanh', 8, 3000, 0, 'UR', 0, 3, 'qypsl', 'Mặc dù không có gì được viết trên mặt lá bài này - nhưng lá bài này có thể được Triệu hồi Đặc biệt!', '0'),
(12152, 'DD Griffin', 'Ác Ma', 'Ám', 'DD', 4, 1200, 1200, 'UR', 0, 3, 'ddsj', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được Reiji AkaMa Pháp - chủ tịch <LDS> sử dụng trong <Yu-Gi-Oh ARC-V>. Sê-ri Bộ Bài đầu tiên bao gồm 4 <Phương pháp triệu hồi đặc biệt của Bộ Bài bổ sung> bao gồm Fusion - Synchro - XYZ - Pendulum và Link - và 1 <Phương pháp triệu hồi đặc biệt bằng lá bài tay cho Bộ Bài phụ>.', '0'),
(12153, 'Người hầu Quái Thú kiên cường', 'Thú', 'Thủy', 'Không có', 2, 900, 2000, 'UR', 0, 3, 'bqdsp', 'Orc sẽ không bao giờ là nô lệ! ! ! Trừ khi bao gồm thức ăn và chỗ ở! ! !', '0'),
(12154, 'cô gái lửa', 'Chiến Sĩ', 'Thủy', 'Không có', 1, 100, 100, 'UR', 0, 3, 'qhnl', '<Nữ hoàng> Đội ngũ nhân viên hậu cần trên bộ bài cầu nguyện cho các chiến sĩ trở về an toàn.', '0'),
(12155, 'Công chúa cổ tích Rochka', 'Pháp Sư', 'Quang', 'Công Chúa Cổ Tích', 4, 1850, 1000, 'UR', 0, 3, 'yjcjlqk', 'Một con Quái Thú được đặt theo tên của nhân vật chính trong truyện cổ tích - Rochka - dựa trên Snow Maiden của Nga.', '0'),
(12156, 'Cúi đầu Leleye', 'Ác Ma', 'Ám', 'Không có', 4, 1800, 1600, 'UR', 0, 3, 'gslly', 'Tôi nghĩ lại hồi đó - tôi đã bắn xuyên qua đầu gối của vô số người ~~~', '0'),
(12157, 'Hiệp sĩ ác mộng mắt đen', 'Ác Ma', 'Ám', 'Không có', 4, 1700, 1700, 'UR', 0, 3, 'aymyqs', 'Bạn có muốn cả thế giới bị hủy diệt trong chốc lát không? À - xin lỗi - 0 0', '0'),
(12158, 'Cô gái giải cứu Stella', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 300, 800, 'UR', 0, 3, 'jfsnsdl', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Stella muốn gắn bó với Elise.', '0'),
(12159, 'Cô gái dính Stella', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 800, 300, 'UR', 0, 3, 'ttsnsdl', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Stella muốn gắn bó với Elise.', '0'),
(12160, 'Cứu Elise', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 500, 800, 'UR', 0, 3, 'jfsnals', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Elise muốn gắn bó với Stella.', '0'),
(12161, 'Cô Gái Dính Chắc·Elise', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 800, 500, 'UR', 0, 3, 'ttsnals', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Elise muốn gắn bó với Stella.', '0'),
(12162, 'Cô gái giải cứu Irena', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 400, 800, 'UR', 0, 3, 'jfsnyln', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Irena muốn gắn bó với Sophia.', '0'),
(12163, 'Cô gái dính ·Irena', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 800, 400, 'UR', 0, 3, 'ttsnyln', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Irena muốn gắn bó với Sophia.', '0'),
(12164, 'Giải cứu cô gái Sophia', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 100, 800, 'UR', 0, 3, 'jfsnsfy', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Sophia muốn gắn bó với Irena.', '0'),
(12165, 'Cô Gái Dính Chắc·Sofia', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 800, 100, 'UR', 0, 3, 'ttsnsfy', 'Hãy cẩn thận để phân biệt giữa vợ của bạn và vợ của vợ bạn. Sophia muốn gắn bó với Irena.', '0'),
(12166, 'Phù Thủy biên niên sử', 'Pháp Sư', 'Ám', 'Không có', 7, 2500, 2500, 'UR', 0, 3, 'ndjmss', 'Người biên soạn (tong) năm (ren) ghi (ai) ghi (hao) về tình yêu và hận thù giữa <Dark Magician> và <Rồng Trắng Mắt Xanh>.', '0'),
(12167, 'Rồng sao đen mắt đỏ đích thực', 'Rồng', 'Ám', 'Mắt Đỏ', 6, 2000, 2000, 'UR', 0, 3, 'zhyhxl', 'Kỳ thật lúc đó ta cùng sao băng Hắc Long tới đây - nhưng khi đào ngươi đã đào hắn trước.', '0'),
(12168, 'Tâm hồn đỏ đích thực', 'Rồng', 'Ám', 'Mắt Đỏ', 4, 900, 2000, 'UR', 0, 3, 'zhzh', 'Là Bộ Bài bị Yusanjia đánh nhiều nhất - tôi muốn tung ra một lá bài. Ai đồng ý? Ai phản đối?', '0'),
(12169, 'Halloween · Phù Thủy Tộc', 'Pháp Sư', 'Ám', 'Ghostrick', 4, 1200, 1200, 'UR', 0, 3, 'wsynw', 'Waku waku~', '0'),
(12170, 'Halloween·Frankenstein', 'Zombie', 'Ám', 'Ghostrick', 4, 2000, 0, 'UR', 0, 3, 'wsykxgr', 'Bạn phải tin rằng tôi thực sự là một chàng trai đẹp trai trước khi trở nên như thế này~', '0'),
(12171, 'Giải cứu cô gái Marfa', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 1600, 800, 'UR', 0, 3, 'jfsnmef', 'Vợ mới của vợ tôi xuất hiện. Marfa muốn gắn bó với Elise.', '0'),
(12172, 'Cô gái dính ·Malfa', 'Pháp Sư', 'Quang', 'Khủng Long Cơ Xảo', 4, 800, 1600, 'UR', 0, 3, 'ttsnmef', 'Vợ mới của vợ tôi xuất hiện. Marfa muốn gắn bó với Elise.', '0'),
(12173, 'Anh hùng nguyên tố · Tinh linh Xinyu', 'Chiến Sĩ', 'Quang', 'Anh Hùng Nguyên Tố', 7, 2500, 2000, 'UR', 0, 3, 'ysyxxyjl', 'Nó thuộc về Bộ Bài đầu tiên trong năm Bộ Bài thuộc series <HERO> và là Bộ Bài yêu thích của Judai Yujo - nhân vật chính của <Yu-Gi-Oh GX>.', '0'),
(12174, 'Megalodon', 'Rồng', 'Địa', 'Không có', 4, 1400, 2000, 'UR', 0, 3, 'jyl', 'Răng trắng!', '0'),
(12175, 'chị em chim', 'Chim Thú', 'Phong', 'Không có', 2, 200, 2000, 'UR', 0, 3, 'qjm', 'Khi có người khóa cửa - bạn nên biết chị em đang nghe bài gì.', '0'),
(12176, 'Rời khỏi thế giới này', 'Ác Ma', 'Ám', 'Không có', 1, 0, 0, 'UR', 0, 3, 'xsl', 'Tuyên bố có tội!', '0'),
(12177, 'Ác Ma Pháp sắc đẹp·Da Ji', 'Zombie', 'Thủy', 'Ác Ma', 2, 1000, 0, 'UR', 0, 3, 'lzmydj', 'Một trong những Bộ Bài Yu-Gi-Oh. Series <Demon> dựa trên chủ đề về Quái Thú huyền thoại của Nhật Bản. Những Quái Thú được Misawa Land sử dụng đã bị biến thành xác sống sau khi bị biến thành OCG.', '0'),
(12178, 'Biên niên sử phù Thủy Tộc', 'Pháp Sư', 'Ám', 'Không có', 4, 1250, 1250, 'UR', 0, 3, 'ndjnw', 'Người học việc của <Pháp Sư Biên Niên Sử>.', '0'),
(12179, 'Chuỗi đại tá C', 'Chiến Sĩ', 'Quang', 'Không có', 4, 1400, 1600, 'UR', 0, 3, 'cxsx', 'Thưa các anh em - tôi tính phí trước vì sự tôn trọng!', '0'),
(12180, 'TÁm Tộc vị thần sấm sét', 'Ảo Tưởng', 'Quang', 'Không có', 8, 2000, 2000, 'UR', 0, 3, 'blts', 'Sấm sét! Chuyện phiếm!', '0'),
(12181, 'Kuriboh Tái Sinh', 'Thiên Thần', 'Quang', 'Kuriboh', 1, 300, 200, 'UR', 0, 1, 'sslzq', 'Dù tôi chỉ là một Kuriboh nhỏ bé - nhưng vẫn nguyện dùng sinh mệnh để đổi lấy Kazuki Takahashi hồi sinh một lần nữa.', '0'),
(12182, 'Súng công lý', 'Chiến Sĩ', 'Quang', 'Không có', 4, 2200, 0, 'UR', 0, 3, 'zyzq', 'Một người đàn ông trong sáng phải thực hiện những đường cắt cuối cùng! An An!', '0'),
(12183, 'Di tích của quân đội', 'Thủy Tộc', 'Thủy', 'Tàu Sushi Gunkan', 4, 2000, 0, 'UR', 0, 3, 'sljg', 'Một Bộ Bài dựa trên sushi. Lá bài này là cơm nắm đầu tiên. Nó cần được xử lý sau. Bạn đang làm gì trong cơn choáng váng? Thêm rau! ! !', '0'),
(12184, 'Lưỡi đài phun nước', 'Tâm Linh', 'Địa', 'Không có', 4, 1628, 1628, 'UR', 0, 3, 'qzr', 'Ngày mà thanh kiếm gãy được rèn lại - khi hiệp sĩ trở lại.', '0'),
(12185, 'Cao quý Punk Zeami', 'Tâm Linh', 'Địa', 'Trẻ Nghịch Ngợm', 3, 600, 600, 'UR', 0, 3, 'npksam', 'Khi nào loli có thể có từ khóa? ! !', '0'),
(12186, 'Yale Punk·Harmony', 'Tâm Linh', 'Địa', 'Trẻ Nghịch Ngợm', 3, 900, 600, 'UR', 0, 3, 'ylpkhq', 'Hãy vững vàng và đừng dao động - không phải điểm nóng nào cũng có thể khai thác được!', '0'),
(12187, 'Ukiyo-e Punk·Sarazai', 'Tâm Linh', 'Địa', 'Trẻ Nghịch Ngợm', 3, 1200, 600, 'UR', 0, 3, 'fshpkplz', 'Tại sao bạn không tận dụng một điểm nóng? Sắt cũ~~~', '0'),
(12188, 'Con rối cơ khí · búp bê bisque', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 8, 1000, 1000, 'UR', 0, 3, 'jgklscro', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(12189, 'Hư không lõi lửa của Shaddoll', 'Ác Ma', 'Thủy', 'Búp Bê Bóng Đêm Shaddoll', 9, 2900, 2900, 'UR', 0, 3, 'yydyhxk', 'Một trong những Bộ Bài xuất hiện trong thế giới quan độc lập <Duel Terminal/DT (Duel Terminal)> trong <Yu-Gi-Oh!> loạt. Một loạt Bộ Bài sử dụng phép triệu hồi hợp nhất làm chiến thuật chính.', '0'),
(12190, 'Raptor·Đại bàng phản diện', 'Chim Thú', 'Ám', 'Chim Săn Mồi Raidraptor', 3, 700, 700, 'UR', 0, 3, 'jxmqfpd', 'Những con Quái Thú bao gồm chim bách thanh - đại bàng - chim ưng - cú rừng - kền kền và các loài chim khác với khả năng săn mồi mạnh mẽ. Mặc dù chúng là thú chim nhưng hình dạng của chúng có xu hướng được cơ giới hóa. Quái Thú XYZ cấp cao hơn còn được trang bị tên lửa - bom xăng - pháo hạt nổi - pháo vệ tinh - pháo lỗ đen và các vũ khí - thiết bị nhiệt khác.', '0'),
(12191, 'Linh hồn của Death Eye: Psyche Pompos', 'Zombie', 'Địa', 'Không có', 2, 0, 0, 'UR', 0, 3, 'syzclpxkpbs', 'Điều này có phần vô lý phải không? Bạn có cần phải làm tôi tức giận không?', '0'),
(12192, 'đội trưởng chiến binh aMa Phápzon', 'Chiến Sĩ', 'Địa', 'Amazoness', 5, 1900, 0, 'UR', 0, 3, 'ymxzsz', 'Thủ lĩnh chiến binh của bộ tộc Amazoness có kinh nghiệm chiến đấu vô cùng Phong Tộc phú.', '0'),
(12193, 'Món tráng miệng Golem·Rusk Butler', 'Pháp Sư', 'Địa', 'Bánh Ngọt Madolche', 4, 1500, 800, 'UR', 0, 3, 'motdmbggj', 'Hãy uống trà trước.', '0'),
(12194, 'Công chúa trắng của Rikka', 'Thực Vật', 'Hỏa', 'Hoa Tuyết Rikka', 4, 0, 0, 'UR', 0, 3, 'lhdbj', 'Unity là một loại Quái Thú thực vật. Nó là một Bộ Bài chủ yếu tập trung vào siêu triệu hồi. Nó chủ yếu xuất hiện dưới hình dạng một cô gái.', '0'),
(12195, 'kẻ lang thang thần giao cách cảm', 'Tâm Linh', 'Địa', 'Xúc Xắc Speedroid', 2, 0, 700, 'UR', 0, 3, 'nlllz', 'Một chiến binh lang thang giữa các vương quốc của telekinesis.', '0'),
(12196, 'Quỷ bóng sắt·Gulugun', 'Ác Ma', 'Ám', 'Xúc Xắc Speedroid', 3, 450, 400, 'UR', 0, 3, 'tqmsglg', '<Rolling Ball> đã được sửa đổi và bây giờ bạn có thể biết phía trước ở đâu.', '0'),
(12197, 'Noble Punk·Gạc Xianyin', 'Tâm Linh', 'Địa', 'Trẻ Nghịch Ngợm', 5, 2100, 1800, 'UR', 0, 3, 'npkljxy', 'Tôi có 3 bộ trang phục - bạn thích bộ nào?', '0'),
(12198, 'Noh Punk·Oni Noh', 'Tâm Linh', 'Địa', 'Trẻ Nghịch Ngợm', 8, 2500, 2000, 'UR', 0, 3, 'npkgnl', 'Không cần tìm đâu xa - không có tùy chọn góc tù.', '0'),
(12199, 'Tinh thể biển·san hô', 'Cyberse', 'Hỏa', 'Công Chúa Biển', 4, 1100, 1800, 'UR', 0, 3, 'hjsnsh', 'Đừng nhìn tôi. Điều này không liên quan gì đến việc viết quảng cáo của tôi - phải không? (Chửi anh ấy thì không mắng được tôi đâu~~~)', '0'),
(12200, 'trang phục halloween', 'Zombie', 'Ám', 'Ghostrick', 1, 0, 0, 'UR', 0, 3, 'wsybz', 'Ca khúc <Anh Yêu Em Như Ai> được dành tặng tất cả mọi người có mặt.', '0'),
(12201, 'Halloween·Thiên thần bất tử', 'Zombie', 'Ám', 'Ghostrick', 4, 0, 0, 'UR', 0, 3, 'wsybxts', 'Những gì từng là thiên thần đã trở thành bất tử.', '0'),
(12202, 'Halloween·Xác ướp', 'Zombie', 'Ám', 'Ghostrick', 4, 2000, 1500, 'UR', 0, 3, 'wsymny', 'Tôi vừa lẻn ra khỏi bảo tàng - một số miếng băng trên người hơi bị dính.', '0'),
(12203, 'trên tay tử thần', 'Zombie', 'Ám', 'Không có', 8, 1600, 1600, 'UR', 0, 3, 'sws', 'Tay các bạn thế nào rồi?', '0'),
(12204, 'Bóng Dẻ Dải Ngân Hà', 'Ác Ma', 'Quang', 'Kuriboh', 1, 300, 200, 'UR', 0, 3, 'yhlzq', '<Curizi Ball> khoác lên Galaxy Armor.', '0'),
(12205, 'triệu hồi thiên hà', 'Pháp Sư', 'Quang', 'Ngân Hà Galaxy', 4, 1600, 1400, 'UR', 0, 3, 'yhzhs', 'Phần chính trong Bộ Bài của AMa Phápgi Kaito trong anime <Yu-Gi-Oh! ZEXAL> là Bộ Bài thuộc tính ánh sáng với <Galaxy Eyes Photon Dragon> làm cốt lõi.', '0'),
(12206, 'Chất xúc tác Balrog', 'Ác Ma', 'Thủy', 'Không có', 4, 1600, 200, 'UR', 0, 3, 'ymchs', 'Đầu hàng trước Thần Lửa - người già hơn cả thế giới. Đầu hàng trước sự diệt vong của bạn!', '0'),
(12207, 'nữ hoàng thiên hà', 'Pháp Sư', 'Quang', 'Ngân Hà Galaxy', 1, 500, 500, 'UR', 0, 3, 'yhnw', 'Phần chính trong Bộ Bài của AMa Phápgi Kaito trong anime <Yu-Gi-Oh! ZEXAL> là Bộ Bài thuộc tính ánh sáng với <Galaxy Eyes Photon Dragon> làm cốt lõi.', '0'),
(12208, 'Hầu gái nửa rồng·Hầu gái rồng Canghe', 'Rồng', 'Hỏa', 'hầu gái nửa rồng', 7, 2600, 1600, 'UR', 0, 3, 'blnpchln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12209, 'Hầu gái nửa rồng·Bà giặt giũ', 'Rồng', 'Hỏa', 'hầu gái nửa rồng', 2, 500, 1600, 'UR', 0, 3, 'blnpxyln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12210, 'Cô hầu gái nửa rồng ·Cô gái rồng nhân từ trần gian', 'Rồng', 'Địa', 'hầu gái nửa rồng', 7, 2600, 1600, 'UR', 0, 3, 'blnpdcln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12211, 'Cô hầu gái nửa rồng · Cô gái điều dưỡng rồng', 'Rồng', 'Địa', 'hầu gái nửa rồng', 2, 500, 1600, 'UR', 0, 3, 'blnpyyln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12212, 'Cô hầu gái nửa rồng ·Cô hầu gái thiên Phong Tộc rồng', 'Rồng', 'Phong', 'hầu gái nửa rồng', 8, 2700, 1700, 'UR', 0, 3, 'blnptfln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12213, 'Hầu gái nửa rồng ·Tầu hầu phòng khách rồng', 'Rồng', 'Phong', 'hầu gái nửa rồng', 3, 500, 1700, 'UR', 0, 3, 'blnpktln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12214, 'Cô hầu gái nửa rồng · Cô gái rồng lửa đỏ', 'Rồng', 'Thủy', 'hầu gái nửa rồng', 8, 2700, 1700, 'UR', 0, 3, 'blnpcyln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12215, 'Chúa tể máu rồng·Ma cà rồng', 'Zombie', 'Ám', 'Vampire', 8, 2800, 2100, 'UR', 0, 3, 'lxgxxg', 'Một trong những Ma Pháp cà rồng lâu đời nhất trong đế chế Ma Pháp cà rồng.', '0'),
(12216, 'người theo dõi chéo', 'Chiến Sĩ', 'Ám', 'Không có', 2, 400, 400, 'UR', 0, 3, 'jcksy', 'Từ người khuân vác: Đã lâu không gặp - anh nhớ em rất nhiều.', '0');
INSERT INTO `card_monsters` (`id`, `name`, `category`, `attribute`, `keyword`, `stars`, `atk`, `def`, `quality`, `cost`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(12217, 'hoàng đế photon', 'Chiến Sĩ', 'Quang', 'Photon', 8, 2800, 1000, 'UR', 0, 3, 'gzhd', 'Phần chính trong Bộ Bài của AMa Phápgi Kaito trong anime <Yu-Gi-Oh! ZEXAL> là Bộ Bài thuộc tính ánh sáng với <Galaxy Eyes Photon Dragon> làm cốt lõi.', '0'),
(12218, 'Nàng tiên biển độc ác', 'Pháp Sư', 'Hỏa', 'Di Sản Tinh Tú', 10, 3000, 1800, 'UR', 0, 3, 'xysxyhxn', 'Tất cả các lá bài Quái Thú đều có thuộc tính nước và được đặc trưng bởi nghi lễ triệu hồi. Đây là loạt bài theo chủ đề nghi thức triệu hồi đầu tiên sử dụng thống nhất các lá bài Phép Thuật nghi lễ cụ thể.', '0'),
(12219, 'Thần điềm báo', 'Thiên Thần', 'Quang', 'Không có', 4, 1400, 1000, 'UR', 0, 3, 'zss', 'Có lẽ sau này sẽ có <Kyote God>~~~', '0'),
(12220, 'Vua tử thần DDD·Thần tận cùng Địa Tộc ngục', 'Ác Ma', 'Ám', 'DDD', 8, 3000, 1000, 'UR', 0, 3, 'dddswwdyzms', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được Reiji AkaMa Pháp - chủ tịch <LDS> sử dụng trong <Yu-Gi-Oh ARC-V>. Sê-ri Bộ Bài đầu tiên bao gồm 4 <Phương pháp triệu hồi đặc biệt của Bộ Bài bổ sung> bao gồm Fusion - Synchro - XYZ - Pendulum và Link - và 1 <Phương pháp triệu hồi đặc biệt bằng lá bài tay cho Bộ Bài phụ>.', '0'),
(12221, 'Người triệu hồi vòng tròn·Tiên', 'Thực Vật', 'Phong', 'Không có', 3, 800, 1500, 'UR', 0, 3, 'yhsxn', 'Tôi muốn quay lại núi Lang Lang.', '0'),
(12222, 'Can Punk·Tiaohu', 'Tâm Linh', 'Địa', 'Trẻ Nghịch Ngợm', 8, 2300, 2600, 'UR', 0, 3, 'npkth', 'Tôi đã nói có 3 loại trang phục cơ mà~', '0'),
(12223, 'Người giúp việc nửa rồng·Người giúp việc rồng trong phòng ngủ', 'Rồng', 'Ám', 'hầu gái nửa rồng', 4, 500, 1800, 'UR', 0, 3, 'blnpqsln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12224, 'Phù Thủy với đôi mắt xanh', 'Rồng', 'Quang', 'Mắt Xanh', 1, 0, 1500, 'UR', 0, 3, 'qyxs', 'Dòng máu của Long tộc cuối cùng cũng thức tỉnh.', '0'),
(12225, 'Rồng cỡ nòng', 'Rồng', 'Ám', 'Đạn Pháo', 4, 1700, 100, 'UR', 0, 3, 'dwkjl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12226, 'chiến binh lái xe', 'Cyberse', 'Thủy', 'Không có', 4, 1500, 1000, 'UR', 0, 3, 'qdys', 'Công việc chính của tôi là sửa chữa máy tính và công việc phụ của tôi là cosplay.', '0'),
(12227, 'Thiên đường ánh sáng·Bahalutia', 'Rồng', 'Quang', 'Không có', 7, 2000, 2400, 'UR', 0, 3, 'gztcbhldy', 'Con rồng có cơ thể tỏa ra ánh sáng được cho là Ma Phápng lại hy vọng.', '0'),
(12228, 'ủng hộ Trickstar', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 1, 100, 0, 'UR', 0, 3, 'tqxxfws', 'Hàng loạt Quái Thú có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là bóng đêm - và ngôn ngữ của loài hoa là: trái tim ác độc - bùa tà ác và định mệnh.', '0'),
(12229, 'Kẻ lừa đảo Mandela', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 2, 0, 1000, 'UR', 0, 3, 'tqxxmdl', 'Những con Quái Thú trong truyện có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là: Ma Phápndrake. Ngôn ngữ của hoa là: sợ hãi và run rẩy.', '0'),
(12230, 'Ngôi sao lừa đảo Lilly Belle', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 2, 800, 2000, 'UR', 0, 3, 'tqxxllbe', 'Hàng loạt Quái Thú có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là: bluebell. Ngôn ngữ của các loài hoa: sự thanh khiết - sự đến của hạnh phúc - sự đến của hạnh phúc - sự May mắn và May mắn.', '0'),
(12231, 'Ngôi sao cổ tích nghịch ngợm Manzhu Shihua', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 3, 1600, 1200, 'UR', 0, 3, 'tqxxmzsh', 'Hàng loạt Quái Thú có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là: Hoa dâm bụt. Ngôn ngữ của các loài hoa: ký ức buồn - nỗi nhớ nhau - vẻ đẹp và sự thuần khiết.', '0'),
(12232, 'Thủy tiên lừa gạt', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 4, 1000, 1800, 'UR', 0, 3, 'tqxxnejs', 'Những con Quái Thú trong truyện có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là hoa Thủy Tộc tiên - và ngôn ngữ của các loài hoa là: tình yêu được mong đợi.', '0'),
(12233, 'Trickstar·Shinan', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 4, 1400, 1900, 'UR', 0, 3, 'tqxxsn', 'Hàng loạt Quái Thú có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là cây thạch nam. Ngôn ngữ của hoa là: sự cô đơn - uy nghiêm - trang trọng và dũng cảm.', '0'),
(12234, 'Candina Lừa đảo', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 4, 1800, 400, 'UR', 0, 3, 'tqxxkdn', 'Những con Quái Thú trong truyện có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là Ma Phápndala bằng gỗ. Ngôn ngữ của hoa là: hoa tình yêu - màu trắng và mềm mại. Ai nhìn thấy loài hoa này sẽ thoát khỏi tà ác.', '0'),
(12235, 'Lừa đảo Callowan', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 5, 2000, 1000, 'UR', 0, 3, 'tqxxklbe', 'Hình dạng của loạt Quái Thú là một yêu tinh với tư thế nữ. Nguyên mẫu của yêu tinh là loài hoa nước hoa của Pháp. Ngôn ngữ của loài hoa là: nhã nhặn - duyên dáng - tao nhã - tươi tắn mà tao nhã - tao nhã mà giản dị - trung thành và kiên cường - chỉ yêu vua đến chết.', '0'),
(12236, 'Trickstar·Thiên thần', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 5, 0, 0, 'UR', 0, 3, 'tqxxaqe', 'Hàng loạt Quái Thú có hình dáng giống yêu tinh với tư thế nữ tính. Nguyên mẫu của yêu tinh là cỏ Belladonna. Ngôn ngữ của các loài hoa là: phụ nữ xinh đẹp - sự im lặng - sự quyến rũ lừa dối và lời nguyền quyến rũ.', '0'),
(12237, 'Trickster Star·Phụ kiện', 'Cyberse', 'Quang', 'Ngôi sao lừa đảo', 2, 0, 0, 'UR', 0, 3, 'tqxxaqe', 'Một phụ kiện được các cô gái yêu thích.', '0'),
(12238, 'Những người hầu của nhiệt huyết khác nhau và một trái tim · Hiền nhân có vũ trang', 'Chiến Sĩ', 'Quang', 'Bầy Tôi Zexal ZS', 4, 300, 900, 'UR', 0, 3, 'yrtxczwzxz', 'Một người hầu có quan hệ mật thiết với <Hope Emperor Hope>.', '0'),
(12239, 'Những người theo đuổi với những đam mê khác nhau và một trái tim · Hiền nhân thăng hoa', 'Chiến Sĩ', 'Quang', 'Bầy Tôi Zexal ZS', 4, 900, 300, 'UR', 0, 3, 'yrtxczshxz', 'Một người hầu có quan hệ mật thiết với <Hope Emperor Hope>.', '0'),
(12240, 'Bộ cộng hưởng ngọn lửa', 'Ác Ma', 'Thủy', 'Cộng Hưởng Resonator', 3, 300, 1300, 'UR', 0, 3, 'hygmz', 'Quái Thú <Resonator> đều là những con quỷ cầm búa điều chỉnh và nĩa điều chỉnh trong tay. Vì những công cụ này có thể được sử dụng để kiểm tra sự cộng hưởng nên chúng phù hợp với chủ đề <Cộng hưởng>.', '0'),
