(12270, 'Bóng Ma Pháp thời gian·Cá voi cân bằng', 'Máy Móc', 'Ám', 'Kẻ Trộm Thời Gian', 4, 800, 1400, 'UR', 0, 3, 'sjgdblfj', 'Quái Thú bao gồm các Quái Thú thuộc tính bóng tối từ các loại máy móc và điều khiển từ xa. Chúng có hiệu ứng thu giữ các lá bài của đối phương làm siêu nguyên liệu và là một Bộ Bài sử dụng siêu triệu hồi như một chiến thuật.', '0'),
(12271, 'Quỷ vương', 'Chiến Sĩ', 'Ám', 'Không có', 5, 2400, 1000, 'UR', 0, 3, 'tmdd', 'Lão hoàng đế tới đây~~~', '0'),
(12272, 'Con rồng đen của đêm tối', 'Rồng', 'Ám', 'Không có', 7, 2500, 2100, 'UR', 0, 3, 'aydal', 'Ánh sáng bao trùm vạn vật - và tôi sẽ là cái bóng cuối cùng trong ánh sáng - dùng bóng tối đè bẹp ánh sáng! ! !', '0'),
(12273, 'Một Phù Thủy đen tinh vi', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 3, 900, 700, 'UR', 0, 3, 'ysdhmss', 'Những việc mà học giả làm sao có thể gọi là ăn trộm?', '0'),
(12274, 'Người mê côn trùng của Liesel', 'Thực Vật', 'Địa', 'Quỷ côn trùng', 2, 1800, 1600, 'UR', 0, 3, 'lszchm', 'Một cô gái côn trùng mới đã xuất hiện~~~', '0'),
(12275, 'Quỷ băng · Nhạc Nương', 'Zombie', 'Hỏa', 'Ác Ma', 1, 0, 1900, 'UR', 0, 3, 'bzmyxn', 'Một trong những Bộ Bài Yu-Gi-Oh. Series <Demon> dựa trên chủ đề về Quái Thú huyền thoại của Nhật Bản. Những Quái Thú được Misawa Land sử dụng đã bị biến thành xác sống sau khi bị biến thành OCG.', '0'),
(12276, 'Kích hoạt Wurm', 'Rồng', 'Ám', 'Đạn Pháo', 2, 600, 600, 'UR', 0, 3, 'bjyl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12277, 'kẻ sát nhân điên cuồng', 'Zombie', 'Ám', 'Không có', 2, 400, 200, 'UR', 0, 3, 'fkmsz', 'Bị lây nhiễm bởi <Zombie Carrier> và phát điên.', '0'),
(12278, 'Con rối máy ·Người chạm bóng', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 8, 1000, 1000, 'UR', 0, 3, 'jgklaycmz', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(12279, 'Con rối máy ·Bộ chuyển số', 'Máy Móc', 'Ám', 'Rối Cơ Khí Gimmick', 1, 100, 100, 'UR', 0, 3, 'jgklclbsz', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi nhân vật nổi tiếng IV (ThoMa Pháps Achred) trong anime <Yu-Gi-Oh! ZEXAL>.', '0'),
(12280, 'Rồng nổ', 'Rồng', 'Ám', 'Đạn Pháo', 8, 2100, 2800, 'UR', 0, 3, 'bfl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi thủ lĩnh của lực lượng phản diện <Knights of Hanno> trong <Yu-Gi-Oh! VRAINS> - Mitsumi Kogami (tên người dùng <Connection Reality Net>: Revolver).', '0'),
(12281, 'Đạo giáo tâm linh·Zombie', 'Zombie', 'Ám', 'Không có', 6, 2000, 0, 'UR', 0, 3, 'ldsjs', 'Tôi đoán: Bạn không cần phải chạy khi gặp loại zombie này.', '0'),
(12282, 'Hợp nhất rồng TiMa Phápeus', 'Rồng', 'Quang', 'Phù Thủy Áo Đen', 7, 2500, 2100, 'UR', 0, 3, 'htldmo', 'Con rồng huyền thoại.', '0'),
(12283, 'Quả bóng hạt dẻ Phép Thuật đen', 'Ác Ma', 'Ám', 'Phù Thủy Áo Đen', 1, 300, 200, 'UR', 0, 3, 'hmdlzq', 'Trang phục mới cho <Kuriball>.', '0'),
(12284, 'Phế liệu hạt dẻ', 'Máy Móc', 'Địa', 'Phế Liệu', 1, 300, 200, 'UR', 0, 3, 'fplzq', 'Một trong những Bộ Bài Yu-Gi-Oh. Bộ Bài chủ đề được nhân vật chính Yusei Fudo sử dụng trong <Yu-Gi-Oh 5D\'s>. Sử dụng <Descrap Synchronizer> để điều chỉnh - Synchro sẽ triệu hồi nhiều Quái Thú được Synchro <Descrap> khác nhau.', '0'),
(12285, 'Orcust·Divertimento Devil', 'Máy Móc', 'Ám', 'Orcus', 4, 1700, 1400, 'UR', 0, 3, 'zzsyxyqem', 'Một trong những Bộ Bài Yu-Gi-Oh. Một con Quái Thú máy móc có thể tự chơi nhạc.', '0'),
(12286, 'Chim ăn thịt: Shrike đen', 'Chim Thú', 'Ám', 'Chim Săn Mồi Raidraptor', 4, 1600, 500, 'UR', 0, 3, 'jxmqqhbl', 'Những con Quái Thú bao gồm chim bách thanh - đại bàng - chim ưng - cú rừng - kền kền và các loài chim khác với khả năng săn mồi mạnh mẽ. Mặc dù chúng là thú chim nhưng hình dạng của chúng có xu hướng được cơ giới hóa. Quái Thú XYZ cấp cao hơn còn được trang bị tên lửa - bom xăng - pháo hạt nổi - pháo vệ tinh - pháo lỗ đen và các vũ khí - thiết bị nhiệt khác.', '0'),
(12287, 'Người mê côn trùng của Gina', 'Thực Vật', 'Địa', 'Quỷ côn trùng', 4, 1400, 1400, 'UR', 0, 3, 'jnzchm', 'Bạn sẽ nói gì nếu gặp một cô gái bọ khi bạn đang cúi xuống nhặt sáu đồng xu?', '0'),
(12288, 'Bộ xương Orcust Scherzo', 'Máy Móc', 'Ám', 'Orcus', 3, 1200, 1500, 'UR', 0, 3, 'zzsyxxqkl', 'Một trong những Bộ Bài Yu-Gi-Oh. Một con Quái Thú máy móc có thể tự chơi nhạc.', '0'),
(12289, 'Món tráng miệng Golem·Zongzi', 'Thiên Thần', 'Quang', 'Bánh Ngọt Madolche', 4, 0, 0, 'UR', 0, 3, 'motdzz', 'm(＿＿)m vô cùng xin lỗi vì không thể đăng nhập do máy chủ bị tấn công.', '0'),
(12290, 'Thơm Đêm Stalker Lá Thạch Tràm', 'Thực Vật', 'Quang', 'Hương Thơm', 1, 0, 0, 'UR', 0, 3, 'fxymsnybqc', 'Chủ yếu là Quái Thú <AroMa Pháp Mage> - tên của các Quái Thú trong truyện hầu hết được lấy từ cây thơm dùng để làm tinh dầu.', '0'),
(12291, 'Rồng mắt xanh', 'Rồng', 'Quang', 'Mắt Xanh', 8, 2500, 2500, 'UR', 0, 3, 'qyhl', 'Tổng thống chưa sử dụng lá bài này.', '0'),
(12292, 'Người hầu gái nửa rồng ·Người hầu gái rồng trong nhà máy chưng cất', 'Rồng', 'Thủy', 'hầu gái nửa rồng', 3, 500, 1700, 'UR', 0, 3, 'blnpzlsln', 'Các hiệp sĩ rồng chiến đấu vào ban ngày và các hiệp sĩ rồng chiến đấu vào ban đêm. Hãy chú ý đến cơ thể và bổ sung chất dinh dưỡng kịp thời. Nhớ!', '0'),
(12293, 'Thiên hà chiến rồng', 'Rồng', 'Quang', 'Ngân Hà Galaxy', 4, 1500, 1000, 'UR', 0, 3, 'yhzl', 'Phần chính trong Bộ Bài của AMa Phápgi Kaito trong anime <Yu-Gi-Oh! ZEXAL> là Bộ Bài thuộc tính ánh sáng với <Galaxy Eyes Photon Dragon> làm cốt lõi.', '0'),
(12294, 'X·Pháo du lịch', 'Máy Móc', 'Quang', 'Không có', 4, 1800, 1500, 'UR', 0, 3, 'xcyjnp', '<X·Boss Cannon> Cập nhật trang bị.', '0'),
(12295, 'Vua chạy nhà siêu nóng', 'Chiến Sĩ', 'Thủy', 'Quyến Rũ', 4, 1500, 300, 'UR', 0, 3, 'crxbldw', 'Một phát bắn vào tâm hồn!', '0'),
(12296, 'Chúa tể xương', 'Zombie', 'Quang', 'Bộ Xương', 1, 300, 200, 'UR', 0, 3, 'bglz', 'Đừng dÁm Tộc nói nhảm!', '0'),
(12297, 'Z·Đường đua vô hạn', 'Máy Móc', 'Quang', 'Không có', 4, 1500, 1300, 'UR', 0, 3, 'zwqld', '<Z·Đường ray kim loại>Trang bị được cập nhật.', '0'),
(12298, 'phi công liên minh', 'Máy Móc', 'Quang', 'Không có', 5, 2100, 1000, 'UR', 0, 3, 'tmfxy', 'Phi công Ace áp dụng để chiến đấu!', '0'),
(12299, 'Rồng Trắng Mắt Xanh ngự trong tâm hồn', 'Rồng', 'Quang', 'Mắt Xanh', 8, 3000, 2500, 'UR', 0, 3, 'jsxldqybl', 'Có sẵn hình ảnh mới 0.0', '0'),
(12300, 'Nữ hoàng lửa vĩnh cửu', 'Ác Ma', 'Ám', 'Lửa Vĩnh Cửu Infernity', 3, 300, 300, 'UR', 0, 3, 'yhwh', 'Không giống như hầu hết các Bộ Bài theo đuổi chiến lược tích lũy thêm tài nguyên lá bài trong tay - hầu hết các quái thú <Eternal Fire> và các lá bài Phép & Bẫy chỉ bộc lộ sức mạnh thực sự của chúng khi có 0 lá bài trên tay.', '0'),
(12301, 'Vua lửa bị nguyền rủa · Lời nguyền bùng nổ', 'Ác Ma', 'Thủy', 'Vua Lửa', 3, 1600, 800, 'UR', 0, 3, 'zywbz', 'Dù sao ta tên Yến Vương - nên có từ khóa!', '0'),
(12302, 'Lửa vừa Sita', 'Pháp Sư', 'Thủy', 'Gusto', 5, 1850, 1500, 'UR', 0, 3, 'hlmsxt', '<Sở hữu: Sita> Tiến lên trở thành nhà ngoại cảm thông qua giao tiếp sâu hơn với nguyên tố lửa.', '0'),
(12303, 'Sea Crystal Maiden·Chim kim oanh của Strych hoạt động', 'Cyberse', 'Hỏa', 'Công Chúa Biển', 4, 1200, 1000, 'UR', 0, 3, 'hjsnhysnssjcqd', 'Một trong những Bộ Bài Yu-Gi-Oh. Một loạt Bộ Bài được sử dụng bởi Aoi ZaiMa Phápe (tên người dùng <Connection Realm Network>: Blue Virgin) trong anime <Yu-Gi-Oh! VRAINS>.', '0'),
(12304, 'hàng xóm sấm sét', 'Sấm Sét', 'Quang', 'Rồng Sấm Sét', 4, 500, 1200, 'UR', 0, 3, 'ldlj', 'Xin chào - tôi là hàng xóm cạnh nhà của bạn Lão Lôi ~', '0'),
(12305, 'Gió Trung Uy Âm', 'Pháp Sư', 'Phong', 'Gusto', 5, 1850, 1500, 'UR', 0, 3, 'flmswy', '<Dựa trên ngoại hình·Wei Yin> Tiến lên trở thành một phương tiện tâm linh thông qua giao tiếp sâu hơn với nguyên tố gió.', '0'),
(12306, 'Rồng Sấm·Rồng Sấm', 'Sấm Sét', 'Ám', 'Rồng Sấm Sét', 8, 2800, 0, 'UR', 0, 3, 'ljlll', 'Được mở rộng từ các lá bài cũ <Rồng Sấm> và <Rồng Sấm Hai Đầu> - Quái Thú đều là Quái Thú thuộc loại Sấm sét với thuộc tính ánh sáng hoặc bóng tối. Về cơ bản - chúng có các hiệu ứng được kích hoạt bằng cách loại bỏ các lá bài khỏi tay và các hiệu ứng gây ra khi bị đưa ra khỏi sân hoặc đưa đến Nghĩa Địa.', '0'),
(12307, 'Bức màn của Phù Thủy đen', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 2, 700, 700, 'UR', 0, 3, 'hmssdml', 'Bí mật tiến hóa từ lá bài Phép Thuật thành lá bài Quái Thú~', '0'),
(12308, 'Trái đất tâm linh vừa Ossi', 'Pháp Sư', 'Địa', 'Gusto', 5, 1850, 1500, 'UR', 0, 3, 'dlmsas', '<Thiết bị sở hữu·Osi> Tiến lên trở thành phương tiện tâm linh thông qua giao tiếp sâu hơn với nguyên tố đất.', '0'),
(12309, 'Nước vừa Arya', 'Pháp Sư', 'Hỏa', 'Gusto', 5, 1850, 1500, 'UR', 0, 3, 'slmsaly', '<Sở hữu: Arya> Tiến lên trở thành nhà ngoại cảm thông qua việc giao tiếp sâu hơn với nguyên tố nước.', '0'),
(12310, 'Phù Thủy bóng tối', 'Pháp Sư', 'Ám', 'Phù Thủy Áo Đen', 7, 2500, 2100, 'UR', 0, 3, 'ahmds', 'Làm việc chăm chỉ một cách lặng lẽ và sau đó làm mọi người ngạc nhiên ~', '0'),
(12311, 'Ác anh hùng·Quỷ bong bóng độc', 'Ác Ma', 'Hỏa', 'Anh Hùng Tà Ác', 4, 800, 1200, 'UR', 0, 3, 'xxyxdpm', 'Một trong những Bộ Bài Yu-Gi-Oh. Nó thuộc về một trong sáu Bộ Bài <HERO>. Đây là Bộ Bài được sử dụng bởi Yujo Judai - nhân vật chính của anime <Yu-Gi-Oh GX> - khi anh ngã xuống và trở thành Overlord.', '0'),
(12312, 'Kiếm sĩ ngọn lửa thép', 'Chiến Sĩ', 'Thủy', 'Mắt Đỏ', 6, 2500, 1600, 'UR', 0, 3, 'gyzjs', '<Kiếm Sĩ Lửa> được trang bị áo giáp mới.', '0');
INSERT INTO `card_spells` (`id`, `name`, `type`, `keyword`, `quality`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(20001, 'Sách Phép Thuật', 'Trang Bị', 'Phù Thủy Áo Đen', 'UR', 3, 'mszws', 'Trang bị Phép Thuật của <Dark Magician> và <Dark Magical Girl>.', '0'),
(20002, 'Ngàn Dao', 'Thông Thường', 'Phù Thủy Áo Đen', 'SR', 3, 'qbd', '<Phù Thủy Áo Đen> Phép Thuật độc quyền. Có thể tiêu diệt Quái Thú của đối phương.', '|Mô tả|\\nLá này chỉ có thể được sử dụng khi có một Phù Thủy bóng tối trên sân phe ta để tiêu diệt một quái thú được chỉ định của đối phương.'),
(20003, 'Phép Thuật ảo ảnh', 'Thông Thường', 'Phù Thủy Áo Đen', 'R', 3, 'hxmf', 'Hiến tế Quái Thú Phù Thủy của chính bạn để thêm <Dark Magician> vào tay bạn.', '0'),
(20004, 'vụ nổ Phép Thuật', 'Thông Thường', 'Không có', 'R', 3, 'mfbp', 'Khi Quái Thú loại Phù Thủy của bạn ở trên sân - nó có thể gây sát thương cho đối phương.', '0'),
(20005, 'Dung Hợp', 'Thông Thường', 'Dung Hợp', 'SR', 3, 'rh', 'Phép Thuật triệu hồi Quái Thú hợp nhất.', '|Mô tả|\\nLá bài cốt lõi của hệ thống hợp nhất có thể triệu hồi Quái Thú hợp nhất bằng cách gửi lá bài vật liệu hợp nhất trong lĩnh vực của bạn và đưa đến Nghĩa Địa. Phương pháp triệu hồi này phải có lá bài Quái Thú Dung Hợp để thành công\\nNếu bạn muốn triệu tập nhiều Quái Thú Dung Hợp có cùng tên trên sân cùng một lúc - bạn cần phải có nhiều lá bài Quái Thú Dung Hợp trong Bộ Bài bổ sung.'),
(20006, 'Mảng Phép Thuật đen', 'Vĩnh Cửu', 'Phù Thủy Áo Đen', 'SR', 3, 'hmdz', 'Khi <Dark Mage> của chính bạn được triệu hồi hoặc triệu hồi đặc biệt - bạn có thể hủy lá bài của đối phương.', '|Mô tả|\\nCác lá bài mà Black Magic Array có thể lấy được bao gồm Dark Magician - Thousand Knives - Illusion Magic - Black Magic Array - Black Explosion Magic - Black Magic Explosion - Black Magic - Black Magic Enhanceing - Black Magic Inheritance - Knight\'s Title - Sage\'s Gem - Black Magic\'s Rèm - Magic Spell Book - Miracle Resurrection và Eternal Soul.'),
(20007, 'Rồng trắng giáng xuống', 'Nghi Thức', 'Không có', 'R', 3, 'bljl', 'Một Phép Thuật triệu hồi đặc biệt <White Dragon Paladin>.', '0'),
(20008, 'Phép Thuật lừa gạt 4', 'Thông Thường', 'Không có', 'R', 3, 'gssdmss', '<Trickster> Phép Thuật độc quyền. Có thể sinh ra <Mã thông báo Trickster>.', '0'),
(20009, 'Đen·nổ·nứt·phá vỡ·Phép Thuật·hướng dẫn', 'Thông Thường', 'Phù Thủy Áo Đen', 'SR', 3, 'hblpmd', 'Khi quái thú <Dark Magician> và <Dark Magical Girl> của chính bạn ở trên sân - bạn có thể tiêu diệt tất cả lá bài của đối phương.', '0'),
(20010, 'Hướng dẫn Phép Thuật hắc Ám Tộc', 'Thông Thường', 'Phù Thủy Áo Đen', 'UR', 3, 'hmd', 'Khi có <Phù Thủy Áo Đen> của riêng bạn - bạn có thể phá hủy tất cả Phép Thuật và Cạm Bẫy của đối phương.', '0'),
(20011, 'Đen·Ma thuật·Hướng dẫn·Nổ·Crack·Hỏng', 'Thông Thường', 'Không có', 'SR', 3, 'hmdblp', 'Khi <Dark Magical Girl> của bạn ở trên sân - bạn có thể tiêu diệt quái thú của đối phương.', '0'),
(20012, 'Tăng cường Phép Thuật đen', 'Thông Thường', 'Phù Thủy Áo Đen', 'R', 3, 'hmdqh', 'Tăng cường Phép Thuật của Phù Thủy thuộc tính bóng tối của riêng bạn.', '0'),
(20013, 'Sự kế thừa của Phép Thuật đen', 'Thông Thường', 'Phù Thủy Áo Đen', 'R', 3, 'hmsdjc', 'Loại bỏ các lá bài Phép Thuật khỏi Nghĩa Địa của chính bạn và thêm các lá bài có từ khóa <Black Mage> vào tay bạn.', '0'),
(20014, 'bức màn Phép Thuật đen', 'Thông Thường', 'Phù Thủy Áo Đen', 'UR', 2, 'hmsdml', 'Trả một nửa mạng sống của bạn để Triệu hồi Đặc biệt <Dark Mage>.', '0'),
(20015, 'Hồ Long Đế', 'Thông Thường', 'Không có', 'UR', 3, 'hld', 'Khi <Dragon Dominator> của bạn ở trên sân - bạn có thể triệu hồi đặc biệt các Quái Thú loại rồng.', '|Các kết hợp thường dùng|\\nThần Long + Sáo Gọi Rồng + Rồng Trắng Mắt Xanh'),
(20016, 'quả cầu lửa', 'Thông Thường', 'Không có', 'N', 3, 'hq', 'Gây sát thương trực tiếp cho đối phương.', '0'),
(20017, 'Phép Thuật chéo', 'Thông Thường', 'Không có', 'R', 3, 'jcmf', 'Khi có hai hoặc nhiều quái thú loại Phù Thủy trên sân phe ta - bạn có thể tăng sức tấn công của một trong số chúng.', '0'),
