(21130, 'Cô gái pha lê biển lẻn vào', 'Vĩnh Cửu', 'Công Chúa Biển', 'UR', 3, 'hjsndqh', 'Một Phép Thuật có thể triệu hồi Quái Thú một cách đặc biệt.', '0'),
(21131, 'xả Brontosaurus', 'Vĩnh Cửu', 'Rồng Sấm Sét', 'UR', 3, 'llfd', 'Phép Thuật có thể phá hủy các lá bài.', '0'),
(21132, 'Rồng mắt xanh đang đến', 'Thông Thường', 'Mắt Xanh', 'UR', 3, 'qylhl', 'Một Phép Thuật có thể triệu hồi Quái Thú một cách đặc biệt.', '0'),
(21133, 'cuộc tấn công ác độc', 'Thông Thường', 'Không có', 'UR', 3, 'xeqx', 'Ma thuật Quái Thú có thể được lấy lại.', '0');
INSERT INTO `card_traps` (`id`, `name`, `type`, `keyword`, `quality`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(30001, 'Holy Shield·Sức mạnh phản chiếu', 'Phản Đòn', 'Không có', 'UR', 3, 'ssfhzfszl', 'Kích hoạt khi quái thú của đối phương tấn công - tiêu diệt tất cả quái thú ở vị trí tấn công trên sân đối phương.', '|Mô tả|\\nMột trong những lá bài loại bỏ nhóm mạnh nhất trong trò chơi'),
(30002, 'lỗ thủng', 'Phản Đòn', 'Hố Sụt', 'SR', 3, 'ccdlx', 'Kích hoạt khi đối phương triệu hồi đặc biệt một quái thú để tiêu diệt quái thú đó.', '0'),
(30003, 'Lời nguyền của ngôi sao sáu cánh', 'Trang Bị', 'Không có', 'R', 3, 'lmxzzf', 'Trang bị nó cho quái thú của đối phương và quái thú đó bị <chặn>.', '0'),
(30004, 'Mảng can thiệp Phép Thuật', 'Phản Đòn', 'Không có', 'UR', 3, 'mfgrz', 'Kích hoạt khi đối phương sử dụng Phép Thuật - Phép Thuật không có hiệu lực và bị phá hủy.', '0'),
(30005, 'sao chép bản sao', 'Trang Bị', 'Không có', 'SR', 3, 'klfz', 'Kích hoạt khi đối phương triệu hồi một quái thú để sao chép quái thú đó.', '|Mô tả|\\nHiệu ứng nhân bản chỉ có hiệu lực đối với các triệu hồi thông thường - không phải các triệu hồi đặc biệt\\nQuái Thú nhân bản được tính là Quái Thú bình thường và không thể sao chép các kỹ năng của Quái Thú gốc\\nKhi lá bài nhân bản rời khỏi Vùng Bẫy Phép Thuật - Quái Thú được sao chép cũng sẽ bị tiêu diệt\\nQuái Thú nhân bản sẽ không vào Nghĩa Địa sau khi chết.'),
(30006, 'Cân ngược của rồng', 'Vĩnh Cửu', 'Không có', 'R', 3, 'lznl', 'Nó được kích hoạt khi có một quái thú loại Rồng trên sân phe ta. Khi quái thú hệ Rồng của bạn tấn công - nó có thể gây sát thương cho người chơi đối phương.', '0'),
(30007, 'Lời nguyền bóng tối', 'Trang Bị', 'Không có', 'UR', 3, 'azzf', 'Cách nhận được: |Hộp quà giá trị|.', '|Mô tả|\\nMột lá bài bẫy rất hữu ích. Quái Thú được khống chế thành công rất yếu.'),
(30008, 'kẻ trộm mộ', 'Thông Thường', 'Không có', 'UR', 3, 'dmz', 'Nhận được 1 lá bài Phép Thuật từ Nghĩa Địa của kẻ địch.', '|Mô tả|\\n Dành 2000 mạng để đánh cắp một lá bài Phép Thuật từ Nghĩa Địa của đối phương. Nếu có thể cướp được những lá bài mạnh mẽ như Resurrection of the Dead và Harpy Feather Sweep thì sẽ cực kỳ lãi.'),
(30009, 'Bảy công cụ của tên trộm', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'dzdqdj', 'Khi bẫy của đối phương được kích hoạt - sinh lực sẽ bị tiêu hao để vô hiệu hóa và phá hủy bẫy.', '0'),
(30010, 'Xúc xắc của quỷ', 'Thông Thường', 'Xúc Xắc Speedroid', 'SR', 3, 'emdtz', 'Đổ 1 viên xúc xắc. Tất cả Quái Thú bên phía đối phương đều có khả năng tấn công và phòng thủ liên quan đến số lượng rơi ra.', '0'),
(30011, 'Boomerang có thể khóa', 'Trang Bị', 'Không có', 'SR', 3, 'fshxb', 'Lựa chọn: 1. Trang bị nó cho quái thú của đối phương và quái thú đó sẽ bị <chặn>. 2. Trang bị nó cho quái thú của bạn để tăng sức tấn công của quái thú đó.', '0'),
(30012, 'Vô hiệu hóa tấn công', 'Phản Đòn', 'Không có', 'UR', 3, 'gjwlh', 'Kích hoạt khi quái thú của đối phương tấn công và tất cả quái thú của đối phương bị <chặn> ở lượt này.', '0'),
(30013, 'Phong ấn thanh kiếm ánh sáng', 'Phản Đòn', 'Không có', 'R', 3, 'gzfzj', 'Kích hoạt khi đối phương nhận được lá bài tiếp theo trên tay của họ và tạm thời <trục xuất> lá bài đó trong 3 lượt.', '0'),
(30014, 'Bóng Ma Pháp Phép Thuật hắc Ám Tộc', 'Phản Đòn', 'Không có', 'R', 3, 'hmdhy', 'Kích hoạt vào đầu lượt của đối phương và tất cả Quái Thú loại Phù Thủy thuộc tính bóng tối của riêng bạn đều nhận được <Rào cản nguyên tố>.', '0'),
(30015, 'Quan tài phục sinh của quỷ bóng tối', 'Phản Đòn', 'Không có', 'UR', 3, 'hmzfhg', 'Kích hoạt khi đối phương triệu hồi hoặc triệu hồi đặc biệt một quái thú. Triệu hồi đặc biệt 1 Quái Thú Phù Thủy thuộc tính bóng tối từ Nghĩa Địa của chính bạn.', '|Mô tả|\\nNó rất hữu ích trong các Bộ Bài không có Phép Thuật. Nó có thể hồi sinh những Quái Thú Phù Thủy bóng tối như Phù Thủy Tộc Rừng Đen và Nhà khoa học Phép Thuật.'),
(30016, 'chuyển vị', 'Phản Đòn', 'Không có', 'UR', 3, 'hw', 'Kích hoạt khi một Quái Thú thân thiện trở thành mục tiêu của một Phép Thuật hoặc một cái bẫy. Phép Thuật hoặc cái bẫy bị vô hiệu và bị phá hủy.', '|Mô tả|\\nMột lá bài phản công mạnh mẽ chống lại các Phép & Bẫy mục tiêu đơn lẻ'),
(30017, 'áo giáp phản chiếu Phép Thuật', 'Trang Bị', 'Không có', 'R', 3, 'mffszj', 'Kích hoạt khi quái thú của bạn bị Quái Thú của đối phương tấn công để tăng khả năng tấn công và phòng thủ cho quái thú của bạn.', '0'),
(30018, 'Nồi ấn rồng', 'Vĩnh Cửu', 'Không có', 'SR', 3, 'lzfyzh', 'Kích hoạt khi một Quái Thú loại rồng tấn công và tất cả Quái Thú loại rồng đều bị <chặn>.', '0'),
(30019, 'cuốn sách Phép Thuật', 'Phản Đòn', 'Không có', 'N', 3, 'msdzws', 'Kích hoạt khi quái thú của bạn bị quái thú của đối phương tấn công để tăng sức tấn công cho quái thú của bạn.', '0'),
(30020, 'ống Phép Thuật', 'Phản Đòn', 'Không có', 'SR', 3, 'mft', 'Được tung ra khi Quái Thú của đối phương tấn công trực tiếp vào người chơi - sát thương sẽ do đối phương gánh chịu.', '0'),
(30021, 'chiếc mũ Phép Thuật', 'Phản Đòn', 'Không có', 'SR', 3, 'mslm', 'Kích hoạt khi quái thú của bạn bị tấn công bởi Quái Thú của đối phương. Quái Thú của đối phương có thể tấn công sai mục tiêu.', '0'),
(30022, 'Hướng dẫn Phù Thủy', 'Thông Thường', 'Phù Thủy Áo Đen', 'UR', 3, 'mssdmz', 'Triệu hồi Đặc biệt <Dark Magician> từ tay bạn. Nếu thành công - Triệu hồi Đặc biệt 1 quái thú Dark Magician cấp 6 trở xuống từ Bộ Bài của bạn.', '0'),
(30023, 'hang động Naraku', 'Phản Đòn', 'Hố Sụt', 'UR', 3, 'nldlx', 'Kích hoạt khi đối phương triệu hồi đặc biệt một quái thú - tiêu diệt quái thú đó và <loại bỏ> nó.', '0'),
(30024, 'Sự hồi sinh kỳ diệu', 'Thông Thường', 'Phù Thủy Áo Đen', 'UR', 3, 'qjzfh', 'Loại bỏ 2 <Bộ Đếm Ma Lựcs> của riêng bạn và triệu hồi đặc biệt <Dark Magician> hoặc <Destroying SwordsMa Phápn> trong Nghĩa Địa của chính bạn.', '|Kết hợp thông thường|\\nPhù Thủy trắng có tay nghề + Hồi sinh thần kỳ\\nPhù Thủy đỏ sẫm + Hồi sinh thần kỳ'),
(30025, 'vụ nổ tan chảy', 'Phản Đòn', 'Không có', 'UR', 3, 'rb', 'Kích hoạt khi lá bài của chính mình bị hủy - hủy 1 lá bài của đối phương.', '0'),
(30026, 'Cánh Griffin', 'Phản Đòn', 'Không có', 'R', 3, 'sjzy', 'Kích hoạt khi đối phương sử dụng <Harpy Feather Sweep> - Phép Thuật này sẽ vô hiệu và tất cả Phép Thuật cũng như bẫy của đối phương sẽ bị phá hủy.', '0'),
(30027, 'cỗ máy thời gian', 'Phản Đòn', 'Không có', 'UR', 3, 'sjjx', 'Quái Thú được hồi sinh bởi cỗ máy thời gian sẽ trở về trạng thái ban đầu.', '|Mô tả|\\nNó thường được sử dụng khi chỉ có một Quái Thú cấp cao trên sân phe ta hoặc khi bạn cần giữ Quái Thú đó trên sân phe ta để hiến tế ở lượt tiếp theo. Tuy nhiên - cần lưu ý rằng lá bài Quái Thú được hồi sinh bằng cỗ máy thời gian sẽ không kích hoạt hiệu ứng ban đầu của Quái Thú đi vào Nghĩa Địa.'),
(30028, 'những người bạn đồng hành', 'Phản Đòn', 'Không có', 'UR', 3, 'tlr', 'Kích hoạt khi một quái thú của bản thân bị tiêu diệt và đi vào Nghĩa Địa - tiêu diệt 1 quái thú của đối phương.', '|Mô tả|\\nMột phương pháp loại bỏ lá bài rất hữu ích khi đối phương chỉ có một Quái Thú cấp cao trên sân.'),
(30029, 'mảng gây nhiễu bẫy', 'Phản Đòn', 'Không có', 'UR', 3, 'xjgrz', 'Được tung ra khi đối phương kích hoạt bẫy - bẫy sẽ mất hiệu ứng và bị phá hủy.', '0'),
(30030, 'cái hố', 'Phản Đòn', 'Hố Sụt', 'UR', 2, 'xk', 'Kích hoạt khi đối phương triệu hồi hoặc triệu hồi đặc biệt một quái thú để tiêu diệt quái thú đó.', '0'),
(30031, 'linh hồn vĩnh cửu', 'Vĩnh Cửu', 'Phù Thủy Áo Đen', 'UR', 2, 'yyzh', 'Lá bài KEY của Bộ Bài <Dark Magician>.', '0'),
(30032, 'Vòng tròn Phù Thủy', 'Phản Đòn', 'Không có', 'UR', 3, 'mssdfz', 'Kích hoạt khi một Quái Thú loại Phù Thủy tấn công và mỗi bên triệu hồi đặc biệt 1 Quái Thú loại Phù Thủy từ Bộ Bài.', '|Mô tả|\\nMột trong những lá bài thường được sử dụng trong Bộ Bài Dark Magician - có thể nhanh chóng triệu hồi Quái Thú'),
(30033, 'hấp thụ', 'Phản Đòn', 'Không có', 'N', 3, 'xsmf', 'Kích hoạt khi lá bài bẫy của đối phương được kích hoạt. Bẫy không hợp lệ và bị phá hủy - đồng thời sức tấn công của Quái Thú của bạn tăng thêm 500 điểm.', '0'),
(30034, 'Hủy kết nối', 'Phản Đòn', 'Không có', 'N', 3, 'jcrh', 'Kích hoạt khi Quái Thú Dung Hợp của đối phương tấn công - tiêu diệt Quái Thú Dung Hợp và triệu hồi đặc biệt nguyên liệu Dung Hợp - kết thúc giai đoạn chiến đấu của đối phương.', '0'),
(30035, 'chai dục vọng', 'Thông Thường', 'Không có', 'UR', 3, 'qyzp', 'Cách nhận được: |Hộp quà giá trị|.', '0'),
(30036, 'Tâm hồn mắt đỏ thực sự', 'Thông Thường', 'Mắt Đỏ', 'SR', 3, 'zhyzh', 'Quái Thú có từ khóa <Mắt đỏ> có thể được triệu hồi đặc biệt từ Nghĩa Địa của chính bạn.', '|Các kết hợp thường được sử dụng|\\nLinh hồn mắt đỏ hồi sinh Rồng đen mắt đỏ trong nghĩa trang'),
(30037, 'sự lựa chọn của nữ hoàng', 'Thông Thường', 'Không có', 'SR', 3, 'nwdxz', 'Kích hoạt khi quái thú của bạn có từ khóa <Amazoness> tiêu diệt quái thú của đối phương và triệu hồi đặc biệt một quái thú có từ khóa <Amazoness>.', '0'),
(30038, 'sự trừng phạt của thần thánh', 'Thông Thường', 'Không có', 'UR', 3, 'tf', 'Những lá bài bẫy có thể tiêu diệt Quái Thú của đối phương.', '0'),
(30039, 'giải trừ quân bị', 'Thông Thường', 'Không có', 'UR', 3, 'wzjc', 'Phá hủy tất cả các lá bài Phép Thuật trang bị ở cả hai bên sân đấu.', '0'),
(30041, 'Sự quyến rũ của xác sống', 'Vĩnh Cửu', 'Không có', 'R', 3, 'sldyy', 'Gây sát thương cho chủ lá bài khi lá bài được gửi đến Nghĩa Địa.', '0'),
(30042, 'thiên thần áo trắng', 'Thông Thường', 'Không có', 'R', 3, 'byts', 'Ra mắt khi người chơi nhận sát thương - nó có thể phục hồi sự sống.', '0'),
(30043, 'ân huệ của Chúa', 'Vĩnh Cửu', 'Không có', 'SR', 3, 'szeh', 'Sự sống có thể được phục hồi khi một bên rút được lá bài.', '0'),
(30044, 'Thánh lao', 'Phản Đòn', 'Không có', 'SR', 3, 'ssbq', 'Kích hoạt khi Quái Thú của đối phương tấn công để phục hồi mạng sống của chính nó.', '0'),
(30045, 'Phước lành của Chúa Thánh Thần', 'Thông Thường', 'Không có', 'R', 3, 'sjldzf', 'Càng nhiều Quái Thú ở hai bên sân - chúng càng có thể hồi phục nhiều sinh mạng hơn.', '0'),
(30046, 'phá hủy dây chuyền', 'Phản Đòn', 'Không có', 'SR', 3, 'lsph', 'Kích hoạt khi đối phương triệu hồi Quái Thú và có thể tiêu diệt quái thú trên tay và Bộ Bài của đối phương.', '0'),
(30047, 'Khiên tà ác Sức mạnh bóng tối', 'Phản Đòn', 'Không có', 'UR', 3, 'xefhzahzl', 'Kích hoạt khi quái thú của đối phương tấn công - <trục xuất> tất cả quái thú ở vị trí phòng thủ trên sân đối phương.', '0'),
(30048, 'Ma đạo thư ẩn giấu', 'Thông Thường', 'Sách Phép', 'UR', 3, 'ycdmds', 'Bạn có thể thêm các lá bài Phép Thuật từ Nghĩa Địa của chính mình vào Bộ Bài của mình.', '0'),
(30049, 'thanh lọc Phép Thuật', 'Thông Thường', 'Không có', 'SR', 3, 'mljh', 'Có thể tiêu diệt tất cả các lá bài Phép Thuật vĩnh viễn trên sân.', '0'),
(30050, 'Đường nét của tâm hồn', 'Phản Đòn', 'Không có', 'SR', 3, 'hzg', 'Kích hoạt khi một Quái Thú thân thiện bị tiêu diệt bởi một hiệu ứng và triệu hồi đặc biệt một Quái Thú từ Bộ Bài.', '0'),
(30052, 'Bão Itacua', 'Phản Đòn', 'Không có', 'UR', 1, 'ytkybf', 'Cách nhận được: |Phần thưởng nạp tiền tích lũy|.', '0'),
(30055, 'Chiếc rìu nứt dần', 'Trang Bị', 'Không có', 'SR', 3, 'zjxlzf', 'Trang bị nó cho Quái Thú của đối phương và sức tấn công của Quái Thú đó sẽ bị giảm đi sau mỗi lượt.', '0'),
(30056, 'phản công phản công', 'Phản Đòn', 'Không có', 'SR', 3, 'fjfj', 'Ra mắt khi đối phương tung bẫy phản công - bẫy sẽ mất hiệu ứng và bị phá hủy.', '0'),
(30057, 'Hối lộ cung điện của quỷ', 'Phản Đòn', 'Không có', 'SR', 3, 'mgdhl', 'Kích hoạt khi đối phương kích hoạt Phép Thuật hoặc bẫy. Phép Thuật hoặc cái bẫy bị vô hiệu và bị phá hủy - và đối phương rút một lá bài từ Bộ Bài.', '0'),
(30058, 'Phá hủy áo giáp', 'Phản Đòn', 'Không có', 'SR', 3, 'kjph', 'Kích hoạt khi đối phương sử dụng Phép Thuật trang bị - Phép Thuật không hợp lệ và bị phá hủy.', '0'),
(30059, 'trường lực', 'Phản Đòn', 'Không có', 'SR', 3, 'lc', 'Kích hoạt khi một Quái Thú thân thiện trở thành mục tiêu của một Phép Thuật. Phép thuật bị vô hiệu và bị phá hủy.', '0'),
(30060, 'phục kích', 'Phản Đòn', 'Không có', 'SR', 3, 'fb', 'Kích hoạt khi đối phương triệu hồi một quái thú để Triệu hồi Đặc biệt một quái thú từ tay bạn.', '0'),
(30061, 'bức tường thành phố', 'Phản Đòn', 'Không có', 'R', 3, 'cb', 'Kích hoạt khi quái thú của bạn bị quái thú của đối phương tấn công để tăng khả năng phòng thủ cho quái thú của bạn.', '0'),
(30062, 'lỗ dính', 'Phản Đòn', 'Hố Sụt', 'SR', 3, 'nzdlx', 'Kích hoạt khi đối phương triệu hồi hoặc triệu hồi đặc biệt - và sức tấn công của quái thú được triệu hồi trở thành một nửa giá trị ban đầu.', '0'),
(30063, 'con dấu chạm khắc', 'Thông Thường', 'Không có', 'SR', 3, 'kzfy', 'Sau khi kích hoạt - đối phương không thể rút bài vào đầu lượt tiếp theo.', '0'),
(30064, 'Kỹ thuật tái sinh của Amazoness', 'Thông Thường', 'Amazoness', 'UR', 3, 'ymxzss', 'Tiêu diệt các quái thú có từ khóa <Amazoness> trên sân phe ta và Triệu hồi Đặc biệt cùng số lượng quái thú có từ khóa <Amazoness> từ Nghĩa Địa.', '0'),
(30065, 'Đội nỏ Amazoness', 'Phản Đòn', 'Amazoness', 'UR', 3, 'ymxngd', 'Được tung ra khi đối phương tấn công - nó có thể chuyển tất cả quái thú của đối phương vào vị trí tấn công và giảm sức tấn công của chúng.', '0'),
(30066, 'aMa Phápzon sẽ', 'Trang Bị', 'Amazoness', 'UR', 3, 'ymxdyz', 'Quái Thú có từ khóa <Amazoness> có thể được triệu hồi đặc biệt từ Nghĩa Địa của chính bạn.', '0'),
(30067, 'giật lại', 'Phản Đòn', 'Không có', 'SR', 3, 'fc', 'Kích hoạt khi đối phương triệu hồi - và quái thú được triệu hồi trở về tay đối phương.', '0'),
(30068, 'Tuôn ra', 'Thông Thường', 'Không có', 'SR', 3, 'ths', 'Khi đối phương có bài trong khu vực Phép & Bẫy trên sân - tất cả lá bài Phép & Bẫy có thể bị tiêu diệt.', '0'),
(30069, 'viền tối', 'Phản Đòn', 'Không có', 'SR', 3, 'ahbj', 'Nó có thể được kích hoạt khi bản thân nhận sát thương trực tiếp và triệu hồi đặc biệt một Quái Thú Phù Thủy hắc Ám Tộc từ Bộ Bài.', '0'),
(30070, 'Băng tâm hồn', 'Thông Thường', 'Không có', 'UR', 3, 'hzbj', 'Nó có thể được kích hoạt khi sự khác biệt giữa mạng sống của bạn và mạng sống của đối phương là cực kỳ lớn. Tất cả quái thú của đối phương sẽ không thể tấn công ở lượt tiếp theo.', '0'),
(30071, 'Chuẩn bị kết hợp', 'Thông Thường', 'Không có', 'UR', 3, 'rhzb', 'Bạn có thể thêm nguyên liệu cho Quái Thú Dung Hợp từ Bộ Bài của mình vào tay và bạn có thể tái chế <Fusion> từ Nghĩa Địa của chính mình.', '|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(30072, 'Thuốc tăng cường sức mạnh thể chất ·Super Z', 'Phản Đòn', 'Không có', 'SR', 3, 'tlzqjcjz', 'Kích hoạt khi quái thú của đối phương gây ra một lượng lớn sát thương cho bản thân để phục hồi mạng sống cho chính bạn.', '0'),
(30073, 'Khiên và giáo', 'Phản Đòn', 'Không có', 'R', 3, 'dm', 'Kích hoạt khi quái thú của bạn bị Quái Thú của đối phương tấn công để tăng khả năng tấn công và phòng thủ cho quái thú của bạn.', '0'),
(30074, 'Thế giới ngầm bị đảo ngược', 'Thông Thường', 'Không có', 'UR', 3, 'xsmjnz', 'Các lá bài trong Bộ Bài có thể được hoán đổi với các lá bài trong Nghĩa Địa.', '|Cách nhận được|\\nCó thể mua tại Time Capsule'),
(30076, 'Phản đòn tử thần', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'swfj', 'Kích hoạt khi quái thú của đối phương tấn công trực tiếp người chơi của bạn - tiêu diệt quái thú tấn công trực tiếp người chơi.', '0'),
(30082, 'phá vỡ Phép Thuật', 'Phản Đòn', 'Ojama', 'UR', 3, 'rlms', 'Khi lá này bị tiêu diệt và gửi vào Nghĩa Địa - bạn có thể thêm <Disruption·Green> - <Disruption·Yellow> và <Disruption·Black> vào tay của bạn.', '|Mô tả|\\nNhanh chóng kiểm tra các lá bài để rút nguyên liệu của Vua phá rối - để Vua phá rối xuất hiện trong thời gian sớm nhất'),
(30083, 'làm gián đoạn bộ ba', 'Thông Thường', 'Ojama', 'UR', 3, 'rlsrz', 'Nó có thể được kích hoạt khi đối phương có 3 ô trống trở lên trên sân để triệu hồi mã thông báo trên sân đối phương.', '|Mô tả|\\nMột lá bài bẫy mạnh mẽ có thể được sử dụng với bất kỳ Bộ Bài nào để nén sân đối phương. Kết hợp với Disruption Knight - đối phương thậm chí có thể ngăn cản đối phương triệu hồi bất kỳ Quái Thú nào.'),
(30084, 'thiết bị khai thác cưỡng bức', 'Phản Đòn', 'Không có', 'SR', 3, 'qztczz', 'Kích hoạt khi quái thú của đối phương tấn công và có thể đưa quái thú tấn công về tay đối phương.', '0'),
(30085, 'điệp khúc nước', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'szhc', 'Khi có một Quái Thú có cùng tên trên sân - khả năng tấn công và phòng thủ của Quái Thú có cùng tên có thể được tăng lên.', '|Mô tả|\\nLá bài này chỉ có thể được kích hoạt khi có ít nhất 2 Quái Thú có cùng tên trên sân - điều này có thể giúp lợi thế trên sân ổn định hơn.'),
(30086, 'linh hồn ác quỷ im lặng', 'Phản Đòn', 'Không có', 'UR', 3, 'cmdxel', 'Kích hoạt khi đối phương có nhiều quái thú trên sân và một Quái Thú tấn công. Quái Thú tấn công tấn công ngẫu nhiên Quái Thú của đối phương.', '|Mô tả|\\nCác lá bài bị hạn chế có thể khiến quái thú có sức tấn công cao của đối phương lãng phí cơ hội tấn công và tiêu diệt Quái Thú có sức tấn công thấp của chính đối phương.'),
(30087, 'Đội quân từ bóng tối', 'Thông Thường', 'Không có', 'UR', 3, 'lzahdjs', 'Quái Thú có từ khóa <Dark World> có thể được thêm vào tay bạn từ Nghĩa Địa.', '0'),
(30088, 'thiên thần nhân tạo', 'Vĩnh Cửu', 'Không có', 'UR', 1, 'rzts', 'Khi Bẫy phản công được kích hoạt - <Mã thông báo thiên thần nhân tạo> có thể được triệu tập đặc biệt.', '0'),
(30089, 'mất', 'Thông Thường', 'Không có', 'SR', 3, 'sl', 'Bạn có thể trục xuất một lá bài từ mộ của đối phương.', '0'),
(30090, 'Choraj sốc', 'Thông Thường', 'Không có', 'UR', 3, 'zljcj', 'Nó có thể được kích hoạt khi có Quái Thú loại khủng long với hơn 2500 đòn tấn công trên sân phe ta - phá hủy tất cả lá bài trên sân.', '0'),
(30091, 'Đá năng lượng tối', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'qhdnls', 'Bạn có thể thêm bộ đếm vào các lá bài có thể thêm <bộ đếm Phép Thuật>.', '0'),
(30092, 'đánh ngã', 'Phản Đòn', 'Không có', 'SR', 3, 'dl', 'Kích hoạt khi đối phương rút bài vào đầu lượt tiếp theo và lá bài rút được đưa vào Nghĩa Địa.', '0'),
(30093, 'bản năng săn mồi', 'Phản Đòn', 'Không có', 'UR', 3, 'slbn', 'Kích hoạt khi đối phương triệu hồi đặc biệt một Quái Thú. Triệu hồi đặc biệt một Quái Thú loại Khủng long từ tay bạn.', '0'),
(30094, 'còi rắn', 'Phản Đòn', 'Không có', 'SR', 3, 'ss', 'Kích hoạt khi quái thú Bò sát của một người bị tiêu diệt. Triệu hồi đặc biệt một Quái Thú Reptile có cấp độ 4 trở xuống từ Bộ Bài.', '0'),
(30095, 'bản năng sinh tồn', 'Thông Thường', 'Không có', 'SR', 3, 'scbn', 'Bạn có thể loại bỏ Quái Thú loại khủng long khỏi Nghĩa Địa của riêng mình và mỗi khi loại bỏ một con Quái Thú - mạng sống của người chơi sẽ tăng lên.', '0'),
(30096, 'đi chung xe', 'Phản Đòn', 'Không có', 'SR', 3, 'hc', 'Kích hoạt khi đối phương thêm một lá bài vào tay mình từ Bộ Bài hoặc Nghĩa Địa bằng một phương pháp khác ngoài việc rút một lá bài vào đầu lượt của mình và rút một lá bài.', '0'),
(30097, 'lệnh tấn công cuối cùng', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'zztjml', 'Tất cả quái thú trên sân phải ở tư thế tấn công.', '0'),
(30098, 'sự tiến hóa đột ngột', 'Thông Thường', 'Không có', 'UR', 3, 'trjh', 'Quái thú có từ khóa <Evolution Dragon> có thể được Triệu hồi Đặc biệt từ Bộ Bài.', '0'),
(30099, 'điểm phân kỳ tiến hóa', 'Thông Thường', 'Không có', 'UR', 3, 'jhdfqd', 'Quái thú có từ khóa <Evolution Bug> có thể được Triệu hồi Đặc biệt từ Bộ Bài.', '0'),
(30100, 'buộc phải xuống cấp', 'Thông Thường', 'Không có', 'UR', 3, 'qzth', 'Quái Thú bò sát có thể được Triệu hồi Đặc biệt từ Mộ và Bộ Bài.', '0'),
(30101, 'Sóng Poseidon', 'Phản Đòn', 'Không có', 'UR', 3, 'bsdzl', 'Kích hoạt khi quái thú của đối phương tấn công - <chặn> quái thú và gây sát thương dựa trên quái thú trên sân.', '0'),
(30102, 'sân trượt băng', 'Vĩnh Cửu', 'Không có', 'UR', 2, 'hbc', 'Chuyển sang vị trí phòng thủ khi triệu hồi hoặc triệu hồi Quái Thú đặc biệt không phải thuộc tính nước.', '0'),
(30103, 'Sự bảo vệ của Thần Rồng Biển', 'Thông Thường', 'Không có', 'UR', 3, 'hlsdjh', 'Quái Thú thuộc tính nước của bạn nhận được rào cản <Trận chiến·Quái Thú·Phép Thuật·Bẫy>.', '0'),
(30104, 'Giường sinh sản Phép Thuật', 'Phản Đòn', 'Không có', 'SR', 3, 'mzclc', 'Kích hoạt khi quái thú Cá - Rồng biển hoặc Thủy của bạn bị <trục xuất> để thêm quái thú Cá - Rồng biển hoặc Thủy từ Bộ Bài vào tay bạn.', '0'),
(30105, 'khuyến khích', 'Phản Đòn', 'Không có', 'UR', 3, 'gw', 'Kích hoạt khi quái thú của bạn bị quái thú của đối phương tấn công để tăng sức tấn công cho quái thú của bạn.', '0'),
(30106, 'flashbang', 'Phản Đòn', 'Không có', 'SR', 3, 'sgd', 'Kích hoạt khi quái thú của đối phương tấn công trực tiếp người chơi của bạn và lượt của đối phương kết thúc.', '0'),
(30107, 'một nửa kín', 'Phản Đòn', 'Không có', 'SR', 3, 'bf', 'Kích hoạt khi quái thú của bạn bị quái thú của đối phương tấn công và quái thú bị tấn công nhận được rào chắn <chiến đấu>.', '0'),
(30108, 'Đánh chặn', 'Phản Đòn', 'Đế Vương', 'UR', 3, 'jh', 'Kích hoạt khi đối phương hiến tế một Quái Thú và việc triệu hồi cấp trên thành công - đồng thời thu được Quái Thú do cấp trên triệu hồi.', '0'),
(30109, 'phì đại', 'Thông Thường', 'Không có', 'UR', 1, 'fdh', 'Sức tấn công và phòng thủ của Quái Thú đối phương được tăng gấp đôi và không thể tấn công trực tiếp vào người chơi.', '0'),
(30110, 'Lời nguyền của tuổi già', 'Thông Thường', 'Không có', 'UR', 3, 'lhdzz', 'Tất cả Quái Thú trên sân đối phương đều mất khả năng tấn công và phòng thủ trong lượt này.', '0');
INSERT INTO `card_traps` (`id`, `name`, `type`, `keyword`, `quality`, `max_count`, `pinyin`, `description`, `guide`) VALUES
(30111, 'Nhóm câu đố Su Sheng', 'Phản Đòn', 'Không có', 'UR', 2, 'sspz', 'Kích hoạt khi một quái thú của chính mình bị tiêu diệt bởi một hiệu ứng - và quái thú này được Triệu hồi Đặc biệt từ Mộ.', '0'),
(30112, 'tiếng gầm đáng sợ', 'Thông Thường', 'Không có', 'UR', 3, 'whzpx', 'Tất cả quái thú ở lượt tiếp theo của đối phương không thể tấn công.', '0'),
(30113, 'Rồng tái sinh', 'Thông Thường', 'Không có', 'UR', 2, 'lzzs', 'Chọn một quái thú loại Rồng trên sân phe ta để <loại bỏ> nó - và chọn một quái thú loại Rồng từ tay hoặc mộ của bạn để Triệu hồi Đặc biệt.', '0'),
(30115, 'Lông Harpy thổi tuyết', 'Thông Thường', 'Hài Cốt', 'UR', 1, 'ysnydymcx', 'Chọn 1 <Harpy\'s Feather Sweep> từ Bộ Bài và Nghĩa Địa của bạn và thêm nó vào tay bạn.', '0'),
(30116, 'tinh thể băng', 'Thông Thường', 'Không có', 'SR', 3, 'bj', 'Tiêu diệt Quái Thú thuộc tính nước trên sân và gây sát thương cho đối phương.', '0'),
(30117, 'mưa cá', 'Phản Đòn', 'Không có', 'SR', 3, 'yy', 'Khi một quái thú Cá - Rồng Biển hoặc Thủy trên sân bị loại khỏi trò chơi - triệu hồi đặc biệt một quái thú Cá - Rồng Biển hoặc Thủy 3 sao trở xuống từ tay bạn.', '0'),
(30118, 'Tutankhamun', 'Phản Đòn', 'Không có', 'SR', 3, 'ttjm', 'Bảo vệ Quái Thú bất tử của riêng bạn.', '0'),
(30119, 'Thiên thần sa ngã độc ác', 'Thông Thường', 'Thiên Thần Sa Ngã', 'UR', 3, 'bdddts', 'Nhân danh sự hiến tế - sự phán xét các thiên thần sa ngã được thực hiện.', '0'),
(30120, 'Tiếng kêu của quỷ dữ', 'Thông Thường', 'Ác Ma', 'UR', 3, 'emdxj', 'Hồi sinh Quái Thú bằng từ khóa ác quỷ từ Nghĩa Địa.', '0'),
(30121, 'Gương rào băng', 'Phản Đòn', 'Kết Giới Băng', 'UR', 3, 'bjjzj', 'Chiếc gương bảo vệ của rào chắn băng đóng một vai trò rất lớn trong cuộc chiến xâm lược của người ngoài hành tinh.', '0'),
(30122, 'gió ẩm', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'srzf', 'Gió ẩm thổi hương thơm bay xa.', '0'),
(30123, 'tăng cường năng lượng', 'Phản Đòn', 'Không có', 'UR', 3, 'nlts', 'Sử dụng sức mạnh để giáng những đòn chí mạng vào kẻ thù không chuẩn bị.', '0'),
(30124, 'Kaixuan với đôi mắt đỏ thật sự', 'Vĩnh Cửu', 'Mắt Đỏ', 'UR', 3, 'zhydkx', 'Lá bài bẫy cốt lõi của gia đình Red Eye là mối đe dọa rất lớn đối với đối phương nếu nó vẫn còn trên sân.', '0'),
(30125, 'tấn công bằng bom cá', 'Thông Thường', 'Không có', 'UR', 3, 'ydtj', 'Chọn một Quái Thú cá trên sân phe ta làm chi phí để tiêu diệt một lá bài của đối phương.', '0'),
(30126, 'mạng nhện hang nhện', 'Thông Thường', 'Không có', 'UR', 3, 'zxsw', '<Loại bỏ> Quái Thú côn trùng khỏi Nghĩa Địa của chính bạn như một cái giá phải trả - tiêu diệt Quái Thú của đối phương.', '0'),
(30127, 'Người bảo vệ Phù Thủy', 'Vĩnh Cửu', 'Không có', 'UR', 3, 'mssdsh', 'Vòng tròn Phép Thuật được Phù Thủy vẽ bằng vật liệu bí ẩn có sức mạnh bảo vệ và sự sống.', '0'),
(30128, 'làm phiền nhóm', 'Phản Đòn', 'Ojama', 'UR', 3, 'rlq', 'Kích hoạt khi quái thú của bạn có từ khóa <Disruption> bị tiêu diệt - xáo trộn các lá bài bị tiêu diệt vào Bộ Bài.', '0'),
(30129, 'Đảo ngược số phận', 'Thông Thường', 'Không có', 'UR', 3, 'nzdmy', 'Quái Thú của bạn có từ khóa <Sức mạnh bí ẩn> nhận được hiệu ứng ngược lại của đồng xu.', '0'),
(30130, 'lực từ', 'Thông Thường', 'Không có', 'SR', 3, 'cl', 'Quái thú loại Máy và Đá của bạn nhận được <Monster Barrier>.', '0'),
(30131, 'bom xung', 'Thông Thường', 'Không có', 'UR', 3, 'mczd', 'Chuyển tất cả quái thú của đối phương ở vị trí tấn công sang vị trí phòng thủ.', '0'),
(30132, 'Răng mắt đỏ thật có dây chuyền', 'Trang Bị', 'Mắt Đỏ', 'SR', 1, 'fsldzhyy', 'Quái Thú có từ khóa <Mắt đỏ> ở bên bạn có thể tấn công hai lần sau khi được trang bị.', '0'),
